$script:BrushBtnUnRail    = New-FrozenBrush 0x6E 0x2E 0x2E   # Uninstall
$script:BrushChipBadBg    = [System.Windows.Media.SolidColorBrush]::new([System.Windows.Media.Color]::FromArgb(0x1A,0xE0,0x52,0x52))
$script:BrushChipBadBrd   = New-FrozenBrush 0x6E 0x2E 0x2E
$script:BrushChipBadInk   = New-FrozenBrush 0xE0 0x77 0x77
$script:BrushChipWarnBg   = [System.Windows.Media.SolidColorBrush]::new([System.Windows.Media.Color]::FromArgb(0x1F,0xD9,0xA5,0x21))
