# ============================================================
#  Detection Indexes  (built once per scan, reused for all apps)
# ============================================================
# Speed: rather than walking Program Files separately for every app, build two
# shared indexes once and reuse them for the whole scan:
#   * Registry index -- installed products from the Windows uninstall registry
#     (no disk walk; also catches non-standard install locations).
#   * Exe index -- ONE fast native pass over the search roots collecting the exe
#     names apps look for, so per-app checks become in-memory lookups.
# Both are cleared (Clear-DetectionIndexes) whenever app state may change, and
# every index hit is re-confirmed with Test-Path -- so mild staleness can only
# cause a fall-through to a slower check, never a wrong answer.
$script:RegInstallIndex = $null
$script:ExeFileIndex    = $null
$script:AppxIndex       = $null

function Clear-DetectionIndexes {
    $script:RegInstallIndex = $null
    $script:ExeFileIndex    = $null
    $script:AppxIndex       = $null
    # The public-desktop shortcut index is cached for 15s too. Refresh All clears the
    # detection indexes to force a fresh look at disk, so it MUST also drop this cache -
    # otherwise a rescan evaluates shortcuts (esp. strict-exe cards like Raven Lite)
    # against a stale ≤15s snapshot and a just-repaired icon flaps back to "missing".
    $script:LnkCache        = $null
}

# Provisioned MSIX/Appx packages (machine-wide). Cached per scan like the other
# indexes. Queried on the UI thread on first use -- there's typically only one
# MSIX app so the single Get-AppxProvisionedPackage call is a brief cost. Needs
# admin; without it the query returns nothing and MSIX apps read as missing.
function Get-AppxProvisionedIndex {
    if ($null -ne $script:AppxIndex) { return $script:AppxIndex }
    $list = @()
    try { $list = @(Get-AppxProvisionedPackage -Online -ErrorAction SilentlyContinue) } catch { }
    $script:AppxIndex = $list
    return $list
}

# Roots the exe index covers: system-wide dirs + the user's per-app install
# folder (AppData\Local\Programs, where per-user installers land). Both system
# and user hits come from one index so no phase walks the disk per app.
function Get-DetectionSearchRoots {
    $roots = @("$env:ProgramFiles"; "${env:ProgramFiles(x86)}"; "$env:SystemDrive\Xilinx"; "$env:SystemDrive\ANSYS Inc")
    if ($script:UserProfilePath) {
        $roots += (Join-Path $script:UserProfilePath 'AppData\Local\Programs')
    }
    $roots
}

function Get-RegInstallIndex {
    if ($null -ne $script:RegInstallIndex) { return $script:RegInstallIndex }
    $list = [System.Collections.Generic.List[object]]::new()
    foreach ($rp in @(
        'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*'
        'HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*'
    )) {
        Get-ItemProperty -Path $rp -ErrorAction SilentlyContinue | ForEach-Object {
            if ($_.DisplayName) {
                $list.Add([pscustomobject]@{
                    Name     = [string]$_.DisplayName
                    Location = [string]$_.InstallLocation
                    Icon     = [string]$_.DisplayIcon
                })
            }
        }
    }
    $script:RegInstallIndex = $list
    return $list
}

function Get-ExeFileIndex {
    if ($null -ne $script:ExeFileIndex) { return $script:ExeFileIndex }
    # Distinct exe/jar names any app searches for
    $wanted = @{}
    foreach ($p in $script:AppsConfig.apps.PSObject.Properties) {
        $se = $p.Value.detect.searchExe
        if ($se) { $wanted[$se.ToLowerInvariant()] = $true }
    }
    $index = @{}   # lowercase filename -> List[string] of full paths
    if ($wanted.Count -gt 0) {
        $roots = Get-DetectionSearchRoots
        $stack = New-Object System.Collections.Generic.Stack[object]
        foreach ($r in $roots) { if (Test-Path $r) { $stack.Push([pscustomobject]@{ P = $r; D = 0 }) } }
        # Native recursive walk -- ~50x faster than Get-ChildItem -Include -Recurse,
        # and per-directory try/catch skips access-denied folders without aborting.
        while ($stack.Count -gt 0) {
            $cur = $stack.Pop()
            try {
                foreach ($f in [System.IO.Directory]::EnumerateFiles($cur.P)) {
                    $n = [System.IO.Path]::GetFileName($f).ToLowerInvariant()
                    if ($wanted.ContainsKey($n)) {
                        if (-not $index.ContainsKey($n)) { $index[$n] = [System.Collections.Generic.List[string]]::new() }
                        $index[$n].Add($f)
                    }
                }
                if ($cur.D -lt 5) {
                    foreach ($sd in [System.IO.Directory]::EnumerateDirectories($cur.P)) {
                        $stack.Push([pscustomobject]@{ P = $sd; D = $cur.D + 1 })
                    }
                }
            } catch { }
        }
    }
    $script:ExeFileIndex = $index
    return $index
}

# ============================================================
#  Async Index Build  (keeps the UI responsive during the walk)
# ============================================================
# The indexes are cheap to USE but the exe index costs a ~2s filesystem walk to
# BUILD; running that on the UI thread freezes the window. Instead we build both
# in a background runspace (pure data work -- touches no UI objects), poll for
# completion with a light timer, then apply the results and start the scan on
# the UI thread. A generation counter drops any build whose room was already
# switched away from. Everything except the walk itself runs on the UI thread,
# so there is no shared-state race -- the worker only produces data.
$script:indexGeneration = 0
$script:indexMyGen      = 0
$script:indexPS         = $null
$script:indexRS         = $null
$script:indexHandle     = $null
$script:indexOnReady    = $null
$script:indexPollTimer  = $null

# Self-contained worker: takes the wanted names + roots, returns @{ Reg; Exe }.
# Must NOT reference anything from the main scope (runspaces don't share it).
$script:IndexWorker = {
    param($WantedNames, $Roots)
    $reg = New-Object System.Collections.Generic.List[object]
    foreach ($rp in @(
        'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*'
        'HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*'
    )) {
        Get-ItemProperty -Path $rp -ErrorAction SilentlyContinue | ForEach-Object {
            if ($_.DisplayName) {
                $reg.Add([pscustomobject]@{ Name = [string]$_.DisplayName; Location = [string]$_.InstallLocation; Icon = [string]$_.DisplayIcon })
            }
        }
    }
    $wanted = @{}
    foreach ($n in $WantedNames) { $wanted[$n.ToLowerInvariant()] = $true }
    $exe = @{}
    $stack = New-Object System.Collections.Generic.Stack[object]
    foreach ($r in $Roots) { if (Test-Path $r) { $stack.Push([pscustomobject]@{ P = $r; D = 0 }) } }
    while ($stack.Count -gt 0) {
        $cur = $stack.Pop()
        try {
            foreach ($f in [System.IO.Directory]::EnumerateFiles($cur.P)) {
                $nm = [System.IO.Path]::GetFileName($f).ToLowerInvariant()
                if ($wanted.ContainsKey($nm)) {
                    if (-not $exe.ContainsKey($nm)) { $exe[$nm] = New-Object System.Collections.Generic.List[string] }
                    $exe[$nm].Add($f)
                }
            }
            if ($cur.D -lt 5) {
                foreach ($sd in [System.IO.Directory]::EnumerateDirectories($cur.P)) { $stack.Push([pscustomobject]@{ P = $sd; D = $cur.D + 1 }) }
            }
        } catch { }
    }
    # Provisioned MSIX list too (DISM query can take 1-2s -- better here in the
    # background than freezing the UI on the first appx-detect card).
    $appx = @()
    try { $appx = @(Get-AppxProvisionedPackage -Online -ErrorAction SilentlyContinue | Select-Object DisplayName, PackageName) } catch { }
    return @{ Reg = $reg; Exe = $exe; Appx = $appx }
}

function Stop-IndexBuild {
    if ($script:indexPollTimer) { $script:indexPollTimer.Stop() }
    if ($script:indexPS) {
        try { $script:indexPS.Stop() } catch { }
        try { $script:indexPS.Dispose() } catch { }
        $script:indexPS = $null
    }
    if ($script:indexRS) {
        try { $script:indexRS.Dispose() } catch { }
        $script:indexRS = $null
    }
    $script:indexHandle = $null
}

function Build-IndexesSync {
    # Fallback: build on the UI thread (brief freeze) if the async path fails.
    $null = Get-RegInstallIndex
    $null = Get-ExeFileIndex
}

function Start-IndexBuildAsync {
    param([scriptblock]$OnReady)

    # Already built (e.g. a plain room switch) -> no rebuild, run the scan now
    if ($null -ne $script:RegInstallIndex -and $null -ne $script:ExeFileIndex) {
        if ($OnReady) { & $OnReady }
        return
    }

    $script:indexGeneration++
    $myGen = $script:indexGeneration
    Stop-IndexBuild   # cancel/dispose any in-flight build

    $wanted = @()
    foreach ($p in $script:AppsConfig.apps.PSObject.Properties) {
        if ($p.Value.detect.searchExe) { $wanted += $p.Value.detect.searchExe }
    }
    $roots = Get-DetectionSearchRoots

    try {
        $rs = [runspacefactory]::CreateRunspace()
        $rs.Open()
        $ps = [powershell]::Create()
        $ps.Runspace = $rs
        [void]$ps.AddScript($script:IndexWorker).AddArgument($wanted).AddArgument($roots)
        $script:indexHandle  = $ps.BeginInvoke()
        $script:indexPS      = $ps
        $script:indexRS      = $rs
        $script:indexOnReady = $OnReady
        $script:indexMyGen   = $myGen
    } catch {
        # Could not start a runspace -> synchronous fallback so detection still works
        Write-LabLog -Event 'index.fallback_sync' -Data @{ errorCode = 'E12'; reason = 'runspace start failed'; error = $_.Exception.Message }
        Stop-IndexBuild
        Build-IndexesSync
        if ($OnReady) { & $OnReady }
        return
    }

    if (-not $script:indexPollTimer) {
        $script:indexPollTimer = New-Object System.Windows.Threading.DispatcherTimer
        $script:indexPollTimer.Interval = [TimeSpan]::FromMilliseconds(120)
        $script:indexPollTimer.Add_Tick({
            if (-not $script:indexHandle) { $script:indexPollTimer.Stop(); return }
            if (-not $script:indexHandle.IsCompleted) { return }

            $data = $null
            try {
                $out = $script:indexPS.EndInvoke($script:indexHandle)
                if ($out) {
                    foreach ($o in $out) {
                        if ($o -is [hashtable]) { $data = $o; break }
                    }
                }
            } catch { }

            $gen     = $script:indexMyGen
            $onReady = $script:indexOnReady
            Stop-IndexBuild

            # Ignore a build whose room was already switched away from
            if ($gen -ne $script:indexGeneration) { return }

            if ($data -and $null -ne $data['Reg'] -and $null -ne $data['Exe']) {
                $script:RegInstallIndex = $data['Reg']
                $script:ExeFileIndex    = $data['Exe']
                if ($null -ne $data['Appx']) { $script:AppxIndex = @($data['Appx']) }
            } else {
                Write-LabLog -Event 'index.fallback_sync' -Data @{ errorCode = 'E12'; reason = 'worker returned nothing usable' }
                Build-IndexesSync
            }
            if ($onReady) { & $onReady }
        })
    }
    $script:indexPollTimer.Start()
}

# ============================================================
#  Detection Logic
# ============================================================
function Test-AppInstalled {
    param([string]$AppId)

    $appDef = $script:AppsConfig.apps.$AppId
    if (-not $appDef) { return @{ Installed = $false; Detail = "Unknown app: $AppId"; Searched = @(); UserOnly = $false } }

    $d = $appDef.detect
    $searched = [System.Collections.Generic.List[string]]::new()

    # detect.requireAlso: paths that must ALSO exist before the app counts as
    # COMPLETE. detect.paths is an OR list - the first hit returns "installed" -
    # which is wrong for a card that deploys more than one product. LabVIEW's
    # card is "LabVIEW 2021 SP1 + ELVIS III", and the ELVIS III packages install
    # LAST in the 520-package transaction. A mid-transaction failure (seen for
    # real at package 300 of 520 on 2026-07-27) therefore leaves LabVIEW.exe on
    # disk with no ELVIS III, and the card would have gone green on a machine
    # missing the toolkit the course actually needs.
    $missingExtra = @()
    foreach ($ra in @($d.requireAlso)) {
        if (-not $ra) { continue }
        if (-not (Test-Path $ra)) { $missingExtra += $ra }
    }

    # --- Phase 1: Check known system-wide paths (fast) ---
    switch ($d.method) {
        'path' {
            foreach ($p in $d.paths) {
                $searched.Add($p)
                if (Test-Path $p -PathType Leaf) {
                    if ($missingExtra.Count -gt 0) {
                        $what = if ($d.requireAlsoLabel) { "$($d.requireAlsoLabel)" } else { 'a required component' }
                        return @{ Installed = $true; Detail = $p; Searched = $searched; UserOnly = $false
                                  Partial = $true; PartialWhat = $what; PartialMissing = $missingExtra }
                    }
                    return @{ Installed = $true; Detail = $p; Searched = $searched; UserOnly = $false }
                }
            }
        }
        'folder' {
            foreach ($p in $d.paths) {
                $searched.Add($p)
                # PS 5.1 quirk: -PathType Container returns FALSE for wildcard
                # paths inside locked-down dirs (e.g. DriverStore\FileRepository,
                # whose subfolder ACLs defeat the type check). For wildcard
                # patterns fall back to a plain existence test.
                if ((Test-Path $p -PathType Container) -or (($p -match '[\*\?]') -and (Test-Path $p))) {
                    return @{ Installed = $true; Detail = $p; Searched = $searched; UserOnly = $false }
                }
            }
        }
        'registry' {
            $keyDesc = "$($d.key) -> $($d.value)"
            $searched.Add("Registry: $keyDesc")
            try {
                $reg = Get-ItemProperty -Path $d.key -ErrorAction Stop
                $val = $reg.($d.value)
                if ($val) { return @{ Installed = $true; Detail = $val; Searched = $searched; UserOnly = $false } }
            } catch { }
        }
        'filematch' {
            # CONTENT detection for config-copy cards (Blake, 2026-08-06).
            #
            # Every other method answers "is something there?". This one answers
            # "is the RIGHT thing there?" - it hashes each staged file against
            # the copy on the machine and only reports installed when they are
            # byte-identical. A card using it goes RED when a config has drifted,
            # been overwritten by a reinstall, or was never corrected because a
            # tech clicked Next through a wizard and accepted the wrong defaults.
            # Presence checks cannot see any of that: the file exists either way.
            #
            # Source/destination default to the card's own install block, so a
            # copy card needs no duplicate configuration - detection is simply
            # "would the install still change anything?".
            $inst = $script:AppsConfig.apps.$AppId.install
            $srcSub = if ($d.sourceSub) { $d.sourceSub } else { $inst.sourceSub }
            # destinationS (plural, array) supports apps whose install location
            # moves between versions - SpectroFlo 3.3.0 lands in
            # 'Cytekbio\SpectroFlo' but older builds used other folder names, and
            # a card must not go red merely because the vendor renamed a folder.
            # First candidate that EXISTS wins; falls back to the singular forms.
            $dest = $null
            if ($d.destinations) {
                foreach ($cand in @($d.destinations)) { if ($cand -and (Test-Path $cand)) { $dest = $cand; break } }
            }
            if (-not $dest) { $dest = if ($d.destination) { $d.destination } else { $inst.destination } }
            $src    = if ($srcSub) { Join-Path $script:SourceRoot $srcSub } else { $null }
            $searched.Add("Content match: $src -> $dest")
            if (-not $src -or -not $dest -or -not (Test-Path $src)) {
                return @{ Installed = $false; Detail = 'Cannot compare - staged source folder is missing'; Searched = $searched; UserOnly = $false }
            }
            $files = @(Get-ChildItem -LiteralPath $src -Recurse -File -ErrorAction SilentlyContinue)
            if ($files.Count -eq 0) {
                return @{ Installed = $false; Detail = 'Nothing staged to compare against'; Searched = $searched; UserOnly = $false }
            }
            # GUARD: this method hashes every staged file on EVERY scan. That is
            # fine for a handful of config files and ruinous for a payload like
            # Lab Course (5 GB). Over the cap, compare size only and say so, so a
            # mis-pointed card degrades instead of freezing the scan.
            $total = ($files | Measure-Object -Property Length -Sum).Sum
            $hashOk = ($total -le 25MB)
            $bad = $null
            foreach ($f in $files) {
                $rel = $f.FullName.Substring($src.Length).TrimStart('\')
                $tgt = Join-Path $dest $rel
                if (-not (Test-Path $tgt -PathType Leaf)) { $bad = "missing: $rel"; break }
                if ($hashOk) {
                    $a = (Get-FileHash -LiteralPath $f.FullName -Algorithm SHA256 -ErrorAction SilentlyContinue).Hash
                    $b = (Get-FileHash -LiteralPath $tgt        -Algorithm SHA256 -ErrorAction SilentlyContinue).Hash
                    if (-not $a -or -not $b -or $a -ne $b) { $bad = "differs: $rel"; break }
                } elseif ((Get-Item -LiteralPath $tgt).Length -ne $f.Length) {
                    $bad = "size differs: $rel"; break
                }
            }
            if ($bad) {
                return @{ Installed = $false; Detail = "Config does NOT match the staged copy - $bad"; Searched = $searched; UserOnly = $false }
            }
            $how = if ($hashOk) { 'content identical' } else { 'sizes match (too large to hash)' }
            return @{ Installed = $true; Detail = "$dest  ($($files.Count) file(s), $how)"; Searched = $searched; UserOnly = $false }
        }
        'appx' {
            # Machine-wide MSIX: confirmed via the provisioned-package list
            # (the WindowsApps folder is ACL-locked, so no file-path check).
            $searched.Add("Provisioned MSIX: $($d.packageName)")
            $hit = Get-AppxProvisionedIndex |
                Where-Object { $_.DisplayName -like "*$($d.packageName)*" -or $_.PackageName -like "*$($d.packageName)*" } |
                Select-Object -First 1
            if ($hit) { return @{ Installed = $true; Detail = "$($hit.PackageName)  (provisioned)"; Searched = $searched; UserOnly = $false } }
        }
        'envpath' {
            # "Is this program actually ON THE PATH?" as a first-class fact that
            # is RE-CHECKED on every scan - not a marker file recording that it
            # was once true. If someone later edits PATH, the card goes red again.
            #
            # WHY THIS METHOD EXISTS (Blake, 2026-08-21): "It throws the correct
            # version but the execution app alias is defaulting to a local version
            # that isn't added to path". Windows ships 0-byte App Execution Alias
            # stubs for python.exe/python3.exe in %LOCALAPPDATA%\Microsoft\WindowsApps,
            # and that folder is on every user's USER path. Windows searches SYSTEM
            # entries BEFORE user ones, so a real machine-wide Python shadows the
            # stub - and when the system entry is missing, the 0-byte stub is what
            # a student's `python` resolves to. Confirmed on the bench:
            #   where.exe python
            #     C:\Program Files\Python313\python.exe                    105816 bytes
            #     %LOCALAPPDATA%\Microsoft\WindowsApps\python.exe                 0 bytes
            # No other detect method can see this: 'path' proves a file exists on
            # disk, which is true either way. This one answers the real question.
            #
            #   detect.exe    the file to resolve. Deliberately NOT named
            #                 'searchExe' - that field also triggers the Phase 2
            #                 whole-disk exe fallback further down, which would
            #                 green the card off ANY python.exe found anywhere,
            #                 the exact false positive this method exists to stop.
            #   detect.scope  machine (default) | user | both. Default machine on
            #                 purpose: only the SYSTEM path is true for every
            #                 student. A hit on the imaging tech's user path would
            #                 certify a machine nobody else can use - the same
            #                 per-user trap the Excel ToolPak card documents.
            #   detect.pathMustMatch  optional regex the resolved file must match.
            $scope = if ($d.scope) { "$($d.scope)".ToLowerInvariant() } else { 'machine' }
            $exeName = "$($d.exe)"
            $searched.Add("PATH ($scope) lookup for '$exeName'")
            $rawPaths = @()
            if ($scope -ne 'user') {
                try { $rawPaths += [string](Get-ItemProperty 'HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Environment' -Name 'Path' -ErrorAction Stop).Path } catch { }
            }
            if ($scope -ne 'machine') {
                try { $rawPaths += [string](Get-ItemProperty 'HKCU:\Environment' -Name 'Path' -ErrorAction SilentlyContinue).Path } catch { }
            }
            foreach ($seg in (($rawPaths -join ';') -split ';')) {
                $dir = "$seg".Trim().Trim('"')
                if (-not $dir) { continue }
                try { $dir = [Environment]::ExpandEnvironmentVariables($dir) } catch { }
                # try/catch per segment + -LiteralPath: PATH is MACHINE input,
                # not our config. A garbage segment (illegal chars, wildcards)
                # must skip, never throw - this runs on every scan.
                $cand = $null
                try { $cand = Join-Path $dir $exeName } catch { continue }
                if (-not (Test-Path -LiteralPath $cand -PathType Leaf)) { continue }
                if ($d.pathMustMatch -and $cand -notmatch $d.pathMustMatch) { continue }
                # A 0-byte hit is an App Execution Alias reparse point, not a
                # program. Counting it as installed IS the bug being fixed.
                $len = -1; try { $len = (Get-Item -LiteralPath $cand -ErrorAction Stop).Length } catch { }
                if ($len -le 0) { $searched.Add("ignored 0-byte alias stub: $cand"); continue }
                return @{ Installed = $true; Detail = "$cand  (on the $scope PATH)"; Searched = $searched; UserOnly = $false }
            }
        }
    }

    # --- Phase 1.5: Windows uninstall registry (fast; catches non-standard installs) ---
    # Conservative: the full display name must appear in a registered product's
    # name, AND that product's on-disk location must exist -- so a stale or
    # loosely-matching registry entry can never produce a false "installed".
    if ($appDef.displayName) {
        $cand = Get-RegInstallIndex |
            Where-Object { $_.Name -match [regex]::Escape($appDef.displayName) } |
            Select-Object -First 1
        if ($cand) {
            $searched.Add("Registry: $($cand.Name)")
            $regPath = $null
            if ($cand.Icon) {
                $ic = ($cand.Icon -split ',')[0].Trim('"').Trim()
                if ($ic -and (Test-Path $ic)) { $regPath = $ic }
            }
            if (-not $regPath -and $cand.Location) {
                $loc = $cand.Location.Trim('"').TrimEnd('\')
                if ($loc -and (Test-Path $loc)) { $regPath = $loc }
            }
            if ($regPath -and (-not $d.pathMustMatch -or $regPath -match $d.pathMustMatch)) {
                return @{ Installed = $true; Detail = "$regPath  (registered)"; Searched = $searched; UserOnly = $false }
            }
        }
    }

    # --- Phase 2 & 3: shared exe index (built once per scan, off the UI thread) ---
    # Both system-wide and user-profile hits come from the same index, so NO
    # per-app disk walk runs during the scan (that was the old scroll-freeze).
    # A hit under a system dir is a normal install; a hit under the user's
    # profile is user-only (won't persist for other users). System wins.
    # 'pathMustMatch' still guards generic exe names (java.exe) against other
    # products.
    if ($d.searchExe) {
        $searched.Add("Searched indexed locations for '$($d.searchExe)'")
        $cands = (Get-ExeFileIndex)[$d.searchExe.ToLowerInvariant()]
        if ($cands) {
            $userHit = $null
            foreach ($cp in $cands) {
                if ($d.pathMustMatch -and $cp -notmatch $d.pathMustMatch) { continue }
                $isUser = $script:UserProfilePath -and $cp.StartsWith($script:UserProfilePath, [System.StringComparison]::OrdinalIgnoreCase)
                if ($isUser) {
                    if (-not $userHit -and (Test-Path $cp)) { $userHit = $cp }
                } elseif (Test-Path $cp) {
                    return @{ Installed = $true; Detail = "$cp  (found via search)"; Searched = $searched; UserOnly = $false }
                }
            }
            if ($userHit) {
                $warnDetail = "$userHit  [USER-ONLY: installed for $($script:UserName) only, will not persist for other users]"
                return @{ Installed = $true; Detail = $warnDetail; Searched = $searched; UserOnly = $true }
            }
        }
    }

    # --- Not found anywhere ---
    $checkedCount = $searched.Count
    $shortList = ($searched | ForEach-Object {
        $s = $_ -replace [regex]::Escape("$env:ProgramFiles"), '%PF%' -replace [regex]::Escape("${env:ProgramFiles(x86)}"), '%PF86%'
        if ($script:UserProfilePath) { $s = $s -replace [regex]::Escape($script:UserProfilePath), '%USER%' }
        $s -replace [regex]::Escape("$env:SystemDrive"), 'C:'
    }) -join ' | '
    if ($shortList.Length -gt 140) { $shortList = $shortList.Substring(0, 137) + '...' }

    return @{ Installed = $false; Detail = "Not found - checked $checkedCount location(s): $shortList"; Searched = $searched; UserOnly = $false }
}

# ============================================================
#  Campus hostname decoder
# ============================================================
# UNIV naming convention:  [building 2-3d][room 3-4d][TYPE][refresh]-[machine]
# e.g. 10101LAB34-20 = building 55 (ENG), room 103, LAB, refresh 34, machine 20.
# Tables live in config\buildings.json (optional). Rules:
#   - building split is table-driven, LONGEST code first (handles EXT=902)
#   - low building codes are zero-padded in real hostnames (01103..., confirmed)
#   - machine -01 + type CART = Instructor Station ALWAYS
#   - machine -01 + any other type = role unknown -> flagged, never guessed
# Anything that can't be decoded returns flags instead of wrong answers.
function ConvertFrom-LabHostname {
    param([string]$Hostname = $env:COMPUTERNAME)
    $r = @{ Raw=$Hostname; Matched=$false; Building=$null; BuildingAbbr=$null; BuildingName=$null
            Room=$null; Type=$null; Refresh=$null; Machine=$null; Role=$null; Flags=@() }

    $m = [regex]::Match($Hostname, '^(?<digits>\d{5,7})(?<code>[A-Za-z]+)(?<refresh>\d+)-(?<machine>\d+)$')
    if (-not $m.Success) {
        $r.Flags += 'not-campus-convention'
        # say WHICH part broke the grammar, so the header tooltip can teach
        # instead of shrug - the difference between 'weird name' and 'so close,
        # the refresh digits are just missing'.
        $why = if ($Hostname -notmatch '^\d')                { 'does not start with the building/room digits' }
               elseif ($Hostname -notmatch '^\d{5,7}[A-Za-z]') { 'needs 5-7 leading digits followed by a letter type code' }
               elseif ($Hostname -notmatch '-')                { 'no -machineNumber suffix' }
               elseif ($Hostname -notmatch '-\d+$')           { 'the part after the dash is not a plain number' }
               else                                            { 'type code or refresh digits out of shape' }
        $r.Flags += "why: $why"
        return $r
    }
    $r.Matched = $true
    $digits    = $m.Groups['digits'].Value
    $r.Type    = $m.Groups['code'].Value.ToUpper()
    $r.Refresh = [int]$m.Groups['refresh'].Value
    $r.Machine = [int]$m.Groups['machine'].Value

    # building/room split: longest known building code wins, remainder = room
    if ($script:BuildingsConfig -and $script:BuildingsConfig.buildings) {
        foreach ($len in 3,2) {
            if ($digits.Length -gt $len) {
                $cand = $digits.Substring(0, $len)
                $bldg = $script:BuildingsConfig.buildings.$cand
                if ($bldg) {
                    $r.Building     = $cand
                    $r.BuildingAbbr = $bldg.abbr
                    $r.BuildingName = if ($bldg.fullName) { $bldg.fullName } else { $bldg.abbr }
                    $r.Room         = $digits.Substring($len)
                    break
                }
            }
        }
        if (-not $r.Building) { $r.Flags += "unknown-building ($digits)" }
        else {
            # Room-length sanity: per-building roomDigits (buildings.json) wins
            # when set ("3", "4", or "3-4"); campus default 3-4 otherwise.
            $rd = $script:BuildingsConfig.buildings.($r.Building).roomDigits
            $len = $r.Room.Length
            $lenOk = if ("$rd" -match '^(\d+)-(\d+)$') { $len -ge [int]$Matches[1] -and $len -le [int]$Matches[2] }
                     elseif ("$rd" -match '^\d+$')     { $len -eq [int]$rd }
                     else                              { $len -ge 3 -and $len -le 4 }
            if (-not $lenOk) { $r.Flags += "odd-room-length ($($r.Room) vs expected $(if ($rd) { $rd } else { '3-4' }) digits)" }
        }
    } else {
        $r.Flags += 'no-buildings-table'
    }

    # role: -01 + CART = instructor ALWAYS; -01 + anything else = unknown (ask)
    if ($r.Machine -eq 1) {
        $tc = if ($script:BuildingsConfig -and $script:BuildingsConfig.typeCodes) { $script:BuildingsConfig.typeCodes.($r.Type) } else { $null }
        if ($tc -and $tc.machine01Role -and $tc.machine01Role -ne 'ask') { $r.Role = $tc.machine01Role }
        else { $r.Role = 'Unknown (machine -01, type ' + $r.Type + ')'; $r.Flags += 'machine-01-role-unclear' }
    } else {
        $r.Role = 'Student/General Station'
    }
    return $r
}

# ============================================================
#  Deployment rules resolver
# ============================================================
# deployment-rules.json: ordered list; FIRST matching rule wins.
#   rule = { building: "55", rooms: "103,204-210" (blank=all), types: "CART,LAB"
#            (blank=all), machines: "30-60" (blank=all), profile: "ENG" }
# Blake's "same room, #30-60 get A, #61-90 get B" is two rules on one room.
function Test-NumToken {
    # does integer $n fall inside a token list like "5, 30-60, 103"? blank = all
    param([string]$Tokens, [int]$N)
    if (-not $Tokens -or -not $Tokens.Trim()) { return $true }
    foreach ($t in ($Tokens -split ',')) {
        $t = $t.Trim()
        if ($t -match '^(\d+)\s*-\s*(\d+)$') {
            # normalize a hand-typed inverted range: "60-1" means 1-60, not
            # "matches nothing"
            $lo = [int]$Matches[1]; $hi = [int]$Matches[2]
            if ($lo -gt $hi) { $tmp = $lo; $lo = $hi; $hi = $tmp }
            if ($N -ge $lo -and $N -le $hi) { return $true }
        }
        elseif ($t -match '^\d+$') { if ($N -eq [int]$t) { return $true } }
    }
    return $false
}

# decoded hostname -> the winning RULE object (first match wins), or $null.
# Split out from Resolve-DeployProfile because a rule can now carry its own
# package list instead of pointing at a room profile, and callers need the
# whole rule to see that.
function Resolve-DeployRule {
    param($Decode)
    if (-not $script:RulesConfig -or -not $script:RulesConfig.rules) { return $null }
    if (-not $Decode -or -not $Decode.Matched -or -not $Decode.Building) { return $null }
    foreach ($r in @($script:RulesConfig.rules)) {
        if ("$($r.building)" -ne $Decode.Building) { continue }
        if ($r.rooms -and $r.rooms.Trim() -and -not (Test-NumToken -Tokens $r.rooms -N ([int]$Decode.Room))) { continue }
        if ($r.types -and $r.types.Trim()) {
            $tl = @(($r.types -split ',') | ForEach-Object { $_.Trim().ToUpper() } | Where-Object { $_ })
            if ($tl -notcontains $Decode.Type) { continue }
        }
        if (-not (Test-NumToken -Tokens $r.machines -N $Decode.Machine)) { continue }
        return $r
    }
    return $null
}

# Does this rule carry its OWN app list (the `apps` array the Assign tab
# writes) rather than pointing at a room profile?
#
# Tests for the PROPERTY, never for emptiness: `apps: []` is a real, meaningful
# answer - "these machines get NOTHING" - and that is the whole point. Before
# this existed, "none" could only happen by accident when no rule matched at
# all, so a broad rule could never be overridden back down to empty; Blake's
# "#01-60 get the ENG set, the rest get none" was literally not expressible.
# Inline lists also mean two segments of one room can differ without inventing
# a room profile per segment, so editing one segment can no longer silently
# change a different room that happens to share a profile.
function Test-RuleHasApps {
    param($Rule)
    if (-not $Rule) { return $false }
    return [bool](@($Rule.PSObject.Properties.Name) -contains 'apps')
}

# The rule's own app list, filtered to ids that still exist in apps.json (a
# program deleted from the catalog must not linger as a phantom expectation).
# Returns $null when the rule has no inline list - NOT an empty array, which
# would be indistinguishable from "assigned nothing".
function Get-RuleApps {
    param($Rule)
    if (-not (Test-RuleHasApps -Rule $Rule)) { return $null }
    return @(@($Rule.apps) | Where-Object { $_ -and $script:AppsConfig.apps.$_ })
}

# Short human label for what a rule grants, for lists and the fleet map.
function Get-RuleLabel {
    param($Rule)
    if (-not $Rule) { return '' }
    if (Test-RuleHasApps -Rule $Rule) {
        $n = @(Get-RuleApps -Rule $Rule).Count
        if ($n -eq 0) { return '(none)' }
        return "custom ($n)"
    }
    if ("$($Rule.profile)".Trim()) { return "$($Rule.profile)" }
    return '(none)'
}

function Resolve-DeployProfile {
    # decoded hostname -> profile name via the rules, or $null if none match.
    # Kept for callers that only care about the profile NAME. A rule with an
    # inline app list has no profile key, so this returns '(none)'-ish empty;
    # use Resolve-DeployRule when the app list matters.
    param($Decode)
    $r = Resolve-DeployRule -Decode $Decode
    if (-not $r) { return $null }
    return "$($r.profile)"
}

# Register the winning rule's inline app list as a one-off in-memory room
# profile so every existing downstream consumer (room dropdown, Set-RoomApps,
# Install All Missing, the scan queue) keeps working unchanged. Never written
# back to rooms.json - it is derived state, recomputed each launch.
function Register-AssignedProfile {
    param($Rule, $Decode)
    $apps  = @(Get-RuleApps -Rule $Rule)
    $label = 'Assigned to this machine'
    if ($Decode -and $Decode.Room) {
        $ab = if ($Decode.BuildingAbbr) { $Decode.BuildingAbbr } else { $Decode.Building }
        $label = "$ab $($Decode.Room)"
        if ("$($Rule.machines)".Trim()) { $label += " #$($Rule.machines)" }
        $label += ' (assigned)'
    }
    $obj = [pscustomobject]@{ displayName = $label; apps = $apps }
    $script:RoomsConfig.rooms | Add-Member -NotePropertyName '_assigned_' -NotePropertyValue $obj -Force
    return '_assigned_'
}

# How many machines does this room physically HAVE? Declared per room in
# buildings.json under roomSizes ("55-103": 90), because nothing else knows:
# the fleet map used to assume the highest machine number any log had ever
# shown was the whole room, so a room of 90 with 34 visited looked like a
# room of 34 - and a splitter cannot prove coverage against a guess.
function Get-RoomMachineCount {
    param([string]$Building, [string]$Room, [int]$SeenMax = 0)
    try {
        if ($script:BuildingsConfig -and $script:BuildingsConfig.roomSizes) {
            $v = $script:BuildingsConfig.roomSizes."$Building-$Room"
            if ($v -and [int]$v -gt 0) { return [int]$v }
        }
    } catch { }
    if ($SeenMax -gt 0) { return $SeenMax }
    return 0
}

function Save-RoomMachineCount {
    param([string]$Building, [string]$Room, [int]$Count)
    if (-not $script:BuildingsConfig) { return $false }
    if (-not $script:BuildingsConfig.roomSizes) {
        $script:BuildingsConfig | Add-Member -NotePropertyName 'roomSizes' -NotePropertyValue ([pscustomobject]@{}) -Force
    }
    $script:BuildingsConfig.roomSizes | Add-Member -NotePropertyName "$Building-$Room" -NotePropertyValue $Count -Force
    return (Save-BuildingsConfig)
}

function Get-DetectedRoom {
    $hn = $env:COMPUTERNAME
    # -1. The assignment LEDGER (Rooms & Rules -> Manual Entry): a human explicitly
    #     put this machine in a room. Explicit assignment beats every decoder,
    #     which is what makes fleets with NO naming scheme first-class.
    try {
        $led = $script:AssignLedger.machines.$hn
        if ($led -and -not $led.retired -and $led.room -and $script:RoomsConfig.rooms."$($led.room)") { return "$($led.room)" }
    } catch { }
    # 0. Deployment RULES (most specific: can target machine-number ranges).
    $d0 = ConvertFrom-LabHostname -Hostname $hn
    $rule0 = Resolve-DeployRule -Decode $d0
    if ($rule0) {
        # Rule owns its app list -> no room-profile key exists to return, so
        # publish it as the synthetic '_assigned_' profile and select that.
        if (Test-RuleHasApps -Rule $rule0) { return (Register-AssignedProfile -Rule $rule0 -Decode $d0) }
        if ($script:RoomsConfig.rooms."$($rule0.profile)") { return "$($rule0.profile)" }
    }
    # 1. Decoded match (preferred): room profiles can declare match.building
    #    (whole building) and optionally match.rooms (specific room numbers).
    $d = $d0
    if ($d.Matched -and $d.Building) {
        foreach ($p in $script:RoomsConfig.rooms.PSObject.Properties) {
            $mt = $p.Value.match
            if (-not $mt -or -not $mt.building) { continue }
            if (@($mt.building) -notcontains $d.Building) { continue }
            if ($mt.rooms -and (@($mt.rooms) -notcontains $d.Room)) { continue }
            return $p.Name
        }
    }
    # 2. Legacy regex fallback (kept so hand-set patterns still work)
    foreach ($p in $script:RoomsConfig.rooms.PSObject.Properties) {
        # try/catch: an invalid hostnamePattern regex in rooms.json must not
        # crash startup -- that room just doesn't auto-match.
        try {
            if ($p.Value.match.hostnamePattern -and $hn -match $p.Value.match.hostnamePattern) { return $p.Name }
        } catch { }
    }
    return $null
}

# ============================================================
#  UI pump  (keeps the window alive during unavoidable blocking waits)
# ============================================================
# WPF's DoEvents. A plain Process.WaitForExit() on the UI thread makes Windows
# paint the "Not Responding" ghost over the window - techs think the tool
# crashed and kill it mid-operation. Wait-ProcessResponsive waits the same
# amount of time but pumps the message queue, so the window keeps repainting.
function Invoke-UiDoEvents {
    $frame = New-Object System.Windows.Threading.DispatcherFrame
    [System.Windows.Threading.Dispatcher]::CurrentDispatcher.BeginInvoke(
        [System.Windows.Threading.DispatcherPriority]::Background,
        [System.Windows.Threading.DispatcherOperationCallback]{ param($f) $f.Continue = $false; return $null },
        $frame) | Out-Null
    [System.Windows.Threading.Dispatcher]::PushFrame($frame)
}

function Test-PostInstallDone {
    # Did the app's post-install step already run on THIS machine?
    # Returns $true when there is nothing to check (no postInstall, or no
    # detect rule) so apps without one are never held back.
    # For Vivado the marker is the driver script's OWN log: install_drivers.cmd
    # does `set log=%dir%install_drivers_wrapper.log` and writes it in the folder
    # it ran from, so its presence is direct evidence the script executed.
    # Verified on the bench 2026-07-27: absent on a machine that has Vivado but
    # never had the drivers run, and the Xilinx driver services (windrvr6 /
    # xusbdfwu) were absent too - two independent signals agreeing.
    param([string]$AppId)
    $pi = $script:AppsConfig.apps.$AppId.install.postInstall
    if (-not $pi -or -not $pi.detect) { return $true }
    foreach ($pat in @($pi.detect)) {
        if (-not $pat) { continue }
        try {
            $hit = @(Resolve-Path $pat -ErrorAction SilentlyContinue)
            if ($hit.Count -gt 0) { return $true }
        } catch { }
    }
    return $false
}

function Invoke-AppPostInstall {
    # POST-install dependency: the mirror of a pre-install one (.NET 3.5 before
    # Rockwell). Some vendors ship a step that can only run AFTER their product
    # is on disk - Vivado's JTAG cable drivers live inside the install tree and
    # do not exist until Vivado has been installed. Declared per app as
    # install.postInstall { path, label }. `path` may contain a wildcard so a
    # version bump does not silently break it (the hardcoded-Python-path lesson);
    # the newest match wins.
    # A failure here is reported but never flips the install to FAILED - the app
    # itself is installed and working; only the extra step needs attention.
    param([string]$AppId, $Card)
    $pi = $script:AppsConfig.apps.$AppId.install.postInstall
    if (-not $pi -or -not $pi.path) { return $null }
    $label = if ($pi.label) { "$($pi.label)" } else { 'post-install step' }

    $resolved = $null
    try {
        $resolved = @(Resolve-Path $pi.path -ErrorAction SilentlyContinue | ForEach-Object { $_.Path } |
                      Sort-Object -Descending) | Select-Object -First 1
    } catch { }
    if (-not $resolved) {
        Write-LabLog -Event 'postinstall.not_found' -Data @{ errorCode = 'E71'; appId = $AppId; pattern = "$($pi.path)"; label = $label }
        if ($Card) { $Card.Detail.Text = "Installed - but $label not found (see log)"; $Card.Detail.Foreground = $script:BrushYellow }
        return @{ Ok = $false; Reason = 'not found' }
    }

    Write-LabLog -Event 'postinstall.started' -Data @{ appId = $AppId; label = $label; path = $resolved }
    if ($Card) {
        $Card.Detail.Text       = "Installed - now running $label..."
        $Card.Detail.Foreground = $script:BrushYellow
        $Card.Dot.Fill          = $script:BrushYellow
    }
    $txtStatus.Text = "$AppId : running $label..."
    try {
        $wd = Split-Path $resolved -Parent
        # Optional arguments. Needed for tools that take switches rather than
        # just running (NI's NILicensingCmd.exe /addservers <server> registers
        # the campus volume-license server - a hostname, no credentials).
        # {source} resolves to THIS drive's LabDeploy-InstallerSources, so a
        # post-install helper shipped in the payload works from any stick
        # instead of a hard-coded path to whichever bench authored the card.
        $piArgs = "$($pi.arguments)".Trim()
        if ($piArgs -and $script:SourceRoot) { $piArgs = $piArgs.Replace('{source}', $script:SourceRoot) }
        $cmdLine = if ($piArgs) { '/c ""{0}" {1}"' -f $resolved, $piArgs } else { '/c ""{0}""' -f $resolved }
        $p = Start-Process -FilePath 'cmd.exe' -ArgumentList $cmdLine `
                           -WorkingDirectory $wd -PassThru -WindowStyle Hidden -ErrorAction Stop
        $null = $p.Handle            # cache or ExitCode reads $null after exit (PS 5.1)
        $done = Wait-ProcessResponsive -Proc $p -TimeoutSec 600   # driver installs can be slow
        $code = if ($done) { try { $p.ExitCode } catch { $null } } else { $null }
        if (-not $done) {
            Write-LabLog -Event 'postinstall.timeout' -Data @{ errorCode = 'E71'; appId = $AppId; label = $label }
            if ($Card) { $Card.Detail.Text = "Installed - $label timed out (still running?)" }
            return @{ Ok = $false; Reason = 'timeout' }
        }
        Write-LabLog -Event 'postinstall.finished' -Data @{ appId = $AppId; label = $label; exitCode = $code }
        return @{ Ok = ($code -eq 0); Exit = $code; Label = $label }
    } catch {
        Write-LabLog -Event 'postinstall.launch_failed' -Data @{ errorCode = 'E71'; appId = $AppId; label = $label; error = $_.Exception.Message }
        if ($Card) { $Card.Detail.Text = "Installed - $label could not start (see log)"; $Card.Detail.Foreground = $script:BrushYellow }
        return @{ Ok = $false; Reason = 'launch failed' }
    }
}

function Wait-ProcessResponsive {
    # Returns $true if the process exited within $TimeoutSec, $false on timeout.
    param([System.Diagnostics.Process]$Proc, [int]$TimeoutSec = 120)
    $deadline = (Get-Date).AddSeconds($TimeoutSec)
    while ((Get-Date) -lt $deadline) {
        try { if ($Proc.HasExited) { return $true } } catch { return $true }
        Invoke-UiDoEvents
        Start-Sleep -Milliseconds 150
    }
    try { return $Proc.HasExited } catch { return $true }
}

# ============================================================
#  Operation-State Guards
# ============================================================
# The GUI has one global install/uninstall slot ($script:installProcess +
# $script:installTimer). Every entry point that could start a new operation
# must check this first, or a second operation clobbers the tracking of the
# first. Also covers the post-install verify window ($script:retryTimer).
# Version of the installer we carry on the drive - fully dynamic, no config
# field to maintain: 1) the installer exe's own embedded version info,
# 2) a version-looking number in the file name (VSCodeSetup-x64-1.128.1.exe),
# 3) an 8-digit datestamp build (msys2-x86_64-20260611.exe). Cached per run.
function Get-SourceVersion {
    param([string]$AppId)
    if ($script:SourceVerCache.ContainsKey($AppId)) { return $script:SourceVerCache[$AppId] }
    $ver = $null
    try {
        $inst = $script:AppsConfig.apps.$AppId.install
        # winget apps have no local file, but if they carry a backup installer
        # (install.fallback) show ITS version - that's what's on the drive
        if ($inst -and -not $inst.sourceSub -and $inst.fallback) { $inst = $inst.fallback }
        if ($inst -and $inst.sourceSub) {
            $src = Join-Path $script:SourceRoot $inst.sourceSub
            $candidates = @()
            if (Test-Path $src -PathType Leaf) { $candidates += $src }
            elseif (Test-Path $src -PathType Container) {
                # copy-method image folder: look at its top-level installer-ish files
                $candidates += @(Get-ChildItem $src -File -ErrorAction SilentlyContinue |
                    Where-Object { $_.Extension -match '^\.(exe|msi|msix|appx|msixbundle)$' } |
                    Select-Object -First 8 | ForEach-Object { $_.FullName })
            }
            # Pass 1: a version in the FILE NAME wins - it's what a human named
            # the download (fixes msys2-...-20260611.exe, whose exe metadata
            # carries the installer FRAMEWORK's version, not MSYS2's)
            foreach ($f in $candidates) {
                $leaf = [System.IO.Path]::GetFileNameWithoutExtension($f)   # keep ".exe" away from the datestamp match
                if ($leaf -match '(\d+(?:\.\d+)+)')                { $ver = $Matches[1]; break }
                elseif ($leaf -match '(?<![\d.])(\d{8})(?![\d.])') { $ver = $Matches[1]; break }
            }
            # Pass 2: embedded version info of an exe (e.g. "Arduino IDE.exe")
            if (-not $ver) {
                foreach ($f in @($candidates | Where-Object { $_ -match '\.exe$' })) {
                    $fi = [System.Diagnostics.FileVersionInfo]::GetVersionInfo($f)
                    foreach ($s in @($fi.ProductVersion, $fi.FileVersion)) {
                        if ($s -and $s -match '(\d+(?:\.\d+)+)') { $ver = $Matches[1]; break }
                    }
                    if ($ver) { break }
                }
            }
            # Trim noisy trailing zero segments: 2.3.10.0 -> 2.3.10 (keep at least x.y)
            while ($ver -match '^(\d+(?:\.\d+)+)\.0$' -and ($ver -split '\.').Count -gt 2) { $ver = $Matches[1] }
        }
    } catch { }
    # Fall back to the card's own versionLabel. Wrapper-script installs
    # (install-keil.bat, xsetup.bat, ...) and folder copies have no version in
    # the filename, so those cards showed no version at all. This also makes the
    # Program Adder's captured `versionLabel` actually reach the UI - it was
    # being written to apps.json and then never read.
    if (-not $ver) {
        try {
            $lbl = $script:AppsConfig.apps.$AppId.versionLabel
            if ($lbl) { $ver = "$lbl" }
        } catch { }
    }
    $script:SourceVerCache[$AppId] = $ver
    return $ver
}

function Test-OperationInProgress {
    if ($script:installTimer -and $script:installTimer.IsEnabled) { return $true }
    if ($script:retryTimer -and $script:retryTimer.IsEnabled) { return $true }
    if ($script:offloadCopyTimer -and $script:offloadCopyTimer.IsEnabled) { return $true }
    # Wait-WindowsInstallerFree pumps the UI in a nested dispatcher frame for up
    # to 30 minutes with installTimer stopped and installProcess pointing at the
    # PREVIOUS, exited process - every check above reads idle. Clicks during
    # that window used to sail past this guard and re-enter Start-SingleInstall
    # recursively.
    if ($script:MsiWaitActive) { return $true }
    if ($script:installProcess) {
        try { if (-not $script:installProcess.HasExited) { return $true } } catch { }
    }
    return $false
}

# If the app has never been scanned, scan it now (synchronously) so the card
# shows its real state before any install/uninstall is allowed. Returns $true
# when a cached result already existed (caller may proceed), $false when a
# scan was just performed (caller should stop and let the user re-check).
function Confirm-AppScanned {
    param([string]$AppId, [string]$Trigger)

    if ($script:DetectionCache.ContainsKey($AppId)) { return $true }

    # If the background index build is mid-flight, don't duplicate the whole
    # filesystem walk synchronously on the UI thread -- ask for a moment.
    if ($script:indexHandle) {
        $txtStatus.Text = 'Still indexing installed software - try again in a few seconds'
        return $false
    }

    $appDef = $script:AppsConfig.apps.$AppId
    $name = if ($appDef) { $appDef.displayName } else { $AppId }
    $txtStatus.Text = "Scanning $name first..."
    $result = Test-AppInstalled -AppId $AppId
    $script:DetectionCache[$AppId] = $result
    Write-LabLog -Event 'scan.on_demand' -Data @{
        appId = $AppId
        trigger = $Trigger
        detected = $result.Installed
        userOnly = $result.UserOnly
        detail = $result.Detail
    }
    Update-AppCard -AppId $AppId -Result $result
    Update-Summary
    $txtStatus.Text = "Scanned $name - check its status, then click again to proceed"
    return $false
}

# Continue the "Install All Missing" queue after an item finishes or fails
# to start; re-enables the button when the queue is empty. Every path that
# ends an item must call this (or replicate it), or the queue stalls with
# the button stuck disabled.
function Clear-InstallQueue {
    # Emptying the queue silently is not safe. A card can already be painted
    # with a promise the queue was going to keep - the winget fallback and the
    # catalog auto-fix both repaint the card ("using backup installer...",
    # "will retry automatically...") and DISABLE its Install button before
    # re-queueing the retry at the BACK of the queue. Cancelling any other app
    # then wiped that retry, leaving a greyed-out card advertising a retry that
    # was never coming - recoverable only by a manual per-card Refresh.
    # Repaint every dropped entry from real detection so each card tells the
    # truth and its Install button comes back.
    param([string]$ExceptAppId)
    if (-not $script:installQueue -or $script:installQueue.Count -eq 0) { return }
    $dropped = @($script:installQueue.ToArray())
    $script:installQueue.Clear()
    foreach ($dropId in $dropped) {
        if (-not $dropId -or ($ExceptAppId -and $dropId -eq $ExceptAppId)) { continue }
        try {
            $dr = Test-AppInstalled -AppId $dropId
            $script:DetectionCache[$dropId] = $dr
            Update-AppCard -AppId $dropId -Result $dr
        } catch { }
    }
    Write-LabLog -Event 'install.queue_cleared' -Data @{ dropped = ($dropped -join ', ') }
}

function Resume-InstallQueue {
    # PAUSE GATE (Blake, 2026-08-12). This function is the single between-
    # installers boundary - every completion path funnels here before the next
    # app starts - so this is the one safe place to hold a batch: the previous
    # installer has fully finished, nothing has been dequeued yet. The queue is
    # left intact; the same button that paused resumes by calling back in.
    if ($script:BatchPaused -and $script:installQueue.Count -gt 0) {
        $btnInstallMissing.Content = 'Continue Install All Missing'
        $btnInstallMissing.IsEnabled = $true
        $txtStatus.Text = "Paused - $($script:installQueue.Count) install(s) still queued. Click 'Continue Install All Missing' when ready."
        Write-LabLog -Event 'installall.paused' -Data @{ remaining = $script:installQueue.Count }
        return
    }
    # Skip anything the queue still lists that is ALREADY installed. This kills
    # the double-install case where a dependency chain installed app B early
    # (because app A required it) and B was also queued on its own further down
    # the batch - previously B got installed twice, wasting minutes on big
    # vendor images. Re-checks detection fresh so it can't act on a stale cache.
    # Refresh the detection indexes ONCE per drain, not per item. Clearing them
    # inside the loop meant every skipped app triggered a fresh recursive
    # Program Files scan (~0.7s here, considerably worse on lab hardware) - a
    # 19-app batch would have burned ~13s purely re-indexing. One clear is
    # sufficient: the install-completion path already clears them whenever an
    # install actually changes machine state, so entering this loop the data is
    # current, and nothing changes state while we are merely dequeuing.
    Clear-DetectionIndexes
    while ($script:installQueue.Count -gt 0) {
        $nextId = $script:installQueue.Dequeue()
        $chk = Test-AppInstalled -AppId $nextId
        $script:DetectionCache[$nextId] = $chk
        if ($chk.Installed -and -not $chk.UserOnly) {
            Write-LabLog -Event 'install.queue_skip_already_installed' -Data @{ appId = $nextId; detail = $chk.Detail }
            Update-AppCard -AppId $nextId -Result $chk
            continue
        }
        Start-SingleInstall -AppId $nextId -FromQueue
        return
    }
    $btnInstallMissing.IsEnabled = $true
    $btnInstallMissing.Content = 'Install All Missing'
    $script:BatchPaused = $false
    # Batch finished (queue drained). Log what actually became installed vs what
    # was queued, so a truncated or partly-failed batch is obvious in the ledger
    # instead of having to be inferred from the absence of log lines.
    if ($script:BatchQueued -and $script:BatchQueued.Count) {
        $done = @(); $notDone = @()
        foreach ($id in $script:BatchQueued) {
            $st = $script:DetectionCache[$id]
            if ($st -and $st.Installed -and -not $st.UserOnly) { $done += $id } else { $notDone += $id }
        }
        Write-LabLog -Event 'installall.finished' -Data @{
            queued = $script:BatchQueued.Count
            installed = $done.Count
            stillNotInstalled = ($notDone -join ', ')
            minutes = [math]::Round(((Get-Date) - $script:BatchStarted).TotalMinutes, 1)
        }
        $batchN = $script:BatchQueued.Count
        $script:BatchQueued = @()   # cleared BEFORE the sweep - it is the
                                    # "a batch is running" flag, and leaving it
                                    # set through a long sweep would let a
                                    # second finish double-report.
        Update-Summary
        # ALWAYS the last step of Install All (Blake, 2026-07-30). Runs even if
        # some installs failed: the ones that DID land still deserve their icons,
        # and this is the moment the room is otherwise finished.
        try {
            $txtStatus.Text = 'Batch finished - verifying desktop shortcuts...'
            $sc = Invoke-VerifyShortcuts -Auto
            $txtStatus.Text = "Install All finished: $($done.Count) of $batchN installed. Shortcuts: $($sc.Text)."
        } catch {
            Write-LabLog -Event 'shortcut.verify_all_failed' -Data @{ errorCode = 'E70'; error = $_.Exception.Message }
            $txtStatus.Text = "Install All finished: $($done.Count) of $batchN installed. Shortcut check failed - run Verify Shortcuts by hand."
        }
        # Telemetry: push this session's results so a lab machine's progress reaches
        # the dashboard without anyone being at the master. Bounded; outbox drains the rest.
        try { $null = Push-Observations -DeadlineSec 15 } catch {}
        return
    }
    Update-Summary
}

# ============================================================
#  Windows Installer Busy Check
# ============================================================
# The MSI service only allows one install sequence at a time -- starting
# another while one is running fails with exit 1618. The _MSIExecute mutex
# is held for the duration of the executing install.
function Wait-WindowsInstallerFree {
    # Block until no other MSI transaction is running, pumping the UI so the
    # window keeps repainting.
    #
    # WHY THIS EXISTS (field failure 10101LAB34-01, 2026-07-28): Ansys HFSS
    # reported exit 0 after 4m16s but its launcher had DETACHED - the real
    # installer kept running for minutes afterwards, holding Global\_MSIExecute.
    # The next two MSI-based apps in the batch, Python and Visual Studio, both
    # died with 1618 "another installation is already in progress". MSYS2 and
    # VSCode, sandwiched between them, succeeded - because neither uses the
    # Windows Installer. The disk deltas confirm it: Python "wrote" 2758 MB
    # (it is ~100 MB) and Visual Studio showed MINUS 1863 MB, i.e. Ansys still
    # writing and then cleaning up, attributed to whoever was running.
    #
    # The old code skipped the busy check entirely for queue continuations on
    # the assumption the lock could only "linger a moment". It can linger for
    # minutes behind a detaching vendor installer.
    # Returns $true (lock free), $false (timed out), or 'PAUSED' - the last only
    # with -AllowPauseAbort, when the user hit Pause while we were still waiting
    # for someone ELSE's installer. At that moment OUR app has not launched, so
    # aborting loses nothing: the caller requeues it at the front and holds.
    # Callers must check 'PAUSED' explicitly ('PAUSED' is truthy to -not).
    param([int]$TimeoutSec = 1800, [string]$ForApp = '', [switch]$AllowPauseAbort)
    if (-not (Test-WindowsInstallerBusy)) { return $true }
    $sw = [Diagnostics.Stopwatch]::StartNew()
    Write-LabLog -Event 'install.waiting_for_msi_lock' -Data @{ appId = $ForApp; timeoutSec = $TimeoutSec }
    # Flag consumed by Test-OperationInProgress: while this pump runs, the app
    # must still count as busy. try/finally so no exit path leaks the flag.
    $script:MsiWaitActive = $true
    try {
        while ($sw.Elapsed.TotalSeconds -lt $TimeoutSec) {
            if ($AllowPauseAbort -and $script:BatchPaused) {
                $sw.Stop()
                Write-LabLog -Event 'install.msi_wait_pause_abort' -Data @{ appId = $ForApp; waitedSec = [int]$sw.Elapsed.TotalSeconds }
                return 'PAUSED'
            }
            if (-not (Test-WindowsInstallerBusy)) {
                $sw.Stop()
                Write-LabLog -Event 'install.msi_lock_cleared' -Data @{ appId = $ForApp; waitedSec = [int]$sw.Elapsed.TotalSeconds }
                if ($txtStatus) { $txtStatus.Text = "Windows Installer free after $([int]$sw.Elapsed.TotalSeconds)s - continuing" }
                return $true
            }
            if ($txtStatus) {
                $busyName = Get-WindowsInstallerBusyProduct
                $onWhat = if ($busyName) { " (busy installing: $busyName)" } else { '' }
                $txtStatus.Text = "Waiting for another installer to finish before starting $ForApp$onWhat ... $([int]$sw.Elapsed.TotalSeconds)s"
            }
            Invoke-UiDoEvents
            Start-Sleep -Milliseconds 1000
        }
        $sw.Stop()
        Write-LabLog -Event 'install.msi_lock_timeout' -Data @{ errorCode = 'E62'; appId = $ForApp; waitedSec = [int]$sw.Elapsed.TotalSeconds }
        return $false
    } finally {
        $script:MsiWaitActive = $false
    }
}

function Test-WindowsInstallerBusy {
    try {
        $m = [System.Threading.Mutex]::OpenExisting('Global\_MSIExecute')
        $m.Dispose()
        return $true
    } catch [System.Threading.WaitHandleCannotBeOpenedException] {
        return $false
    } catch {
        # Mutex exists but could not be opened (access denied) = install running
        return $true
    }
}

# WHAT is Windows Installer busy with? Best-effort name for the E62 warnings,
# so "another installation is running" becomes "busy installing: Ansys HFSS".
# Two sources, in order of usefulness:
#   1. live msiexec command lines - /i <package.msi> or a {ProductCode}
#      (resolved to a DisplayName via the Uninstall hives when possible)
#   2. the Installer\InProgress registry key the transaction holds open
# Returns $null when nothing readable is found - callers must phrase around it.
function Get-WindowsInstallerBusyProduct {
    try {
        foreach ($proc in @(Get-CimInstance Win32_Process -Filter "Name='msiexec.exe'" -ErrorAction SilentlyContinue)) {
            $cl = "$($proc.CommandLine)"
            # skip the resident service (/V) and COM-broker (-Embedding) instances
            if (-not $cl -or $cl -match '(?i)/V\s*$|Embedding') { continue }
            if ($cl -match '(?i)[/-](?:i|package|p|update|x|uninstall)\s+"?([^"\s][^"]*?\.ms[ip])"?') {
                return [System.IO.Path]::GetFileName($Matches[1])
            }
            if ($cl -match '\{[0-9A-Fa-f]{8}-[0-9A-Fa-f-]{27}\}') {
                $guid = $Matches[0]
                foreach ($hive in @('HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall',
                                    'HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall')) {
                    $dn = try { (Get-ItemProperty -Path (Join-Path $hive $guid) -ErrorAction Stop).DisplayName } catch { $null }
                    if ($dn) { return "$dn" }
                }
                return $guid
            }
        }
        $ipKey = 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Installer\InProgress'
        $ip = try { (Get-ItemProperty -Path $ipKey -ErrorAction Stop).'(default)' } catch { $null }
        if ($ip) { return "$ip" }
    } catch { }
    return $null
}

# Is Windows waiting on a restart before it will accept more servicing work?
#
# Deliberately does NOT look at PendingFileRenameOperations. That key had 52
# live entries on a perfectly healthy bench machine on 2026-07-28 - it is
# routine background noise, and gating installs on it would block essentially
# every machine, every time. Only the signals that actually mean "Windows will
# refuse or corrupt servicing work until you reboot" are consulted.
#
# Returns @{ Pending = [bool]; Reasons = @(...) }.
function Test-PendingReboot {
    $reasons = @()
    $keys = @(
        @{ Path = 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Component Based Servicing\RebootPending';    Why = 'Windows servicing (CBS) reboot pending' }
        @{ Path = 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Component Based Servicing\RebootInProgress'; Why = 'Windows servicing reboot in progress' }
        @{ Path = 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Component Based Servicing\PackagesPending';  Why = 'Windows packages awaiting reboot' }
        @{ Path = 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\WindowsUpdate\Auto Update\RebootRequired';   Why = 'Windows Update reboot required' }
    )
    foreach ($k in $keys) {
        try { if (Test-Path $k.Path) { $reasons += $k.Why } } catch { }
    }
    # A rename that has been staged but not applied - genuine, and distinct from
    # the PendingFileRenameOperations noise above.
    try {
        $active  = (Get-ItemProperty 'HKLM:\SYSTEM\CurrentControlSet\Control\ComputerName\ActiveComputerName' -Name ComputerName -ErrorAction Stop).ComputerName
        $pending = (Get-ItemProperty 'HKLM:\SYSTEM\CurrentControlSet\Control\ComputerName\ComputerName'       -Name ComputerName -ErrorAction Stop).ComputerName
        if ($active -ne $pending) { $reasons += 'computer rename pending' }
    } catch { }
    return @{ Pending = ($reasons.Count -gt 0); Reasons = $reasons }
}

# ============================================================
#  Uninstall Logic
# ============================================================
# What did the vendor uninstaller leave behind? REPORT ONLY - this never
# deletes anything (E46's caution stands; cleanup is a per-app human decision).
# Looks in the app's own configured roots plus the usual residue spots
# (ProgramData / user AppData) named after those roots' leaf folders.
function Get-UninstallResidue {
    param([string]$AppId)
    $found = New-Object System.Collections.ArrayList
    try {
        $appDef = $script:AppsConfig.apps.$AppId
        if (-not $appDef) { return ,@() }
        $roots = New-Object System.Collections.Generic.List[string]
        if ($appDef.install.destination) { $roots.Add([string]$appDef.install.destination) }
        foreach ($p in @($appDef.detect.paths)) {
            if (-not $p -or "$p" -match '[\*\?]') { continue }   # wildcard detect paths (driver stores) can't be surveyed
            if ($appDef.detect.method -eq 'path') { $roots.Add((Split-Path $p -Parent)) }
            else { $roots.Add([string]$p) }
        }
        $leaves = @($roots | ForEach-Object { Split-Path $_ -Leaf } | Where-Object { $_ } | Select-Object -Unique)
        foreach ($leaf in $leaves) {
            $roots.Add((Join-Path $env:ProgramData $leaf))
            if ($script:UserProfilePath) {
                $roots.Add((Join-Path $script:UserProfilePath "AppData\Local\$leaf"))
                $roots.Add((Join-Path $script:UserProfilePath "AppData\Roaming\$leaf"))
            }
        }
        foreach ($r in @($roots | Select-Object -Unique)) {
            try { if ($r -and (Test-Path $r)) { [void]$found.Add($r) } } catch { }
        }
    } catch { }
    return ,@($found | Select-Object -Unique)
}

function Start-SingleUninstall {
    param([string]$AppId)

    $appDef = $script:AppsConfig.apps.$AppId
    if (-not $appDef) {
        Write-LabLog -Event 'uninstall.no_config' -Data @{ errorCode = 'E40'; appId = $AppId }
        $txtStatus.Text = "[E40] No config for $AppId"
        return
    }

    # --- Manual uninstall handoff (e.g. NI LabVIEW -> NI Package Manager) ---
    # Some vendors hide their software from Windows Programs & Features and only
    # allow removal through their own manager. For these, open that manager and
    # hand off to the user instead of attempting a silent uninstall. The command
    # preview still runs, so a tampered program path would be caught here too.
    if ($appDef.uninstall -and $appDef.uninstall.method -eq 'launch') {
        $prog = $appDef.uninstall.program
        if (-not $prog -or -not (Test-Path $prog)) {
            Write-LabLog -Event 'uninstall.manager_missing' -Data @{ errorCode = 'E47'; appId = $AppId; program = $prog }
            [System.Windows.MessageBox]::Show(
                "[E47] The uninstall manager for $($appDef.displayName) was not found at:`n$prog`n`nOpening Windows Programs & Features instead.",
                'Uninstall Manager Not Found (E47)', 'OK', 'Warning')
            Start-Process 'appwiz.cpl'
            return
        }
        if (-not (Confirm-CommandPreview -DisplayName $appDef.displayName -Verb 'Uninstall' -ExactProgram $prog -AlwaysShow)) {
            Write-LabLog -Event 'uninstall.preview_declined' -Data @{ appId = $AppId; method = 'launch'; command = $prog }
            $txtStatus.Text = "$($appDef.displayName): uninstall cancelled at command preview"
            return
        }
        Write-LabLog -Event 'uninstall.manager_launched' -Data @{ appId = $AppId; program = $prog }
        try {
            Start-Process -FilePath $prog
        } catch {
            Write-LabLog -Event 'uninstall.manager_launch_failed' -Data @{ errorCode = 'E44'; appId = $AppId; program = $prog; error = $_.Exception.Message }
            $txtStatus.Text = "[E44] Failed to open uninstall manager: $($_.Exception.Message)"
            return
        }
        $msg = if ($appDef.uninstall.message) { $appDef.uninstall.message } else { "$($appDef.displayName) is removed through its own manager, which is now opening.`n`nRemove it there, then click Refresh." }
        [System.Windows.MessageBox]::Show($msg, "Uninstall $($appDef.displayName)", 'OK', 'Information')
        $txtStatus.Text = "Opened uninstall manager for $($appDef.displayName) - remove it there, then click Refresh"
        return
    }

    $card = $script:Cards[$AppId]
    if ($card) {
        $card.Dot.Fill = $script:BrushOrange
        $card.Detail.Text = 'Uninstalling...'
        $card.Detail.Foreground = $script:BrushOrange
        $card.BtnInstall.IsEnabled    = $false
        $card.BtnInstall.Visibility   = [System.Windows.Visibility]::Collapsed
        $card.BtnUninstall.IsEnabled  = $false
        $card.BtnUninstall.Visibility = [System.Windows.Visibility]::Collapsed
        $card.BtnCancel.Visibility    = [System.Windows.Visibility]::Visible
        $card.BtnOpen.Visibility      = [System.Windows.Visibility]::Collapsed
        $card.Progress.Value           = 0
        $card.Progress.IsIndeterminate = $true
        $card.Progress.Visibility      = [System.Windows.Visibility]::Visible
        $card.Status = 'Installing'
    }

    # Initialize progress tracking (elapsed timer only for uninstalls)
    $script:installStartTime = [datetime]::Now
    $script:progressMode     = 'timer'
    $script:installExpectedBytes = 0
    $script:installAction    = 'Uninstalling'
    if ($script:progressFile -and (Test-Path $script:progressFile)) {
        Remove-Item $script:progressFile -Force -ErrorAction SilentlyContinue
    }
    $script:progressFile = $null

    $txtStatus.Text = "Uninstalling: $($appDef.displayName)..."
    $inst = $appDef.install
    Write-LabLog -Event 'uninstall.start' -Data @{
        appId = $AppId
        name = $appDef.displayName
        method = $inst.method
        sourceSub = $inst.sourceSub
        id = $inst.id
    }

    # Same launch guard as installs: a missing launcher or access-denied must
    # not crash the click handler.
    try {
    switch ($inst.method) {
        'winget' {
            # E61 preflight (same as install): fail with a clear code if absent
            if (-not (Get-Command winget -ErrorAction SilentlyContinue)) {
                Write-LabLog -Event 'uninstall.winget_missing' -Data @{ errorCode = 'E61'; appId = $AppId }
                $txtStatus.Text = "[E61] winget is not installed on this machine - cannot uninstall $($appDef.displayName)"
                Reset-AppCardState -AppId $AppId -ErrorDetail '[E61] winget (App Installer) missing on this PC'
                return
            }
            $launchFile = 'winget'
            $launchArgs = "uninstall --id $($inst.id) --silent"
            $what = "Windows Package Manager (winget) will remove this package:`n`n    $($inst.id)"
            if (-not (Confirm-CommandPreview -DisplayName $appDef.displayName -Verb 'Uninstall' -WhatHappens $what -ExactProgram $launchFile -ExactArguments $launchArgs -AlwaysShow)) {
                Write-LabLog -Event 'uninstall.preview_declined' -Data @{ appId = $AppId; method = $inst.method; command = "$launchFile $launchArgs" }
                $txtStatus.Text = "$($appDef.displayName): uninstall cancelled at command preview"
                Reset-AppCardState -AppId $AppId
                return
            }
            $script:installProcess = Start-Process -FilePath $launchFile -ArgumentList $launchArgs -PassThru -WindowStyle Hidden
            Write-LabLog -Event 'uninstall.process_started' -Data @{
                appId = $AppId
                method = $inst.method
                filePath = $launchFile
                arguments = $launchArgs
                pid = $script:installProcess.Id
            }
        }
        'copy' {
            $dst = $inst.destination
            if (-not (Test-Path $dst)) {
                Write-LabLog -Event 'uninstall.destination_missing' -Data @{ errorCode = 'E41'; appId = $AppId; method = $inst.method; destination = $dst }
                $txtStatus.Text = "[E41] Folder not found: $dst"
                Reset-AppCardState -AppId $AppId -ErrorDetail "[E41] Folder not found: $dst"
                return
            }
            $launchFile = 'powershell.exe'
            $launchArgs = "-NoProfile -Command `"Remove-Item -Path '$dst' -Recurse -Force`""
            # Destructive: spell out that this permanently deletes the folder
            $what = "This will DELETE the folder (permanent):`n`n    $dst"
            if (-not (Confirm-CommandPreview -DisplayName $appDef.displayName -Verb 'Uninstall' -WhatHappens $what -ExactProgram $launchFile -ExactArguments $launchArgs -AlwaysShow)) {
                Write-LabLog -Event 'uninstall.preview_declined' -Data @{ appId = $AppId; method = $inst.method; destination = $dst }
                $txtStatus.Text = "$($appDef.displayName): uninstall cancelled at command preview"
                Reset-AppCardState -AppId $AppId
                return
            }
            $script:installProcess = Start-Process -FilePath $launchFile -ArgumentList $launchArgs -PassThru -WindowStyle Hidden
            Write-LabLog -Event 'uninstall.process_started' -Data @{
                appId = $AppId
                method = $inst.method
                filePath = $launchFile
                arguments = $launchArgs
                destination = $dst
                pid = $script:installProcess.Id
            }
        }
        'msi' {
            $msiPath = Join-Path $script:SourceRoot $inst.sourceSub
            $launchFile = 'msiexec.exe'
            $launchArgs = "/x `"$msiPath`" /qn /norestart"
            $what = "Windows Installer (msiexec) will UNINSTALL using this file:`n`n    $msiPath"
            if (-not (Confirm-CommandPreview -DisplayName $appDef.displayName -Verb 'Uninstall' -WhatHappens $what -ExactProgram $launchFile -ExactArguments $launchArgs -AlwaysShow)) {
                Write-LabLog -Event 'uninstall.preview_declined' -Data @{ appId = $AppId; method = $inst.method; msi = $msiPath }
                $txtStatus.Text = "$($appDef.displayName): uninstall cancelled at command preview"
                Reset-AppCardState -AppId $AppId
                return
            }
            $script:installProcess = Start-Process -FilePath $launchFile -ArgumentList $launchArgs -PassThru -WindowStyle Hidden
            Write-LabLog -Event 'uninstall.process_started' -Data @{
                appId = $AppId
                method = $inst.method
                filePath = $launchFile
                arguments = $launchArgs
                msi = $msiPath
                pid = $script:installProcess.Id
            }
        }
        'msix' {
            # Machine-wide MSIX: remove provisioning (stops future users getting
            # it) AND remove it from users who already have it. Wrapped in a
            # tracked powershell.exe so the process/exit-code model still holds.
            $pkgName = $appDef.detect.packageName
            if (-not $pkgName) {
                Write-LabLog -Event 'uninstall.msix_no_packagename' -Data @{ errorCode = 'E48'; appId = $AppId }
                $txtStatus.Text = "[E48] No packageName configured for $($appDef.displayName)"
                Reset-AppCardState -AppId $AppId
                return
            }
            $inner = "`$m=Get-AppxProvisionedPackage -Online | Where-Object {`$_.DisplayName -like '*$pkgName*' -or `$_.PackageName -like '*$pkgName*'} | Select-Object -First 1; if(`$m){Remove-AppxProvisionedPackage -Online -PackageName `$m.PackageName -ErrorAction Stop}; Get-AppxPackage -AllUsers -Name '$pkgName' | Remove-AppxPackage -AllUsers -ErrorAction SilentlyContinue"
            $launchFile = 'powershell.exe'
            $launchArgs = "-NoProfile -ExecutionPolicy Bypass -Command `"$inner`""
            $what = "Remove this MSIX for ALL users of this PC:`n`n    $pkgName"
            if (-not (Confirm-CommandPreview -DisplayName $appDef.displayName -Verb 'Uninstall' -WhatHappens $what -ExactProgram $launchFile -ExactArguments $launchArgs -AlwaysShow)) {
                Write-LabLog -Event 'uninstall.preview_declined' -Data @{ appId = $AppId; method = $inst.method; packageName = $pkgName }
                $txtStatus.Text = "$($appDef.displayName): uninstall cancelled at command preview"
                Reset-AppCardState -AppId $AppId
                return
            }
            $script:installProcess = Start-Process -FilePath $launchFile -ArgumentList $launchArgs -PassThru -WindowStyle Hidden
            Write-LabLog -Event 'uninstall.process_started' -Data @{
                appId = $AppId
                method = $inst.method
                filePath = $launchFile
                arguments = $launchArgs
                packageName = $pkgName
                pid = $script:installProcess.Id
            }
        }
        default {
            # Find the app's uninstall entry in the registry.
            # Match the full display name first. Fall back to requiring EVERY
            # word to appear -- matching on any single word hits unrelated
            # products (e.g. "Visual" matches VC++ Redistributables).
            $regPaths = @(
                'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*'
                'HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*'
            )
            $entries = @(foreach ($rp in $regPaths) {
                Get-ItemProperty -Path $rp -ErrorAction SilentlyContinue |
                    Where-Object { $_.DisplayName -and $_.UninstallString }
            })

            # Pick the BEST candidate, not merely the first one the registry
            # happened to return. Products that register many entries (Python
            # registers ~8: launcher, core, tcl/tk, pip, docs...) used to get an
            # arbitrary component removed, leaving a half-installed product.
            # Ranking, strongest signal first:
            #   1. InstallLocation matches where detection actually found the app
            #   2. DisplayName equals the card name exactly
            #   3. biggest EstimatedSize (the main product, not a sub-component)
            $detected = $script:DetectionCache[$AppId]
            $installDir = $null
            try { $installDir = Get-AppInstallDir -AppId $AppId } catch { }
            function Get-EntryScore {
                param($E)
                $score = 0
                $dn = "$($E.DisplayName)"
                if ($dn -eq $appDef.displayName) { $score += 1000 }
                elseif ($dn -like "$($appDef.displayName)*") { $score += 400 }
                if ($installDir -and $E.InstallLocation) {
                    $il = "$($E.InstallLocation)".Trim().TrimEnd('\')
                    $idn = $installDir.TrimEnd('\')
                    # An EXACT location match beats a parent-folder match. Several
                    # entries can share one InstallLocation (a suite and its
                    # components); the one whose location IS the app's own folder
                    # is the product, the others are pieces of it.
                    if ($il -eq $idn)            { $score += 2500 }
                    elseif ($idn -like "$il\*")  { $score += 1800 }
                    elseif ($il  -like "$idn\*") { $score += 1500 }
                }
                # Word overlap with the card name. Decisive when several entries
                # share one InstallLocation (C:\Xilinx has DocNav + Vivado ML +
                # Information Center; C:\Program Files\Autodesk has four): the
                # entry sharing more words with what we're removing is the one.
                foreach ($w in @($appDef.displayName -split '\s+' | Where-Object { $_.Length -ge 3 })) {
                    if ($dn -match [regex]::Escape($w)) { $score += 150 }
                }
                if ($E.EstimatedSize) { $score += [math]::Min(300, [int]([double]$E.EstimatedSize / 1024)) }
                # de-prioritise sub-components, helpers and vendor plumbing -
                # uninstalling one of these leaves the real product half-broken.
                # (Real example on the bench: the plain first-match picked
                # "Windows Driver Package - KEIL ..." instead of Keil uVision.)
                if ($dn -match '(?i)\b(update|updater|launcher|runtime|redistributable|documentation|test suite|add-?on|driver|driver package|sdk|setup|configuration|wmi provider|bootstrap|standard library|core interpreter|development libraries|utility scripts|add to path)\b') { $score -= 800 }
                # the base product almost always has the SHORTEST name among
                # matches ("Keil uVision4" vs "Windows Driver Package - KEIL...")
                $score -= [math]::Min(200, $dn.Length * 2)
                return $score
            }
            $cands = @($entries | Where-Object { $_.DisplayName -match [regex]::Escape($appDef.displayName) })
            if ($cands.Count -eq 0) {
                $words = @($appDef.displayName -split '\s+' | Where-Object { $_.Length -ge 3 })
                if ($words.Count -gt 0) {
                    $cands = @($entries | Where-Object {
                        $dn = $_.DisplayName
                        $all = $true
                        foreach ($w in $words) { if ($dn -notmatch [regex]::Escape($w)) { $all = $false; break } }
                        $all
                    })
                }
            }
            if ($cands.Count -eq 0 -and $installDir) {
                # LAST RESORT: match on WHERE IT IS, not what it's called. Vendors
                # routinely register a name unrelated to ours - "Rockwell CCW"
                # registers as "Connected Components Workbench", "Digilent
                # WaveForms" as "Digilent Software", "ADInstruments LabChart" as
                # "LabChart 8". Name matching alone sent all of those to the
                # manual Programs-and-Features handoff. The install directory we
                # already detected is a far more reliable identifier.
                $idNorm = $installDir.TrimEnd('\')
                $cands = @($entries | Where-Object {
                    $il = "$($_.InstallLocation)".Trim().TrimEnd('\')
                    $il -and ($il -eq $idNorm -or $idNorm -like "$il\*" -or $il -like "$idNorm\*")
                })
                if ($cands.Count) {
                    Write-LabLog -Event 'uninstall.matched_by_location' -Data @{
                        appId = $AppId; installDir = $installDir
                        matched = (@($cands | ForEach-Object { "$($_.DisplayName)" }) -join ' | ')
                    }
                }
            }
            $entry = $null
            if ($cands.Count -eq 1) {
                $entry = $cands[0]
            } elseif ($cands.Count -gt 1) {
                $ranked = @($cands | Sort-Object -Property @{ Expression = { Get-EntryScore $_ } } -Descending)
                $exact = @($cands | Where-Object { "$($_.DisplayName)" -eq $appDef.displayName })
                # REFUSE TO GUESS on component-style products. Python registers
                # ~10 entries (Core Interpreter, Tcl/Tk, pip Bootstrap, Add to
                # Path...) and NONE of them removes the product - whichever we
                # picked would leave a half-installed Python behind. When there
                # are many candidates and none is an exact name match, hand off
                # to Programs & Features instead of silently doing damage.
                if ($exact.Count -eq 0 -and $cands.Count -ge 4 -and -not $installDir) {
                    Write-LabLog -Event 'uninstall.ambiguous_entries' -Data @{
                        appId = $AppId; candidates = $cands.Count
                        names = (@($ranked | ForEach-Object { "$($_.DisplayName)" }) -join ' | ')
                    }
                    $entry = $null   # falls through to the E42 manual-uninstall handoff
                } else {
                    $entry = $ranked[0]
                    Write-LabLog -Event 'uninstall.multiple_entries' -Data @{
                        appId = $AppId; candidates = $cands.Count
                        chosen = "$($entry.DisplayName)"; chosenLocation = "$($entry.InstallLocation)"
                        others = (@($ranked | Select-Object -Skip 1 | ForEach-Object { "$($_.DisplayName)" }) -join ' | ')
                    }
                }
            }

            if (-not $entry) {
                Write-LabLog -Event 'uninstall.no_uninstaller' -Data @{ errorCode = 'E42'; appId = $AppId; method = $inst.method; name = $appDef.displayName }
                [System.Windows.MessageBox]::Show(
                    "[E42] Could not find an automatic uninstaller for $($appDef.displayName).`n`nOpening Programs & Features so you can remove it manually.",
                    'Manual Uninstall (E42)', 'OK', 'Information')
                Start-Process 'appwiz.cpl'
                Reset-AppCardState -AppId $AppId
                return
            }

            # Prefer QuietUninstallString -- it already carries the right silent switches
            $uninstallCmd = if ($entry.QuietUninstallString) { $entry.QuietUninstallString } else { $entry.UninstallString }

            $uninstallExe  = $null
            $uninstallArgs = ''
            if ($uninstallCmd -match '(?i)msiexec') {
                # MSI: rebuild the command from the product code. Running the raw
                # string would fail (quoted exe + args parsed as one path) or
                # trigger a repair instead of an uninstall.
                if ($uninstallCmd -match '(\{[0-9A-Fa-f\-]{36}\})') {
                    $uninstallExe  = 'msiexec.exe'
                    $uninstallArgs = "/x $($Matches[1]) /qn /norestart"
                }
            }
            if (-not $uninstallExe) {
                # Split into exe + its own arguments.
                if ($uninstallCmd -match '^\s*"([^"]+)"\s*(.*)$') {
                    # quoted exe - unambiguous
                    $uninstallExe = $Matches[1]; $uninstallArgs = $Matches[2]
                } else {
                    # UNQUOTED. Splitting at the first space breaks every path
                    # with a space in it (C:\Program Files\App\unins000.exe /x
                    # became exe='C:\Program' -> bogus E43 on a perfectly good
                    # uninstaller). Walk the tokens and keep the LONGEST leading
                    # run that is a real file on disk; the rest are arguments.
                    $raw = "$uninstallCmd".Trim()
                    $tok = $raw -split '\s+'
                    for ($i = $tok.Count; $i -ge 1; $i--) {
                        $cand = ($tok[0..($i-1)] -join ' ')
                        if (Test-Path $cand -PathType Leaf -ErrorAction SilentlyContinue) {
                            $uninstallExe  = $cand
                            $uninstallArgs = if ($i -lt $tok.Count) { ($tok[$i..($tok.Count-1)] -join ' ') } else { '' }
                            break
                        }
                    }
                    if (-not $uninstallExe -and $raw -match '^\s*(\S+)\s*(.*)$') {
                        # nothing on disk matched - fall back to the old split so
                        # the E43 handler still reports something meaningful
                        $uninstallExe = $Matches[1]; $uninstallArgs = $Matches[2]
                    }
                }
                # Generic silent switches are only safe on uninstallers that
                # UNDERSTAND them. Appending /S to a plain MSI-style or custom
                # uninstaller made it show a dialog we then hid (WindowStyle
                # Hidden) - it sat there invisibly forever. Only add them for
                # the bootstrapper families that document these switches, and
                # only when the registry didn't already give us a quiet string.
                if (-not $entry.QuietUninstallString -and $uninstallExe) {
                    $leaf = try { Split-Path $uninstallExe -Leaf } catch { '' }
                    $knownSilent = ($leaf -match '(?i)^(unins\d*|uninstall|uninst|setup)\.exe$') -or
                                   ($uninstallArgs -match '(?i)/uninstall|--uninstall|/x')
                    if ($knownSilent) {
                        $uninstallArgs = ("$uninstallArgs /S /VERYSILENT /NORESTART").Trim()
                    } else {
                        Write-LabLog -Event 'uninstall.no_silent_switches' -Data @{
                            appId = $AppId; exe = $uninstallExe
                            reason = 'unrecognised uninstaller - running it as registered so it cannot hang invisibly'
                        }
                    }
                }
            }

            if (-not $uninstallExe -or ($uninstallExe -ne 'msiexec.exe' -and -not (Test-Path $uninstallExe -PathType Leaf))) {
                Write-LabLog -Event 'uninstall.bad_uninstall_string' -Data @{ errorCode = 'E43'; appId = $AppId; command = $uninstallCmd; parsedExe = $uninstallExe }
                $txtStatus.Text = "[E43] Uninstall string could not be run: $uninstallCmd"
                Reset-AppCardState -AppId $AppId -ErrorDetail '[E43] Uninstaller path invalid - remove via Programs & Features'
                Start-Process 'appwiz.cpl'
                return
            }

            # Preview the ACTUAL parsed command (found via registry match), not
            # the raw registry string -- this is exactly what will run.
            $what = "Run the uninstaller registered by this installed program:`n`n    $($entry.DisplayName)`n`n(found in the Windows uninstall registry)"
            if (-not (Confirm-CommandPreview -DisplayName $appDef.displayName -Verb 'Uninstall' -WhatHappens $what -ExactProgram $uninstallExe -ExactArguments $uninstallArgs -AlwaysShow)) {
                Write-LabLog -Event 'uninstall.preview_declined' -Data @{ appId = $AppId; method = $inst.method; entryName = $entry.DisplayName; command = "$uninstallExe $uninstallArgs" }
                $txtStatus.Text = "$($appDef.displayName): uninstall cancelled at command preview"
                Reset-AppCardState -AppId $AppId
                return
            }

            $txtStatus.Text = "Launching uninstaller for $($appDef.displayName)..."
            try {
                if ($uninstallArgs) {
                    $script:installProcess = Start-Process -FilePath $uninstallExe `
                        -ArgumentList $uninstallArgs -PassThru -WindowStyle Hidden
                } else {
                    $script:installProcess = Start-Process -FilePath $uninstallExe -PassThru -WindowStyle Hidden
                }
            } catch {
                Write-LabLog -Event 'uninstall.launch_failed' -Data @{ errorCode = 'E44'; appId = $AppId; exe = $uninstallExe; arguments = $uninstallArgs; error = $_.Exception.Message }
                $txtStatus.Text = "[E44] Failed to launch uninstaller: $($_.Exception.Message)"
                Reset-AppCardState -AppId $AppId -ErrorDetail '[E44] Uninstaller failed to launch'
                return
            }
            Write-LabLog -Event 'uninstall.process_started' -Data @{
                appId = $AppId
                method = $inst.method
                filePath = $uninstallExe
                arguments = $uninstallArgs
                registryEntry = $entry.DisplayName
                registryUninstallString = $uninstallCmd
                pid = $script:installProcess.Id
            }
        }
    }
    } catch {
        Write-LabLog -Event 'uninstall.launch_exception' -Data @{ errorCode = 'E44'; appId = $AppId; method = $inst.method; error = $_.Exception.Message }
        $txtStatus.Text = "[E44] Could not start uninstall of $($appDef.displayName): $($_.Exception.Message)"
        Reset-AppCardState -AppId $AppId -ErrorDetail "[E44] Could not start: $($_.Exception.Message)"
        return
    }

    $script:installAppId = $AppId
    $script:installTimer.Start()
}

# ============================================================
#  XAML  (Dark Mode)
# ============================================================
[xml]$xaml = @'
<Window
    xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
    xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
    Title="LabLifter"
    Width="920" Height="745"
    MinWidth="640" MinHeight="400"
    WindowStartupLocation="Manual"
    Background="#1e1e2e"
    FontFamily="Segoe UI"
    UseLayoutRounding="True"
    TextOptions.TextFormattingMode="Display"
    TextOptions.TextRenderingMode="ClearType">

    <Window.Resources>
        <!-- Header plate accent (Blake, 2026-07-31): #2E4EED drives the spine,
             the titlebar tint, the decode line, Refresh All, and the active-tab
             underline. Declared FIRST: templates above resolve StaticResource
             forward references lazily, but XamlReader's deferred dictionaries
             do not - a later declaration means a crash at first render. -->
        <SolidColorBrush x:Key="AccentBrush" Color="#2E4EED"/>

        <!-- ============================================================
             Button colours - DesignerUp jewel/neutral system (Blake, 2026-07-30)
             ============================================================
             Two bands only, defined in HSB (every brush carries its HSB so the
             band is auditable):
               JEWEL    S 73-83, B 56-76   active, draws attention
               NEUTRAL  S 1-10,  B 70-99   passive, recedes
             Decision order: writes state -> jewel (max ONE per view);
             destructive -> red jewel, never rightmost; reads/prepares ->
             neutral fill + dark text; navigates/dismisses -> ghost outline.
             Irreversibility ~ saturation.
             Interaction states derive by B ONLY: hover +6, pressed -8; H and S
             never move. Disabled swaps category entirely, never dims a jewel.
             Status colours share the jewel S/B band - lock S/B, vary hue.
             NOTE: the spec says App.xaml/Application.Resources; this is a
             single-file XamlReader app, so Window.Resources IS that scope.
             Previous (muted) values for a straight revert:
               BtnPrimary #107C10, BtnAccent #0078D4, BtnBlue #1F4A6E,
               BtnPurple #4A2E6E, BtnNeutral #50505A, BtnDanger #8B2E2E,
               BtnStateOn #145A2E, BtnStateOff #555555. -->
        <!-- Primary re-anchored to the header accent #2E4EED (Blake, 2026-07-31)
             so Install All Missing, Refresh All, and the progress fills all
             speak ONE blue, exactly like the HTML mockups. -->
        <SolidColorBrush x:Key="BrushPrimary"        Color="#2E4EED"/>
        <SolidColorBrush x:Key="BrushPrimaryHover"   Color="#4667FF"/>
        <SolidColorBrush x:Key="BrushPrimaryPressed" Color="#2843D6"/>
        <SolidColorBrush x:Key="BrushDanger"         Color="#A32C24"/> <!-- H4 S78 B64 red jewel -->
        <SolidColorBrush x:Key="BrushDangerHover"    Color="#B23127"/> <!-- B70 (+6) -->
        <SolidColorBrush x:Key="BrushDangerPressed"  Color="#8F271F"/> <!-- B56 (-8) -->
        <SolidColorBrush x:Key="BrushSuccess"        Color="#269E58"/> <!-- H145 S76 B62 status -->
        <SolidColorBrush x:Key="BrushWarning"        Color="#B88725"/> <!-- H40 S80 B72 status -->
        <SolidColorBrush x:Key="BrushNeutralBg"      Color="#DDE2EB"/> <!-- H215 S6 B92 secondary fill -->
        <SolidColorBrush x:Key="BrushNeutralHover"   Color="#EBF1FA"/> <!-- B98 (+6) -->
        <SolidColorBrush x:Key="BrushNeutralPressed" Color="#C9CFD6"/> <!-- B84 (-8) -->
        <SolidColorBrush x:Key="BrushNeutralBorder"  Color="#C0C5CC"/> <!-- H215 S6 B80 ghost border -->
        <SolidColorBrush x:Key="BrushGhostHoverBg"   Color="#E4E9F0"/> <!-- H215 S5 B94 ghost hover fill -->
        <SolidColorBrush x:Key="BrushTextOnJewel"    Color="#FFFFFF"/>
        <SolidColorBrush x:Key="BrushTextOnNeutral"  Color="#292D33"/> <!-- H215 S20 B20 -->
        <SolidColorBrush x:Key="BrushTextGhost"      Color="#E0E0E0"/> <!-- app body text -->
        <SolidColorBrush x:Key="BrushDisabledBg"     Color="#DADCE0"/> <!-- H215 S3 B88 -->
        <SolidColorBrush x:Key="BrushDisabledText"   Color="#949699"/> <!-- B60 -->
        <SolidColorBrush x:Key="BrushFocusRing"      Color="#82A6D9"/> <!-- primary at S40 B85 -->

        <!-- Exception 1: elevation via SHADOW, never gradient. One tier only -
             the top-level panels get this, the app cards INSIDE the shadowed
             list panel do not (stacked tiers, and a per-card bitmap effect on
             a scrolling list is a real perf cost - see Invoke-UiDoEvents
             history). Shadow colour is the neutral hue driven dark (H215 S40
             B12), not pure black. -->
        <DropShadowEffect x:Key="PanelShadow" Color="#12171F" Opacity="0.15" BlurRadius="14" ShadowDepth="2" Direction="270"/>
        <!-- Exception 2: the ONE gradient in the app, on progress fills only -
             same jewel hue, B 66 -> 74 along the fill direction. Anything else
             wanting a gradient is decoration and doesn't get one. -->
        <LinearGradientBrush x:Key="BrushProgressFill" StartPoint="0,0" EndPoint="1,0">
            <GradientStop Color="#2E4EED" Offset="0"/> <!-- header accent -->
            <GradientStop Color="#4667FF" Offset="1"/> <!-- its hover shade -->
        </LinearGradientBrush>

        <!-- The three category styles. Focus = 2px ring (border appears on
             keyboard focus only, so mouse work sees no size shift worth
             caring about). Disabled swaps to the disabled pair via triggers -
             never opacity, never an in-place desaturation.
             HOVER IS ANIMATED, 130ms ColorAnimation, not an instant swap. Two
             mechanics that follow from it: the rest fill is a LOCAL brush
             declared inside each template (a {StaticResource} brush arrives
             frozen and a frozen brush cannot be animated), and pressed stays
             an instant Setter on purpose - a press should feel immediate,
             only the glide in/out of hover is eased. Exit animation has no To,
             so it eases back to the declared rest colour. -->
        <Style x:Key="PrimaryButton" TargetType="Button">
            <Setter Property="Foreground" Value="{StaticResource BrushTextOnJewel}"/>
            <Setter Property="Background" Value="{StaticResource BrushPrimary}"/>
            <Setter Property="Cursor" Value="Hand"/>
            <Setter Property="FontSize" Value="13"/>
            <Setter Property="FontWeight" Value="SemiBold"/>
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="Button">
                        <Border x:Name="bd"
                                BorderBrush="Transparent" BorderThickness="0"
                                CornerRadius="4" Padding="{TemplateBinding Padding}">
                            <Border.Background>
                                <SolidColorBrush Color="#2E4EED"/> <!-- rest: BrushPrimary / header accent -->
                            </Border.Background>
                            <ContentPresenter x:Name="cp" HorizontalAlignment="Center" VerticalAlignment="Center"/>
                        </Border>
                        <ControlTemplate.Triggers>
                            <Trigger Property="IsMouseOver" Value="True">
                                <Trigger.EnterActions>
                                    <BeginStoryboard>
                                        <Storyboard>
                                            <ColorAnimation Storyboard.TargetName="bd"
                                                            Storyboard.TargetProperty="(Border.Background).(SolidColorBrush.Color)"
                                                            To="#4667FF" Duration="0:0:0.13"/>
                                        </Storyboard>
                                    </BeginStoryboard>
                                </Trigger.EnterActions>
                                <Trigger.ExitActions>
                                    <BeginStoryboard>
                                        <Storyboard>
                                            <ColorAnimation Storyboard.TargetName="bd"
                                                            Storyboard.TargetProperty="(Border.Background).(SolidColorBrush.Color)"
                                                            Duration="0:0:0.13"/>
                                        </Storyboard>
                                    </BeginStoryboard>
                                </Trigger.ExitActions>
                            </Trigger>
                            <Trigger Property="IsPressed" Value="True">
                                <Setter TargetName="bd" Property="Background" Value="{StaticResource BrushPrimaryPressed}"/>
                            </Trigger>
                            <Trigger Property="IsKeyboardFocused" Value="True">
                                <Setter TargetName="bd" Property="BorderThickness" Value="2"/>
                                <Setter TargetName="bd" Property="BorderBrush" Value="{StaticResource BrushFocusRing}"/>
                            </Trigger>
                            <Trigger Property="IsEnabled" Value="False">
                                <Setter TargetName="bd" Property="Background" Value="{StaticResource BrushDisabledBg}"/>
                                <Setter TargetName="cp" Property="TextElement.Foreground" Value="{StaticResource BrushDisabledText}"/>
                            </Trigger>
                        </ControlTemplate.Triggers>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>

        <!-- Spec wants danger to BE PrimaryButton with the brushes swapped.
             XAML cannot swap a trigger's brush from outside the template, so
             this is that swap written out - same template, danger tokens. -->
        <Style x:Key="DangerButton" TargetType="Button">
            <Setter Property="Foreground" Value="{StaticResource BrushTextOnJewel}"/>
            <Setter Property="Background" Value="{StaticResource BrushDanger}"/>
            <Setter Property="Cursor" Value="Hand"/>
            <Setter Property="FontSize" Value="13"/>
            <Setter Property="FontWeight" Value="SemiBold"/>
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="Button">
                        <Border x:Name="bd"
                                BorderBrush="Transparent" BorderThickness="0"
                                CornerRadius="4" Padding="{TemplateBinding Padding}">
                            <Border.Background>
                                <SolidColorBrush Color="#A32C24"/> <!-- rest: BrushDanger -->
                            </Border.Background>
                            <ContentPresenter x:Name="cp" HorizontalAlignment="Center" VerticalAlignment="Center"/>
                        </Border>
                        <ControlTemplate.Triggers>
                            <Trigger Property="IsMouseOver" Value="True">
                                <Trigger.EnterActions>
                                    <BeginStoryboard>
                                        <Storyboard>
                                            <ColorAnimation Storyboard.TargetName="bd"
                                                            Storyboard.TargetProperty="(Border.Background).(SolidColorBrush.Color)"
                                                            To="#B23127" Duration="0:0:0.13"/>
                                        </Storyboard>
                                    </BeginStoryboard>
                                </Trigger.EnterActions>
                                <Trigger.ExitActions>
                                    <BeginStoryboard>
                                        <Storyboard>
                                            <ColorAnimation Storyboard.TargetName="bd"
                                                            Storyboard.TargetProperty="(Border.Background).(SolidColorBrush.Color)"
                                                            Duration="0:0:0.13"/>
                                        </Storyboard>
                                    </BeginStoryboard>
                                </Trigger.ExitActions>
                            </Trigger>
                            <Trigger Property="IsPressed" Value="True">
                                <Setter TargetName="bd" Property="Background" Value="{StaticResource BrushDangerPressed}"/>
                            </Trigger>
                            <Trigger Property="IsKeyboardFocused" Value="True">
                                <Setter TargetName="bd" Property="BorderThickness" Value="2"/>
                                <Setter TargetName="bd" Property="BorderBrush" Value="{StaticResource BrushFocusRing}"/>
                            </Trigger>
                            <Trigger Property="IsEnabled" Value="False">
                                <Setter TargetName="bd" Property="Background" Value="{StaticResource BrushDisabledBg}"/>
                                <Setter TargetName="cp" Property="TextElement.Foreground" Value="{StaticResource BrushDisabledText}"/>
                            </Trigger>
                        </ControlTemplate.Triggers>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>

        <!-- Quiet DARK secondary (Blake, 2026-07-31), matching the mockups'
             chrome: #2A2A33 fill, hairline border, light text - replaces the
             light chips that fought the dark plates. Same 130ms hover ease. -->
        <Style x:Key="SecondaryButton" TargetType="Button">
            <Setter Property="Foreground" Value="#E0E0E0"/>
            <Setter Property="Background" Value="#2A2A33"/>
            <Setter Property="Cursor" Value="Hand"/>
            <Setter Property="FontSize" Value="13"/>
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="Button">
                        <Border x:Name="bd"
                                BorderBrush="#3A3A44" BorderThickness="1"
                                CornerRadius="4" Padding="{TemplateBinding Padding}">
                            <Border.Background>
                                <SolidColorBrush Color="#2A2A33"/> <!-- rest: quiet dark -->
                            </Border.Background>
                            <ContentPresenter x:Name="cp" HorizontalAlignment="Center" VerticalAlignment="Center"/>
                        </Border>
                        <ControlTemplate.Triggers>
                            <Trigger Property="IsMouseOver" Value="True">
                                <Trigger.EnterActions>
                                    <BeginStoryboard>
                                        <Storyboard>
                                            <ColorAnimation Storyboard.TargetName="bd"
                                                            Storyboard.TargetProperty="(Border.Background).(SolidColorBrush.Color)"
                                                            To="#33333D" Duration="0:0:0.13"/>
                                        </Storyboard>
                                    </BeginStoryboard>
                                </Trigger.EnterActions>
                                <Trigger.ExitActions>
                                    <BeginStoryboard>
                                        <Storyboard>
                                            <ColorAnimation Storyboard.TargetName="bd"
                                                            Storyboard.TargetProperty="(Border.Background).(SolidColorBrush.Color)"
                                                            Duration="0:0:0.13"/>
                                        </Storyboard>
                                    </BeginStoryboard>
                                </Trigger.ExitActions>
                            </Trigger>
                            <Trigger Property="IsPressed" Value="True">
                                <Setter TargetName="bd" Property="Background" Value="#26262C"/>
                            </Trigger>
                            <Trigger Property="IsKeyboardFocused" Value="True">
                                <Setter TargetName="bd" Property="BorderThickness" Value="2"/>
                                <Setter TargetName="bd" Property="BorderBrush" Value="{StaticResource BrushFocusRing}"/>
                            </Trigger>
                            <Trigger Property="IsEnabled" Value="False">
                                <Setter TargetName="bd" Property="Background" Value="#26262C"/>
                                <Setter TargetName="cp" Property="TextElement.Foreground" Value="#666A72"/>
                            </Trigger>
                        </ControlTemplate.Triggers>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>

        <!-- Navigate/dismiss. Zero fill = zero urgency. On hover it takes the
             light neutral fill, so its text must flip dark at the same time. -->
        <Style x:Key="GhostButton" TargetType="Button">
            <Setter Property="Foreground" Value="{StaticResource BrushTextGhost}"/>
            <Setter Property="Background" Value="Transparent"/>
            <Setter Property="Cursor" Value="Hand"/>
            <Setter Property="FontSize" Value="13"/>
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="Button">
                        <!-- Rest fill is the hover colour at alpha 0, so the
                             hover animation only moves alpha - hue never
                             shifts mid-glide. Text animates dark in the same
                             130ms, or it would flash dark-on-dark while the
                             fill is still translucent. -->
                        <Border x:Name="bd"
                                BorderBrush="{StaticResource BrushNeutralBorder}" BorderThickness="1"
                                CornerRadius="4" Padding="{TemplateBinding Padding}">
                            <Border.Background>
                                <SolidColorBrush Color="#00E4E9F0"/>
                            </Border.Background>
                            <ContentPresenter x:Name="cp" HorizontalAlignment="Center" VerticalAlignment="Center">
                                <TextElement.Foreground>
                                    <SolidColorBrush Color="#E0E0E0"/> <!-- rest: BrushTextGhost -->
                                </TextElement.Foreground>
                            </ContentPresenter>
                        </Border>
                        <ControlTemplate.Triggers>
                            <Trigger Property="IsMouseOver" Value="True">
                                <Trigger.EnterActions>
                                    <BeginStoryboard>
                                        <Storyboard>
                                            <ColorAnimation Storyboard.TargetName="bd"
                                                            Storyboard.TargetProperty="(Border.Background).(SolidColorBrush.Color)"
                                                            To="#E4E9F0" Duration="0:0:0.13"/>
                                            <ColorAnimation Storyboard.TargetName="cp"
                                                            Storyboard.TargetProperty="(TextElement.Foreground).(SolidColorBrush.Color)"
                                                            To="#292D33" Duration="0:0:0.13"/>
                                        </Storyboard>
                                    </BeginStoryboard>
                                </Trigger.EnterActions>
                                <Trigger.ExitActions>
                                    <BeginStoryboard>
                                        <Storyboard>
                                            <ColorAnimation Storyboard.TargetName="bd"
                                                            Storyboard.TargetProperty="(Border.Background).(SolidColorBrush.Color)"
                                                            Duration="0:0:0.13"/>
                                            <ColorAnimation Storyboard.TargetName="cp"
                                                            Storyboard.TargetProperty="(TextElement.Foreground).(SolidColorBrush.Color)"
                                                            Duration="0:0:0.13"/>
                                        </Storyboard>
                                    </BeginStoryboard>
                                </Trigger.ExitActions>
                            </Trigger>
                            <Trigger Property="IsPressed" Value="True">
                                <Setter TargetName="bd" Property="Background" Value="{StaticResource BrushNeutralPressed}"/>
                                <Setter TargetName="cp" Property="TextElement.Foreground" Value="{StaticResource BrushTextOnNeutral}"/>
                            </Trigger>
                            <Trigger Property="IsKeyboardFocused" Value="True">
                                <Setter TargetName="bd" Property="BorderThickness" Value="2"/>
                                <Setter TargetName="bd" Property="BorderBrush" Value="{StaticResource BrushFocusRing}"/>
                            </Trigger>
                            <Trigger Property="IsEnabled" Value="False">
                                <Setter TargetName="cp" Property="TextElement.Foreground" Value="{StaticResource BrushDisabledText}"/>
                            </Trigger>
                        </ControlTemplate.Triggers>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>

        <Style x:Key="FlatBtn" TargetType="Button">
            <Setter Property="Foreground" Value="White"/>
            <Setter Property="BorderThickness" Value="0"/>
            <Setter Property="Cursor" Value="Hand"/>
            <Setter Property="FontSize" Value="13"/>
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="Button">
                        <Border x:Name="bd" Background="{TemplateBinding Background}"
                                CornerRadius="4" Padding="{TemplateBinding Padding}">
                            <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center"/>
                        </Border>
                        <ControlTemplate.Triggers>
                            <Trigger Property="IsMouseOver" Value="True">
                                <Setter TargetName="bd" Property="Opacity" Value="0.85"/>
                            </Trigger>
                            <Trigger Property="IsPressed" Value="True">
                                <Setter TargetName="bd" Property="Opacity" Value="0.7"/>
                            </Trigger>
                            <Trigger Property="IsEnabled" Value="False">
                                <Setter TargetName="bd" Property="Opacity" Value="0.35"/>
                            </Trigger>
                        </ControlTemplate.Triggers>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>

        <!-- Indicator chip (Blake, 2026-07-31): the footer's Caffeine/winget
             readouts, restyled from green jewel-lookalike buttons into pill
             chips - same language as the health pill on the tab rail. The
             clickable Button stays (handlers keep their names); state is now
             shown by the inner Ellipse dot + TextBlock, which runtime swaps
             instead of repainting the whole button background. -->
        <Style x:Key="ChipBtn" TargetType="Button">
            <Setter Property="Cursor" Value="Hand"/>
            <Setter Property="Padding" Value="13,0"/>
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="Button">
                        <!-- Height 28 / radius 14 = the health pill's stadium
                             shape. NOT CornerRadius 999: WPF does not clamp an
                             oversized radius like CSS does and the ends render
                             as an oval lens. -->
                        <Border x:Name="bd" Background="#10FFFFFF" BorderBrush="#3A3A40" BorderThickness="1"
                                Height="28" CornerRadius="14" Padding="{TemplateBinding Padding}">
                            <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center"/>
                        </Border>
                        <ControlTemplate.Triggers>
                            <Trigger Property="IsMouseOver" Value="True">
                                <Setter TargetName="bd" Property="BorderBrush" Value="#4A4A56"/>
                                <Setter TargetName="bd" Property="Background" Value="#1AFFFFFF"/>
                            </Trigger>
                            <Trigger Property="IsPressed" Value="True">
                                <Setter TargetName="bd" Property="Opacity" Value="0.75"/>
                            </Trigger>
                            <Trigger Property="IsEnabled" Value="False">
                                <Setter TargetName="bd" Property="Opacity" Value="0.45"/>
                            </Trigger>
                        </ControlTemplate.Triggers>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>

        <!-- Card button: FlatBtn's chrome, but content is LEFT-aligned and
             stretched so a title + subtitle stack reads as a card, not a label. -->
        <Style x:Key="CardBtn" TargetType="Button">
            <Setter Property="BorderThickness" Value="0"/>
            <Setter Property="Cursor" Value="Hand"/>
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="Button">
                        <Border x:Name="bd" Background="{TemplateBinding Background}"
                                CornerRadius="6" Padding="{TemplateBinding Padding}">
                            <ContentPresenter HorizontalAlignment="Left" VerticalAlignment="Center"/>
                        </Border>
                        <ControlTemplate.Triggers>
                            <Trigger Property="IsMouseOver" Value="True">
                                <Setter TargetName="bd" Property="Opacity" Value="0.85"/>
                            </Trigger>
                            <Trigger Property="IsPressed" Value="True">
                                <Setter TargetName="bd" Property="Opacity" Value="0.7"/>
                            </Trigger>
                        </ControlTemplate.Triggers>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>

        <Style x:Key="SmallBtn" TargetType="Button">
            <Setter Property="Foreground" Value="White"/>
            <Setter Property="BorderThickness" Value="0"/>
            <Setter Property="Cursor" Value="Hand"/>
            <Setter Property="FontSize" Value="11"/>
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="Button">
                        <Border x:Name="bd" Background="{TemplateBinding Background}"
                                CornerRadius="3" Padding="{TemplateBinding Padding}">
                            <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center"/>
                        </Border>
                        <ControlTemplate.Triggers>
                            <Trigger Property="IsMouseOver" Value="True">
                                <Setter TargetName="bd" Property="Opacity" Value="0.8"/>
                            </Trigger>
                            <Trigger Property="IsEnabled" Value="False">
                                <Setter TargetName="bd" Property="Opacity" Value="0.3"/>
                            </Trigger>
                        </ControlTemplate.Triggers>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>

        <Style TargetType="ComboBox">
            <Setter Property="FontSize" Value="13"/>
            <Setter Property="Padding" Value="6,4"/>
        </Style>

        <!-- Underline tabs (Blake, 2026-07-31), matching the Rail mockups: no
             chip boxes - muted labels, faint hover wash, and a 3px accent bar
             under the active tab. 11px side padding keeps the master's 8 tabs +
             health pill + GP/CM sharing one row at 1180px. -->
        <Style TargetType="TabItem">
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="TabItem">
                        <Grid>
                            <Border x:Name="bd" Background="Transparent" CornerRadius="6,6,0,0" Padding="11,8,11,10" Margin="0,0,2,0">
                                <ContentPresenter ContentSource="Header" VerticalAlignment="Center"/>
                            </Border>
                            <Border x:Name="ul" Height="3" Background="{StaticResource AccentBrush}" CornerRadius="2,2,0,0"
                                    VerticalAlignment="Bottom" Margin="9,0,11,0" Visibility="Collapsed"/>
                        </Grid>
                        <ControlTemplate.Triggers>
                            <Trigger Property="IsMouseOver" Value="True">
                                <Setter TargetName="bd" Property="Background" Value="#0DFFFFFF"/>
                            </Trigger>
                            <Trigger Property="IsSelected" Value="True">
                                <Setter TargetName="ul" Property="Visibility" Value="Visible"/>
                            </Trigger>
                        </ControlTemplate.Triggers>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
            <Setter Property="Foreground" Value="#8a8a95"/>
            <Setter Property="FontSize" Value="13"/>
            <Setter Property="Cursor" Value="Hand"/>
            <Style.Triggers>
                <!-- hover first, selected second: a hovered ACTIVE tab must stay
                     white (later trigger wins for the same property) -->
                <Trigger Property="IsMouseOver" Value="True">
                    <Setter Property="Foreground" Value="#e0e0e0"/>
                </Trigger>
                <Trigger Property="IsSelected" Value="True">
                    <Setter Property="Foreground" Value="#FFFFFF"/>
                    <Setter Property="FontWeight" Value="SemiBold"/>
                </Trigger>
            </Style.Triggers>
        </Style>


        <!-- Quiet dark dropdown for the room profile. The stock ComboBox chip
             was a bright white slab that shouted louder than the hostname; this
             recedes into the #1e1e1e plate. Minimal template - toggle, selected
             text, dark popup list. -->
        <Style x:Key="RoomCombo" TargetType="ComboBox">
            <Setter Property="Foreground" Value="#e0e0e0"/>
            <Setter Property="FontSize" Value="13"/>
            <Setter Property="Height" Value="30"/>
            <Setter Property="ItemContainerStyle">
                <Setter.Value>
                    <Style TargetType="ComboBoxItem">
                        <Setter Property="Foreground" Value="#e0e0e0"/>
                        <Setter Property="Background" Value="Transparent"/>
                        <Setter Property="Padding" Value="10,6"/>
                        <Setter Property="Template">
                            <Setter.Value>
                                <ControlTemplate TargetType="ComboBoxItem">
                                    <Border x:Name="ib" Background="{TemplateBinding Background}" Padding="{TemplateBinding Padding}">
                                        <ContentPresenter/>
                                    </Border>
                                    <ControlTemplate.Triggers>
                                        <Trigger Property="IsHighlighted" Value="True">
                                            <Setter TargetName="ib" Property="Background" Value="#33333f"/>
                                        </Trigger>
                                    </ControlTemplate.Triggers>
                                </ControlTemplate>
                            </Setter.Value>
                        </Setter>
                    </Style>
                </Setter.Value>
            </Setter>
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="ComboBox">
                        <Grid>
                            <ToggleButton x:Name="tb" Focusable="False" ClickMode="Press"
                                          IsChecked="{Binding IsDropDownOpen, Mode=TwoWay, RelativeSource={RelativeSource TemplatedParent}}">
                                <ToggleButton.Template>
                                    <ControlTemplate TargetType="ToggleButton">
                                        <Border x:Name="bd" Background="#232330" BorderBrush="#3a3a44" BorderThickness="1" CornerRadius="5">
                                            <Path HorizontalAlignment="Right" VerticalAlignment="Center" Margin="0,0,11,0"
                                                  Data="M0,0 L4,4 L8,0 Z" Fill="#8a8a95"/>
                                        </Border>
                                        <ControlTemplate.Triggers>
                                            <Trigger Property="IsMouseOver" Value="True">
                                                <Setter TargetName="bd" Property="BorderBrush" Value="#4a4a56"/>
                                            </Trigger>
                                        </ControlTemplate.Triggers>
                                    </ControlTemplate>
                                </ToggleButton.Template>
                            </ToggleButton>
                            <ContentPresenter IsHitTestVisible="False" Content="{TemplateBinding SelectionBoxItem}"
                                              ContentTemplate="{TemplateBinding SelectionBoxItemTemplate}"
                                              Margin="12,0,28,0" VerticalAlignment="Center" HorizontalAlignment="Left"/>
                            <Popup x:Name="PART_Popup" Placement="Bottom" AllowsTransparency="True" Focusable="False"
                                   IsOpen="{TemplateBinding IsDropDownOpen}" PopupAnimation="Slide">
                                <Border Background="#232330" BorderBrush="#3a3a44" BorderThickness="1" CornerRadius="5"
                                        MinWidth="{Binding ActualWidth, RelativeSource={RelativeSource TemplatedParent}}"
                                        MaxHeight="320" Margin="0,2,0,4">
                                    <Border.Effect><DropShadowEffect BlurRadius="14" ShadowDepth="2" Opacity="0.4" Color="#12171F"/></Border.Effect>
                                    <ScrollViewer><StackPanel IsItemsHost="True"/></ScrollViewer>
                                </Border>
                            </Popup>
                        </Grid>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>

        <!-- ============================================================
             Scrollbars (Blake, 2026-08-02)
             ============================================================
             The default Windows scrollbar is light-grey chrome and reads as a
             foreign object on this dark UI. These are IMPLICIT styles (no
             x:Key), so every ScrollBar in every tab picks them up - the app
             list, the fleet map, the config lists, and the ComboBox dropdowns.
             Thin, no arrow buttons; the thumb IS the card grey (#232323, =
             BrushRowBg) so it reads as part of the cards, lifting to the card
             hairline #2C2C32 on hover/drag so it stays grabbable. Track is
             transparent - the panel behind shows through.
             Declared here (near the end of the dictionary) BEFORE the ScrollBar
             style that references them: XamlReader resolves StaticResource
             forward-refs lazily and a later declaration crashes at first render
             (see the AccentBrush note up top). ScrollThumb + ScrollPageButton
             first, ScrollBar last. -->
        <Style x:Key="ScrollThumb" TargetType="Thumb">
            <Setter Property="OverridesDefaultStyle" Value="True"/>
            <Setter Property="IsTabStop" Value="False"/>
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="Thumb">
                        <Border x:Name="tb" CornerRadius="3" Background="#232323" Margin="2"/>
                        <ControlTemplate.Triggers>
                            <Trigger Property="IsMouseOver" Value="True">
                                <Setter TargetName="tb" Property="Background" Value="#2C2C32"/>
                            </Trigger>
                            <Trigger Property="IsDragging" Value="True">
                                <Setter TargetName="tb" Property="Background" Value="#2C2C32"/>
                            </Trigger>
                        </ControlTemplate.Triggers>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>
        <Style x:Key="ScrollPageButton" TargetType="RepeatButton">
            <Setter Property="OverridesDefaultStyle" Value="True"/>
            <Setter Property="Background" Value="Transparent"/>
            <Setter Property="Focusable" Value="False"/>
            <Setter Property="IsTabStop" Value="False"/>
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="RepeatButton">
                        <Border Background="Transparent"/>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>
        <Style TargetType="ScrollBar">
            <Setter Property="Background" Value="Transparent"/>
            <Setter Property="Width" Value="10"/>
            <Setter Property="MinWidth" Value="10"/>
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="ScrollBar">
                        <Grid x:Name="root" Background="Transparent">
                            <Track x:Name="PART_Track" IsDirectionReversed="True">
                                <Track.DecreaseRepeatButton>
                                    <RepeatButton Style="{StaticResource ScrollPageButton}" Command="ScrollBar.PageUpCommand"/>
                                </Track.DecreaseRepeatButton>
                                <Track.Thumb>
                                    <Thumb Style="{StaticResource ScrollThumb}"/>
                                </Track.Thumb>
                                <Track.IncreaseRepeatButton>
                                    <RepeatButton Style="{StaticResource ScrollPageButton}" Command="ScrollBar.PageDownCommand"/>
                                </Track.IncreaseRepeatButton>
                            </Track>
                        </Grid>
                        <ControlTemplate.Triggers>
                            <Trigger Property="Orientation" Value="Horizontal">
                                <Setter Property="Width" Value="Auto"/>
                                <Setter Property="Height" Value="10"/>
                                <Setter Property="MinWidth" Value="0"/>
                                <Setter Property="MinHeight" Value="10"/>
                                <Setter TargetName="PART_Track" Property="IsDirectionReversed" Value="False"/>
                            </Trigger>
                        </ControlTemplate.Triggers>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>
    </Window.Resources>

    <Grid Margin="16">
        <Grid.RowDefinitions>
            <RowDefinition Height="Auto"/>
            <RowDefinition Height="Auto"/>
            <RowDefinition Height="*"/>
            <RowDefinition Height="Auto"/>
        </Grid.RowDefinitions>

        <!-- ============================================================
             Command Bar header  (Blake, 2026-07-31)
             ============================================================
             Design 3 "Command Bar" from the header-fusion mockups: the
             two-tier plate AND the tab rail fused into ONE card, two rows.
             Row 1: the brand demoted to an eyebrow over the hostname hero
             (the window titlebar already says "LabLifter"), decode
             inline beside it, Room Profile + Summary + Refresh All docked
             right on the #2E4EED tint. Row 2: an empty 36px rail whose top
             hairline replaces the old standalone tab underline Border - the
             REAL TabPanel (still owned by tabMain in Grid.Row 2) rides up
             over it via this card's -37px bottom margin (36 rail + 1 card
             border), so tab selection, master-tab collapsing and every handler
             are untouched. The pill + GP/CM overlay re-anchors into the
             rail's right side. Left edge keeps the 4px accent spine, now
             spanning command row AND rail. txtUser stays as a Collapsed
             target for its startup assignment. Row 1 of the outer grid is
             still unused (0px). -->
        <Border Grid.Row="0" Background="#1e1e1e" CornerRadius="5,14,14,5" Margin="0,0,0,-37"
                BorderBrush="#3e3e44" BorderThickness="1" Effect="{StaticResource PanelShadow}">
            <Grid>
                <Grid.ColumnDefinitions>
                    <ColumnDefinition Width="4"/>
                    <ColumnDefinition Width="*"/>
                </Grid.ColumnDefinitions>

                <!-- accent spine -->
                <Border Grid.Column="0" Background="{StaticResource AccentBrush}" CornerRadius="4,0,0,4"/>

                <Grid Grid.Column="1">
                    <Grid.RowDefinitions>
                        <RowDefinition Height="Auto"/>
                        <RowDefinition Height="36"/>
                    </Grid.RowDefinitions>

                    <!-- COMMAND ROW: eyebrow + hostname hero | room + summary + refresh -->
                    <Border Grid.Row="0" Padding="16,11,20,9">
                        <Border.Background>
                            <LinearGradientBrush StartPoint="0,0" EndPoint="1,0">
                                <GradientStop Color="#2E2E4EED" Offset="0"/>
                                <GradientStop Color="#002E4EED" Offset="0.7"/>
                            </LinearGradientBrush>
                        </Border.Background>
                        <DockPanel>
                            <Button Name="btnRefreshAll" DockPanel.Dock="Right" Content="Refresh All"
                                    VerticalAlignment="Center" Padding="16,7"
                                    Background="{StaticResource AccentBrush}" Style="{StaticResource FlatBtn}"/>
                            <Button Name="btnSyncCloud" DockPanel.Dock="Right" Content="Sync To Server"
                                    VerticalAlignment="Center" Padding="14,7" Margin="0,0,10,0"
                                    Background="#2F6F4F" Foreground="#FFFFFF" Style="{StaticResource FlatBtn}"
                                    ToolTip="Send this machine's results to the Cloudflare dashboard now. Always works - no room or scan needed."/>
                            <StackPanel DockPanel.Dock="Right" VerticalAlignment="Center" Margin="0,0,26,0">
                                <TextBlock Text="SUMMARY" FontSize="10" Foreground="#666" FontWeight="SemiBold"/>
                                <TextBlock Name="txtSummary" FontSize="14" FontWeight="SemiBold" Foreground="#e0e0e0" Text="--"
                                           Margin="0,7,0,0" TextTrimming="CharacterEllipsis"
                                           ToolTip="{Binding Text, RelativeSource={RelativeSource Self}}"/>
                            </StackPanel>
                            <StackPanel DockPanel.Dock="Right" Width="200" VerticalAlignment="Center" Margin="0,0,26,0">
                                <TextBlock Text="ROOM PROFILE" FontSize="10" Foreground="#666" FontWeight="SemiBold"/>
                                <ComboBox Name="cmbRoom" Margin="0,5,0,0" Style="{StaticResource RoomCombo}"/>
                            </StackPanel>
                            <StackPanel VerticalAlignment="Center">
                                <!-- eyebrow: WPF TextBlocks have no letter-spacing,
                                     so the mockup's tracked caps are approximated
                                     by size/weight/colour alone -->
                                <StackPanel Orientation="Horizontal">
                                    <TextBlock Text="LABLIFTER" FontSize="10.5" FontWeight="Bold"
                                               Foreground="#8a8a95" VerticalAlignment="Center"/>
                                    <TextBlock Name="txtAdminBadge" Text="ADMIN" FontSize="11" FontWeight="Bold"
                                               Foreground="#4EC749" VerticalAlignment="Center" Margin="10,0,0,0"/>
                                    <TextBlock Name="txtMasterBadge" Text="" FontSize="11" FontWeight="Bold" Visibility="Collapsed"
                                               Foreground="#B98CE8" VerticalAlignment="Center" Margin="7,0,0,0"
                                               ToolTip="This PC is the fleet master (C:\LabDeployMaster exists), so it gets the Deployment Tracker / Assign / Layout Designer / Config / Sticks / Add App tabs."/>
                                </StackPanel>
                                <StackPanel Orientation="Horizontal" Margin="0,3,0,0">
                                    <TextBlock Name="txtHostname" FontSize="22" FontWeight="Bold" Foreground="#e0e0e0"
                                               MaxWidth="520" TextTrimming="CharacterEllipsis"/>
                                    <!-- decoded campus id, e.g. "ENG 103 #20"; accent
                                         by default, code flips it amber when the name
                                         carries a flag. Bottom margin fakes baseline
                                         alignment with the 22px hostname. Hidden on
                                         machines that don't decode. -->
                                    <TextBlock Name="txtDecode" FontSize="12.5" FontWeight="SemiBold"
                                               Foreground="{StaticResource AccentBrush}" Visibility="Collapsed"
                                               VerticalAlignment="Bottom" Margin="14,0,0,3" TextTrimming="CharacterEllipsis"/>
                                </StackPanel>
                                <TextBlock Name="txtUser" Visibility="Collapsed"/>
                            </StackPanel>
                        </DockPanel>
                    </Border>

                    <!-- RAIL: deliberately empty - the live TabPanel and the
                         pill/GP/CM overlay render on top of this strip. Only
                         the top hairline is drawn here. -->
                    <Border Grid.Row="1" BorderBrush="#2C2C34" BorderThickness="0,1,0,0"/>
                </Grid>
            </Grid>
        </Border>

        <!-- ONE codebase, two faces (ROADMAP "Architecture decision"): a lab
             machine shows ONLY the Deploy tab and behaves exactly as it did
             before; the master PC (C:\LabDeployMaster exists) has the rest
             un-hidden at startup. Replaces the old separate Master window. -->
        <!-- the standalone hairline that lived here moved into the Command Bar
             card's rail row. Top padding 16 puts tab CONTENT clear of the
             card's 37px reach into this row (36 rail + 1 border) with a 14px
             gap: strip ~35 + 16 = 51 > 37 + 14. tabDeploy's left margin
             indents the first tab to the mockup's 20px text inset. -->
        <TabControl Grid.Row="2" Name="tabMain" Background="Transparent" BorderThickness="0" Padding="0,16,0,0" Margin="0,0,0,12">
        <TabItem Header="Deploy" Name="tabDeploy" Margin="9,0,0,0">
        <!-- Left margin 0 (Blake, 2026-08-02): aligns the app-list panel's left
             edge with the header/footer cards (all share the outer 16px grid),
             so the status spines and the accent spines form one line. -->
        <Grid Margin="0,2,2,2">
            <Grid.RowDefinitions>
                <RowDefinition Height="Auto"/>
                <RowDefinition Height="*"/>
                <RowDefinition Height="Auto"/>
            </Grid.RowDefinitions>

        <!-- The Machine Health strip that lived here (Blake, 2026-07-31) moved
             to the tab row: a compact health PILL (dots + issue count, click
             for the breakdown popover) rides the tab strip's empty right side
             together with the GP Update / Run CM Actions buttons. See the
             overlay panel right after </TabControl>. Row 0 is now empty. -->

        <!-- App List. This shadow is the perf watchpoint: an Effect renders
             its whole subtree to an intermediate surface, and this one scrolls.
             If card scrolling ever stutters on lab hardware, delete THIS
             Effect first and leave the other panels alone. -->
        <!-- Padding left=0 (Blake, 2026-08-02): the cards sit flush to the
             panel's left edge so their status spines line up under the header
             and footer accent spines - one continuous accent line down the
             window instead of the old ~9px zigzag. Top/right/bottom keep 8. -->
        <Border Grid.Row="1" Background="#1e1e1e" CornerRadius="5,12,12,5" Padding="0,8,8,8"
                BorderBrush="#303036" BorderThickness="1" Effect="{StaticResource PanelShadow}">
            <ScrollViewer Name="scrApps" VerticalScrollBarVisibility="Auto">
                <StackPanel Name="pnlApps"/>
            </ScrollViewer>
        </Border>

        <!-- The Bottom Action Buttons plate that lived in Grid.Row 2 moved
             (Blake, 2026-07-31) into the global Status Dock footer card after
             the status bar - one card for actions + status, Deploy-only rows
             collapse on the master tabs. Row 2 is now empty; the app list's old
             bottom margin went with it (the TabControl's own bottom margin is
             the gap to the dock now). -->

        </Grid>
        </TabItem>

        <!-- ============ MASTER TABS (hidden unless C:\LabDeployMaster exists) ============ -->

        <!-- Header renamed 2026-07-30 (Blake); the control name stays tabFleet
             so every binding, test and handler keeps working. Display name and
             control name are allowed to differ - renaming the control would
             touch dozens of sites for no behaviour change. -->
        <TabItem Header="Deployment Tracker" Name="tabFleet" Visibility="Collapsed">
            <DockPanel Margin="4">
                <DockPanel DockPanel.Dock="Top" Margin="0,0,0,8">
                    <Button Name="btnFleetRefresh" Content="Refresh" DockPanel.Dock="Right"
                            Padding="12,6" Margin="6,0,0,0" Background="#0078D4" Style="{StaticResource FlatBtn}"
                            ToolTip="Re-merge any plugged-in stick's logs, then rebuild the map"/>
                    <Button Name="btnFleetExport" Content="Export CSV" DockPanel.Dock="Right"
                            Padding="12,6" Margin="6,0,0,0" Background="#50505A" Style="{StaticResource FlatBtn}"
                            ToolTip="Writes the whole fleet rollup to C:\LabDeployMaster\fleet-export.csv"/>
                    <Button Name="btnFleetPrint" Content="Print Sheets" DockPanel.Dock="Right"
                            Padding="12,6" Margin="6,0,0,0" Background="#50505A" Style="{StaticResource FlatBtn}"
                            ToolTip="Generates the recheck to-do list and the per-room program config checklists as PDFs (C:\LabDeployMaster\prints). Room filters live on the Cloudflare Print Station tab."/>
                    <TextBox Name="txtFleetSearch" Width="170" DockPanel.Dock="Right" Margin="10,0,0,0"
                             Background="#1b1b20" Foreground="#e0e0e0" BorderBrush="#444" VerticalContentAlignment="Center"
                             ToolTip="Type part of a hostname, or a program name to find every machine MISSING it (e.g. LabVIEW)"/>
                    <TextBlock Name="txtFleetTitle" Text="Loading fleet..." Foreground="#aaa"
                               VerticalAlignment="Center" TextWrapping="Wrap" Margin="0,0,8,0"/>
                </DockPanel>
                <Grid>
                    <Grid.ColumnDefinitions>
                        <ColumnDefinition Width="*"/>
                        <ColumnDefinition Width="300"/>
                    </Grid.ColumnDefinitions>
                    <ScrollViewer Name="scrFleet" Grid.Column="0" VerticalScrollBarVisibility="Auto">
                        <StackPanel Name="pnlFleet"/>
                    </ScrollViewer>
                    <Border Grid.Column="1" Background="#26262b" CornerRadius="6" Padding="10" Margin="8,0,0,0"
                            BorderBrush="#3e3e44" BorderThickness="1">
                        <ScrollViewer Name="scrFleetInsp" VerticalScrollBarVisibility="Auto">
                            <StackPanel Name="pnlFleetInsp">
                                <TextBlock Text="Click any machine tile to see its app-by-app breakdown here."
                                           Foreground="#77777f" FontSize="11" TextWrapping="Wrap"/>
                            </StackPanel>
                        </ScrollViewer>
                    </Border>
                </Grid>
            </DockPanel>
        </TabItem>

        <TabItem Header="Assign" Name="tabAssign" Visibility="Collapsed">
            <Grid Margin="4">
                <Grid.ColumnDefinitions>
                    <ColumnDefinition Width="165"/>
                    <ColumnDefinition Width="*"/>
                    <ColumnDefinition Width="285"/>
                </Grid.ColumnDefinitions>

                <DockPanel Grid.Column="0">
                    <TextBlock DockPanel.Dock="Top" Text="ROOMS" Foreground="#666" FontSize="10" FontWeight="SemiBold" Margin="0,0,0,6"/>
                    <StackPanel DockPanel.Dock="Bottom" Margin="0,8,0,0">
                        <TextBlock Text="NEW ROOM (real or not)" Foreground="#666" FontSize="10" FontWeight="SemiBold" Margin="0,0,0,4"/>
                        <ComboBox Name="cmbAsgNewBldg" Margin="0,0,0,4" ToolTip="Building"/>
                        <DockPanel>
                            <Button Name="btnAsgNewRoom" Content="Open" DockPanel.Dock="Right" Padding="10,4" Margin="4,0,0,0"
                                    Background="#6E3FA3" Style="{StaticResource FlatBtn}"/>
                            <TextBox Name="txtAsgNewRoom" Background="#1b1b20" Foreground="#e0e0e0" BorderBrush="#444"
                                     VerticalContentAlignment="Center" ToolTip="Room number, e.g. 103. Becomes real when its first rule is saved."/>
                        </DockPanel>
                    </StackPanel>
                    <ScrollViewer Name="scrAsgRooms" VerticalScrollBarVisibility="Auto">
                        <StackPanel Name="pnlAsgRooms"/>
                    </ScrollViewer>
                </DockPanel>

                <DockPanel Grid.Column="1" Margin="8,0,8,0">
                    <TextBlock Name="txtAsgTitle" DockPanel.Dock="Top" Text="Pick a room on the left."
                               Foreground="#e0e0e0" FontSize="13" FontWeight="SemiBold" TextWrapping="Wrap"/>
                    <DockPanel DockPanel.Dock="Top" Margin="0,8,0,8">
                        <Button Name="btnAsgSize" Content="Set" DockPanel.Dock="Right"
                                Padding="12,5" Margin="6,0,0,0" Background="#50505A" Style="{StaticResource FlatBtn}"
                                ToolTip="Save this room's machine count (stored in buildings.json, shared to every stick)"/>
                        <TextBox Name="txtAsgSize" Width="55" DockPanel.Dock="Right"
                                 Background="#1b1b20" Foreground="#e0e0e0" BorderBrush="#444" VerticalContentAlignment="Center"
                                 ToolTip="How many machines does this room physically have?"/>
                        <TextBlock Text="Machines in this room:" Foreground="#aaa" FontSize="11.5" VerticalAlignment="Center"/>
                    </DockPanel>
                    <WrapPanel DockPanel.Dock="Top" Margin="0,0,0,8">
                        <TextBlock Text="Health checks:" Foreground="#aaa" FontSize="11.5" VerticalAlignment="Center" Margin="0,0,8,4"/>
                        <CheckBox Name="chkAsgPKI" Content="PKI certificate" Foreground="#e0e0e0" VerticalAlignment="Center" Margin="0,0,12,4"
                                  ToolTip="Off = machines in this room never receive a machine certificate, so the PKI dot and the PKI Check button disappear on them (three dots become two). Saved with SAVE this room."/>
                        <CheckBox Name="chkAsgImage" Content="Imaging date" Foreground="#e0e0e0" VerticalAlignment="Center" Margin="0,0,6,4"
                                  ToolTip="Off = no imaging-date dot on this room's machines. Saved with SAVE this room."/>
                        <TextBlock Text="from" Foreground="#666" FontSize="11" VerticalAlignment="Center" Margin="0,0,4,4"/>
                        <TextBox Name="txtAsgImageFile" Width="200" Margin="0,0,0,4" Background="#1b1b20" Foreground="#e0e0e0" BorderBrush="#444" VerticalContentAlignment="Center"
                                 ToolTip="A file your imaging lays down (a date written inside it wins, else its timestamp) - or the word auto to read the Windows install date from the registry, which needs zero setup on any machine."/>
                    </WrapPanel>
                    <ScrollViewer Name="scrAsgRuler" DockPanel.Dock="Top" MaxHeight="160" VerticalScrollBarVisibility="Auto"
                                  Margin="0,0,0,6">
                        <WrapPanel Name="pnlAsgRuler"/>
                    </ScrollViewer>
                    <WrapPanel DockPanel.Dock="Top" Margin="0,0,0,8">
                        <Button Name="btnAsgSplit" Content="Split a segment" Padding="12,6" Margin="0,0,6,4"
                                Background="#4A2E6E" Style="{StaticResource FlatBtn}"
                                ToolTip="Then click a machine above to place the boundary. Split as many times as the room has machines."/>
                        <Button Name="btnAsgMerge" Content="Merge with next" Padding="12,6" Margin="0,0,6,4"
                                Background="#50505A" Style="{StaticResource FlatBtn}"/>
                        <Button Name="btnAsgSave" Content="SAVE this room" Padding="12,6" Margin="0,0,6,4"
                                Background="#107C10" Style="{StaticResource FlatBtn}"
                                ToolTip="Writes one deployment rule per segment. The previous rules are kept as deployment-rules.json.bak"/>
                        <TextBlock Text="Split at #" Foreground="#aaa" FontSize="11.5" VerticalAlignment="Center" Margin="8,0,4,4"/>
                        <TextBox Name="txtAsgSplitAt" Width="55" Margin="0,0,4,4"
                                 Background="#1b1b20" Foreground="#e0e0e0" BorderBrush="#444" VerticalContentAlignment="Center"
                                 ToolTip="Machine number the NEW segment starts at. Works past the ruler - 1000 is fine; the room grows to reach it."/>
                        <Button Name="btnAsgSplitAt" Content="Go" Padding="9,5" Margin="0,0,0,4"
                                Background="#50505A" Style="{StaticResource FlatBtn}"/>
                    </WrapPanel>
                    <ScrollViewer Name="scrAsgSegs" VerticalScrollBarVisibility="Auto">
                        <StackPanel Name="pnlAsgSegs"/>
                    </ScrollViewer>
                </DockPanel>

                <DockPanel Grid.Column="2">
                    <TextBlock Name="txtAsgSeg" DockPanel.Dock="Top" Text="Programs" Foreground="#e0e0e0"
                               FontSize="12" FontWeight="SemiBold" TextWrapping="Wrap" Margin="0,0,0,4"/>
                    <WrapPanel DockPanel.Dock="Top" Margin="0,0,0,6">
                        <Button Name="btnAsgNone" Content="(none)" Padding="9,4" Margin="0,0,5,4"
                                Background="#50505A" Style="{StaticResource FlatBtn}"
                                ToolTip="This segment gets NOTHING - a real, saveable answer"/>
                        <ComboBox Name="cmbAsgProfile" Width="130" Margin="0,0,5,4"
                                  ToolTip="Fill the ticks from an existing room profile"/>
                        <Button Name="btnAsgApply" Content="Use" Padding="9,4" Margin="0,0,0,4"
                                Background="#50505A" Style="{StaticResource FlatBtn}"/>
                    </WrapPanel>
                    <ScrollViewer Name="scrAsgApps" VerticalScrollBarVisibility="Auto">
                        <WrapPanel Name="pnlAsgApps"/>
                    </ScrollViewer>
                </DockPanel>
            </Grid>
        </TabItem>

        <!-- Renamed "Rooms & Rules" 2026-08-02 (consolidation Phase 3); control
             name stays tabCover. Hosts a nested tab strip: Designer (the visual
             drill-down), Advanced (raw rules/buildings/types/dry-run, folded in
             from the old Config tab), Backups (named configs + snapshots).
             Nested TabItems inherit the implicit underline style; the nested
             TabControl is transparent/borderless to match tabMain. -->
        <TabItem Header="Rooms &amp; Rules" Name="tabCover" Visibility="Collapsed">
            <TabControl Name="tabRR" Background="Transparent" BorderThickness="0" Padding="0,10,0,0">
            <TabItem Header="Layout Designer">
            <DockPanel Margin="4">
                <DockPanel DockPanel.Dock="Top" Margin="0,0,0,8">
                    <!-- Refresh is docked Right FIRST, so it is always the
                         right-most button (Blake, 2026-07-30) - it is the one
                         constant here, and a fixed target should not shuffle
                         sideways as the level-dependent actions come and go. -->
                    <Button Name="btnCoverRefresh" Content="Refresh" DockPanel.Dock="Right"
                            Padding="12,6" Background="#0078D4" Style="{StaticResource FlatBtn}"/>
                    <!-- Level actions sit to its LEFT. Only the ones that make
                         sense where you are standing are shown -
                         Update-CoverageMap owns their visibility. -->
                    <!-- Room-level set completed 2026-07-31 (Blake): Room Size /
                         Split / Merge / Remove joined Add Program, which is
                         everything the Assign tab could do. Ordered structure
                         first (how the room is carved) then content (what those
                         machines get), so the toolbar reads the same way the
                         work does. Colours follow the tool's contract: green
                         adds, red removes, purple is the intent domain, grey is
                         a neutral edit. -->
                    <StackPanel Name="pnlCoverActions" DockPanel.Dock="Right" Orientation="Horizontal" Margin="0,0,8,0">
                        <Button Name="btnCoverAddBldg" Content="+ Add Building" Margin="8,0,0,0"
                                Padding="12,6" Background="#107C10" Style="{StaticResource FlatBtn}"
                                Visibility="Collapsed"/>
                        <Button Name="btnCoverAddRoom" Content="+ Add Classroom" Margin="8,0,0,0"
                                Padding="12,6" Background="#107C10" Style="{StaticResource FlatBtn}"
                                Visibility="Collapsed"/>
                        <Button Name="btnCoverSize" Content="Room Size" Margin="8,0,0,0"
                                Padding="12,6" Background="#50505A" Style="{StaticResource FlatBtn}"
                                Visibility="Collapsed"
                                ToolTip="How many machines this room physically has. Only decides how far the segment strip is drawn - rules past it still work."/>
                        <Button Name="btnCoverSplit" Content="Split Room" Margin="8,0,0,0"
                                Padding="12,6" Background="#6E3FA3" Style="{StaticResource FlatBtn}"
                                Visibility="Collapsed"
                                ToolTip="Cut the selected segment in two at a machine number. Both halves start with the same programs."/>
                        <Button Name="btnCoverMerge" Content="Merge Next" Margin="8,0,0,0"
                                Padding="12,6" Background="#50505A" Style="{StaticResource FlatBtn}"
                                Visibility="Collapsed"
                                ToolTip="Join the selected segment with the one after it. The selected segment's program list is the one that survives."/>
                        <Button Name="btnCoverAddProg" Content="+ Add Program" Margin="8,0,0,0"
                                Padding="12,6" Background="#107C10" Style="{StaticResource FlatBtn}"
                                Visibility="Collapsed"/>
                        <Button Name="btnCoverRemProg" Content="- Remove Program" Margin="8,0,0,0"
                                Padding="12,6" Background="#8B2E2E" Style="{StaticResource FlatBtn}"
                                Visibility="Collapsed"
                                ToolTip="Take programs off the selected segment. Changes what these machines SHOULD have - it never uninstalls anything already on them."/>
                        <!-- Delete, so nothing this tab creates is permanent by
                             accident. Last before Refresh: the spec forbids a
                             destructive action in the default/edge position. -->
                        <Button Name="btnCoverUnclaim" Content="Unclaim" Margin="8,0,0,0"
                                Padding="12,6" Background="#8B2E2E" Style="{StaticResource FlatBtn}"
                                Visibility="Collapsed"
                                ToolTip="Delete the selected segment's rule. Those machines go back to inheriting whatever a building-wide rule or profile gives them, or to nothing. Never uninstalls anything."/>
                    </StackPanel>
                    <Button Name="btnCoverBack" Content="&#x2190;  Back" DockPanel.Dock="Left"
                            Padding="12,6" Margin="0,0,10,0" Background="#3a3a44" Style="{StaticResource FlatBtn}"
                            Visibility="Collapsed"/>
                    <TextBlock Name="txtCoverTitle" Text="Who gets what" Foreground="#aaa"
                               VerticalAlignment="Center" TextWrapping="Wrap" Margin="0,0,8,0"/>
                </DockPanel>
                <!-- Room header (Blake, 2026-07-31): the plate + proportional
                     rail + hover readout for the room level, built in code by
                     Show-CoverageRoom. Docked Top and OUTSIDE scrCover on
                     purpose - the rail is the room's index, so it must not
                     scroll away when a selected segment expands into a
                     fourteen-row program list. Empty and Collapsed at the
                     other two levels. -->
                <StackPanel Name="pnlCoverHead" DockPanel.Dock="Top" Visibility="Collapsed" Margin="0,0,0,10"/>
                <ScrollViewer Name="scrCover" HorizontalScrollBarVisibility="Disabled" VerticalScrollBarVisibility="Auto">
                    <StackPanel Name="pnlCover" Margin="2"/>
                </ScrollViewer>
            </DockPanel>
            </TabItem>

            <!-- ADVANCED: raw rules / buildings / type codes / dry run, folded in
                 from the old Config tab (consolidation Phase 3, 2026-08-02). The
                 ScrollViewer keeps the name scrConfig so the slow-scroll list and
                 any other reference still resolve; all control names are unchanged. -->
            <TabItem Header="Manual Entry">
            <DockPanel Margin="6">
                <StackPanel DockPanel.Dock="Top">
                    <TextBlock Foreground="#aaa" TextWrapping="Wrap" Margin="0,0,0,8"
                               Text="Assign machines to rooms BY HAND - for hostnames with no naming scheme. An assignment beats the decoder, and freed numbers are never reused."/>
                    <WrapPanel>
                        <TextBlock Text="Room:" Foreground="#ccc" VerticalAlignment="Center" Margin="0,0,6,4"/>
                        <ComboBox Name="cmbLedRoom" Width="230" Margin="0,0,10,4"/>
                        <TextBox Name="txtLedNewRoom" Width="170" Margin="0,0,4,4" Background="#1b1b20" Foreground="#e0e0e0" BorderBrush="#444"
                                 VerticalContentAlignment="Center" ToolTip="New room name, e.g. ARTS-101. Also creates a matching (empty) room profile in rooms.json if one does not exist."/>
                        <Button Name="btnLedNewRoom" Content="Create room" Padding="10,4" Margin="0,0,0,4" Background="#6E3FA3" Style="{StaticResource FlatBtn}"/>
                    </WrapPanel>
                    <Border Background="#26262b" CornerRadius="6" Padding="8" Margin="0,4,0,8">
                        <WrapPanel>
                            <CheckBox Name="chkLedNumbered" Foreground="#ccc" VerticalAlignment="Center" Margin="0,0,14,0"
                                      Content="This room has multiple machines and I want to NUMBER them"/>
                            <TextBlock Text="start at:" Foreground="#ccc" VerticalAlignment="Center" Margin="0,0,6,0"/>
                            <RadioButton Name="rbLedStart1" GroupName="ledStart" Content="1" IsChecked="True" Foreground="#ccc" VerticalAlignment="Center" Margin="0,0,8,0"/>
                            <RadioButton Name="rbLedStart0" GroupName="ledStart" Content="0" Foreground="#ccc" VerticalAlignment="Center" Margin="0,0,14,0"/>
                            <TextBlock Text="numbering:" Foreground="#ccc" VerticalAlignment="Center" Margin="0,0,6,0"/>
                            <RadioButton Name="rbLedModeSeen" GroupName="ledMode" Content="by when a stick FIRST SAW each machine" IsChecked="True" Foreground="#ccc" VerticalAlignment="Center" Margin="0,0,8,0"
                                         ToolTip="Walk the room in order with a stick: the walk order becomes the numbering order (earliest session log per machine)."/>
                            <RadioButton Name="rbLedModeManual" GroupName="ledMode" Content="by hand" Foreground="#ccc" VerticalAlignment="Center" Margin="0,0,14,0"
                                         ToolTip="Assign without numbers, then select a machine and use Set # below."/>
                            <Button Name="btnLedSaveRoom" Content="Save room settings" Padding="10,4" Background="#50505A" Style="{StaticResource FlatBtn}"/>
                        </WrapPanel>
                    </Border>
                </StackPanel>
                <TextBlock Name="txtLedStatus" DockPanel.Dock="Bottom" Foreground="#b8b8c0" TextWrapping="Wrap" Margin="0,6,0,0" Text=""/>
                <Grid>
                    <Grid.ColumnDefinitions>
                        <ColumnDefinition Width="*"/>
                        <ColumnDefinition Width="12"/>
                        <ColumnDefinition Width="*"/>
                    </Grid.ColumnDefinitions>
                    <DockPanel Grid.Column="0">
                        <TextBlock DockPanel.Dock="Top" Text="UNASSIGNED - seen in session logs, no room, hostname decodes to nothing:" Foreground="#666" FontSize="10" FontWeight="SemiBold" Margin="0,0,0,4"/>
                        <Button Name="btnLedAssign" DockPanel.Dock="Bottom" Content="Assign selected to this room" Padding="12,6" Margin="0,6,0,0"
                                Background="#107C10" Style="{StaticResource FlatBtn}" HorizontalAlignment="Left"/>
                        <ListBox Name="lstLedUnassigned" SelectionMode="Extended" Background="#1b1b20" Foreground="#e0e0e0" BorderBrush="#444"/>
                    </DockPanel>
                    <DockPanel Grid.Column="2">
                        <TextBlock Name="txtLedRoomTitle" DockPanel.Dock="Top" Text="ASSIGNED to this room:" Foreground="#666" FontSize="10" FontWeight="SemiBold" Margin="0,0,0,4"/>
                        <WrapPanel DockPanel.Dock="Bottom" Margin="0,6,0,0">
                            <TextBox Name="txtLedNum" Width="55" Margin="0,0,4,4" Background="#1b1b20" Foreground="#e0e0e0" BorderBrush="#444" VerticalContentAlignment="Center" ToolTip="Number for Set #"/>
                            <Button Name="btnLedSetNum" Content="Set #" Padding="10,5" Margin="0,0,8,4" Background="#50505A" Style="{StaticResource FlatBtn}"
                                    ToolTip="Give ONE selected machine this number (must be free in this room)"/>
                            <Button Name="btnLedSwap" Content="Swap numbers" Padding="10,5" Margin="0,0,8,4" Background="#4A2E6E" Style="{StaticResource FlatBtn}"
                                    ToolTip="Select exactly TWO machines - their numbers trade places. No temp-number dance."/>
                            <Button Name="btnLedUnassign" Content="Unassign" Padding="10,5" Margin="0,0,8,4" Background="#50505A" Style="{StaticResource FlatBtn}"/>
                            <Button Name="btnLedRetire" Content="Retire" Padding="10,5" Margin="0,0,0,4" Background="#6E2E2E" Style="{StaticResource FlatBtn}"
                                    ToolTip="Machine was renamed or scrapped: kept in history, hidden everywhere, its number stays vacant."/>
                        </WrapPanel>
                        <ListBox Name="lstLedAssigned" SelectionMode="Extended" Background="#1b1b20" Foreground="#e0e0e0" BorderBrush="#444"/>
                    </DockPanel>
                </Grid>
            </DockPanel>
            </TabItem>
            <TabItem Header="Advanced (raw rules &amp; codes)">
            <ScrollViewer Name="scrConfig" VerticalScrollBarVisibility="Auto">
            <StackPanel Margin="6">
                <TextBlock Text="DRY RUN - type any hostname (blank = this PC) and see exactly what it would get. Touches nothing:"
                           Foreground="#aaa" TextWrapping="Wrap" Margin="0,0,0,8"/>
                <Border Background="#26262b" CornerRadius="6" Padding="10" Margin="0,0,0,14">
                    <StackPanel>
                        <DockPanel>
                            <Button Name="btnDryRun" Content="What would it get?" DockPanel.Dock="Right"
                                    Padding="12,6" Margin="8,0,0,0" Background="#0078D4" Foreground="White" BorderThickness="0" Cursor="Hand"/>
                            <TextBox Name="txtDryHost" Background="#1b1b20" Foreground="#e0e0e0" BorderBrush="#444"
                                     VerticalContentAlignment="Center" ToolTip="e.g. 10101LAB34-75"/>
                        </DockPanel>
                        <TextBox Name="txtDryResult" IsReadOnly="True" BorderThickness="0" Background="Transparent"
                                 Foreground="#b8b8c0" FontFamily="Consolas" FontSize="12" TextWrapping="Wrap"
                                 Margin="0,8,0,0" Text="Nothing tested yet."/>
                    </StackPanel>
                </Border>
                <TextBlock Text="BUILDINGS (campus hostname codes) - add one and every stick understands it after its next update:"
                           Foreground="#aaa" TextWrapping="Wrap" Margin="0,0,0,8"/>
                <StackPanel Name="pnlBldgList" Margin="0,0,0,10"/>
                <Border Background="#26262b" CornerRadius="6" Padding="10">
                    <StackPanel>
                        <TextBlock Text="Add a building:" Foreground="#aaa" Margin="0,0,0,6"/>
                        <DockPanel>
                            <Button Name="btnAddBldg" Content="Add Building" DockPanel.Dock="Right"
                                    Padding="12,6" Margin="8,0,0,0" Background="#6E3FA3" Foreground="White" BorderThickness="0" Cursor="Hand"/>
                            <ComboBox Name="cmbRoomDigits" Width="150" DockPanel.Dock="Right" Margin="8,0,0,0"
                                      ToolTip="How many digits do ROOM numbers have in this building?"/>
                            <TextBox Name="txtBldgName" DockPanel.Dock="Right" Width="220" Margin="8,0,0,0"
                                     Background="#1b1b20" Foreground="#e0e0e0" BorderBrush="#444" VerticalContentAlignment="Center"
                                     ToolTip="Full name (optional), e.g. Kellogg Library"/>
                            <TextBox Name="txtBldgAbbr" DockPanel.Dock="Right" Width="110" Margin="8,0,0,0"
                                     Background="#1b1b20" Foreground="#e0e0e0" BorderBrush="#444" VerticalContentAlignment="Center"
                                     ToolTip="Short label, e.g. LIB (any length is fine)"/>
                            <TextBox Name="txtBldgCode" Width="80"
                                     Background="#1b1b20" Foreground="#e0e0e0" BorderBrush="#444" VerticalContentAlignment="Center"
                                     ToolTip="The building NUMBER from hostnames - 2 or 3 digits, e.g. 17 or 902"/>
                        </DockPanel>
                        <TextBlock Foreground="#77777f" FontSize="10" Margin="0,4,0,0"
                                   Text="code (2-3 digits)   |   abbreviation   |   full name (optional)   |   room digits"/>
                    </StackPanel>
                </Border>
                <TextBlock Text="TYPE CODES - the letters segment of a hostname (e.g. LAB, CART):"
                           Foreground="#aaa" TextWrapping="Wrap" Margin="0,14,0,8"/>
                <StackPanel Name="pnlTypeList" Margin="0,0,0,10"/>
                <Border Background="#26262b" CornerRadius="6" Padding="10">
                    <DockPanel>
                        <Button Name="btnAddType" Content="Add Type" DockPanel.Dock="Right"
                                Padding="12,6" Margin="8,0,0,0" Background="#6E3FA3" Foreground="White" BorderThickness="0" Cursor="Hand"/>
                        <ComboBox Name="cmbType01" Width="200" DockPanel.Dock="Right" Margin="8,0,0,0"
                                  ToolTip="What is machine -01 of this type?"/>
                        <TextBox Name="txtTypeCode" Width="110"
                                 Background="#1b1b20" Foreground="#e0e0e0" BorderBrush="#444" VerticalContentAlignment="Center"
                                 ToolTip="Letter code as it appears in hostnames, e.g. POD"/>
                    </DockPanel>
                </Border>
                <TextBlock Text="DEPLOYMENT RULES (first match wins, top to bottom). The Layout Designer writes these for you - edit raw only if you must:"
                           Foreground="#aaa" TextWrapping="Wrap" Margin="0,14,0,8"/>
                <StackPanel Name="pnlRuleList" Margin="0,0,0,10"/>
                <Border Background="#26262b" CornerRadius="6" Padding="10">
                    <StackPanel>
                        <TextBlock Text="Add a rule by hand. Blank rooms/types/machines = ALL; ranges (30-60) and lists (1,5,9) work:" Foreground="#aaa" TextWrapping="Wrap" Margin="0,0,0,6"/>
                        <DockPanel>
                            <Button Name="btnAddRule" Content="Add Rule" DockPanel.Dock="Right"
                                    Padding="12,6" Margin="8,0,0,0" Background="#6E3FA3" Foreground="White" BorderThickness="0" Cursor="Hand"/>
                            <ComboBox Name="cmbRuleProfile" Width="150" DockPanel.Dock="Right" Margin="8,0,0,0" ToolTip="Which package set (room profile) these machines get"/>
                            <TextBox Name="txtRuleMachines" Width="90" DockPanel.Dock="Right" Margin="8,0,0,0" Background="#1b1b20" Foreground="#e0e0e0" BorderBrush="#444" VerticalContentAlignment="Center" ToolTip="Machine numbers, e.g. 30-60 (blank = all)"/>
                            <TextBox Name="txtRuleTypes" Width="90" DockPanel.Dock="Right" Margin="8,0,0,0" Background="#1b1b20" Foreground="#e0e0e0" BorderBrush="#444" VerticalContentAlignment="Center" ToolTip="Types, e.g. CART,LAB (blank = all)"/>
                            <TextBox Name="txtRuleRooms" Width="110" DockPanel.Dock="Right" Margin="8,0,0,0" Background="#1b1b20" Foreground="#e0e0e0" BorderBrush="#444" VerticalContentAlignment="Center" ToolTip="Rooms, e.g. 103 or 100-199 or 103,205 (blank = all)"/>
                            <ComboBox Name="cmbRuleBldg" ToolTip="Building"/>
                        </DockPanel>
                        <TextBlock Foreground="#77777f" FontSize="10" Margin="0,4,0,0"
                                   Text="building   |   rooms   |   types   |   machine #s   |   package set"/>
                    </StackPanel>
                </Border>
            </StackPanel>
            </ScrollViewer>
            </TabItem>

            <!-- BACKUPS: named configs + dated snapshots (D1). -->
            <TabItem Header="Backups">
            <ScrollViewer Name="scrBackups" VerticalScrollBarVisibility="Auto">
            <StackPanel Margin="6">
                <TextBlock Text="SAVED CONFIGURATIONS - deliberate keepers. Save this year's finished setup by name (e.g. Summer 2026):"
                           Foreground="#aaa" TextWrapping="Wrap" Margin="0,0,0,8"/>
                <Border Background="#26262b" CornerRadius="6" Padding="10" Margin="0,0,0,10">
                    <DockPanel>
                        <Button Name="btnCfgSaveName" Content="Save current as..." DockPanel.Dock="Right"
                                Padding="12,6" Margin="8,0,0,0" Background="#107C10" Foreground="White" BorderThickness="0" Cursor="Hand"/>
                        <TextBox Name="txtCfgSaveName" Background="#1b1b20" Foreground="#e0e0e0" BorderBrush="#444"
                                 VerticalContentAlignment="Center" ToolTip="Name it what you'd call it out loud - Summer 2026, Fall pilot, ..."/>
                    </DockPanel>
                </Border>
                <StackPanel Name="pnlSavedCfg" Margin="0,0,0,10"/>
                <Expander Foreground="#aaa" Margin="0,0,0,14">
                    <Expander.Header>
                        <TextBlock Text="Emergency backups (automatic, dated - one per config save)" Foreground="#77777f" FontSize="11"/>
                    </Expander.Header>
                    <StackPanel Name="pnlSnapList" Margin="0,6,0,0"/>
                </Expander>
            </StackPanel>
            </ScrollViewer>
            </TabItem>
            </TabControl>
        </TabItem>

        <TabItem Header="Sticks" Name="tabSticks" Visibility="Collapsed">
            <ScrollViewer Name="scrSticks" VerticalScrollBarVisibility="Auto">
            <StackPanel Margin="6">
                <DockPanel Margin="0,0,0,10">
                    <Button Name="btnStickRescan" Content="Rescan Drives" DockPanel.Dock="Right"
                            Padding="12,6" Background="#0078D4" Foreground="White" BorderThickness="0" Cursor="Hand"
                            VerticalAlignment="Top"/>
                    <Button Name="btnStickTrust" Content="Trust Encrypted Sticks" DockPanel.Dock="Right"
                            Padding="12,6" Margin="0,0,8,0" Background="#6E3FA3" Foreground="White" BorderThickness="0" Cursor="Hand"
                            VerticalAlignment="Top"
                            ToolTip="BitLocker sticks stop asking for the password ON THIS PC ONLY (lab machines still ask - that is the point). Also files each stick's recovery key to C:\LabDeployMaster\bitlocker-keys.txt. Needs C: to be encrypted."/>
                    <Button Name="btnStickAll" Content="Update ALL Known Sticks" DockPanel.Dock="Right"
                            Padding="12,6" Margin="0,0,8,0" Background="#107C10" Foreground="White" BorderThickness="0" Cursor="Hand"
                            VerticalAlignment="Top"
                            ToolTip="Queues every stick listed below. Brand-new/unrecognised drives are never touched - those go through Initialize."/>
                    <TextBlock Text="LabDeploy sticks (only USB-removable drives with the LabDeploy marker ever appear here):"
                               Foreground="#aaa" VerticalAlignment="Center" TextWrapping="Wrap" Margin="0,0,12,0"/>
                </DockPanel>
                <StackPanel Name="pnlStickList"/>
                <Border Background="#26262b" CornerRadius="6" Padding="10" Margin="0,14,0,0">
                    <StackPanel>
                        <TextBlock Text="Initialize a NEW stick (writes LabDeployment + launcher onto a blank USB drive; never deletes its other files):"
                                   Foreground="#aaa" TextWrapping="Wrap" Margin="0,0,0,8"/>
                        <DockPanel>
                            <Button Name="btnInitStick" Content="Initialize" DockPanel.Dock="Right"
                                    Padding="12,6" Background="#6E3FA3" Foreground="White" BorderThickness="0" Cursor="Hand"/>
                            <TextBox Name="txtInitConfirm" Width="120" Margin="8,0" DockPanel.Dock="Right"
                                     Background="#1b1b20" Foreground="#e0e0e0" BorderBrush="#444"
                                     VerticalContentAlignment="Center" ToolTip="Type the drive letter to confirm"/>
                            <ComboBox Name="cmbNewStick"/>
                        </DockPanel>
                    </StackPanel>
                </Border>
            </StackPanel>
            </ScrollViewer>
        </TabItem>

        <TabItem Header="Applications" Name="tabAddApp" Visibility="Collapsed">
            <TabControl Name="tabApps" Background="Transparent" BorderThickness="0" Padding="0,10,0,0">
            <TabItem Header="Catalog">
            <ScrollViewer Name="scrAddApp" VerticalScrollBarVisibility="Auto">
            <StackPanel Margin="6">
                <TextBlock Text="ALL APPLICATIONS. Untick = disabled fleet-wide (kept, greyed out, skipped). Edit changes name, icon and open-after-install:"
                           Foreground="#aaa" TextWrapping="Wrap" Margin="0,0,0,8"/>
                <StackPanel Name="pnlAppCatalog" Margin="0,0,0,16"/>
            </StackPanel>
            </ScrollViewer>
            </TabItem>

            <TabItem Header="Build New Card">
            <ScrollViewer Name="scrBuildCard" VerticalScrollBarVisibility="Auto">
            <StackPanel Margin="6">
                <TextBlock Text="BUILD A NEW CARD. Pick the source; the install runs ON THIS PC while the tool watches, so the card learns how to DETECT the program - not just install it."
                           Foreground="#aaa" TextWrapping="Wrap" Margin="0,0,0,8"/>
                <Border Background="#26262b" CornerRadius="6" Padding="10">
                    <StackPanel>
                        <StackPanel Orientation="Horizontal">
                            <RadioButton Name="rbBuildFile" GroupName="buildSrc" IsChecked="True" Foreground="#e0e0e0" Margin="0,0,24,0"
                                         Content="From an installer file (.exe / .msi)"/>
                            <RadioButton Name="rbBuildWinget" GroupName="buildSrc" Foreground="#e0e0e0"
                                         Content="From winget (Windows Package Manager - needs internet)"/>
                        </StackPanel>
                        <DockPanel Margin="0,10,0,0">
                            <TextBlock Text="Card name:" Foreground="#ccc" VerticalAlignment="Center" Margin="0,0,8,0"/>
                            <TextBox Name="txtCapName" Background="#1b1b20" Foreground="#e0e0e0" BorderBrush="#444" VerticalContentAlignment="Center"
                                     ToolTip="What should the program's card be called? e.g. AutoCAD 2027. Auto-filled when you pick a winget match."/>
                        </DockPanel>

                        <StackPanel Name="pnlBuildFile" Margin="0,10,0,0">
                            <DockPanel>
                                <Button Name="btnCapBrowse" Content="Pick the installer file..." DockPanel.Dock="Right"
                                        Padding="12,6" Margin="8,0,0,0" Background="#0078D4" Foreground="White" BorderThickness="0" Cursor="Hand"/>
                                <TextBlock Name="txtCapFile" Foreground="#77777f" FontSize="11" TextWrapping="Wrap" VerticalAlignment="Center" Text="No installer picked yet."/>
                            </DockPanel>
                            <CheckBox Name="chkCapOffload" Foreground="#ccc" Content="Copy to PC before running (big installers)" Margin="0,8,0,0"/>
                        </StackPanel>

                        <StackPanel Name="pnlBuildWinget" Visibility="Collapsed" Margin="0,10,0,0">
                            <TextBlock Text="Search winget, or paste an exact package Id (e.g. Google.Chrome):" Foreground="#ccc"/>
                            <TextBox Name="txtWgQuery" Background="#1b1b20" Foreground="#e0e0e0" BorderBrush="#444" Margin="0,4,0,0"
                                     VerticalContentAlignment="Center"
                                     ToolTip="Type 3+ characters and pause - matches appear below (one winget search per pause, never per keystroke). Or paste a package Id straight in."/>
                            <TextBlock Name="txtWgSearchStatus" Foreground="#77777f" FontSize="11" Margin="0,4,0,0" Text=""/>
                            <ListBox Name="lstWgSuggest" MaxHeight="150" Margin="0,4,0,0" Visibility="Collapsed"
                                     Background="#1b1b20" Foreground="#e0e0e0" BorderBrush="#444"/>
                            <TextBlock Text="Winget switches for this card (all recommended - untick only on purpose; --exact is always passed):" Foreground="#ccc" Margin="0,8,0,0"/>
                            <CheckBox Name="chkWgSilent" IsChecked="True" Foreground="#ccc" Margin="0,4,0,0"
                                      Content="Silent install (does not always work - a badly authored package can still show UI)"/>
                            <CheckBox Name="chkWgScope" IsChecked="True" Foreground="#ccc" Margin="0,4,0,0"
                                      Content="Install for ALL users / machine scope (some packages are per-user only and will refuse)"/>
                            <CheckBox Name="chkWgAcceptPkg" IsChecked="True" Foreground="#ccc" Margin="0,4,0,0"
                                      Content="Accept package agreements automatically (untick = a person must answer the licence prompt)"/>
                            <CheckBox Name="chkWgAcceptSrc" IsChecked="True" Foreground="#ccc" Margin="0,4,0,0"
                                      Content="Accept source agreements automatically (the winget repo's own terms prompt)"/>
                            <TextBlock Foreground="#77777f" FontSize="11" TextWrapping="Wrap" Margin="0,6,0,0"
                                       Text="Winget cards need internet at install time. For offline rooms, use an installer file instead."/>
                        </StackPanel>

                        <StackPanel Orientation="Horizontal" Margin="0,12,0,0">
                            <CheckBox Name="chkCapOpen" Foreground="#ccc" Content="1) Open the app after it finishes installing?"/>
                        </StackPanel>
                        <StackPanel Orientation="Horizontal" Margin="0,4,0,0">
                            <CheckBox Name="chkCapAsk" Foreground="#ccc" IsChecked="True"
                                      Content="2) ...and pop up a question asking whether they did it? (card stays yellow until confirmed)"/>
                        </StackPanel>
                        <TextBlock Text="3) What should that popup ask?" Foreground="#ccc" Margin="0,6,0,0"/>
                        <TextBox Name="txtCapPrompt" Background="#1b1b20" Foreground="#e0e0e0" BorderBrush="#444" Margin="0,2,0,0"
                                 VerticalContentAlignment="Center" ToolTip="Shown to the tech word-for-word after the app opens"
                                 Text="Did you open the app and do the required first-run steps?"/>
                        <DockPanel Margin="0,8,0,0">
                            <ComboBox Name="cmbCapRequires" Width="220" DockPanel.Dock="Right" ToolTip="Does this app need another app installed first?"/>
                            <TextBlock Text="Needs another app installed first:" Foreground="#ccc" VerticalAlignment="Center"/>
                        </DockPanel>
                        <CheckBox Name="chkCapLast" Foreground="#ccc" Content="Install last during Install All" Margin="0,8,0,0"/>
                        <CheckBox Name="chkCapAllRooms" Foreground="#ccc" Margin="0,8,0,0"
                                  Content="Add to ALL room profiles (every profile below, including the DEFAULT set)"/>
                        <TextBlock Name="txtCapRooms" Foreground="#ccc" Margin="0,8,0,0" Text="...or pick specific room profiles (DEFAULT = machines whose hostname matches no room):"/>
                        <WrapPanel Name="pnlCapRooms"/>
                        <Button Name="btnCapStart" Content="START CAPTURE (runs the installer - click through it like normal)"
                                Padding="14,8" Margin="0,12,0,0" Background="#107C10" Foreground="White" BorderThickness="0" Cursor="Hand" HorizontalAlignment="Left"/>
                        <TextBlock Name="txtCapStatus" Foreground="#b8b8c0" Margin="0,8,0,0" TextWrapping="Wrap" Text=""/>
                    </StackPanel>
                </Border>
            </StackPanel>
            </ScrollViewer>
            </TabItem>

            <TabItem Header="Update Installer">
            <ScrollViewer Name="scrUpdApp" VerticalScrollBarVisibility="Auto">
            <StackPanel Margin="6">
                <TextBlock Text="UPDATE AN EXISTING PROGRAM (yearly refresh - swap in this year's installer):"
                           Foreground="#aaa" TextWrapping="Wrap" Margin="0,0,0,8"/>
                <Border Background="#26262b" CornerRadius="6" Padding="10" Margin="0,0,0,14">
                    <StackPanel>
                        <DockPanel>
                            <Button Name="btnUpdBrowse" Content="Where is the new installer?" DockPanel.Dock="Right"
                                    Padding="12,6" Margin="8,0,0,0" Background="#0078D4" Foreground="White" BorderThickness="0" Cursor="Hand"/>
                            <ComboBox Name="cmbUpdApp" ToolTip="Which program are you updating?"/>
                        </DockPanel>
                        <TextBlock Name="txtUpdCurrent" Foreground="#77777f" FontSize="11" Margin="0,6,0,0" TextWrapping="Wrap" Text="Pick a program to see what installer it currently uses."/>
                    </StackPanel>
                </Border>
            </StackPanel>
            </ScrollViewer>
            </TabItem>
            </TabControl>
        </TabItem>

        <!-- Settings: visible on LAB MACHINES TOO, deliberately. The screen that
             most needs a scale change is a tech's laptop in the field, not the
             master, so a master-only settings tab would miss the actual problem. -->
        <TabItem Header="Settings" Name="tabSettings">
            <ScrollViewer Name="scrSettings" VerticalScrollBarVisibility="Auto">
            <StackPanel Margin="10">
                <TextBlock Text="DISPLAY" Foreground="#666" FontSize="10" FontWeight="SemiBold" Margin="0,0,0,8"/>
                <Border Background="#26262b" CornerRadius="6" Padding="12" Margin="0,0,0,16">
                    <StackPanel>
                        <DockPanel>
                            <ComboBox Name="cmbUiScale" Width="130" DockPanel.Dock="Right"
                                      ToolTip="Makes everything - cards, tiles, text, buttons - bigger or smaller. &quot;Fit to window&quot; (the default) does it automatically: drag the window to any size and the whole UI scales to match, instead of hiding behind scrollbars. Pick a fixed % instead if you want one size no matter how the window is sized. Saved on this drive, so it follows this stick to every machine you use it on."/>
                            <TextBlock Text="Size of everything on screen:" Foreground="#e0e0e0" VerticalAlignment="Center"/>
                        </DockPanel>
                        <TextBlock Foreground="#77777f" FontSize="11" TextWrapping="Wrap" Margin="0,8,0,0"
                                   Text="For screens where the tool reads too small or too large. Applies immediately; saved on THIS drive."/>
                    </StackPanel>
                </Border>

                <!-- Master-only toggles (hidden on lab machines). Back in
                     Settings by request 2026-08-26: one place for every switch.
                     Values persist to master-config.json as before. -->
                <StackPanel Name="pnlSettingsMaster" Visibility="Collapsed">
                <TextBlock Text="MASTER - DEPLOYMENT TRACKER" Foreground="#666" FontSize="10" FontWeight="SemiBold" Margin="0,0,0,8"/>
                <Border Background="#26262b" CornerRadius="6" Padding="12" Margin="0,0,0,16">
                    <StackPanel>
                        <CheckBox Name="chkHideUnknown" Margin="0,0,0,8" IsChecked="True"
                                  Content="Hide machines with unrecognised names on the Deployment Tracker" Foreground="#e0e0e0"
                                  ToolTip="Machines whose hostname doesn't decode to a building and room - a laptop, a spare, a renamed PC. Display-only: their logs still merge and they still get re-check orders."/>
                        <CheckBox Name="chkLimitVendorLogs" IsChecked="False"
                                  Content="Limit vendor installer logs (keep only the most recent per machine)" Foreground="#e0e0e0"
                                  ToolTip="The master copies every installer log off every stick. Those are debug trails, not fleet history, and they are 99% of the disk this store uses. Ticking this keeps the 2 newest per program per machine - 5 for Visual Studio, Rockwell and LabVIEW, which are under investigation - and deletes the rest at every sync. Fleet history (LabDeploy_*.log) is never touched."/>
                    </StackPanel>
                </Border>
                </StackPanel>
                <TextBlock Text="SCANNING AND INSTALLING" Foreground="#666" FontSize="10" FontWeight="SemiBold" Margin="0,0,0,8"/>
                <Border Background="#26262b" CornerRadius="6" Padding="12">
                    <StackPanel>
                        <CheckBox Name="chkAutoScan" Content="Auto-scan apps when a room loads" Foreground="#e0e0e0" IsChecked="True"
                                  ToolTip="When off, apps are only scanned when you click Refresh or act on them - faster startup"/>
                        <TextBlock Foreground="#77777f" FontSize="11" TextWrapping="Wrap" Margin="22,3,0,10"
                                   Text="Off makes the tool open faster; cards then say 'not scanned' until you click Refresh or act on one."/>
                        <CheckBox Name="chkOffload" Content="Copy big installers to this PC before running them" Foreground="#e0e0e0" IsChecked="True"
                                  ToolTip="For large vendor images (Vivado, Ansys, MATLAB): copy to local disk first, install from there (faster/more reliable), then delete. Falls back to installing from the drive if off or low on space."/>
                        <TextBlock Foreground="#77777f" FontSize="11" TextWrapping="Wrap" Margin="22,3,0,0"
                                   Text="Stages multi-GB installers to the local disk first - faster and more reliable than running them from USB."/>
                    </StackPanel>
                </Border>
            </StackPanel>
            </ScrollViewer>
        </TabItem>
        </TabControl>

        <!-- ============================================================
             Health pill + GP/CM  (Blake, 2026-07-31) - rides the tab row
             ============================================================
             Same grid row as the TabControl, declared AFTER it so it paints on
             top, pinned to the right side of the Command Bar card's rail
             (top margin 4 centers the 28px controls in the 36px rail, right
             margin 12 matches the mockup inset). The pill is the whole
             old health strip compressed: four state dots + an issue count;
             clicking it opens the breakdown popover. GP Update / Run CM Actions
             kept as always-visible buttons beside it (they carry their own
             progress fill, so they cannot live in a closed popover). -->
        <StackPanel Grid.Row="2" Orientation="Horizontal" HorizontalAlignment="Right" VerticalAlignment="Top"
                    Margin="0,4,12,0" Panel.ZIndex="5">
            <Border Name="brdHealthPill" CornerRadius="14" BorderThickness="1" BorderBrush="#3A3A40"
                    Background="#10FFFFFF" Padding="9,0,9,0" Cursor="Hand" VerticalAlignment="Center"
                    Height="28" ToolTip="Machine health - click for the breakdown">
                <StackPanel Orientation="Horizontal" VerticalAlignment="Center">
                    <StackPanel Name="pnlPillDots" Orientation="Horizontal" VerticalAlignment="Center"/>
                    <TextBlock Name="txtHealthIssues" Text="checking..." FontSize="11" FontWeight="SemiBold"
                               Foreground="#8a8a95" Margin="3,0,0,0" VerticalAlignment="Center"/>
                </StackPanel>
            </Border>
            <Popup Name="popHealth" PlacementTarget="{Binding ElementName=brdHealthPill}" Placement="Bottom"
                   StaysOpen="False" AllowsTransparency="True" PopupAnimation="Fade" HorizontalOffset="-170" VerticalOffset="6">
                <Border Background="#26262E" BorderBrush="#3E3E46" BorderThickness="1" CornerRadius="10"
                        Padding="0,3,0,6" Margin="8,2,8,10" MinWidth="290">
                    <Border.Effect><DropShadowEffect BlurRadius="16" ShadowDepth="2" Opacity="0.45" Color="#12171F"/></Border.Effect>
                    <StackPanel>
                        <TextBlock Text="MACHINE HEALTH" FontSize="10" FontWeight="Bold" Foreground="#666A72"
                                   Margin="14,7,14,6"/>
                        <StackPanel Name="pnlHealthRows"/>
                    </StackPanel>
                </Border>
            </Popup>
            <Button Name="btnGPUpdate" Width="112" Height="28" Margin="7,0,0,0"
                    Style="{StaticResource SecondaryButton}"
                    ToolTip="Runs gpupdate /force in the background. The button itself fills up as the update progresses. Safe to use while installs are running.">
                <Grid Width="104">
                    <ProgressBar Name="pbGP" Height="22" Minimum="0" Maximum="100" Value="0"
                                 Background="Transparent" Foreground="{StaticResource BrushProgressFill}" BorderThickness="0" Opacity="0.35"/>
                    <TextBlock Name="txtGPBtn" Text="GP Update" Foreground="#E0E0E0" FontSize="12"
                               HorizontalAlignment="Center" VerticalAlignment="Center"/>
                </Grid>
            </Button>
            <!-- label shortened to "Run CM" for the shared row; the tooltip and
                 every runtime progress string ("CM: 3/9") were already short -->
            <Button Name="btnCMActions" Width="108" Height="28" Margin="7,0,0,0"
                    Style="{StaticResource SecondaryButton}"
                    ToolTip="Run CM Actions: triggers every available Configuration Manager client action (same list as the Control Panel applet). Safe to use while installs are running.">
                <Grid Width="100">
                    <ProgressBar Name="pbCM" Height="22" Minimum="0" Maximum="100" Value="0"
                                 Background="Transparent" Foreground="{StaticResource BrushProgressFill}" BorderThickness="0" Opacity="0.35"/>
                    <TextBlock Name="txtCMBtn" Text="Run CM" Foreground="#E0E0E0" FontSize="12"
                               HorizontalAlignment="Center" VerticalAlignment="Center"/>
                </Grid>
            </Button>
        </StackPanel>

        <!-- ============================================================
             Status Dock footer  (Blake, 2026-07-31)
             ============================================================
             Design 3 "Status Dock" from the footer mockups: the Deploy tab's
             button plate, the status bar and the stick line fused into ONE
             card mirroring the Command Bar header - accent spine, action row,
             darker status band. Caffeine/winget are ChipBtn indicator chips
             now (dot + label swapped at runtime instead of repainting a
             button background). pnlFooterActions is Deploy-only: a tabMain
             SelectionChanged handler collapses it on the master tabs, so those
             get just the band. brdDriveGone stopped being a fourth plate: it
             shares the band's grid cell and paints it red, so the alarm
             replaces the band instead of stacking under it. brdStickStatus
             keeps its name so Initialize-MasterTabs still unhides it on the
             master; it stays Collapsed on lab machines. -->
        <Border Grid.Row="3" Background="#1e1e1e" CornerRadius="5,12,12,5"
                BorderBrush="#303036" BorderThickness="1" Effect="{StaticResource PanelShadow}">
            <Grid>
                <Grid.ColumnDefinitions>
                    <ColumnDefinition Width="4"/>
                    <ColumnDefinition Width="*"/>
                </Grid.ColumnDefinitions>

                <!-- accent spine, bookending the header's -->
                <Border Grid.Column="0" Background="{StaticResource AccentBrush}" CornerRadius="4,0,0,4"/>

                <Grid Grid.Column="1">
                    <Grid.RowDefinitions>
                        <RowDefinition Height="Auto"/>
                        <RowDefinition Height="Auto"/>
                    </Grid.RowDefinitions>

                    <!-- ROW 1: things you DO on the left, indicator chips right -->
                    <DockPanel Grid.Row="0" Name="pnlFooterActions" Margin="16,10,16,6">
                        <!-- chips are right-docked winget-outermost so the pair
                             reads Caffeine | winget left-to-right -->
                        <Button Name="btnWinget" DockPanel.Dock="Right" Style="{StaticResource ChipBtn}"
                                Margin="8,0,0,4" VerticalAlignment="Center"
                                ToolTip="Shows whether winget (App Installer) is present on this PC. If it shows MISSING, click to install it straight from this drive - no internet needed.">
                            <StackPanel Orientation="Horizontal">
                                <Ellipse Name="dotWinget" Width="8" Height="8" Fill="#55555E" VerticalAlignment="Center"/>
                                <TextBlock Name="txtWingetChip" Text="winget checking..." FontSize="12" FontWeight="SemiBold"
                                           Foreground="#C9C9D2" Margin="7,0,0,0" VerticalAlignment="Center"/>
                            </StackPanel>
                        </Button>
                        <Button Name="btnCaffeine" DockPanel.Dock="Right" Style="{StaticResource ChipBtn}"
                                Margin="8,0,0,4" VerticalAlignment="Center"
                                ToolTip="Keeps this PC awake while installs run. Click to toggle.">
                            <StackPanel Orientation="Horizontal">
                                <Ellipse Name="dotCaffeine" Width="8" Height="8" Fill="#55555E" VerticalAlignment="Center"/>
                                <TextBlock Name="txtCaffeineChip" Text="Caffeine OFF" FontSize="12" FontWeight="SemiBold"
                                           Foreground="#C9C9D2" Margin="7,0,0,0" VerticalAlignment="Center"/>
                            </StackPanel>
                        </Button>
                        <WrapPanel>
                            <!-- The row's ONE jewel-filled button: the only thing
                                 here that writes machine state (rule 1). -->
                            <Button Name="btnInstallMissing" Content="Install All Missing" Padding="18,9" Margin="0,0,8,4"
                                    Style="{StaticResource PrimaryButton}"/>
                            <!-- Verify = validate-and-mend, closest to rule 3; the
                                 single-jewel invariant settles the tie (install has
                                 the bigger blast radius). -->
                            <Button Name="btnShortcuts" Content="Verify Shortcuts" Padding="18,9" Margin="0,0,8,4"
                                    Style="{StaticResource SecondaryButton}"/>
                            <Button Name="btnPKI" Content="PKI Check" Padding="18,9" Margin="0,0,8,4"
                                    Style="{StaticResource SecondaryButton}"/>
                            <!-- Rule 2: deletes files -> red jewel, and deliberately
                                 NOT the rightmost slot (the spec forbids danger in
                                 the default/edge position). -->
                            <Button Name="btnCleanTemp" Content="Clean Temp Files" Padding="18,9" Margin="0,0,8,4"
                                    Style="{StaticResource DangerButton}"
                                    ToolTip="Big installers (MATLAB, Vivado, Ansys) are staged to C:\LabDeployOffload_Temp before installing and deleted afterwards. If a run crashed, tens of GB can be stranded there. This finds and removes ONLY the files this tool creates, and shows you the list before deleting anything."/>
                        </WrapPanel>
                    </DockPanel>

                    <!-- ROW 2: the status band. txtStatus fills left; the master's
                         stick/fleet line docks right with a MASTER eyebrow. Both
                         single-line with ellipsis + self-tooltip. -->
                    <Border Grid.Row="1" Background="#18181D" BorderBrush="#2C2C34" BorderThickness="0,1,0,0"
                            CornerRadius="0,0,12,0" Padding="16,9">
                        <DockPanel>
                            <StackPanel Name="brdStickStatus" DockPanel.Dock="Right" Orientation="Horizontal"
                                        Visibility="Collapsed" VerticalAlignment="Center" Margin="18,0,0,0" MaxWidth="640">
                                <TextBlock Text="MASTER" FontSize="10" FontWeight="Bold" Foreground="#63636D"
                                           VerticalAlignment="Center" Margin="0,1,8,0"/>
                                <TextBlock Name="txtStickStatus" Foreground="#A9A9B4" FontSize="12.5" Text="--"
                                           VerticalAlignment="Center" TextTrimming="CharacterEllipsis"
                                           ToolTip="{Binding Text, RelativeSource={RelativeSource Self}}"/>
                            </StackPanel>
                            <TextBlock Name="txtStatus" Text="Starting..." Foreground="#8a8a95" FontSize="12.5"
                                       VerticalAlignment="Center" TextTrimming="CharacterEllipsis"
                                       ToolTip="{Binding Text, RelativeSource={RelativeSource Self}}"/>
                        </DockPanel>
                    </Border>

                    <!-- Drive-removed alarm: same cell as the band, painted red.
                         Loud on purpose: once the stick is gone nothing is being
                         logged, so a quiet failure would let a tech keep working
                         while the session records nothing. -->
                    <Border Grid.Row="1" Name="brdDriveGone" Background="#6E1E1E" BorderBrush="#7E2E2E"
                            BorderThickness="0,1,0,0" CornerRadius="0,0,12,0" Padding="16,9" Visibility="Collapsed">
                        <TextBlock Name="txtDriveGone" Foreground="#FFD9D6" FontSize="12.5" FontWeight="SemiBold" TextWrapping="Wrap"
                                   Text="This drive has been disconnected."/>
                    </Border>
                </Grid>
            </Grid>
        </Border>
    </Grid>
</Window>
'@

# ============================================================
#  Create Window + Get Element References
# ============================================================
$reader = New-Object System.Xml.XmlNodeReader $xaml
$window = [System.Windows.Markup.XamlReader]::Load($reader)

# --- Console-hide P/Invoke (defined here; actually hidden right before the GUI
# shows, so the console stays visible through ALL init and any startup error) ---
try {
    if (-not ([System.Management.Automation.PSTypeName]'LabDeploy.Win32').Type) {
        Add-Type -Namespace LabDeploy -Name Win32 -MemberDefinition '
[System.Runtime.InteropServices.DllImport("kernel32.dll")] public static extern System.IntPtr GetConsoleWindow();
[System.Runtime.InteropServices.DllImport("user32.dll")] public static extern bool ShowWindow(System.IntPtr hWnd, int nCmdShow);'
    }
} catch { }

# --- Fit the window to THIS screen's work area ---
# Lab laptops (smaller screens / 125-150% DPI scaling) can render the default
# 745-tall window taller than the visible desktop, pushing the title bar (and
# min/close buttons) off the top edge - "full screen but not", can't minimize
# or exit. Clamp to the work area (DIPs, DPI-correct) and center within it so
# the title bar is ALWAYS on-screen and reachable, on any machine.
try {
    $wa = [System.Windows.SystemParameters]::WorkArea
    $marg = 16
    if ($window.Width  -gt ($wa.Width  - $marg)) { $window.Width  = [math]::Floor($wa.Width  - $marg) }
    if ($window.Height -gt ($wa.Height - $marg)) { $window.Height = [math]::Floor($wa.Height - $marg) }
    $window.Left = $wa.Left + [math]::Max(0, [math]::Floor(($wa.Width  - $window.Width)  / 2))
    $window.Top  = $wa.Top  + [math]::Max(0, [math]::Floor(($wa.Height - $window.Height) / 2))
} catch { }

$txtAdminBadge     = $window.FindName('txtAdminBadge')
$txtHostname       = $window.FindName('txtHostname')
$txtUser           = $window.FindName('txtUser')
$cmbRoom           = $window.FindName('cmbRoom')
$txtSummary        = $window.FindName('txtSummary')
$btnRefreshAll     = $window.FindName('btnRefreshAll')
$btnSyncCloud      = $window.FindName('btnSyncCloud')
$pnlApps           = $window.FindName('pnlApps')
$scrApps           = $window.FindName('scrApps')
$btnInstallMissing = $window.FindName('btnInstallMissing')

# Scroll speed: 75% of the Windows default (Blake, 2026-07-28 for the card list;
# 2026-07-29 extended to every Master tab, which had been left at stock rate).
# WPF has no scroll-rate property, so intercept the wheel and scroll a scaled
# distance ourselves. PreviewMouseWheel fires before the ScrollViewer's own
# handler, and marking it Handled stops the default full-speed scroll from ALSO
# running - without that you get both and it scrolls further, not less.
$script:ScrollScale = 0.75

# One implementation for every ScrollViewer in the tool, so the rate can never
# drift between the main window and the Master tabs. Call this for any
# ScrollViewer added in future - a new tab does NOT inherit it automatically.
function Add-SlowScroll {
    param($ScrollViewer)
    if (-not $ScrollViewer) { return }
    $ScrollViewer.Add_PreviewMouseWheel({
        param($s, $e)
        try {
            # SystemParameters.WheelScrollLines respects the user's own Windows
            # mouse setting, so this scales THEIR preference rather than
            # replacing it. -1 means "a screenful per notch"; fall back to 3.
            #
            # The [int] cast is NOT decoration. If $lines is ever a STRING,
            # "$lines -le 0" does a culture-aware STRING compare in which "-1"
            # sorts ABOVE "0" (the hyphen is effectively ignored) - so the guard
            # returns false, -1 survives, and the wheel scrolls BACKWARDS at the
            # wrong speed. The property is typed int today; the cast means this
            # cannot break if that ever changes.
            $lines = [int][System.Windows.SystemParameters]::WheelScrollLines
            if ($lines -le 0) { $lines = 3 }
            # ~16 px per line is WPF's internal scroll increment.
            $dist = ($e.Delta / 120.0) * $lines * 16.0 * $script:ScrollScale
            $s.ScrollToVerticalOffset($s.VerticalOffset - $dist)
            $e.Handled = $true
        } catch { }   # never let a scroll event break the window
    })
}

Add-SlowScroll -ScrollViewer $scrApps
$btnShortcuts      = $window.FindName('btnShortcuts')
$btnPKI            = $window.FindName('btnPKI')
$btnCaffeine       = $window.FindName('btnCaffeine')
$btnWinget         = $window.FindName('btnWinget')
# Status Dock chips + footer action row (Blake, 2026-07-31)
$dotCaffeine       = $window.FindName('dotCaffeine')
$txtCaffeineChip   = $window.FindName('txtCaffeineChip')
$dotWinget         = $window.FindName('dotWinget')
$txtWingetChip     = $window.FindName('txtWingetChip')
$pnlFooterActions  = $window.FindName('pnlFooterActions')
$tabMain           = $window.FindName('tabMain')
$tabDeploy         = $window.FindName('tabDeploy')
# The Status Dock is global (Grid.Row 3), but its action row is Deploy's:
# collapse it on the master tabs so they get just the status band. Guarded on
# OriginalSource - SelectionChanged from ComboBoxes inside tab content
# bubbles up to the TabControl and must not retrigger this.
$tabMain.Add_SelectionChanged({
    param($s, $e)
    if ($e.OriginalSource -ne $tabMain) { return }
    $pnlFooterActions.Visibility = if ($tabMain.SelectedItem -eq $tabDeploy) {
        [System.Windows.Visibility]::Visible
    } else {
        [System.Windows.Visibility]::Collapsed
    }
})
$btnCleanTemp      = $window.FindName('btnCleanTemp')
$btnCleanTemp.Add_Click({ Invoke-TempCleanupFlow })

# ============================================================
#  UI scale
# ============================================================
# LayoutTransform, NOT RenderTransform: LayoutTransform re-runs layout at the
# new size, so text is re-rendered crisply and panels re-wrap. RenderTransform
# (and a ViewBox) would stretch the finished bitmap - blurry glyphs and type
# sizes that stop meaning anything. Applied to the root Grid so the window
# chrome itself is untouched.
$script:UiBaseSize = $null   # window size at 100%, captured once
function Set-UiScale {
    param([double]$Scale, [switch]$Silent)
    if ($Scale -lt 0.5) { $Scale = 0.5 }
    if ($Scale -gt 3.0) { $Scale = 3.0 }
    $root = $window.Content
    if (-not $root) { return }
    if (-not $script:UiBaseSize) { $script:UiBaseSize = @{ W = $window.Width; H = $window.Height } }
    if ([math]::Abs($Scale - 1.0) -lt 0.001) {
        $root.LayoutTransform = $null
    } else {
        $root.LayoutTransform = New-Object System.Windows.Media.ScaleTransform($Scale, $Scale)
    }
    # Grow the window so scaled-up content still fits, clamped to the work area.
    # Only ever GROWS - shrinking would stomp a window the tech sized by hand.
    try {
        $wa = [System.Windows.SystemParameters]::WorkArea
        $wantW = [math]::Min($script:UiBaseSize.W * $Scale, $wa.Width  - 20)
        $wantH = [math]::Min($script:UiBaseSize.H * $Scale, $wa.Height - 20)
        if ($wantW -gt $window.Width)  { $window.Width  = $wantW }
        if ($wantH -gt $window.Height) { $window.Height = $wantH }
        # MinWidth/Height are in unscaled units; at 200% they would pin the
        # window larger than the screen and it could not be resized back.
        $window.MinWidth  = [math]::Min(640 * $Scale, $wa.Width  - 20)
        $window.MinHeight = [math]::Min(400 * $Scale, $wa.Height - 20)
    } catch { }
    $script:UiScale = $Scale
    if (-not $Silent) {
        Save-GuiSettings
        Write-LabLog -Event 'ui.scale_changed' -Data @{ scale = $Scale }
        $txtStatus.Text = "Display size set to $([int]($Scale * 100))% - saved on this drive, so it stays this size next time."
    }
}

# ============================================================
#  Fit to window  (Blake, 2026-07-30)
# ============================================================
# The complaint this fixes: dragging the window smaller used to keep the UI at
# its full size and just hang scrollbars on it, so a small window showed a
# small PORTION of the app instead of the whole app, smaller.
#
# Same mechanism as Set-UiScale (LayoutTransform on the root Grid, so glyphs
# re-render crisply and WrapPanels re-wrap - see the note above it), but the
# factor is derived from the window instead of picked from a menu. Two rules
# keep it from fighting the user:
#   * it NEVER resizes the window (Set-UiScale does; that would be a feedback
#     loop - resize -> scale -> resize),
#   * the baseline is the window's size the FIRST time we measure it, not the
#     920x745 in the XAML. The master widens the window at startup for its extra
#     tabs; treating 920 as 100% would magnify the master by ~50% on launch, which
#     is the opposite of why it was widened.
$script:UiFitMin = 0.55   # below this the 10px header labels stop being legible
$script:UiFitMax = 2.0
function Update-UiFit {
    if (-not $script:UiFit) { return }
    $root = $window.Content
    if (-not $root) { return }
    $w = $window.ActualWidth; $h = $window.ActualHeight
    if ($w -le 0 -or $h -le 0) { return }   # not laid out yet
    if (-not $script:UiFitBase) { $script:UiFitBase = @{ W = $w; H = $h } }
    # min of the two ratios = "fit", the same rule a Viewbox uses. Height counts
    # as well as width: a short window otherwise keeps a full-height app list
    # that only scrollbars could reach.
    $s = [math]::Min($w / $script:UiFitBase.W, $h / $script:UiFitBase.H)
    if ($s -lt $script:UiFitMin) { $s = $script:UiFitMin }
    if ($s -gt $script:UiFitMax) { $s = $script:UiFitMax }
    # Quantise to 1%: a drag fires SizeChanged per pixel and each one costs a
    # full layout pass over ~19 app cards. 1% steps are invisible and cheap.
    $s = [math]::Round($s, 2)
    if ($null -ne $script:UiFitApplied -and [math]::Abs($s - $script:UiFitApplied) -lt 0.005) { return }
    $script:UiFitApplied = $s
    if ([math]::Abs($s - 1.0) -lt 0.005) { $root.LayoutTransform = $null }
    else { $root.LayoutTransform = New-Object System.Windows.Media.ScaleTransform($s, $s) }
}
function Enable-UiFit {
    param([switch]$Silent)
    $script:UiFit = $true
    $script:UiFitApplied = $null
    # A previous fixed % left MinWidth/MinHeight scaled up (see Set-UiScale).
    # In fit mode the content shrinks instead, so hand them back their real
    # floor or the window cannot be dragged small enough to see it work.
    try { $window.MinWidth = 640; $window.MinHeight = 400 } catch { }
    Update-UiFit
    if (-not $Silent) {
        Save-GuiSettings
        Write-LabLog -Event 'ui.fit_enabled' -Data @{ scale = $script:UiFitApplied }
        $txtStatus.Text = 'Display size now follows the window - drag it bigger or smaller and the whole UI scales with it. Saved on this drive.'
    }
}
# Repaint on every resize. Cheap when nothing changed (Update-UiFit early-outs).
$window.Add_SizeChanged({ Update-UiFit })
# Belt and braces: if the initial layout ever failed to raise SizeChanged, the
# baseline would instead be captured on the tech's FIRST drag - so that drag
# would compute 1.0 and appear to do nothing. ContentRendered always fires.
$window.Add_ContentRendered({ Update-UiFit })

$cmbUiScale = $window.FindName('cmbUiScale')
# Index 0 is the MODE, the rest are fixed sizes. Keep it first: it is the
# default and the answer to "the text is too small on this monitor".
[void]$cmbUiScale.Items.Add('Fit to window')
foreach ($s in $script:UiScaleSteps) {
    $lbl = '{0}%{1}' -f [int]($s * 100), $(if ([math]::Abs($s - 1.0) -lt 0.001) { '  (normal)' } else { '' })
    [void]$cmbUiScale.Items.Add($lbl)
}
if ($script:UiFit) {
    $cmbUiScale.SelectedIndex = 0
} else {
    # select the saved value (nearest step, so a hand-edited 1.3 still shows sanely)
    $best = 0; $bestDiff = [double]::MaxValue
    for ($i = 0; $i -lt $script:UiScaleSteps.Count; $i++) {
        $d = [math]::Abs($script:UiScaleSteps[$i] - $script:UiScale)
        if ($d -lt $bestDiff) { $bestDiff = $d; $best = $i }
    }
    $cmbUiScale.SelectedIndex = $best + 1
}
$cmbUiScale.Add_SelectionChanged({
    $i = $cmbUiScale.SelectedIndex
    if ($i -eq 0) { Enable-UiFit }
    elseif ($i -ge 1 -and $i -le $script:UiScaleSteps.Count) {
        $script:UiFit = $false
        $script:UiFitApplied = $null
        Set-UiScale -Scale $script:UiScaleSteps[$i - 1]
    }
})
$btnGPUpdate       = $window.FindName('btnGPUpdate')
$pbGP              = $window.FindName('pbGP')
$txtGPBtn          = $window.FindName('txtGPBtn')
$btnCMActions      = $window.FindName('btnCMActions')
$pbCM              = $window.FindName('pbCM')
$txtCMBtn          = $window.FindName('txtCMBtn')
# pnlHealth retired 2026-07-31 - health lives in the tab-row pill (brdHealthPill)
$chkAutoScan       = $window.FindName('chkAutoScan')
$chkOffload        = $window.FindName('chkOffload')
$txtStatus         = $window.FindName('txtStatus')
$txtDecode         = $window.FindName('txtDecode')
$txtMasterBadge       = $window.FindName('txtMasterBadge')

# Master Mode: master PC only (C:\LabDeployMaster exists). On a lab machine none
# of this runs, the master tabs stay Collapsed, and the window is the same size
# and shape it has always been - the field face is untouched.
if ($script:IsMaster) {
    try {
        # The tabs need room the 920x745 deploy window doesn't have. Clamped to
        # the work area so a small lab monitor can't get an off-screen window.
        $wa = [System.Windows.SystemParameters]::WorkArea
        $window.Width  = [Math]::Min(1180, [Math]::Max(920, $wa.Width  - 40))
        $window.Height = [Math]::Min(880,  [Math]::Max(745, $wa.Height - 40))
        $window.WindowStartupLocation = 'CenterScreen'
        if ($txtMasterBadge) {
            # no leading spaces: the Command Bar eyebrow spaces badges by Margin
            $txtMasterBadge.Text = 'MASTER'
            $txtMasterBadge.Visibility = [System.Windows.Visibility]::Visible
        }
        Initialize-MasterTabs
    } catch {
        Write-LabLog -Event 'master.tabs_error' -Data @{ errorCode = 'E70'; error = $_.Exception.Message; at = $_.ScriptStackTrace }
        # A broken master tab must never cost the tech the Deploy tab, which is
        # the only thing that actually installs software.
        $txtStatus.Text = "[E70] Master tabs failed to load: $($_.Exception.Message) - the Deploy tab still works."
    }
}

$txtHostname.Text = $env:COMPUTERNAME

# Decoded campus identity under the hostname: "ENG 103 - LAB r34 - #20 - Student".
# Only shown when the hostname matches the campus convention; unknown parts are
# flagged in the tooltip rather than guessed at.
$script:MachineDecode = ConvertFrom-LabHostname
if ($script:MachineDecode.Matched) {
    $d = $script:MachineDecode
    $bldgTxt = if ($d.BuildingAbbr) { $d.BuildingAbbr } else { '?bldg' }
    $roleTxt = if ($d.Machine -eq 1) { $d.Role } else { 'Student' }
    # Header shows the short form "ENG 103 #20"; the full breakdown (type,
    # refresh, role) still lives in the tooltip below.
    $txtDecode.Text = ('{0} {1} #{2}' -f $bldgTxt, $d.Room, $d.Machine)
    $tip = "Decoded from the campus naming convention:`nBuilding: $($d.Building) = $($d.BuildingName)`nRoom: $($d.Room)`nType: $($d.Type)`nRefresh: $($d.Refresh)`nMachine #: $($d.Machine)`nRole: $($d.Role)"
    if ($d.Flags.Count) { $tip += "`nFlags: $($d.Flags -join ', ')" }
    $txtDecode.ToolTip = $tip
    $txtDecode.Visibility = [System.Windows.Visibility]::Visible
    if ($d.Flags.Count) { $txtDecode.Foreground = $script:BrushYellow }
} else {
    # an undecoded name used to just show NOTHING - now it says so, and the
    # tooltip explains why and where to go (DEFAULT room / the Machines tab).
    $txtDecode.Text = 'name not decoded'
    $txtDecode.Foreground = $script:BrushMuted
    $txtDecode.ToolTip = "'$env:COMPUTERNAME' does not follow the naming grammar ($($script:MachineDecode.Flags -join '; ')).`nNothing is broken: this machine uses the DEFAULT room profile until a person assigns it a room in Rooms & Rules -> Manual Entry."
    $txtDecode.Visibility = [System.Windows.Visibility]::Visible
}
Write-LabLog -Event 'machine.decoded' -Data @{
    matched = $script:MachineDecode.Matched
    building = $script:MachineDecode.Building; buildingAbbr = $script:MachineDecode.BuildingAbbr
    room = $script:MachineDecode.Room; type = $script:MachineDecode.Type
    refresh = $script:MachineDecode.Refresh; machine = $script:MachineDecode.Machine
    role = $script:MachineDecode.Role; flags = ($script:MachineDecode.Flags -join '; ')
}
# Imaging stamp into the ledger: the Fleet Map shows each machine's image date,
# so every session records it (date parsed from C:\timestamp_Cart.txt content,
# else that file's creation/write time; absent = machine wasn't imaged normally)
try {
    $imgD = Get-ImagedDate
    $imgCreated = $null
    if (Test-Path 'C:\timestamp_Cart.txt') { try { $imgCreated = (Get-Item 'C:\timestamp_Cart.txt').CreationTime.ToString('yyyy-MM-dd HH:mm:ss') } catch { } }
    Write-LabLog -Event 'machine.imaged_stamp' -Data @{
        present = (Test-Path 'C:\timestamp_Cart.txt')
        date = $(if ($imgD) { $imgD.ToString('yyyy-MM-dd') } else { $null })
        fileCreated = $imgCreated
    }
} catch { }
foreach ($w in $script:BuildingsWarnings) {
    Write-LabLog -Event 'config.buildings_warning' -Data @{ warning = $w }
}
if ($script:BuildingsWarnings.Count) {
    $txtStatus.Text = "buildings.json warning: $($script:BuildingsWarnings[0])"
}

if ($script:UserName -and $script:UserProfilePath) {
    $txtUser.Text = $script:UserName
    $txtUser.Foreground = $script:BrushText
} elseif ($script:UserName) {
    $txtUser.Text = "$($script:UserName) (no profile)"
    $txtUser.Foreground = $script:BrushYellow
} else {
    $txtUser.Text = 'None detected'
    $txtUser.Foreground = $script:BrushMuted
}

if (-not $script:IsAdmin) {
    # no leading spaces: the Command Bar eyebrow spaces badges by Margin
    $txtAdminBadge.Text = 'NOT ADMIN'
    $txtAdminBadge.Foreground = $script:BrushRed
}

# ============================================================
#  UI Helper: Create an App Card
# ============================================================
function New-AppCard {
    param([string]$AppId)

    $appDef      = $script:AppsConfig.apps.$AppId
    $displayName = if ($appDef) { $appDef.displayName } else { $AppId }
    $method      = if ($appDef -and $appDef.install -and $appDef.install.method) { [string]$appDef.install.method } else { '?' }
    # Config-driven kill switch: an app can be disabled in apps.json (e.g. its
    # installer file is missing). The card is still shown, but greyed-out and
    # inert -- no scan, no install/uninstall. Flip disabled to false to restore.
    $isDisabled  = [bool]($appDef -and $appDef.disabled)

    # ============================================================
    # Rail row (Blake, 2026-07-31), matching design/body-redesign-mockups.html:
    # [4px status SPINE][mid: name+tag / detail / chips / progress][actions].
    # The spine is a Rectangle stored under the historic 'Dot' key - Rectangle
    # has .Fill, so every consumer that recolours the old status dot recolours
    # the spine instead, untouched. Left corners square-ish, right corners
    # round: the rail signature.
    # ============================================================
    $border = New-Object System.Windows.Controls.Border
    $border.Padding         = [System.Windows.Thickness]::new(0)
    $border.Margin          = [System.Windows.Thickness]::new(0, 0, 0, 7)
    $border.Background      = $script:BrushRowBg
    $border.BorderBrush     = $script:BrushRowBorder
    $border.BorderThickness = [System.Windows.Thickness]::new(1)
    $border.CornerRadius    = [System.Windows.CornerRadius]::new(4, 8, 8, 4)

    # -- Grid: [spine 4px] [mid *] [actions auto] --
    $grid = New-Object System.Windows.Controls.Grid
    foreach ($w in @(4, -1, 0)) {
        $col = New-Object System.Windows.Controls.ColumnDefinition
        if ($w -gt 0) { $col.Width = [System.Windows.GridLength]::new($w) }
        elseif ($w -eq -1) { $col.Width = [System.Windows.GridLength]::new(1, [System.Windows.GridUnitType]::Star) }
        else { $col.Width = [System.Windows.GridLength]::Auto }
        $grid.ColumnDefinitions.Add($col)
    }

    # -- Status spine (key 'Dot': .Fill contract preserved) --
    $dot = New-Object System.Windows.Shapes.Rectangle
    $dot.Width   = 4
    $dot.RadiusX = 2; $dot.RadiusY = 2
    $dot.Fill    = $script:BrushGray
    $dot.VerticalAlignment   = [System.Windows.VerticalAlignment]::Stretch
    $dot.HorizontalAlignment = [System.Windows.HorizontalAlignment]::Left
    [System.Windows.Controls.Grid]::SetColumn($dot, 0)
    $grid.Children.Add($dot) | Out-Null

    # -- Mid panel --
    $info = New-Object System.Windows.Controls.StackPanel
    $info.VerticalAlignment = [System.Windows.VerticalAlignment]::Center
    $info.Margin = [System.Windows.Thickness]::new(14, 11, 14, 12)
    [System.Windows.Controls.Grid]::SetColumn($info, 1)

    # name + method tag inline (tag moved off the right column, per the mock)
    $namePanel = New-Object System.Windows.Controls.WrapPanel
    $namePanel.Orientation = [System.Windows.Controls.Orientation]::Horizontal

    $nameBlock = New-Object System.Windows.Controls.TextBlock
    $nameBlock.Text       = $displayName
    $nameBlock.FontSize   = 13.5
    $nameBlock.FontWeight = [System.Windows.FontWeights]::SemiBold
    $nameBlock.Foreground = $script:BrushText
    $nameBlock.VerticalAlignment = [System.Windows.VerticalAlignment]::Center
    $namePanel.Children.Add($nameBlock) | Out-Null
    $info.Children.Add($namePanel) | Out-Null

    # Detail row: selectable/copyable TextBox (the Open-file-location action
    # now lives in the "..." menu; created below, parented into the menu)
    $detailPanel = New-Object System.Windows.Controls.DockPanel

    $btnOpen = New-Object System.Windows.Controls.Button
    $btnOpen.Content    = 'Open file location'
    $btnOpen.Visibility = [System.Windows.Visibility]::Collapsed
    $btnOpen.ToolTip    = 'Open location in Explorer'
    $btnOpen.Tag        = $AppId

    $btnOpen.Add_Click({
        $id   = $this.Tag
        $card = $script:Cards[$id]
        if (-not $card) { return }
        $text = $card.Detail.Text
        $path = ($text -split '  \(|  \[')[0].Trim()
        if (-not $path) { return }
        try {
            if (Test-Path $path -PathType Leaf) {
                Start-Process explorer.exe -ArgumentList "/select,`"$path`""
            } elseif (Test-Path $path -PathType Container) {
                Start-Process explorer.exe -ArgumentList "`"$path`""
            }
        } catch { }
    })

    # TextBox styled to look like a label but supports select + copy
    $detailBlock = New-Object System.Windows.Controls.TextBox
    $detailBlock.Text            = 'Scanning...'
    $detailBlock.FontSize        = 11
    $detailBlock.Foreground      = $script:BrushMuted
    $detailBlock.Background      = [System.Windows.Media.Brushes]::Transparent
    $detailBlock.BorderThickness = [System.Windows.Thickness]::new(0)
    $detailBlock.IsReadOnly      = $true
    $detailBlock.IsReadOnlyCaretVisible = $false
    $detailBlock.Padding         = [System.Windows.Thickness]::new(0)
    $detailBlock.Margin          = [System.Windows.Thickness]::new(0, 3.5, 0, 0)
    $detailBlock.ToolTip         = 'Select text to copy. Open file location lives in the ... menu.'
    $detailPanel.Children.Add($detailBlock) | Out-Null

    $info.Children.Add($detailPanel) | Out-Null

    # Progress bar (hidden unless an install/uninstall is running).
    # Indeterminate until a percent source reports; then shows real progress.
    $pbar = New-Object System.Windows.Controls.ProgressBar
    $pbar.Height          = 3
    $pbar.Minimum         = 0
    $pbar.Maximum         = 100
    $pbar.Margin          = [System.Windows.Thickness]::new(0, 8, 0, 0)
    $pbar.MaxWidth        = 340
    $pbar.HorizontalAlignment = [System.Windows.HorizontalAlignment]::Left
    $pbar.Foreground      = $script:BrushProgressFill   # the app's one gradient
    $pbar.Background      = $script:BrushProgressTrack
    $pbar.BorderThickness = [System.Windows.Thickness]::new(0)
    $pbar.Visibility      = [System.Windows.Visibility]::Collapsed
    $info.Children.Add($pbar) | Out-Null

    $grid.Children.Add($info) | Out-Null

    # -- Install-type tag --
    # Friendly label + color per install type, so techs can tell at a glance
    # how each app installs. Overridable per app via install.methodLabel in
    # apps.json (used for the big vendor images like MATLAB / Vivado).
    $methodLabel = $null
    $tagBrush    = $script:BrushChipGray   # default gray
    if ($appDef -and $appDef.install.methodLabel) {
        $methodLabel = $appDef.install.methodLabel
        $tagBrush    = $script:BrushTagMaroon   # maroon: special/image
    } else {
        switch ($method) {
            'winget' { $methodLabel = 'Winget Install'; $tagBrush = $script:BrushTagBlue }
            'copy'   { $methodLabel = 'File Copy';      $tagBrush = $script:BrushTagGreen }
            'msi'    { $methodLabel = 'MSI Install';    $tagBrush = $script:BrushTagPurple }
            'psadt'  { $methodLabel = 'PSADT Package' }
            'exe'    {
                if ($appDef -and -not $appDef.install.arguments) {
                    $methodLabel = 'Interactive Install'
                    $tagBrush    = $script:BrushTagBrown   # orange-brown: needs clicks
                } else {
                    $methodLabel = 'Silent EXE'
                }
            }
            default  { $methodLabel = $method.ToUpper() }
        }
    }
    # Offload apps get an "Offload" prefix on the type tag, e.g. "Offload Image Install"
    if ($appDef -and $appDef.install.offload) {
        $methodLabel = "Offload $methodLabel"
        $tagBrush    = $script:BrushTagTeal   # teal-green: staged
    }
    # Version of the installer on the drive - "Silent EXE  v1.128.1". Reading
    # it means touching the (slow) USB drive: a dir listing plus exe version
    # metadata, up to a few hundred ms per app on a cold stick. Card creation
    # therefore only uses an ALREADY-CACHED value; uncached apps get their tag
    # backfilled by the version timer after the room is on screen, so building
    # 40+ cards never blocks the window on 40 sequential drive reads.
    $tagBase = $methodLabel
    if ($script:SourceVerCache.ContainsKey($AppId)) {
        $srcVer = $script:SourceVerCache[$AppId]
        if ($srcVer) { $methodLabel = "$methodLabel  v$srcVer" }
    } elseif (-not $isDisabled) {
        $script:verQueue.Enqueue($AppId)
        if (-not $script:verTimer.IsEnabled) { $script:verTimer.Start() }
    }

    # Method tag: rides the NAME line now (grey pill per the Rail mock; the
    # method colour still lives in the tooltip text and the App info popover)
    $tag = New-Object System.Windows.Controls.Border
    $tag.CornerRadius      = [System.Windows.CornerRadius]::new(3)
    $tag.Padding           = [System.Windows.Thickness]::new(7, 2, 7, 2)
    $tag.Margin            = [System.Windows.Thickness]::new(8, 0, 0, 0)
    $tag.VerticalAlignment = [System.Windows.VerticalAlignment]::Center
    $tag.Background        = $script:BrushTagNeutral

    $tagText = New-Object System.Windows.Controls.TextBlock
    $tagText.Text       = $methodLabel
    $tagText.FontSize   = 9.5
    $tagText.FontWeight = [System.Windows.FontWeights]::Bold
    $tagText.Foreground = $script:BrushTagInk
    $tag.Child = $tagText
    # Hovering the tag shows exactly which file on the drive installs this app
    if ($appDef -and $appDef.install.sourceSub) { $tag.ToolTip = "Installs from: $($appDef.install.sourceSub)" }
    elseif ($appDef -and $appDef.install.fallback.sourceSub) { $tag.ToolTip = "Installs via winget; backup on drive: $($appDef.install.fallback.sourceSub)" }
    $namePanel.Children.Add($tag) | Out-Null

    # Chips row: exception-only pills under the detail line (shortcut missing /
    # app-opened confirm) + the desktop-icon policy checkbox. Inserted before
    # the progress bar so the mid column reads name / detail / chips / progress.
    $tagPanel = New-Object System.Windows.Controls.WrapPanel
    $tagPanel.Orientation = [System.Windows.Controls.Orientation]::Horizontal
    $tagPanel.Margin      = [System.Windows.Thickness]::new(0, 8.5, 0, 0)
    $info.Children.Insert(2, $tagPanel) | Out-Null

    # Shortcut chip: shown ONLY when the shortcut is missing (exception-only);
    # the chip IS the fix button - clicking it creates the shortcut.
    # STADIUM SHAPE, matching the footer's Caffeine/winget chips and the health
    # pill on the tab rail: Height 28 + CornerRadius 14 (Blake, 2026-08-06).
    # Was radius 20 on an auto-height border, which is a DIFFERENT shape - the
    # radius exceeded half the height, so WPF drew the ends as an oval lens
    # rather than a true stadium. Half the height is the whole trick; see the
    # ChipBtn style's own note about why 999 does not work here like CSS.
    $sbox = New-Object System.Windows.Controls.Border
    $sbox.CornerRadius      = [System.Windows.CornerRadius]::new(14)
    $sbox.Height            = 28
    $sbox.Padding           = [System.Windows.Thickness]::new(13, 0, 13, 0)
    $sbox.Margin            = [System.Windows.Thickness]::new(0, 0, 7, 0)
    $sbox.BorderThickness   = [System.Windows.Thickness]::new(1)
    $sbox.VerticalAlignment = [System.Windows.VerticalAlignment]::Center
    $sbox.Cursor            = [System.Windows.Input.Cursors]::Hand
    $sbox.Visibility        = [System.Windows.Visibility]::Collapsed
    $sbox.Tag               = $AppId
    $sbox.ToolTip           = 'This app''s shortcut is missing from the shared (Public) desktop. Click to create it.'
    $stext = New-Object System.Windows.Controls.TextBlock
    $stext.FontSize   = 10
    $stext.FontWeight = [System.Windows.FontWeights]::Bold
    $stext.Foreground = $script:BrushChipBadInk
    # The border now has a FIXED height, so the text must centre itself in it -
    # without this it sits at the top of the pill.
    $stext.VerticalAlignment = [System.Windows.VerticalAlignment]::Center
    $sbox.Child = $stext
    $sbox.Add_MouseLeftButtonUp({
        $id = $this.Tag
        $nm = $script:AppsConfig.apps.$id.displayName
        $st = Repair-AppShortcut -AppId $id
        if (-not $st.Applicable)  { $txtStatus.Text = "$nm does not use a desktop shortcut" }
        elseif ($st.Present)      { $txtStatus.Text = "Shortcut created for $($nm): '$($st.Lnk)' is on the shared desktop" }
        else                      { $txtStatus.Text = "Could not create a shortcut for $nm - no launchable exe found" }
        Write-LabLog -Event 'shortcut.chip_fix' -Data @{ appId = $id; applicable = $st.Applicable; present = $st.Present; lnk = $st.Lnk }
        Update-ShortcutBox -AppId $id   # chip hides itself on success
    })
    $tagPanel.Children.Add($sbox) | Out-Null

    # Desktop-icon POLICY box. Visible on any card that can have an icon (even
    # before it is installed - you want to set policy up front), unlike the chip
    # above which only reports state once installed. Ticked = keep dropping an
    # icon on the shared desktop after installs, which is how it has always
    # behaved, so absent config = ticked.
    $chkIcon = New-Object System.Windows.Controls.CheckBox
    $chkIcon.Content   = 'Desktop icon'
    $chkIcon.FontSize  = 10
    $chkIcon.Foreground = $script:BrushMuted
    $chkIcon.VerticalAlignment = [System.Windows.VerticalAlignment]::Center
    $chkIcon.Margin    = [System.Windows.Thickness]::new(0, 0, 10, 0)
    $chkIcon.Tag       = $AppId
    $chkIcon.ToolTip   = 'Ticked: installing this app also puts its icon on the shared (Public) desktop, and Verify Shortcuts keeps it there. Unticked: no icon is created automatically - the Shortcut button still makes one on demand. Saved to apps.json and shared with every stick.'
    $chkIcon.IsChecked = (Test-AppAutoShortcut -AppId $AppId)
    $chkIcon.Visibility = $(if ($appDef -and -not $appDef.noShortcut -and -not $isDisabled) {
        [System.Windows.Visibility]::Visible } else { [System.Windows.Visibility]::Collapsed })
    $chkIcon.Add_Click({
        $id = [string]$this.Tag
        $on = [bool]$this.IsChecked
        if (Set-AppAutoShortcut -AppId $id -Enabled $on) {
            $nm = "$($script:AppsConfig.apps.$id.displayName)"
            $txtStatus.Text = if ($on) {
                "$nm will get a desktop icon after installing (saved - update sticks to share it)"
            } else {
                "$nm will NOT get a desktop icon automatically any more (saved - update sticks to share it). Existing icons are left alone."
            }
            Update-ShortcutBox -AppId $id
        } else {
            $this.IsChecked = -not $on   # save failed - do not let the tick lie
        }
    })
    $tagPanel.Children.Add($chkIcon) | Out-Null

    # "App Opened?" chip (needsOpen apps only): yellow "App Opened?" until the
    # tech confirms they launched it and did the post-install steps, then green
    # "App Opened". Click it to confirm. Hidden for apps that don't need opening.
    # Same stadium shape as the shortcut chip above and the footer chips.
    $obox = New-Object System.Windows.Controls.Border
    $obox.CornerRadius      = [System.Windows.CornerRadius]::new(14)
    $obox.Height            = 28
    $obox.Padding           = [System.Windows.Thickness]::new(13, 0, 13, 0)
    $obox.Margin            = [System.Windows.Thickness]::new(0, 0, 7, 0)
    $obox.BorderThickness   = [System.Windows.Thickness]::new(1)
    $obox.Background        = $script:BrushChipWarnBg
    $obox.BorderBrush       = $script:BrushChipWarnBrd
    $obox.VerticalAlignment = [System.Windows.VerticalAlignment]::Center
    $obox.Cursor            = [System.Windows.Input.Cursors]::Hand
    $obox.Visibility        = [System.Windows.Visibility]::Collapsed
    $obox.ToolTip           = 'Click to confirm you opened this app and did the required first-run updates/installs.'
    $otext = New-Object System.Windows.Controls.TextBlock
    $otext.FontSize   = 10
    $otext.FontWeight = [System.Windows.FontWeights]::Bold
    $otext.Foreground = $script:BrushChipWarnInk
    # Fixed-height border, so centre the text (see the shortcut chip above).
    $otext.VerticalAlignment = [System.Windows.VerticalAlignment]::Center
    $obox.Child = $otext
    $obox.Tag = $AppId
    $obox.Add_MouseLeftButtonUp({ Confirm-AppOpened -AppId $this.Tag })
    $tagPanel.Children.Add($obox) | Out-Null
    # (chips row already lives inside the mid panel - no grid column here)

    # -- Action zone (Rail declutter): ONE state-appropriate primary
    #    (BtnInstall, whose Content/Background Update-AppCard already rewrites),
    #    Uninstall, Cancel-while-running, and a "..." menu holding everything
    #    else. The demoted actions are still real Buttons stored under their
    #    historic keys, so every consumer that toggles their Visibility or
    #    IsEnabled keeps working - they just live inside a Popup now. --
    $btnPanel = New-Object System.Windows.Controls.StackPanel
    $btnPanel.Orientation       = [System.Windows.Controls.Orientation]::Horizontal
    $btnPanel.VerticalAlignment = [System.Windows.VerticalAlignment]::Center
    $btnPanel.Margin            = [System.Windows.Thickness]::new(0, 0, 12, 0)
    [System.Windows.Controls.Grid]::SetColumn($btnPanel, 2)

    $smallBtnStyle = $window.FindResource('SmallBtn')

    # Install / Reinstall / Run drivers - the primary slot
    $btnInstall = New-Object System.Windows.Controls.Button
    $btnInstall.Content    = 'Install'
    $btnInstall.FontSize   = 11.5
    $btnInstall.FontWeight = [System.Windows.FontWeights]::SemiBold
    $btnInstall.Padding    = [System.Windows.Thickness]::new(12, 6, 12, 6)
    $btnInstall.Margin     = [System.Windows.Thickness]::new(0, 0, 6, 0)
    $btnInstall.Background = $script:BrushBtnGet
    $btnInstall.Style      = $smallBtnStyle
    $btnInstall.Tag        = $AppId
    $btnPanel.Children.Add($btnInstall) | Out-Null

    # Uninstall
    $btnUninstall = New-Object System.Windows.Controls.Button
    $btnUninstall.Content    = 'Uninstall'
    $btnUninstall.FontSize   = 11.5
    $btnUninstall.FontWeight = [System.Windows.FontWeights]::SemiBold
    $btnUninstall.Padding    = [System.Windows.Thickness]::new(12, 6, 12, 6)
    $btnUninstall.Margin     = [System.Windows.Thickness]::new(0, 0, 6, 0)
    $btnUninstall.Background = $script:BrushBtnUnRail
    $btnUninstall.Style      = $smallBtnStyle
    $btnUninstall.Tag        = $AppId
    $btnUninstall.Visibility = [System.Windows.Visibility]::Collapsed
    $btnPanel.Children.Add($btnUninstall) | Out-Null

    # Cancel (only while an install/uninstall is running)
    $btnCancel = New-Object System.Windows.Controls.Button
    $btnCancel.Content    = 'Cancel'
    $btnCancel.FontSize   = 11.5
    $btnCancel.FontWeight = [System.Windows.FontWeights]::SemiBold
    $btnCancel.Padding    = [System.Windows.Thickness]::new(12, 6, 12, 6)
    $btnCancel.Margin     = [System.Windows.Thickness]::new(0, 0, 6, 0)
    $btnCancel.Background = $script:BrushBtnCancel
    $btnCancel.Style      = $smallBtnStyle
    $btnCancel.Tag        = $AppId
    $btnCancel.Visibility = [System.Windows.Visibility]::Collapsed
    $btnPanel.Children.Add($btnCancel) | Out-Null

    # "..." - opens the overflow menu
    $btnMore = New-Object System.Windows.Controls.Button
    $btnMore.Content    = [char]0x22EF   # â‹¯
    $btnMore.FontSize   = 13
    $btnMore.FontWeight = [System.Windows.FontWeights]::Bold
    $btnMore.Padding    = [System.Windows.Thickness]::new(11, 4, 11, 6)
    $btnMore.Background = $script:BrushBtnNeutral
    $btnMore.Style      = $smallBtnStyle
    $btnMore.Tag        = $AppId
    $btnMore.ToolTip    = 'More: app info, shortcut, quiet updater, open app, file location, refresh'
    $btnPanel.Children.Add($btnMore) | Out-Null

    $grid.Children.Add($btnPanel) | Out-Null
    $border.Child = $grid

    # -- The "..." menu (Popup; StaysOpen=False closes it on any outside click).
    #    Demoted buttons are restyled as left-aligned menu rows here. --
    $mkMenuItem = {
        param($btn, $label)
        $btn.Content    = $label
        $btn.FontSize   = 12
        $btn.Foreground = $script:BrushText
        $btn.Background = $script:BrushMenuBg
        $btn.Padding    = [System.Windows.Thickness]::new(10, 7, 10, 7)
        $btn.Margin     = [System.Windows.Thickness]::new(0)
        $btn.HorizontalAlignment        = [System.Windows.HorizontalAlignment]::Stretch
        $btn.HorizontalContentAlignment = [System.Windows.HorizontalAlignment]::Left
        $btn.Style = $window.FindResource('CardBtn')
        # row bg matches the popup bg, so CardBtn's opacity-hover is invisible
        # here - swap in an explicit hover fill instead (mock: #33333D)
        $btn.Add_MouseEnter({ $this.Background = $script:BrushMenuHover })
        $btn.Add_MouseLeave({ $this.Background = $script:BrushMenuBg })
        $btn
    }
    $menuStack = New-Object System.Windows.Controls.StackPanel
    $menuStack.MinWidth = 176

    $btnInfo = New-Object System.Windows.Controls.Button
    $btnInfo.Tag = $AppId
    [void](& $mkMenuItem $btnInfo 'App info')
    $menuStack.Children.Add($btnInfo) | Out-Null

    $mkSep = {
        $s = New-Object System.Windows.Controls.Border
        $s.Height = 1; $s.Background = $script:BrushMenuSep
        $s.Margin = [System.Windows.Thickness]::new(6, 4, 6, 4)
        $s
    }
    $menuStack.Children.Add((& $mkSep)) | Out-Null

    # Shortcut (create/verify on demand)
    $btnShortcutCard = New-Object System.Windows.Controls.Button
    $btnShortcutCard.Tag = $AppId
    $btnShortcutCard.Visibility = [System.Windows.Visibility]::Collapsed
    [void](& $mkMenuItem $btnShortcutCard 'Create shortcut')
    $menuStack.Children.Add($btnShortcutCard) | Out-Null

    # Quiet Updater: disables the vendor updater scheduled tasks named in this
    # card's quietTasks (NI/LabVIEW only today) - the retrofit action.
    $btnQuiet = New-Object System.Windows.Controls.Button
    $btnQuiet.Tag = $AppId
    $btnQuiet.Visibility = [System.Windows.Visibility]::Collapsed
    [void](& $mkMenuItem $btnQuiet 'Quiet updater')
    $menuStack.Children.Add($btnQuiet) | Out-Null

    # Open App: launches a needsOpen app for its first-run updates
    $btnOpenApp = New-Object System.Windows.Controls.Button
    $btnOpenApp.Tag = $AppId
    $btnOpenApp.Visibility = [System.Windows.Visibility]::Collapsed
    [void](& $mkMenuItem $btnOpenApp 'Open app')
    $btnOpenApp.Add_Click({ Open-App -AppId $this.Tag })
    $menuStack.Children.Add($btnOpenApp) | Out-Null

    # Show setup prompt: reopens the needsOpen/licence dialog on demand.
    # Exists because a licence prompt carries the actual key the tech types, and
    # the old flow gave exactly one chance to read it - dismiss it by accident
    # and the code was gone from the screen. Deliberately does NOT relaunch the
    # app: the tech usually still has it open and wants the text back, not a
    # second copy of LabChart.
    $btnSetupPrompt = New-Object System.Windows.Controls.Button
    $btnSetupPrompt.Tag = $AppId
    $btnSetupPrompt.Visibility = [System.Windows.Visibility]::Collapsed
    [void](& $mkMenuItem $btnSetupPrompt 'Show setup prompt')
    $btnSetupPrompt.Add_Click({ [void](Show-AppSetupPrompt -AppId $this.Tag) })
    $menuStack.Children.Add($btnSetupPrompt) | Out-Null

    $menuStack.Children.Add((& $mkSep)) | Out-Null

    # Open file location (visibility still driven by Update-AppCard)
    [void](& $mkMenuItem $btnOpen 'Open file location')
    $menuStack.Children.Add($btnOpen) | Out-Null

    # Refresh this app
    $btnRefresh = New-Object System.Windows.Controls.Button
    $btnRefresh.Tag = $AppId
    [void](& $mkMenuItem $btnRefresh 'Refresh this app')
    $menuStack.Children.Add($btnRefresh) | Out-Null

    $menuBorder = New-Object System.Windows.Controls.Border
    $menuBorder.Background      = $script:BrushMenuBg
    $menuBorder.BorderBrush     = $script:BrushMenuBorder
    $menuBorder.BorderThickness = [System.Windows.Thickness]::new(1)
    $menuBorder.CornerRadius    = [System.Windows.CornerRadius]::new(9)
    $menuBorder.Padding         = [System.Windows.Thickness]::new(5)
    $menuBorder.Child           = $menuStack

    $menuPop = New-Object System.Windows.Controls.Primitives.Popup
    $menuPop.PlacementTarget    = $btnMore
    $menuPop.Placement          = [System.Windows.Controls.Primitives.PlacementMode]::Bottom
    $menuPop.StaysOpen          = $false
    $menuPop.AllowsTransparency = $true
    $menuPop.VerticalOffset     = 4
    $menuPop.Child              = $menuBorder

    $btnMore.Add_Click({
        $c = $script:Cards[$this.Tag]
        if ($c -and $c.MenuPop) { $c.MenuPop.IsOpen = -not $c.MenuPop.IsOpen }
    })
    # every menu action also closes the menu (second handler; both run)
    foreach ($mi in @($btnInfo, $btnShortcutCard, $btnQuiet, $btnOpenApp, $btnSetupPrompt, $btnOpen, $btnRefresh)) {
        $mi.Add_Click({ $c = $script:Cards[$this.Tag]; if ($c -and $c.MenuPop) { $c.MenuPop.IsOpen = $false } })
    }

    # -- App info popover: the reference facts, out of the row (declutter v2) --
    $infoHost = New-Object System.Windows.Controls.StackPanel
    $infoBorder = New-Object System.Windows.Controls.Border
    $infoBorder.Background      = $script:BrushMenuBg
    $infoBorder.BorderBrush     = $script:BrushMenuBorder
    $infoBorder.BorderThickness = [System.Windows.Thickness]::new(1)
    $infoBorder.CornerRadius    = [System.Windows.CornerRadius]::new(11)
    $infoBorder.Padding         = [System.Windows.Thickness]::new(0, 4, 0, 8)
    $infoBorder.MaxWidth        = 440
    $infoBorder.MinWidth        = 320
    $infoBorder.Child           = $infoHost

    $infoPop = New-Object System.Windows.Controls.Primitives.Popup
    $infoPop.PlacementTarget    = $btnMore
    $infoPop.Placement          = [System.Windows.Controls.Primitives.PlacementMode]::Bottom
    $infoPop.StaysOpen          = $false
    $infoPop.AllowsTransparency = $true
    $infoPop.VerticalOffset     = 4
    $infoPop.Child              = $infoBorder

    $btnInfo.Add_Click({
        $id  = $this.Tag
        $c   = $script:Cards[$id]
        if (-not $c) { return }
        $def = $script:AppsConfig.apps.$id
        $ih = $c.InfoHost
        $ih.Children.Clear()
        $hdr = New-Object System.Windows.Controls.TextBlock
        $hdr.Text = 'APP INFO'; $hdr.FontSize = 10; $hdr.FontWeight = [System.Windows.FontWeights]::Bold
        $hdr.Foreground = $script:BrushGray
        $hdr.Margin = [System.Windows.Thickness]::new(14, 6, 14, 6)
        $ih.Children.Add($hdr) | Out-Null
        $addRow = {
            param($k, $v, $mono)
            if (-not $v) { return }
            $g = New-Object System.Windows.Controls.Grid
            $c1 = New-Object System.Windows.Controls.ColumnDefinition; $c1.Width = [System.Windows.GridLength]::new(92)
            $c2 = New-Object System.Windows.Controls.ColumnDefinition
            $g.ColumnDefinitions.Add($c1); $g.ColumnDefinitions.Add($c2)
            $g.Margin = [System.Windows.Thickness]::new(14, 4, 14, 4)
            $kt = New-Object System.Windows.Controls.TextBlock
            $kt.Text = $k; $kt.FontSize = 11; $kt.Foreground = $script:BrushMuted
            $vt = New-Object System.Windows.Controls.TextBox
            $vt.Text = "$v"; $vt.FontSize = 11.5; $vt.Foreground = $script:BrushText
            $vt.Background = [System.Windows.Media.Brushes]::Transparent
            $vt.BorderThickness = [System.Windows.Thickness]::new(0)
            $vt.IsReadOnly = $true; $vt.TextWrapping = [System.Windows.TextWrapping]::Wrap
            if ($mono) { $vt.FontFamily = New-Object System.Windows.Media.FontFamily('Consolas'); $vt.FontSize = 10.5; $vt.Foreground = $script:BrushMuted }
            [System.Windows.Controls.Grid]::SetColumn($vt, 1)
            $g.Children.Add($kt) | Out-Null; $g.Children.Add($vt) | Out-Null
            $ih.Children.Add($g) | Out-Null
        }
        & $addRow 'Method'   $c.TagBase $false
        $srcSub = if ($def.install.sourceSub) { $def.install.sourceSub } elseif ($def.install.fallback.sourceSub) { "winget; drive backup: $($def.install.fallback.sourceSub)" } else { $null }
        & $addRow 'Source'   $srcSub $true
        $sv = if ($script:SourceVerCache.ContainsKey($id)) { $script:SourceVerCache[$id] } else { $null }
        & $addRow 'On stick' $sv $false
        & $addRow 'Requires' $(if ($def.requires) { @($def.requires) -join ', ' }) $false
        # The RAW detection output, not the card's friendly line - this row is
        # the diagnostic, and "Successfully Installed on <date>" answers nothing
        # a person opening App info is asking.
        & $addRow 'Detected' $(if ("$($c.DetectedRaw)".Trim()) { $c.DetectedRaw } else { $c.Detail.Text }) $true
        $c.MenuPop.IsOpen = $false
        $c.InfoPop.IsOpen = $true
    })

    # -- Wire button clicks --
    $btnShortcutCard.Add_Click({
        $id = $this.Tag
        $nm = $script:AppsConfig.apps.$id.displayName
        $st = Repair-AppShortcut -AppId $id
        if (-not $st.Applicable)  { $txtStatus.Text = "$nm does not use a desktop shortcut" }
        elseif ($st.Present)      { $txtStatus.Text = "Shortcut OK for $($nm): '$($st.Lnk)' is on the shared desktop" }
        else                      { $txtStatus.Text = "Could not create a shortcut for $nm - no launchable exe found" }
        Write-LabLog -Event 'shortcut.card_verify' -Data @{ appId = $id; applicable = $st.Applicable; present = $st.Present; lnk = $st.Lnk }
    })

    $btnQuiet.Add_Click({
        $id = $this.Tag
        $nm = $script:AppsConfig.apps.$id.displayName
        if (-not $script:IsAdmin) {
            [System.Windows.MessageBox]::Show("[E60] Disabling a scheduled task requires admin.`nRe-launch via Launch.bat.", 'Admin Required (E60)', 'OK', 'Warning')
            return
        }
        $q = Set-AppQuietTasks -AppId $id
        if (-not $q.Applicable) { $txtStatus.Text = "$nm has no updater tasks configured"; return }
        # Spell out every outcome - "already quiet" and "not present" both mean
        # nothing to do, and the tech should be able to tell them apart from a
        # genuine failure without opening the log.
        $parts = @()
        if ($q.Disabled -gt 0) { $parts += "$($q.Disabled) disabled" }
        if ($q.Already  -gt 0) { $parts += "$($q.Already) already quiet" }
        if ($q.Missing  -gt 0) { $parts += "$($q.Missing) not present" }
        if ($q.Failed   -gt 0) { $parts += "$($q.Failed) FAILED - see log" }
        $txtStatus.Text = "$($nm) updater tasks: " + ($parts -join ', ')
    })

    $btnRefresh.Add_Click({
        $id   = $this.Tag
        $card = $script:Cards[$id]
        # Block refresh if this app (or any app) is mid-install/uninstall
        if ($card.Status -eq 'Installing') { return }
        if ($script:installTimer.IsEnabled -and $script:installAppId -eq $id) { return }

        $card.Dot.Fill          = $script:BrushGray
        $card.Detail.Text       = 'Scanning...'
        $card.Detail.Foreground = $script:BrushMuted
        $card.BtnOpen.Visibility = [System.Windows.Visibility]::Collapsed
        # Clear cache for this app so it re-scans. Route through the async
        # index build: instant when the index already exists, and avoids a
        # UI-thread index build on the cold path (auto-scan off since launch).
        $script:DetectionCache.Remove($id)
        $script:scanQueue.Enqueue($id)
        if (-not $script:scanTimer.IsEnabled) {
            Start-IndexBuildAsync -OnReady { if (-not $script:scanTimer.IsEnabled) { $script:scanTimer.Start() } }
        }
    })

    $btnInstall.Add_Click({
        $id   = $this.Tag
        # Safeguard: one operation at a time (single global install slot)
        if (Test-OperationInProgress) {
            $txtStatus.Text = 'Another install/uninstall is still in progress - wait for it to finish'
            return
        }
        # Never-scanned app: scan it first so the button reflects the real
        # state (Install vs Reinstall) before anything is launched
        if (-not (Confirm-AppScanned -AppId $id -Trigger 'install')) { return }
        if (-not $script:IsAdmin) {
            [System.Windows.MessageBox]::Show("[E60] Installing requires admin.`nRe-launch via Launch.bat.", 'Admin Required (E60)', 'OK', 'Warning')
            return
        }
        Start-SingleInstall -AppId $id
    })

    $btnUninstall.Add_Click({
        $id   = $this.Tag
        $appDef = $script:AppsConfig.apps.$id
        $name = if ($appDef) { $appDef.displayName } else { $id }
        # Safeguard: one operation at a time
        if (Test-OperationInProgress) {
            $txtStatus.Text = 'Another install/uninstall is still in progress - wait for it to finish'
            return
        }
        # Never-scanned app: scan first so we know what we are uninstalling
        if (-not (Confirm-AppScanned -AppId $id -Trigger 'uninstall')) { return }
        if (-not $script:IsAdmin) {
            [System.Windows.MessageBox]::Show("[E60] Uninstalling requires admin.`nRe-launch via Launch.bat.", 'Admin Required (E60)', 'OK', 'Warning')
            return
        }
        # No separate "are you sure" here -- Start-SingleUninstall always shows
        # its own plain "Uninstall X - Are you sure?" confirm (AlwaysShow), so a
        # second dialog would be redundant.
        $script:DetectionCache.Remove($id)
        Start-SingleUninstall -AppId $id
    })

    $btnCancel.Add_Click({
        $id = $this.Tag
        $card = $script:Cards[$id]
        $appDef = $script:AppsConfig.apps.$id
        $name = if ($appDef) { $appDef.displayName } else { $id }

        # Cancel during the OFFLOAD COPY phase (installProcess isn't set yet --
        # the copy runs as its own robocopy process tracked by offloadCopyTimer)
        if ($script:offloadCopyTimer -and $script:offloadCopyTimer.IsEnabled -and $script:offloadCtx -and $script:offloadCtx.AppId -eq $id) {
            $script:offloadCopyTimer.Stop()
            $tempBase = $script:offloadCtx.TempBase
            try { if ($script:offloadCopyProc) { Start-Process -FilePath 'taskkill' -ArgumentList "/PID $($script:offloadCopyProc.Id) /T /F" -WindowStyle Hidden -Wait -ErrorAction SilentlyContinue } } catch { }
            Remove-Item $tempBase -Recurse -Force -ErrorAction SilentlyContinue
            Write-LabLog -Event 'offload.copy_cancelled' -Data @{ appId = $id; name = $name }
            $script:offloadCopyProc = $null; $script:offloadCtx = $null
            Clear-InstallQueue   # repaints the dropped cards instead of silently dropping them
            $script:DetectionCache.Remove($id)
            $result = Test-AppInstalled -AppId $id
            $script:DetectionCache[$id] = $result
            Update-AppCard -AppId $id -Result $result
            Update-Summary
            $txtStatus.Text = "Cancelled offload copy: $name"
            $btnInstallMissing.IsEnabled = $true
            $btnInstallMissing.Content = 'Install All Missing'
            $script:BatchPaused = $false
            return
        }

        # Only cancel if this is the currently active install/uninstall
        if ($script:installAppId -ne $id) { return }
        if (-not $script:installProcess) { return }

        # Stop the timers first so they don't interfere. The retry (verify)
        # timer may also be live -- Cancel stays visible during the verify
        # window, and a running retry tick would overwrite the cancelled state.
        $script:installTimer.Stop()
        if ($script:retryTimer -and $script:retryTimer.IsEnabled) { $script:retryTimer.Stop() }

        # Kill the process tree
        try {
            $procId = $script:installProcess.Id
            # Use taskkill /T to kill child processes too (e.g. winget spawns installers)
            Start-Process -FilePath 'taskkill' -ArgumentList "/PID $procId /T /F" `
                -WindowStyle Hidden -Wait -ErrorAction SilentlyContinue
            Write-LabLog -Event 'operation.cancelled' -Data @{
                appId = $id
                name = $name
                pid = $procId
                action = $script:installAction
            }
        } catch { }

        # Clean up temp files
        if ($script:progressFile -and (Test-Path $script:progressFile)) {
            Remove-Item $script:progressFile -Force -ErrorAction SilentlyContinue
        }
        Get-ChildItem -Path $env:TEMP -Filter 'labdeploy_copy_*.ps1' -ErrorAction SilentlyContinue |
            Remove-Item -Force -ErrorAction SilentlyContinue
        $script:progressFile = $null
        $script:installProcess = $null

        # If this was an offloaded install, delete the staged local copy too
        Clear-OffloadTemp

        # Clear the install queue too
        Clear-InstallQueue   # repaints the dropped cards instead of silently dropping them

        # Re-detect to see what state we're in after cancellation. Indexes are
        # stale too -- the cancelled install may have half-written files/registry.
        Clear-DetectionIndexes
        $script:DetectionCache.Remove($id)
        $result = Test-AppInstalled -AppId $id
        $script:DetectionCache[$id] = $result
        Write-LabLog -Event 'operation.cancel_detected_state' -Data @{
            appId = $id
            name = $name
            detected = $result.Installed
            userOnly = $result.UserOnly
            detail = $result.Detail
        }
        Update-AppCard -AppId $id -Result $result
        Update-Summary

        $txtStatus.Text = "Cancelled: $name"
        $btnInstallMissing.IsEnabled = $true
        $btnInstallMissing.Content = 'Install All Missing'
        $script:BatchPaused = $false
    })

    # -- Store refs --
    $cardHash = @{
        Border       = $border
        Dot          = $dot
        Detail       = $detailBlock
        Progress     = $pbar
        BtnOpen      = $btnOpen
        BtnRefresh   = $btnRefresh
        BtnInstall   = $btnInstall
        BtnUninstall = $btnUninstall
        BtnCancel    = $btnCancel
        BtnShortcut  = $btnShortcutCard
        BtnQuiet     = $btnQuiet
        SBox         = $sbox
        SText        = $stext
        BtnOpenApp   = $btnOpenApp
        BtnSetupPrompt = $btnSetupPrompt
        OBox         = $obox
        OText        = $otext
        TagText      = $tagText   # method tag TextBlock -- version backfill rewrites it
        TagBase      = $tagBase   # tag label without the version suffix
        AppId        = $AppId
        Status       = 'Scanning'
        Disabled     = $isDisabled
        MenuPop      = $menuPop    # "..." overflow menu Popup
        InfoPop      = $infoPop    # App info popover Popup
        InfoHost     = $infoHost   # StackPanel the info rows are rebuilt into
    }

    # -- Disabled card: grey it out and make every button inert. This runs last
    #    so it wins over the default styling above. Update-AppCard and the scan
    #    queue both skip Disabled cards, so this state sticks until re-enabled.
    if ($isDisabled) {
        $border.Opacity   = 0.5
        $dot.Fill         = $script:BrushGray
        $reason = if ($appDef.disabledReason) { $appDef.disabledReason } else { 'This app is disabled in the configuration.' }
        $detailBlock.Text        = "DISABLED - $reason"
        $detailBlock.Foreground  = $script:BrushMuted
        $tagText.Text            = 'Disabled'
        $tag.Background          = $script:BrushChipGray
        $btnRefresh.IsEnabled    = $false
        $btnInstall.IsEnabled    = $false
        $btnInstall.ToolTip      = 'This app is disabled'
        $btnUninstall.Visibility = [System.Windows.Visibility]::Collapsed
        $btnCancel.Visibility    = [System.Windows.Visibility]::Collapsed
        $cardHash.Status         = 'Disabled'
    }

    $script:Cards[$AppId] = $cardHash
    return $border
}

# ============================================================
#  UI Helper: Update a Card After Detection
# ============================================================
# Version of what is ACTUALLY installed, read from the exe detection found.
# The card's version chip shows the version on the DRIVE, which is what we would
# install - useful, but actively misleading when a different version is already
# on the machine (a green "Python v3.14.6" card while 3.13.7 is what is really
# there). Returns $null when it cannot tell, and never throws.
function Get-InstalledVersion {
    param($Result)
    try {
        if (-not $Result -or -not $Result.Detail) { return $null }
        # Detail can carry suffixes: "  (found via search)", "  (registered)",
        # "  [USER-ONLY: ...]" - take the path portion only.
        $path = (($Result.Detail -split '\s\s\(|\s\s\[')[0]).Trim()
        if (-not $path -or $path -match '[\*\?]') { return $null }
        if (-not (Test-Path $path -PathType Leaf)) { return $null }
        if ($path -notmatch '\.(exe|dll)$') { return $null }
        $vi = [System.Diagnostics.FileVersionInfo]::GetVersionInfo($path)
        foreach ($v in @($vi.ProductVersion, $vi.FileVersion)) {
            if ($v -and $v -match '(\d+(?:\.\d+)+)') { return $Matches[1] }
        }
    } catch { }
    return $null
}

# ============================================================
#  The card's detail line  (Blake, 2026-08-03)
# ============================================================
# It used to print raw detection output: the full install path when green
# ("C:\Program Files\ImageJ") and the entire searched-locations list when red
# ("Not found - checked 4 location(s): %PF%\... | %PF86%\... | ..."). Both
# wrapped to two lines, and neither answered what a tech actually asks at a
# glance - is it on, and since when.
#
# The path is NOT lost. It moves to the Detail tooltip and stays on the info
# popover's "Detected" row, which is where a diagnostic belongs.
#
# Test-AppInstalled's own Detail is deliberately UNCHANGED: four callers parse
# it as a path (Repair-AppShortcut, the shortcut cache, Get-InstalledVersion,
# and the leftover-file sweep). This is presentation, nothing else.

function Get-AppDetectedPath {
    param($Result)
    if (-not $Result -or -not "$($Result.Detail)".Trim()) { return '' }
    # Detail carries suffixes: "  (found via search)", "  (registered)",
    # "  (provisioned)", "  [USER-ONLY: ...]" - keep the path portion only.
    return (("$($Result.Detail)" -split '\s\s\(|\s\s\[')[0]).Trim()
}

# When did it land on this machine? The detected item's creation time is the
# honest answer for both shapes this tool installs: a copy-install's folder is
# created at copy time, and an MSI/EXE's Program Files folder at install time.
# detect.paths may hold WILDCARDS ("...\Java\jre1.8*\bin\java.exe"), so this
# resolves through Get-Item instead of Test-Path.
function Get-AppInstallStamp {
    param($Result)
    try {
        $p = Get-AppDetectedPath -Result $Result
        if (-not $p) { return $null }
        $item = $(if ($p -match '[\*\?]') { @(Get-Item -Path $p -Force -ErrorAction SilentlyContinue)[0] }
                  else { Get-Item -LiteralPath $p -Force -ErrorAction SilentlyContinue })
        if ($item) { return $item.CreationTime }
    } catch { }
    return $null
}

# ISO date so it still sorts and matches every other date in the tool, 12-hour
# clock because that is how the techs read it. InvariantCulture is not optional:
# with the current culture, 'tt' yields something other than AM/PM on a
# non-English desktop - the same trap the log-name parser documents.
function Format-LabStamp {
    param([datetime]$At)
    $inv = [System.Globalization.CultureInfo]::InvariantCulture
    return "$($At.ToString('yyyy-MM-dd', $inv)) at $($At.ToString('h:mm tt', $inv))"
}

function Get-AppCardDetail {
    param($Result, $Now = $null)
    if (-not $Now) { $Now = Get-Date }
    if ($Result -and $Result.Installed) {
        $at = Get-AppInstallStamp -Result $Result
        # No "Successfully" - the dot is already green, and no noun for the
        # program, whose name is on the line directly above this one.
        if ($at) { return "Installed $(Format-LabStamp -At $at)" }
        # Registry-value and provisioned-MSIX detections resolve to no file, so
        # there is nothing to date. Say that rather than stamping it with now,
        # which would read as "installed this second".
        return 'Installed - date not recorded'
    }
    # The green date is a fact about the APP (when it arrived). THIS date is a
    # fact about the SCAN (how fresh the claim is). Giving both the same "on X
    # at Y" shape implied a symmetry that does not exist, so this one leads with
    # the state and trails the check time.
    #
    # The date is dropped while the check is from TODAY - which it nearly always
    # is, since detection is in-memory and re-runs every session - and comes
    # back the moment it is not. A tool left open across midnight therefore
    # cannot quietly present a stale scan as current.
    # The "at" belongs to the time-only branch. Bolting it on outside gives
    # "checked at 2026-08-02 at 2:21 PM" on the other-day path - Format-LabStamp
    # already carries its own "at".
    $inv  = [System.Globalization.CultureInfo]::InvariantCulture
    $when = $(if ($Now.Date -eq (Get-Date).Date) { "at $($Now.ToString('h:mm tt', $inv))" }
              else { Format-LabStamp -At $Now })
    # Char code, not a literal middle dot: this file is round-tripped by editors
    # and harnesses that do not all agree on encoding, and the year header's
    # chevron already uses [char]0x25BE for the same reason.
    return "Not installed  $([char]0x00B7)  checked $when"
}

<#
    Test-AppPayloadMissing
    True when this card's installer is genuinely not on the media we are running
    from - i.e. the stick was scoped to other rooms and never received it.

    THIS IS NOT A FAILURE. A stick deliberately carrying eleven of a room's
    twelve cards is correct; the card simply cannot be installed from HERE. The
    difference matters: a red "install failed" sends a tech hunting for a broken
    installer, while "not on this stick" tells them to fetch the right stick.

    winget cards and anything with no sourceSub are never "missing" - there is
    no local payload to be absent.
#>
function Test-AppPayloadMissing {
    param([string]$AppId)
    try {
        $inst = $script:AppsConfig.apps.$AppId.install
        if (-not $inst) { return $false }
        $sub = $inst.sourceSub
        if (-not $sub -and $inst.fallback) { $sub = $inst.fallback.sourceSub }
        if (-not $sub) { return $false }
        return -not (Test-Path (Join-Path $script:SourceRoot $sub))
    } catch { return $false }
}

function Update-AppCard {
    param([string]$AppId, [hashtable]$Result)

    $card = $script:Cards[$AppId]
    if (-not $card) { return }
    # Disabled cards are inert -- never overwrite their greyed-out state.
    if ($card.Disabled) { return }

    # Raw detection output, kept off the visible line but one hover away. Set
    # before the branches so every state - green, amber, red - carries it.
    $card.DetectedRaw = "$($Result.Detail)"
    $card.Detail.ToolTip = $(if ("$($Result.Detail)".Trim()) { "$($Result.Detail)" } else { $null })

    # Always hide cancel/progress and restore button visibility when updating card state
    $card.BtnCancel.Visibility       = [System.Windows.Visibility]::Collapsed
    $card.Progress.Visibility        = [System.Windows.Visibility]::Collapsed
    $card.Progress.IsIndeterminate   = $false
    $card.BtnInstall.Visibility      = [System.Windows.Visibility]::Visible

    # NOT ON THIS STICK. Checked before the normal states so a scoped stick says
    # what is actually true instead of offering an Install that cannot work.
    # Only for apps that are NOT installed - if the app is already on the machine
    # its real state is far more interesting than where the installer came from.
    if (-not $Result.Installed -and (Test-AppPayloadMissing -AppId $AppId)) {
        $card.Dot.Fill              = $script:BrushMuted
        $card.Detail.Text           = 'Not on this stick - this drive is scoped to other rooms'
        $card.Detail.Foreground     = $script:BrushMuted
        $card.Detail.ToolTip        = "This card's installer was not copied to this drive, so it cannot be installed from here. Use a stick whose scope includes this room, or widen this stick's scope on the master's Sticks tab."
        $card.BtnInstall.IsEnabled  = $false
        $card.BtnInstall.Content    = 'Unavailable'
        $card.BtnUninstall.Visibility = [System.Windows.Visibility]::Collapsed
        $card.BtnOpen.Visibility    = [System.Windows.Visibility]::Collapsed
        # NOT 'Missing': Missing feeds "Install All Missing", which would queue an
        # install that is guaranteed to fail on every run. This state is inert.
        $card.Status = 'NotOnMedia'
        return
    }

    if ($Result.Installed -and $Result.UserOnly) {
        $card.Dot.Fill            = $script:BrushYellow
        $card.Detail.Text         = $Result.Detail
        $card.Detail.Foreground   = $script:BrushYellow
        $card.BtnInstall.Content  = 'Install'
        $card.BtnInstall.IsEnabled = $true
        $card.BtnInstall.Background = $script:BrushBtnGet
        $card.BtnUninstall.Visibility = [System.Windows.Visibility]::Collapsed
        $card.BtnOpen.Visibility  = [System.Windows.Visibility]::Visible
        $card.Status = 'UserOnly'
    } elseif ($Result.Installed) {
        $appDef = $script:AppsConfig.apps.$AppId
        # askAfterOpen defaults TRUE when absent, so existing cards keep the
        # yellow confirm-gate. When it is explicitly false the app is merely
        # launched after install - nothing to confirm, so no yellow state.
        $needsOpenPending = (Test-AppNeedsOpenConfirm -AppId $AppId) -and -not (Test-AppOpened -AppId $AppId)
        # FAILSAFE for machines deployed before a post-install step existed: the
        # app is installed but its vendor follow-up (Vivado's cable drivers)
        # never ran here. Amber, not green - green would claim a working JTAG
        # setup that isn't. Install becomes a cheap "run just that step".
        $postPending = -not (Test-PostInstallDone -AppId $AppId)
        if ($Result.Partial) {
            # Main product present but a bundled component of the SAME card is
            # not. Amber, never green: green here would certify a machine that
            # is missing something the course needs.
            $card.Dot.Fill          = $script:BrushYellow
            $card.Detail.Text       = "INCOMPLETE - $($Result.PartialWhat) is missing. Click Install again (it resumes), then restart if asked."
            $card.Detail.Foreground = $script:BrushYellow
            $card.Status = 'Installed'
        } elseif ($postPending) {
            $piLabel = $appDef.install.postInstall.label
            if (-not $piLabel) { $piLabel = 'post-install step' }
            $card.Dot.Fill          = $script:BrushYellow
            $card.Detail.Text       = "Installed - but $piLabel have NOT been run on this PC. Click 'Run drivers'."
            $card.Detail.Foreground = $script:BrushYellow
            $card.Status = 'Installed'
        } elseif ($needsOpenPending) {
            # Installed but not yet opened+verified -> YELLOW (not green) until confirmed
            $card.Dot.Fill            = $script:BrushYellow
            $card.Detail.Text         = "Installed - open it once to finish setup, then confirm (App Opened?)"
            $card.Detail.Foreground   = $script:BrushYellow
            $card.Status = 'NeedsOpen'
        } else {
            $card.Dot.Fill            = $script:BrushGreen
            # Surface a VERSION MISMATCH. The chip shows the drive's version;
            # if what is actually installed differs, say so on the card rather
            # than letting a green "v3.14.6" imply that is what is on the box.
            $detailText = Get-AppCardDetail -Result $Result
            $instVer = Get-InstalledVersion -Result $Result
            # Cache-only on purpose: an uncached Get-SourceVersion reads the USB
            # drive, and this runs on every scan tick. If the version hasn't
            # been read yet, the backfill timer re-renders this card once it is.
            $srcVer2 = if ($script:SourceVerCache.ContainsKey($AppId)) { $script:SourceVerCache[$AppId] } else { $null }
            # Some vendors version the PACKAGE and the EXE differently, so a raw
            # comparison cries wolf. Keil MDK 5.41 ships uVision 5.40.0.12 - the
            # chip claimed "installed v5.40.0.12 - the drive has v5.41" on a
            # perfectly correct install. installedVersionLabel records what the
            # exe legitimately reports; matching it means no warning.
            $expectInst = $appDef.installedVersionLabel
            $vendorSplitOk = $expectInst -and $instVer -and
                             (($instVer -eq $expectInst) -or $instVer.StartsWith($expectInst))
            if (-not $vendorSplitOk -and $instVer -and $srcVer2 -and ($instVer -ne $srcVer2) -and -not $srcVer2.StartsWith($instVer) -and -not $instVer.StartsWith($srcVer2)) {
                $detailText = "$detailText   [installed v$instVer - the drive has v$srcVer2]"
            }
            $card.Detail.Text         = $detailText
            $card.Detail.Foreground   = $script:BrushGreen
            $card.Status = 'Installed'
        }
        $card.BtnInstall.Content  = if ($postPending) { 'Run drivers' } else { 'Reinstall' }
        $card.BtnInstall.IsEnabled = $true
        $card.BtnInstall.Background = $(if ($postPending) { $script:BrushBtnAmber } else { $script:BrushBtnGreenDark })
        $card.BtnUninstall.Visibility = [System.Windows.Visibility]::Visible
        $card.BtnUninstall.IsEnabled  = $true
        $card.BtnOpen.Visibility  = [System.Windows.Visibility]::Visible
    } else {
        $card.Dot.Fill            = $script:BrushRed
        $card.Detail.Text         = Get-AppCardDetail -Result $Result
        $card.Detail.Foreground   = $script:BrushRedSoft
        $card.BtnInstall.Content  = 'Install'
        $card.BtnInstall.IsEnabled = $true
        $card.BtnInstall.Background = $script:BrushBtnGet
        $card.BtnUninstall.Visibility = [System.Windows.Visibility]::Collapsed
        $card.BtnOpen.Visibility  = [System.Windows.Visibility]::Collapsed
        $card.Status = 'Missing'
    }

    # Scanning an app also refreshes its shortcut chip, its "App Opened?" chip
    # and whether the Quiet Updater button applies to it
    Update-ShortcutBox -AppId $AppId
    Update-OpenBox -AppId $AppId
    Update-QuietButton -AppId $AppId
}

# ============================================================
#  UI Helper: Update Summary Text
# ============================================================
# One log line of per-app truth each time a scan pass finishes: which apps this
# machine HAS, is MISSING, has only per-user, or has partially. The fleet
# rollup treats each list as timestamped evidence per app - so "machine 1 is
# all good now" reaches the fleet map on the next plug-in even when nobody
# installed anything through the tool this session. Only apps that were
# actually scanned (present in DetectionCache) are mentioned: a partial scan
# (single room) simply provides evidence about fewer apps, never false
# "missing" claims about apps it didn't look at.
function Write-ScanSnapshot {
    try {
        $inst = New-Object System.Collections.ArrayList
        $miss = New-Object System.Collections.ArrayList
        $user = New-Object System.Collections.ArrayList
        $part = New-Object System.Collections.ArrayList
        foreach ($id in $script:DetectionCache.Keys) {
            $res = $script:DetectionCache[$id]
            if ($null -eq $res -or $res.Installed -isnot [bool]) { continue }   # scan errors carry no evidence
            if ($res.Installed -and $res.UserOnly)    { [void]$user.Add($id) }
            elseif ($res.Installed -and $res.Partial) { [void]$part.Add($id) }
            elseif ($res.Installed)                   { [void]$inst.Add($id) }
            else                                      { [void]$miss.Add($id) }
        }
        if (($inst.Count + $miss.Count + $user.Count + $part.Count) -eq 0) { return }
        Write-LabLog -Event 'scan.snapshot' -Data @{
            installed = ($inst -join ';'); missing = ($miss -join ';')
            userOnly  = ($user -join ';'); partial = ($part -join ';')
            count     = $script:DetectionCache.Count
        }
    } catch { }   # a snapshot failure must never break the scan that succeeded
}

function Update-Summary {
    # Disabled apps are excluded from the totals entirely (not installed, not
    # missing, not scanning) so they don't skew the "X / total" count.
    $total = @($script:Cards.Values | Where-Object { -not $_.Disabled }).Count
    if ($total -eq 0) { $txtSummary.Text = '--'; return }

    $installed  = @($script:Cards.Values | Where-Object { $_.Status -eq 'Installed'  }).Count
    $missing    = @($script:Cards.Values | Where-Object { $_.Status -eq 'Missing'    }).Count
    $userOnly   = @($script:Cards.Values | Where-Object { $_.Status -eq 'UserOnly'   }).Count
    $installing = @($script:Cards.Values | Where-Object { $_.Status -eq 'Installing' }).Count
    $unknown    = @($script:Cards.Values | Where-Object { $_.Status -eq 'Unknown'    }).Count
    $needsOpen  = @($script:Cards.Values | Where-Object { $_.Status -eq 'NeedsOpen'  }).Count
    $scanErr    = @($script:Cards.Values | Where-Object { $_.Status -eq 'ScanError'  }).Count
    # MUST be subtracted below. $scanning is computed by subtraction, so any
    # status missing from this list is silently reported as 'scanning...'
    # forever - which is exactly what NotOnMedia did before it was counted here.
    $notOnMedia = @($script:Cards.Values | Where-Object { $_.Status -eq 'NotOnMedia' }).Count
    $scanning   = $total - $installed - $missing - $userOnly - $installing - $unknown - $needsOpen - $scanErr - $notOnMedia

    $parts = @()
    if ($installing -gt 0) { $parts += "$installing installing" }
    if ($missing    -gt 0) { $parts += "$missing missing" }
    if ($scanErr    -gt 0) { $parts += "$scanErr scan error" }
    if ($needsOpen  -gt 0) { $parts += "$needsOpen need opening" }
    if ($userOnly   -gt 0) { $parts += "$userOnly user-only" }
    if ($unknown    -gt 0) { $parts += "$unknown not scanned" }
    if ($notOnMedia -gt 0) { $parts += "$notOnMedia not on this stick" }
    if ($scanning   -gt 0) { $parts += 'scanning...' }
    $suffix = if ($parts.Count -gt 0) { '  (' + ($parts -join ', ') + ')' } else { '' }

    # NotOnMedia does NOT block "All good": a stick scoped to other rooms is not
    # failing at anything. It still appears in the suffix, so the tally never
    # claims a completeness it does not have.
    if ($missing -eq 0 -and $userOnly -eq 0 -and $installing -eq 0 -and $scanning -eq 0 -and $unknown -eq 0 -and $needsOpen -eq 0 -and $scanErr -eq 0) {
        # "All good" still names the not-on-this-stick cards. Dropping the suffix
        # here would let a scoped stick report a bare "12 / 14 - All good!", and
        # the two absent cards would be invisible at exactly the moment someone
        # is deciding the laptop is finished.
        $txtSummary.Text = if ($notOnMedia -gt 0) { "$installed / $total  -  All good on this stick$suffix" }
                           else { "$installed / $total  -  All good!" }
        $txtSummary.Foreground = $script:BrushGreen
    } elseif ($missing -gt 0 -or $scanErr -gt 0) {
        $txtSummary.Text = "$installed / $total$suffix"
        $txtSummary.Foreground = $script:BrushRed
    } elseif ($installing -gt 0) {
        $txtSummary.Text = "$installed / $total$suffix"
        $txtSummary.Foreground = $script:BrushOrange
    } elseif ($userOnly -gt 0) {
        $txtSummary.Text = "$installed / $total$suffix"
        $txtSummary.Foreground = $script:BrushYellow
    } else {
        $txtSummary.Text = "$installed / $total$suffix"
        $txtSummary.Foreground = $script:BrushMuted
    }
}

# ============================================================
#  UI Helper: Restore a Card After an Aborted Operation
# ============================================================
# Start-SingleInstall / Start-SingleUninstall hide the action buttons and
# set Status='Installing' before their error checks run. Every early-return
# path must go through here, or the card is left stuck showing only a dead
# Cancel button with per-card Refresh blocked.
function Reset-AppCardState {
    param([string]$AppId, [string]$ErrorDetail)

    $card = $script:Cards[$AppId]
    if (-not $card) { return }

    $result = $script:DetectionCache[$AppId]
    if (-not $result) {
        $result = Test-AppInstalled -AppId $AppId
        $script:DetectionCache[$AppId] = $result
    }
    Update-AppCard -AppId $AppId -Result $result

    if ($ErrorDetail) {
        $card.Detail.Text       = $ErrorDetail
        $card.Detail.Foreground = $script:BrushRed
    }
    Update-Summary
}

# ============================================================
#  Scan Timer  (one app per tick, uses cache)
# ============================================================
$script:scanQueue = New-Object System.Collections.Queue
$script:scanTimer = New-Object System.Windows.Threading.DispatcherTimer
$script:scanTimer.Interval = [TimeSpan]::FromMilliseconds(60)
$script:scanTimer.Add_Tick({
    # Process a small batch per tick: detection is index-based (microseconds
    # per app), so batching fills the list fast while the UI stays fluid.
    # Each app is guarded individually -- one bad config entry (e.g. an
    # invalid pathMustMatch regex) marks that card as an error and moves on
    # instead of killing the whole application.
    $batch = 0
    while ($script:scanQueue.Count -gt 0 -and $batch -lt 6) {
        $batch++
        $id     = $script:scanQueue.Dequeue()
        $appDef = $script:AppsConfig.apps.$id
        $name   = if ($appDef) { $appDef.displayName } else { $id }
        try {
            if ($script:DetectionCache.ContainsKey($id)) {
                $result = $script:DetectionCache[$id]
                Write-LabLog -Event 'scan.cached' -Data @{
                    appId = $id
                    name = $name
                    detected = $result.Installed
                    userOnly = $result.UserOnly
                    detail = $result.Detail
                }
            } else {
                $result = Test-AppInstalled -AppId $id
                $script:DetectionCache[$id] = $result
                Write-LabLog -Event 'scan.result' -Data @{
                    appId = $id
                    name = $name
                    detected = $result.Installed
                    userOnly = $result.UserOnly
                    detail = $result.Detail
                }
            }
            Update-AppCard -AppId $id -Result $result
        } catch {
            Write-LabLog -Event 'scan.error' -Data @{ errorCode = 'E10'; appId = $id; error = $_.Exception.Message }
            $card = $script:Cards[$id]
            if ($card) {
                $card.Dot.Fill          = $script:BrushRed
                $card.Detail.Text       = "[E10] Scan error: $($_.Exception.Message)"
                $card.Detail.Foreground = $script:BrushRed
                # Status 'ScanError', NOT 'Missing': a card whose detection threw
                # is UNKNOWN, not known-absent. Marking it Missing let it get
                # swept into "Install All Missing" and reinstalled over a working
                # app. It stays clickable for a deliberate manual install.
                $card.Status = 'ScanError'
            }
        }
    }
    Update-Summary
    if ($script:scanQueue.Count -eq 0) {
        $script:scanTimer.Stop()
        $txtStatus.Text = 'Ready'
        # Scan pass complete -> log the snapshot. THIS is what lets the fleet
        # map notice a machine got FIXED without the tool doing the fixing: a
        # reboot that cured LabVIEW, a manual install, a reimage. Install events
        # only capture what the tool itself did; the snapshot captures what the
        # machine actually HAS, timestamped, so the rollup's newest-evidence-wins
        # fold can retire stale errors.
        Write-ScanSnapshot

        # Refresh All (and any scan that asked to) pushes the fresh snapshot to Cloudflare
        # NOW, so an individual stick in the field updates the dashboard without waiting for
        # Install All or the app to close. Bounded + never throws; no-op if telemetry is off.
        if ($script:PushAfterScan) {
            $script:PushAfterScan = $false
            try { $txtStatus.Text = 'Sending results to Cloudflare...' } catch { }
            try { $null = Push-Observations -DeadlineSec 15 } catch { }
            try { $txtStatus.Text = 'Ready' } catch { }
        }

        # -Auto hand-off. It can only happen HERE: the scan is what decides which
        # cards are Missing, so pressing Install All any earlier would install
        # nothing. One-shot - a later manual Refresh must not re-trigger it.
        if ($script:AutoInstallPending) {
            $script:AutoInstallPending = $false
            Write-LabLog -Event 'auto.install_all' -Data @{ room = $script:CurrentRoom; computer = $env:COMPUTERNAME }
            $txtStatus.Text = 'Unattended mode: starting Install All Missing...'
            # Raise the REAL button's Click rather than duplicating its body, so
            # every guard it owns still runs: admin check, image gate, pending
            # reboot block, one-operation lock, dependency ordering.
            try {
                $script:btnInstallMissing.RaiseEvent(
                    (New-Object System.Windows.RoutedEventArgs([System.Windows.Controls.Primitives.ButtonBase]::ClickEvent)))
            } catch {
                Write-LabLog -Event 'auto.install_failed' -Data @{ errorCode = 'E70'; error = $_.Exception.Message }
                $txtStatus.Text = "[E70] Unattended install could not start: $($_.Exception.Message)"
            }
        }
    } else {
        $txtStatus.Text = "Scanning installed software... ($($script:scanQueue.Count) left)"
    }
})

# ============================================================
#  Version Backfill Timer  (one app per tick)
# ============================================================
# Get-SourceVersion reads the installer on the USB drive (dir listing + exe
# version metadata) -- up to a few hundred ms per app on a cold stick, and
# New-AppCard used to do that synchronously for EVERY card while the room was
# still building, so a cold room switch froze the window on dozens of
# sequential drive reads. Cards now render with a plain method tag and this
# timer appends the "vX.Y" afterwards, one app per tick so input and render
# get serviced between reads. Results land in SourceVerCache, so each app is
# only ever paid for once per session.
$script:verQueue = New-Object System.Collections.Queue
$script:verTimer = [System.Windows.Threading.DispatcherTimer]::new([System.Windows.Threading.DispatcherPriority]::Background)
$script:verTimer.Interval = [TimeSpan]::FromMilliseconds(80)
$script:verTimer.Add_Tick({
    if ($script:verQueue.Count -eq 0) { $script:verTimer.Stop(); return }
    $id = $script:verQueue.Dequeue()
    try {
        $ver = Get-SourceVersion -AppId $id   # fills SourceVerCache
        if (-not $ver) { return }
        $card = $script:Cards[$id]
        if (-not $card -or $card.Disabled) { return }   # room switched away / card inert
        if ($card.TagText) { $card.TagText.Text = "$($card.TagBase)  v$ver" }
        # The green-state version-mismatch note needs the source version; a card
        # scanned BEFORE its version arrived skipped that check (cache-only), so
        # re-render it now. Only Status 'Installed' -- never touch a card that
        # is mid-install (Update-AppCard resets its progress/cancel UI).
        if ($card.Status -eq 'Installed' -and $script:DetectionCache.ContainsKey($id)) {
            Update-AppCard -AppId $id -Result $script:DetectionCache[$id]
        }
    } catch { }   # a version read failure must never take down the timer loop
})

# ============================================================
#  Install Timer  (polls running process, used for install AND uninstall)
# ============================================================
$script:installProcess = $null
$script:installAppId   = $null
$script:retryTimer     = $null
$script:MsiWaitActive  = $false   # inside Wait-WindowsInstallerFree's UI pump
$script:installQueue   = New-Object System.Collections.Queue
# What an "Install All" batch queued, so the ledger can report started/finished
# and show anything the batch did not manage to install.
$script:BatchQueued    = @()
# Pause requested mid-batch: honoured by Resume-InstallQueue AFTER the current
# installer finishes - never by interrupting a vendor installer mid-flight.
$script:BatchPaused    = $false
$script:BatchStarted   = $null

$script:installTimer = New-Object System.Windows.Threading.DispatcherTimer
$script:installTimer.Interval = [TimeSpan]::FromSeconds(1)
$script:installTimer.Add_Tick({
    try {
        $appDef = $script:AppsConfig.apps.($script:installAppId)
        $name   = if ($appDef) { $appDef.displayName } else { $script:installAppId }
        $card   = $script:Cards[$script:installAppId]
        $action = if ($script:installAction) { $script:installAction } else { 'Working' }
        $hasExited = try { $script:installProcess.HasExited } catch { $true }

        if ($script:installProcess -and -not $hasExited) {
            # --- Still running: update progress display ---
            $pct = $null

            if ($script:progressMode -eq 'percent' -and $script:progressFile -and (Test-Path $script:progressFile)) {
                # Exact percent written by a subprocess (copy method)
                try {
                    $raw = Get-Content $script:progressFile -Tail 1 -ErrorAction SilentlyContinue
                    if ($raw -match '(\d+)') { $pct = [math]::Min([int]$Matches[1], 100) }
                } catch { }
            } elseif ($script:progressMode -eq 'diskdelta' -and $script:installExpectedBytes -gt 0) {
                # Estimate percent from disk space consumed vs. expectedSizeMB.
                # Capped at 95 -- completion is declared by the process exiting,
                # never by the estimate reaching 100.
                try {
                    $freeNow = (Get-PSDrive -Name $script:installDriveName -ErrorAction Stop).Free
                    $delta = $script:installStartFreeBytes - $freeNow
                    if ($delta -lt 0) { $delta = 0 }
                    $pct = [math]::Min(95, [math]::Floor($delta * 100 / $script:installExpectedBytes))
                } catch { }
            }

            $elapsedText = ''
            if ($script:installStartTime) {
                $elapsed = [datetime]::Now - $script:installStartTime
                $elapsedText = '{0:d2}m {1:d2}s' -f [int][math]::Floor($elapsed.TotalMinutes), $elapsed.Seconds
            }

            if ($null -ne $pct) {
                $estTag = if ($script:progressMode -eq 'diskdelta') { '% (estimated)' } else { '%' }
                $progressText = "$pct$estTag - $elapsedText elapsed"
            } elseif ($elapsedText) {
                $progressText = "$elapsedText elapsed..."
            } else {
                $progressText = 'working...'
            }

            # The pause message must WIN the status line: this tick repaints
            # every second, and without the suffix it silently stomped "will
            # pause after the current install", making Pause look ignored.
            $pauseTag = if ($script:BatchPaused) { '   -   PAUSING after this one finishes' } else { '' }
            $txtStatus.Text = "${action}: $name  $progressText$pauseTag"
            if ($card) {
                $card.Detail.Text = "${action}...  $progressText"
                if ($null -ne $pct) {
                    $card.Progress.IsIndeterminate = $false
                    $card.Progress.Value = $pct
                }
            }

        } elseif ($script:installProcess -and $hasExited) {
            # --- Finished ---
            $script:installTimer.Stop()

            # Clean up temp files
            if ($script:progressFile -and (Test-Path $script:progressFile)) {
                Remove-Item $script:progressFile -Force -ErrorAction SilentlyContinue
            }
            Get-ChildItem -Path $env:TEMP -Filter 'labdeploy_copy_*.ps1' -ErrorAction SilentlyContinue |
                Remove-Item -Force -ErrorAction SilentlyContinue
            $script:progressFile = $null

            $timeStr = '??'
            if ($script:installStartTime) {
                $elapsed = [datetime]::Now - $script:installStartTime
                $timeStr = '{0:d2}m {1:d2}s' -f [int][math]::Floor($elapsed.TotalMinutes), $elapsed.Seconds
            }
            $code = try { $script:installProcess.ExitCode } catch { '?' }

            # Final disk delta: logged so expectedSizeMB in apps.json can be
            # calibrated from a real install instead of guessed
            $finalDeltaMB = $null
            if ($script:progressMode -eq 'diskdelta' -and $script:installStartFreeBytes -gt 0) {
                try {
                    $freeNow = (Get-PSDrive -Name $script:installDriveName -ErrorAction Stop).Free
                    $finalDeltaMB = [math]::Round(($script:installStartFreeBytes - $freeNow) / 1MB)
                } catch { }
            }

            # Determine if the exit code means failure
            $appDef2 = $script:AppsConfig.apps.($script:installAppId)
            $method  = if ($appDef2) { $appDef2.install.method } else { '' }
            # If this run was the automatic winget fallback, judge the exit code
            # by the BACKUP installer's method (msi/exe), not winget's rules
            if ($method -eq 'winget' -and $appDef2.install.fallback -and $script:WingetFallback.ContainsKey($script:installAppId)) {
                $method = $appDef2.install.fallback.method
            }
            $isFail  = $false
            switch ($method) {
                'winget' { $isFail = ($code -ne 0) }
                'copy'   { $isFail = ($code -ne 0) }    # copy runs a powershell.exe script (0=ok, non-0=error) - NOT robocopy
                default  { $isFail = ($code -ne 0 -and $code -ne 3010 -and $code -ne 1641) }  # 3010/1641 = reboot needed = success
            }

            # Clear cache and re-detect. Rebuild indexes too -- an install/uninstall
            # just changed disk + registry state, so the shared indexes are stale.
            Clear-DetectionIndexes
            $script:DetectionCache.Remove($script:installAppId)
            $result = Test-AppInstalled -AppId $script:installAppId
            $script:DetectionCache[$script:installAppId] = $result
            Write-LabLog -Event 'install.process_exited' -Data @{
                appId = $script:installAppId
                name = $name
                action = $action
                method = $method
                exitCode = $code
                time = $timeStr
                failedByExitCode = $isFail
                detected = $result.Installed
                userOnly = $result.UserOnly
                detail = $result.Detail
                diskDeltaMB = $finalDeltaMB
            }

            # --- Handle failure ---
            if ($isFail -and $action -ne 'Uninstalling') {
                # Retire the in-progress affordances for EVERY failure branch:
                # the success path calls Update-AppCard (which hides these), but
                # the failure branches set state by hand, so without this the
                # Cancel button stays live (could taskkill a recycled PID) and
                # the progress bar keeps animating on a failed card.
                if ($card) {
                    $card.BtnCancel.Visibility     = [System.Windows.Visibility]::Collapsed
                    $card.Progress.Visibility      = [System.Windows.Visibility]::Collapsed
                    $card.Progress.IsIndeterminate = $false
                }
                # Install/reinstall failed. Error code by failure class:
                # E25 winget | E62 busy (1618) | E26 MSI fatal (1603) | E23 generic
                $failCode = if ($method -eq 'winget') { 'E25' }
                            elseif ($code -eq 1618)   { 'E62' }
                            elseif ($code -eq 1603)   { 'E26' }
                            else                      { 'E23' }
                $failMsg = "[$failCode] FAILED: $name (exit $code, took $timeStr)"

                # Winget-specific help
                if ($method -eq 'winget') {
                    # SOURCE_DATA_MISSING family (0x8A15000F/14/15): winget's
                    # package catalog was never downloaded (fresh winget).
                    # Self-heal ONCE per app: update the catalog, retry via the
                    # normal install queue. Matched both signed and unsigned.
                    $srcErrs = @(-1978335217, -1978335212, -1978335211, 1978335217, 1978335212, 1978335211)
                    if ($appDef2.install.fallback -and -not $script:WingetFallback.ContainsKey($script:installAppId)) {
                        # AUTOMATIC FALLBACK: the drive carries a backup installer
                        # for this app. Any winget failure -> switch to it and
                        # retry through the queue. Local file, works offline,
                        # zero clicks. (Preferred over the catalog self-heal
                        # because it cannot fail on a bad network.)
                        $script:WingetFallback[$script:installAppId] = $true
                        Write-LabLog -Event 'install.winget_fallback_engaged' -Data @{ appId = $script:installAppId; exitCode = $code }
                        $failMsg = "winget failed for $name (exit $code) - using the backup installer from the drive instead..."
                        if ($card) {
                            $card.Detail.Text       = 'winget failed - using backup installer from the drive...'
                            $card.Detail.Foreground = $script:BrushOrange
                            $card.Status = 'Missing'
                        }
                        $script:installQueue.Enqueue($script:installAppId)   # picked up by the queue step below
                    } elseif (($srcErrs -contains $code) -and -not $script:WingetSrcFixed.ContainsKey($script:installAppId)) {
                        $script:WingetSrcFixed[$script:installAppId] = $true
                        Write-LabLog -Event 'install.winget_source_autofix' -Data @{ appId = $script:installAppId; exitCode = $code }
                        $failMsg = "winget's package catalog was empty (fresh winget) - updating it, then retrying $name..."
                        if ($card) {
                            $card.Detail.Text       = 'Updating winget catalog - will retry automatically...'
                            $card.Detail.Foreground = $script:BrushMuted
                            $card.Status = 'Missing'
                        }
                        $txtStatus.Text = $failMsg
                        $window.Dispatcher.Invoke([action]{}, [System.Windows.Threading.DispatcherPriority]::Render)
                        try {
                            $p = Start-Process -FilePath 'winget' -ArgumentList 'source update' -WindowStyle Hidden -PassThru -ErrorAction Stop
                            if (-not (Wait-ProcessResponsive -Proc $p -TimeoutSec 120)) { try { $p.Kill() } catch { } }
                        } catch { }
                        $script:installQueue.Enqueue($script:installAppId)   # picked up by the queue step below
                    } else {
                        $failMsg += ' - try running: winget source update'
                        if ($card) {
                            $card.Dot.Fill          = $script:BrushRed
                            $card.Detail.Text       = "[E25] Install failed (exit $code) - run 'winget source update' then retry"
                            $card.Detail.Foreground  = $script:BrushRed
                            $card.BtnInstall.IsEnabled = $true
                            $card.Status = 'Missing'
                        }
                    }
                } elseif ($code -eq 1618) {
                    # ERROR_INSTALL_ALREADY_RUNNING -- another installer holds the MSI lock
                    $failMsg = "[E62] FAILED: $name - another installation is already running (exit 1618). Wait for it to finish, then retry."
                    if ($card) {
                        $card.Dot.Fill          = $script:BrushRed
                        $card.Detail.Text       = '[E62] Another installation is already running (exit 1618) - wait for it to finish, then retry'
                        $card.Detail.Foreground  = $script:BrushRed
                        $card.BtnInstall.IsEnabled = $true
                        $card.Status = 'Missing'
                    }
                } elseif ($code -eq 1603) {
                    # MSI fatal error -- classic causes: pending reboot, antivirus,
                    # or a broken earlier install of the same product
                    $failMsg = "[E26] FAILED: $name - MSI fatal error 1603. Reboot the PC, then retry; if it persists check antivirus / broken prior install."
                    if ($card) {
                        $card.Dot.Fill          = $script:BrushRed
                        $card.Detail.Text       = '[E26] Install failed (MSI 1603) - reboot and retry; check antivirus or a broken prior install'
                        $card.Detail.Foreground  = $script:BrushRed
                        $card.BtnInstall.IsEnabled = $true
                        $card.Status = 'Missing'
                    }
                } elseif ($card) {
                    $card.Dot.Fill          = $script:BrushRed
                    $card.Detail.Text       = "[E23] Install failed (exit $code)"
                    $card.Detail.Foreground  = $script:BrushRed
                    $card.BtnInstall.IsEnabled = $true
                    $card.Status = 'Missing'
                }

                # DETECTION OVERRIDES THE EXIT CODE. Some vendor installers finish
                # the job and still return non-zero (NIPM returned -125071 after a
                # good 46-minute LabVIEW install on 2026-07-27 - most of its
                # sub-packages installed, a late/optional one complained). If the
                # app is genuinely on disk afterwards, this is a SUCCESS with a
                # warning, not a failure - saying "FAILED" for software that is
                # installed and working sends techs chasing ghosts.
                if ($result.Installed -and -not $result.UserOnly) {
                    Write-LabLog -Event 'install.failure_overridden_by_detection' -Data @{
                        appId = $script:installAppId
                        exitCode = $code
                        detail = $result.Detail
                    }
                    Update-AppCard -AppId $script:installAppId -Result $result
                    # Post-install steps the success path would have done
                    if (Test-AppAutoShortcut -AppId $script:installAppId) {
                        $sc2 = Repair-AppShortcut -AppId $script:installAppId
                        Write-LabLog -Event 'shortcut.post_install' -Data @{ appId = $script:installAppId; applicable = $sc2.Applicable; present = $sc2.Present; lnk = $sc2.Lnk }
                    } else {
                        Write-LabLog -Event 'shortcut.post_install_skipped' -Data @{ appId = $script:installAppId; reason = 'desktop icon turned off on the card' }
                    }
                    Write-LabLog -Event 'install.verified_despite_exitcode' -Data @{
                        appId = $script:installAppId; name = $name; exitCode = $code
                        time = $timeStr; detail = $result.Detail
                    }
                    if ($card) {
                        # Field lesson (LabVIEW on 10101LAB34-80, 2026-07-27). Two
                        # DIFFERENT NI codes both land here, and telling a tech the
                        # wrong one costs an unnecessary multi-GB reinstall:
                        #   -125071 = "A system reboot is needed to complete the
                        #             transaction." Everything installed. SUCCESS,
                        #             pending a reboot - NOT a failure.
                        #   -125083 = a package's MSI genuinely failed mid-chain
                        #             (seen at package 300 of 520). The rest never
                        #             installed, so the app is incomplete and will
                        #             not launch. NI feed installs RESUME, so the
                        #             fix is restart + Install again.
                        # Blake was one step from reinstalling LabVIEW by hand
                        # because a -125071 read as "stopped early". It had worked.
                        $rebootPending = ($code -eq -125071)
                        if ($rebootPending) {
                            $card.Detail.Text = "INSTALLED - reboot required to finish (code $code). Restart this PC, then it's done. Do NOT reinstall."
                        } else {
                            $card.Detail.Text = "Installed, but the installer stopped early (code $code). If it won't open: RESTART this PC, then click Install again - it resumes where it stopped."
                        }
                        $card.Detail.Foreground = $script:BrushYellow
                        $card.Dot.Fill          = $script:BrushYellow
                        $card.Status = 'Installed'
                    }
                    $txtStatus.Text = "$name is INSTALLED (took $timeStr). Its installer returned code $code, so please open it once to confirm it works."
                    Update-Summary
                } else {
                    Write-LabLog -Event 'install.failed' -Data @{
                        errorCode = $failCode
                        appId = $script:installAppId
                        name = $name
                        method = $method
                        exitCode = $code
                        time = $timeStr
                        detected = $result.Installed
                        detail = $result.Detail
                    }
                    $txtStatus.Text = $failMsg
                    Update-Summary
                }
                # KEEP THE BATCH GOING. Only the SUCCESS path reached the verify
                # timer, and that timer is the only thing that called
                # Resume-InstallQueue - so a failed install silently ABORTED the
                # rest of "Install All". Proven in Blake's run of 2026-07-27:
                # LabVIEW reported failure at 02:28:35 and MATLAB, the next and
                # last item, never started. In a lab that means a tech watches
                # one app fail and never learns that everything after it was
                # skipped too. Resume-InstallQueue is safe to call
                # unconditionally: with an empty queue it just re-enables the
                # Install All button.
                Clear-OffloadTemp
                Resume-InstallQueue
                # RETURN, do not fall through. Resume-InstallQueue OWNS queue
                # advancement: it starts exactly one app and returns, or drains
                # and re-enables the button. The common tail below (the
                # Clear-OffloadTemp + Dequeue at the end of this handler) runs on
                # every path, so without this return a failure advanced the queue
                # TWICE - starting two installs concurrently, overwriting
                # $script:installProcess with the second, and stranding the first
                # card on "Installing" forever with an inert Cancel. It also let
                # that trailing Clear-OffloadTemp delete the staged copy of the
                # install Resume had just started. Only reproducible with >=2
                # apps left after a failure, which is why the LabVIEW->MATLAB
                # run (1 left) never showed it.
                return

            } elseif ($isFail) {
                # Uninstall failed by exit code -- surface it instead of
                # falling through to the success path
                Write-LabLog -Event 'uninstall.failed' -Data @{
                    errorCode = 'E45'
                    appId = $script:installAppId
                    name = $name
                    method = $method
                    exitCode = $code
                    time = $timeStr
                    detected = $result.Installed
                    detail = $result.Detail
                }
                $txtStatus.Text = "[E45] FAILED: uninstall of $name (exit $code, took $timeStr)"
                Update-AppCard -AppId $script:installAppId -Result $result
                Update-Summary

            } else {
                # Success (or uninstall)
                $txtStatus.Text = "Finished $($action.ToLower()): $name (exit $code, took $timeStr) - verifying..."

                # If install succeeded but detection can't find the app yet, wait and retry.
                # Some installers (especially winget) take a few seconds to fully register.
                if ($action -ne 'Uninstalling' -and -not $result.Installed) {
                    if ($card) { $card.Detail.Text = 'Verifying... waiting for install to register' }

                    # Retry timer: checks every 3 seconds, up to 5 attempts (15 sec total)
                    $retryData = @{
                        AppId      = [string]$script:installAppId
                        Name       = [string]$name
                        TimeStr    = [string]$timeStr
                        Code       = $code
                        Action     = [string]$action
                        Attempt    = 0
                        MaxRetries = 5
                    }
                    $script:retryTimer = New-Object System.Windows.Threading.DispatcherTimer
                    $script:retryTimer.Interval = [TimeSpan]::FromSeconds(3)
                    $script:retryTimer.Tag = $retryData
                    $script:retryTimer.Add_Tick({
                        $rd = $this.Tag
                        $rd.Attempt++
                        # Look the card up fresh -- locals from the install timer's
                        # scope are gone by the time this tick fires
                        $card = $script:Cards[$rd.AppId]

                        # Rebuild the detection indexes each retry: they were
                        # built at process-exit and are stale for installers that
                        # register a few seconds late, so an index-only detection
                        # (searchExe fallback) could never newly succeed -> false E24.
                        Clear-DetectionIndexes
                        $script:DetectionCache.Remove($rd.AppId)
                        $retryResult = Test-AppInstalled -AppId $rd.AppId
                        $script:DetectionCache[$rd.AppId] = $retryResult
                        Write-LabLog -Event 'install.verify_retry' -Data @{
                            appId = $rd.AppId
                            name = $rd.Name
                            attempt = $rd.Attempt
                            maxRetries = $rd.MaxRetries
                            detected = $retryResult.Installed
                            userOnly = $retryResult.UserOnly
                            detail = $retryResult.Detail
                        }

                        if ($retryResult.Installed) {
                            $this.Stop()
                            Write-LabLog -Event 'install.verified' -Data @{
                                appId = $rd.AppId
                                name = $rd.Name
                                exitCode = $rd.Code
                                time = $rd.TimeStr
                                detail = $retryResult.Detail
                            }
                            if (Test-AppAutoShortcut -AppId $rd.AppId) { $null = Repair-AppShortcut -AppId $rd.AppId }
                            Update-AppCard -AppId $rd.AppId -Result $retryResult
                            Update-Summary
                            $txtStatus.Text = "Finished $($rd.Action.ToLower()): $($rd.Name) (exit $($rd.Code), took $($rd.TimeStr))"

                            Clear-OffloadTemp
                            Resume-InstallQueue
                        } elseif ($rd.Attempt -ge $rd.MaxRetries) {
                            $this.Stop()
                            Write-LabLog -Event 'install.not_detected_after_verify' -Data @{
                                errorCode = 'E24'
                                appId = $rd.AppId
                                name = $rd.Name
                                attempts = $rd.Attempt
                                exitCode = $rd.Code
                                time = $rd.TimeStr
                                detail = $retryResult.Detail
                            }
                            Update-AppCard -AppId $rd.AppId -Result $retryResult
                            Update-Summary
                            $txtStatus.Text = "[E24] Finished $($rd.Action.ToLower()): $($rd.Name) - not detected after $($rd.Attempt) checks, try Refresh"

                            Clear-OffloadTemp
                            Resume-InstallQueue
                        } else {
                            if ($card) { $card.Detail.Text = "Verifying... attempt $($rd.Attempt) of $($rd.MaxRetries)" }
                            $txtStatus.Text = "Waiting for $($rd.Name) to finish registering... (attempt $($rd.Attempt)/$($rd.MaxRetries))"
                        }
                    })
                    $script:retryTimer.Start()
                    return  # The retry timer handles the rest
                }

                # Shortcut management after successful operation
                if ($action -ne 'Uninstalling' -and $result.Installed) {
                    # Install verified -> one more automatic step: verify (create
                    # if missing) the shared-desktop shortcut, then paint the chip.
                    # Skipped when the card's desktop-icon box is unticked.
                    if (Test-AppAutoShortcut -AppId $script:installAppId) {
                        $sc = Repair-AppShortcut -AppId $script:installAppId
                        Write-LabLog -Event 'shortcut.post_install' -Data @{ appId = $script:installAppId; applicable = $sc.Applicable; present = $sc.Present; lnk = $sc.Lnk }
                    } else {
                        Write-LabLog -Event 'shortcut.post_install_skipped' -Data @{ appId = $script:installAppId; reason = 'desktop icon turned off on the card' }
                    }
                    Write-LabLog -Event 'install.verified' -Data @{
                        appId = $script:installAppId
                        name = $name
                        exitCode = $code
                        time = $timeStr
                        detail = $result.Detail
                    }
                    # Vendor steps that can only run once the app is on disk
                    # (Vivado's JTAG cable drivers). Runs here, after detection
                    # has confirmed the install - never before.
                    $piRes = Invoke-AppPostInstall -AppId $script:installAppId -Card $card
                    if ($piRes -and -not $piRes.Ok) {
                        $piLbl = if ($piRes.Label) { $piRes.Label } else { 'a post-install step' }
                        $txtStatus.Text = "$name installed, but $piLbl did not complete - see the log"
                    }
                    # FOLLOW-ON CARDS: pull in any companion this app owns (a
                    # licence file, today) BEFORE the needs-open gate, so the
                    # follower is already queued whether or not a human answers
                    # the prompt. Re-detect this app first: chaining a licence
                    # copy off an install that did not really land would write a
                    # config for an app that is not there, and the copy would
                    # then satisfy the licence card's own detect - a false green.
                    $foChk = Test-AppInstalled -AppId $script:installAppId
                    $script:DetectionCache[$script:installAppId] = $foChk
                    if ($foChk.Installed -and -not $foChk.UserOnly) {
                        $foQueued = Add-FollowOnInstalls -AppId $script:installAppId
                        if ($foQueued.Count) {
                            $foNames = @($foQueued | ForEach-Object {
                                $d = $script:AppsConfig.apps.$_
                                if ($d -and $d.displayName) { $d.displayName } else { $_ } })
                            $txtStatus.Text = "$name installed - also queuing $($foNames -join ', ')"
                        }
                    }

                    # NEEDS-OPEN GATE: if this app needs a manual first launch and
                    # isn't already confirmed, auto-open it and ask. The card stays
                    # yellow (via Update-AppCard) until the tech answers Yes.
                    $ndAppId = $script:installAppId
                    $ndDef   = $script:AppsConfig.apps.$ndAppId
                    $ndAsks = ($null -eq $ndDef.askAfterOpen) -or [bool]$ndDef.askAfterOpen
                    if ($ndDef.needsOpen -and -not $ndAsks) {
                        # "open it, don't ask" - just launch it and move on
                        Open-App -AppId $ndAppId
                        Write-LabLog -Event 'app.opened_no_prompt' -Data @{ appId = $ndAppId }
                    } elseif ($ndDef.needsOpen -and -not (Test-AppOpened -AppId $ndAppId) -and
                              (Test-ManualStepCoveredByCard -AppId $ndAppId)) {
                        # A companion card is going to do by hand what this
                        # prompt was going to ask a human to do. Do not ask.
                        Set-AppOpened -AppId $ndAppId
                        $ndRes2 = if ($script:DetectionCache.ContainsKey($ndAppId)) { $script:DetectionCache[$ndAppId] } else { $result }
                        Update-AppCard -AppId $ndAppId -Result $ndRes2
                        Update-Summary
                    } elseif ($ndDef.needsOpen -and -not (Test-AppOpened -AppId $ndAppId)) {
                        # Timed by default, NOT MessageBox: this prompt sits on the
                        # install queue's own thread, so an unanswered box froze a
                        # whole Install All run whenever the tech stepped away.
                        # Cards that set openPromptNoTimeout (licence prompts) opt
                        # out and DO hold the queue - see Get-AppPromptTimeoutSec.
                        # Shared with the card's "Show setup prompt" menu item so
                        # the reopened dialog is identical, key text included.
                        $ans = Show-AppSetupPrompt -AppId $ndAppId -Relaunch
                        if ($ans -eq 'Timeout') {
                            # Nobody was at the machine. Carry on with the queue -
                            # the yellow card is the reminder, and the close gate
                            # will not let the GUI exit while it is still yellow.
                            $txtStatus.Text = "$($ndDef.displayName) installed - nobody confirmed it was opened, so the card stays YELLOW. Open it and tick 'App Opened?'"
                        } elseif ($ans -ne 'Yes') {
                            $txtStatus.Text = "$($ndDef.displayName) installed but NOT confirmed opened - the card stays yellow until you confirm it (reopen from the card's ... menu)"
                        }
                    }
                } elseif ($action -eq 'Uninstalling' -and -not $result.Installed) {
                    # Uninstall succeeded and app is gone -- remove shortcut from Public Desktop
                    Remove-AppShortcut -AppId $script:installAppId
                    Update-ShortcutBox -AppId $script:installAppId
                    Write-LabLog -Event 'uninstall.verified_removed' -Data @{
                        appId = $script:installAppId
                        name = $name
                        exitCode = $code
                        time = $timeStr
                    }
                    # RESIDUE SURVEY - report only, delete nothing (Blake,
                    # 2026-07-30: E46's caution stays; just show what the vendor
                    # uninstaller left so cleanup is a per-app human decision).
                    $residue = Get-UninstallResidue -AppId $script:installAppId
                    if ($residue.Count -gt 0) {
                        Write-LabLog -Event 'uninstall.residue' -Data @{
                            appId = $script:installAppId; count = $residue.Count
                            paths = ($residue -join '; ')
                        }
                        $txtStatus.Text = "$name uninstalled OK - but left $($residue.Count) folder(s) behind (harmless; see log): $($residue[0])$(if ($residue.Count -gt 1) { ' ...' })"
                    }
                }

                # If uninstall but files still detected, offer to nuke them
                if ($action -eq 'Uninstalling' -and $result.Installed) {
                    Write-LabLog -Event 'uninstall.leftover_detected' -Data @{
                        appId = $script:installAppId
                        name = $name
                        detail = $result.Detail
                    }
                    $leftoverPath = ($result.Detail -split '  \(|  \[')[0].Trim()
                    $folderToRemove = $null
                    if ($leftoverPath -and (Test-Path $leftoverPath -PathType Leaf)) {
                        $folderToRemove = Split-Path $leftoverPath -Parent
                    } elseif ($leftoverPath -and (Test-Path $leftoverPath -PathType Container)) {
                        $folderToRemove = $leftoverPath
                    }

                    # Only offer deletion for locations this app is configured to
                    # own. A detection false positive (generic searchExe hit) must
                    # never lead to deleting another product's folder.
                    if ($folderToRemove) {
                        $allowedRoots = @()
                        if ($appDef2.install.destination) { $allowedRoots += $appDef2.install.destination }
                        foreach ($p in @($appDef2.detect.paths)) {
                            if (-not $p) { continue }
                            if ($appDef2.detect.method -eq 'path') { $allowedRoots += (Split-Path $p -Parent) }
                            else { $allowedRoots += $p }
                        }
                        $isAllowed = $false
                        try {
                            $fullTarget = [System.IO.Path]::GetFullPath($folderToRemove).TrimEnd('\')
                            foreach ($allowedRoot in $allowedRoots) {
                                # Skip wildcard detect paths (e.g. ST-Link's DriverStore
                                # patterns): GetFullPath throws on * or ?, which would
                                # abort the whole check and falsely refuse cleanup (E46).
                                if ($allowedRoot -match '[\*\?]') { continue }
                                $fullRoot = [System.IO.Path]::GetFullPath($allowedRoot).TrimEnd('\')
                                if ($fullTarget -eq $fullRoot -or $fullTarget.StartsWith("$fullRoot\", [System.StringComparison]::OrdinalIgnoreCase)) {
                                    $isAllowed = $true
                                    break
                                }
                            }
                        } catch { $isAllowed = $false }
                        if (-not $isAllowed) {
                            Write-LabLog -Event 'uninstall.leftover_outside_config' -Data @{
                                errorCode = 'E46'
                                appId = $script:installAppId
                                folder = $folderToRemove
                                allowedRoots = $allowedRoots
                            }
                            $txtStatus.Text = "[E46] Files at $folderToRemove are outside $name's configured folders - not offering deletion"
                            $folderToRemove = $null
                        }
                    }

                    if ($folderToRemove) {
                        $answer = [System.Windows.MessageBox]::Show(
                            "Uninstaller finished, but files were still found at:`n$folderToRemove`n`nThis can happen when the app was installed by file copy instead of an installer.`n`nDelete this folder now?",
                            'Leftover Files Detected', 'YesNo', 'Warning')
                        if ($answer -eq 'Yes') {
                            try {
                                Remove-Item -Path $folderToRemove -Recurse -Force -ErrorAction Stop
                                $txtStatus.Text = "Deleted leftover folder: $folderToRemove"
                                Write-LabLog -Event 'uninstall.leftover_removed' -Data @{
                                    appId = $script:installAppId
                                    folder = $folderToRemove
                                }
                            } catch {
                                $txtStatus.Text = "Failed to delete: $($_.Exception.Message)"
                                Write-LabLog -Event 'uninstall.leftover_remove_failed' -Data @{
                                    appId = $script:installAppId
                                    folder = $folderToRemove
                                    error = $_.Exception.Message
                                }
                            }
                            $result = Test-AppInstalled -AppId $script:installAppId
                            $script:DetectionCache[$script:installAppId] = $result
                            # If truly gone now, remove shortcut too
                            if (-not $result.Installed) {
                                Remove-AppShortcut -AppId $script:installAppId
                            }
                        }
                    }
                }

                Update-AppCard -AppId $script:installAppId -Result $result
                Update-Summary
            }

            # Offloaded install finished (success or fail) -> delete the staged copy
            Clear-OffloadTemp

            # Next in queue -- through Resume-InstallQueue, which OWNS queue
            # advancement (its rule, stated at the failure path's return above).
            # This tail used to Dequeue directly, which silently bypassed all
            # three things that only live in Resume: the already-installed skip
            # (a dependency chain's early install got REINSTALLED when its own
            # queue turn came), the installall.finished ledger, and the batch's
            # closing Verify Shortcuts sweep - so a batch where every install
            # succeeded first-try never wrote its ledger at all. Found by
            # tests\test-installpipe.ps1 (2026-08-02).
            if (-not $isFail -and $script:installQueue.Count -eq 0) {
                $txtStatus.Text = "Finished $($action.ToLower()): $name (exit $code, took $timeStr)"
            }
            Resume-InstallQueue
        }
    } catch {
        # Safety net: if anything throws, stop the timer so we don't loop errors forever
        $script:installTimer.Stop()
        Clear-OffloadTemp
        Write-LabLog -Event 'operation.timer_error' -Data @{
            errorCode = 'E70'
            appId = $script:installAppId
            action = $action
            error = $_.Exception.Message
        }
        $txtStatus.Text = "[E70] Error during ${action}: $($_.Exception.Message)"
        # Stopping the timer is not enough on its own. Without the cleanup below
        # the card stays Status='Installing' with a live Cancel and a spinning
        # bar; per-card Refresh refuses to touch an 'Installing' card, so the
        # only recovery was restarting the GUI. Worse, $script:installProcess
        # still referenced the exited process, so that stale Cancel would
        # taskkill a PID Windows may have already recycled onto something else.
        $deadId = $script:installAppId
        $script:installProcess = $null
        $script:installAppId   = $null
        if ($deadId) {
            try {
                $r = Test-AppInstalled -AppId $deadId
                $script:DetectionCache[$deadId] = $r
                Update-AppCard -AppId $deadId -Result $r   # retires Cancel + progress
            } catch { }
        }
        # Keep the batch alive: an exception here used to abandon everything
        # still queued, exactly like the failure path did before it was fixed.
        Resume-InstallQueue
    }
})

# ============================================================
#  Command Preview  (safeguard / tamper tripwire)
# ============================================================
# Shows, in plain language plus the literal command, exactly what a click will
# run BEFORE it runs. COMMAND-PREVIEW POPUPS REMOVED (2026-07-15, user
# request): installs, reinstalls and every automatic retry run with NO popup
# at all. The tamper trail is not lost - every operation still logs its exact
# program + arguments to install.process_started in the drive logs.
# The ONLY remaining dialog is a plain are-you-sure for -AlwaysShow calls
# (uninstalls), because one misclick there deletes software; it shows no
# command text. All original call sites still work unchanged.
function Confirm-CommandPreview {
    param(
        [string]$DisplayName,
        [string]$Verb,                 # 'Install', 'Reinstall' or 'Uninstall'
        [string]$WhatHappens,          # plain-English description
        [string]$ExactProgram = '',    # e.g. msiexec.exe  (blank for file-copy)
        [string]$ExactArguments = '',
        [switch]$AlwaysShow
    )
    if ($script:SuppressPreviewOnce) { $script:SuppressPreviewOnce = $false }
    if (-not $AlwaysShow) { return $true }
    $ans = [System.Windows.MessageBox]::Show(
        "$($Verb): $DisplayName`n`nAre you sure?",
        "$Verb - $DisplayName",
        [System.Windows.MessageBoxButton]::YesNo,
        [System.Windows.MessageBoxImage]::Warning)
    return ($ans -eq [System.Windows.MessageBoxResult]::Yes)
}

# ============================================================
#  Offload  (stage big images to local disk, install, then delete)
# ============================================================
# ============================================================
#  Leftover staging cleanup  (the "Clean Temp Files" button)
# ============================================================
# Big vendor images (MATLAB, Vivado, Ansys) are copied to
# C:\LabDeployOffload_Temp before installing and deleted afterwards - but a
# crash, a kill, or a yanked stick mid-copy strands tens of GB there. Startup
# already sweeps that folder; this is the on-demand version, plus the small
# helper files we scatter in %TEMP%.
#
# STRICTLY our own footprint. Every entry below is a path or filename pattern
# THIS TOOL creates; nothing else in %TEMP% is even looked at, so it can never
# eat another program's work.
function Get-LabDeployTempItems {
    $items = New-Object System.Collections.ArrayList
    $addPath = {
        param([string]$Path, [string]$What)
        try {
            if (-not (Test-Path $Path)) { return }
            $it = Get-Item $Path -Force -ErrorAction Stop
            $bytes = 0
            if ($it.PSIsContainer) {
                $bytes = [int64](Get-ChildItem $Path -Recurse -File -Force -ErrorAction SilentlyContinue |
                                 Measure-Object -Property Length -Sum).Sum
            } else { $bytes = [int64]$it.Length }
            [void]$items.Add(@{ Path = $it.FullName; What = $What; Bytes = $bytes; IsDir = $it.PSIsContainer })
        } catch { }
    }
    # 1. the offload staging root (the MATLAB/Vivado/Ansys case - the big one)
    & $addPath $script:OffloadRoot 'staged installer payload'
    # 2. the small helpers we drop in %TEMP%
    foreach ($pat in @(
        @{ f = 'labdeploy_copy_*.ps1';     w = 'copy helper script' },
        @{ f = 'labdeploy_progress_*.txt'; w = 'progress file' },
        @{ f = 'labdeploy_stick_*.txt';    w = 'stick sync output' },
        @{ f = 'labdeploy_gp_*.txt';       w = 'group-policy output' }
    )) {
        foreach ($h in @(Get-ChildItem -Path $env:TEMP -Filter $pat.f -File -Force -ErrorAction SilentlyContinue)) {
            & $addPath $h.FullName $pat.w
        }
    }
    return ,@($items)
}

function Invoke-TempCleanupFlow {
    # Never sweep while something is mid-flight: the offload folder in use right
    # now IS the install that is running.
    if (Test-OperationInProgress) {
        $txtStatus.Text = 'Cannot clean up while an install/uninstall is running - the staging folder is in use.'
        return
    }
    $items = Get-LabDeployTempItems   # no @() - it returns ,@(...); wrapping nests it
    if ($items.Count -eq 0) {
        $txtStatus.Text = 'Nothing to clean - no leftover LabDeploy staging files on this PC.'
        Write-LabLog -Event 'tempclean.none' -Data @{ }
        return
    }
    $total = [int64]0; foreach ($i in $items) { $total += [int64]$i.Bytes }
    $lines = @($items | Sort-Object { -[int64]$_.Bytes } | Select-Object -First 12 | ForEach-Object {
        '   {0}   ({1}, {2:N1} MB)' -f $_.Path, $_.What, ($_.Bytes / 1MB)
    })
    $more = if ($items.Count -gt 12) { "`n   ...and $($items.Count - 12) more" } else { '' }
    $ans = [System.Windows.MessageBox]::Show(
        ("Found $($items.Count) leftover LabDeploy item(s), {0:N1} GB total:`n`n{1}{2}`n`nThese are only files this tool creates while staging installers. Delete them now?" -f ($total / 1GB), ($lines -join "`n"), $more),
        'Leftover staging files', 'YesNo', 'Question')
    if ($ans -ne 'Yes') { $txtStatus.Text = 'Cleanup cancelled - nothing was deleted.'; return }

    $freed = [int64]0; $gone = 0; $stuck = 0
    foreach ($i in $items) {
        try {
            Remove-Item -LiteralPath $i.Path -Recurse -Force -ErrorAction Stop
            $freed += [int64]$i.Bytes; $gone++
        } catch { $stuck++ }
    }
    Write-LabLog -Event 'tempclean.done' -Data @{ deleted = $gone; failed = $stuck; freedMB = [math]::Round($freed / 1MB) }
    $txtStatus.Text = if ($stuck -eq 0) {
        'Cleaned up {0} leftover item(s), freed {1:N1} GB.' -f $gone, ($freed / 1GB)
    } else {
        'Cleaned up {0} item(s) ({1:N1} GB). {2} could not be deleted - likely still open; reboot and try again.' -f $gone, ($freed / 1GB), $stuck
    }
}

function Clear-OffloadTemp {
    if ($script:offloadTempBase) {
        $p = $script:offloadTempBase
        $script:offloadTempBase = $null
        try { Remove-Item $p -Recurse -Force -ErrorAction SilentlyContinue } catch { }
        Write-LabLog -Event 'offload.cleanup' -Data @{ path = $p }
    }
}

# Phase 2: run the installer from the local copy, then let the install timer
# finish + Clear-OffloadTemp deletes the staged folder on completion.
function Start-OffloadInstall {
    $ctx = $script:offloadCtx
    if (-not $ctx) { return }
    $inst = $ctx.Inst; $tempBase = $ctx.TempBase; $name = $ctx.Name
    $card = $script:Cards[$ctx.AppId]
    $installer = Join-Path $tempBase $inst.sourceSub   # e.g. <temp>\MatlabImage\setup.exe

    if (-not (Test-Path $installer)) {
        Write-LabLog -Event 'offload.installer_missing' -Data @{ errorCode = 'E27'; appId = $ctx.AppId; installer = $installer }
        Remove-Item $tempBase -Recurse -Force -ErrorAction SilentlyContinue
        $aid = $ctx.AppId; $fromQ = $ctx.FromQueue; $script:offloadCtx = $null
        $txtStatus.Text = "[E27] Offloaded installer not found after copy - installing $name from the drive instead"
        Start-SingleInstall -AppId $aid -NoOffload -FromQueue:$fromQ
        return
    }

    # Build the launch command against the LOCAL copy ({source} -> tempBase)
    if ($inst.method -eq 'msi') {
        $margs = "/i `"$installer`" /qn /norestart"
        if ($inst.arguments -and $inst.arguments -ne '') { $margs = Expand-LicenceTokens (($inst.arguments -replace '\{file\}', $installer) -replace '\{source\}', $tempBase) }
        $margs = Add-MsiVerboseLog -Arguments $margs -AppId $ctx.AppId
        $launchFile = 'msiexec.exe'; $launchArgs = $margs
    } else {
        $a = if ($inst.arguments) { Expand-LicenceTokens (($inst.arguments -replace '\{source\}', $tempBase) -replace '\{file\}', $installer) } else { '' }
        $launchFile = 'cmd.exe'; $launchArgs = "/c `"`"$installer`" $a`""
    }

    $what = "Install $name from the LOCAL copy just staged:`n`n    $installer`n`n(temp is deleted automatically once the install finishes)"
    if (-not (Confirm-CommandPreview -DisplayName $name -Verb 'Install' -WhatHappens $what -ExactProgram $launchFile -ExactArguments $launchArgs)) {
        Write-LabLog -Event 'install.preview_declined' -Data @{ appId = $ctx.AppId; method = $inst.method; command = "$launchFile $launchArgs"; offloaded = $true }
        Remove-Item $tempBase -Recurse -Force -ErrorAction SilentlyContinue
        $aid = $ctx.AppId; $fromQ = $ctx.FromQueue; $script:offloadCtx = $null
        Reset-AppCardState -AppId $aid
        $txtStatus.Text = "$($name): cancelled at command preview"
        if ($fromQ) { Resume-InstallQueue }
        return
    }

    # Install-phase progress = disk-delta on the install footprint
    $script:installStartTime = [datetime]::Now
    $script:progressMode = if ($inst.expectedSizeMB) { 'diskdelta' } else { 'timer' }
    $script:installExpectedBytes  = if ($inst.expectedSizeMB) { [double]$inst.expectedSizeMB * 1MB } else { 0 }
    $script:installStartFreeBytes = try { (Get-PSDrive -Name $script:installDriveName -ErrorAction Stop).Free } catch { 0 }
    $script:installAction   = 'Installing'
    $script:offloadTempBase = $tempBase   # completion + cancel delete this

    if ($card) {
        $card.Detail.Text = 'Installing (from local copy)...'
        $card.Detail.Foreground = $script:BrushOrange
        $card.Progress.IsIndeterminate = $true
    }
    $txtStatus.Text = "Installing $name from local copy..."

    try {
        $script:installProcess = Start-Process -FilePath $launchFile -ArgumentList $launchArgs -PassThru -WindowStyle Hidden
    } catch {
        Write-LabLog -Event 'install.launch_exception' -Data @{ errorCode = 'E22'; appId = $ctx.AppId; method = $inst.method; error = $_.Exception.Message; offloaded = $true }
        Clear-OffloadTemp
        $aid = $ctx.AppId; $fromQ = $ctx.FromQueue; $script:offloadCtx = $null
        $txtStatus.Text = "[E22] Could not start offloaded install of $name"
        Reset-AppCardState -AppId $aid -ErrorDetail "[E22] Could not start: $($_.Exception.Message)"
        if ($fromQ) { Resume-InstallQueue }
        return
    }
    Write-LabLog -Event 'install.process_started' -Data @{ appId = $ctx.AppId; method = $inst.method; filePath = $launchFile; arguments = $launchArgs; offloaded = $true; pid = $script:installProcess.Id }
    $script:installAppId = $ctx.AppId
    $script:offloadCtx = $null
    $script:installTimer.Start()
}

# Phase 1: copy the vendor image to local disk (fast robocopy), tracked by a
# dedicated poll timer that chains to Start-OffloadInstall on success, or falls
# back to a from-the-drive install on failure.
function Start-OffloadCopy {
    param([string]$AppId, [string]$OffloadSrc, [string]$FirstSeg, [double]$SrcBytes, [switch]$FromQueue)
    $appDef = $script:AppsConfig.apps.$AppId
    $name   = $appDef.displayName
    $card   = $script:Cards[$AppId]
    $tempBase = Join-Path $script:OffloadRoot $AppId

    try {
        if (Test-Path $tempBase) { Remove-Item $tempBase -Recurse -Force -ErrorAction SilentlyContinue }
        New-Item -ItemType Directory -Force $tempBase | Out-Null
    } catch {
        Write-LabLog -Event 'offload.temp_create_failed' -Data @{ errorCode = 'E27'; appId = $AppId; error = $_.Exception.Message }
        $txtStatus.Text = "[E27] Could not create offload folder - installing $name from the drive instead"
        Start-SingleInstall -AppId $AppId -NoOffload -FromQueue:$FromQueue
        return
    }

    $dst = Join-Path $tempBase $FirstSeg
    $script:offloadCtx = @{ AppId = $AppId; Name = $name; Inst = $appDef.install; TempBase = $tempBase; FromQueue = [bool]$FromQueue }
    $script:offloadSrcBytes  = $SrcBytes
    $script:offloadStartFree = try { (Get-PSDrive -Name $script:installDriveName -ErrorAction Stop).Free } catch { 0 }
    $script:installStartTime = [datetime]::Now
    Write-LabLog -Event 'offload.copy_start' -Data @{ appId = $AppId; source = $OffloadSrc; dest = $dst; sizeGB = [math]::Round($SrcBytes/1GB,2) }

    if ($card) {
        $card.Dot.Fill = $script:BrushOrange
        $card.Detail.Text = 'Copying to local disk...'
        $card.Detail.Foreground = $script:BrushOrange
        $card.BtnInstall.IsEnabled = $false
        $card.BtnUninstall.Visibility = [System.Windows.Visibility]::Collapsed
        $card.BtnCancel.Visibility = [System.Windows.Visibility]::Visible
        $card.BtnOpen.Visibility = [System.Windows.Visibility]::Collapsed
        $card.Progress.Value = 0
        $card.Progress.IsIndeterminate = $false
        $card.Progress.Visibility = [System.Windows.Visibility]::Visible
        $card.Status = 'Installing'
    }
    $txtStatus.Text = "Copying $name to local disk..."

    try {
        $script:offloadCopyProc = Start-Process -FilePath 'robocopy' `
            -ArgumentList "`"$OffloadSrc`" `"$dst`" /E /R:1 /W:1 /NFL /NDL /NP /NJH /NJS" `
            -PassThru -WindowStyle Hidden
    } catch {
        Write-LabLog -Event 'offload.copy_launch_failed' -Data @{ errorCode = 'E27'; appId = $AppId; error = $_.Exception.Message }
        Remove-Item $tempBase -Recurse -Force -ErrorAction SilentlyContinue
        $script:offloadCtx = $null
        $txtStatus.Text = "[E27] Offload copy could not start - installing $name from the drive instead"
        Start-SingleInstall -AppId $AppId -NoOffload -FromQueue:$FromQueue
        return
    }

    if (-not $script:offloadCopyTimer) {
        $script:offloadCopyTimer = New-Object System.Windows.Threading.DispatcherTimer
        $script:offloadCopyTimer.Interval = [TimeSpan]::FromSeconds(1)
        $script:offloadCopyTimer.Add_Tick({
            try {
                $ctx  = $script:offloadCtx
                $proc = $script:offloadCopyProc
                if (-not $ctx -or -not $proc) { $script:offloadCopyTimer.Stop(); return }
                $card = $script:Cards[$ctx.AppId]
                $hasExited = try { $proc.HasExited } catch { $true }

                if (-not $hasExited) {
                    $freeNow = try { (Get-PSDrive -Name $script:installDriveName -ErrorAction Stop).Free } catch { $script:offloadStartFree }
                    $copied = $script:offloadStartFree - $freeNow
                    if ($copied -lt 0) { $copied = 0 }
                    $pct = if ($script:offloadSrcBytes -gt 0) { [math]::Min(99, [math]::Floor($copied * 100 / $script:offloadSrcBytes)) } else { 0 }
                    $txtStatus.Text = "Copying $($ctx.Name) to local disk: $pct%  ({0:N1} GB)" -f ($copied/1GB)
                    if ($card) { $card.Detail.Text = "Copying to local disk... $pct%"; $card.Progress.Value = $pct }
                    return
                }

                $script:offloadCopyTimer.Stop()
                $code = try { $proc.ExitCode } catch { 8 }
                $script:offloadCopyProc = $null

                if ($code -lt 8) {
                    Write-LabLog -Event 'offload.copied' -Data @{ appId = $ctx.AppId; robocopyExit = $code }
                    Start-OffloadInstall
                } else {
                    Write-LabLog -Event 'offload.copy_failed' -Data @{ errorCode = 'E27'; appId = $ctx.AppId; robocopyExit = $code }
                    Remove-Item $ctx.TempBase -Recurse -Force -ErrorAction SilentlyContinue
                    $aid = $ctx.AppId; $nm = $ctx.Name; $fromQ = $ctx.FromQueue
                    $script:offloadCtx = $null
                    $txtStatus.Text = "[E27] Offload copy failed (robocopy $code) - installing $nm from the drive instead"
                    if ($card) { $card.Detail.Text = '[E27] Offload copy failed - using the drive'; $card.Detail.Foreground = $script:BrushYellow }
                    Start-SingleInstall -AppId $aid -NoOffload -FromQueue:$fromQ
                }
            } catch {
                $script:offloadCopyTimer.Stop()
                Write-LabLog -Event 'offload.timer_error' -Data @{ errorCode = 'E70'; error = $_.Exception.Message }
                # Nulling the handles is NOT enough. robocopy is a separate
                # process: drop the handle and it keeps mirroring a multi-GB
                # vendor image into C:\LabDeployOffload_Temp with nothing left
                # that can stop it, and the card stays on "Installing" with a
                # Cancel button whose offload branch can no longer fire (it
                # requires the timer + ctx we just cleared). Same cleanup the
                # Cancel path does, so an exception lands in a known state.
                $deadCtx = $script:offloadCtx
                try {
                    if ($script:offloadCopyProc) {
                        Start-Process -FilePath 'taskkill' -ArgumentList "/PID $($script:offloadCopyProc.Id) /T /F" -WindowStyle Hidden -Wait -ErrorAction SilentlyContinue
                    }
                } catch { }
                if ($deadCtx -and $deadCtx.TempBase) {
                    Remove-Item $deadCtx.TempBase -Recurse -Force -ErrorAction SilentlyContinue
                }
                $script:offloadCopyProc = $null; $script:offloadCtx = $null
                if ($deadCtx -and $deadCtx.AppId) {
                    $r = Test-AppInstalled -AppId $deadCtx.AppId
                    $script:DetectionCache[$deadCtx.AppId] = $r
                    Update-AppCard -AppId $deadCtx.AppId -Result $r   # retires Cancel + progress
                }
                $txtStatus.Text = "[E70] Error while copying to local disk: $($_.Exception.Message)"
                $btnInstallMissing.IsEnabled = $true
                $btnInstallMissing.Content = 'Install All Missing'
                $script:BatchPaused = $false
            }
        })
    }
    $script:offloadCopyTimer.Start()
}

# ============================================================
#  Install: Launch a Single App Install
# ============================================================
function Start-SingleInstall {
    param([string]$AppId, [switch]$FromQueue, [switch]$NoOffload)

    # IMAGE GATE: stale or missing image on a campus-named machine -> confirm
    # once per session before anything installs. Skipped for -FromQueue because
    # Install All already asked before it queued anything; asking here too would
    # re-prompt mid-batch on the dependency-chain re-entry path.
    if (-not $FromQueue -and -not (Confirm-ImageGate)) { return }

    $appDef = $script:AppsConfig.apps.$AppId
    if (-not $appDef) {
        Write-LabLog -Event 'install.no_config' -Data @{ appId = $AppId }
        $txtStatus.Text = "No install config for $AppId"
        if ($FromQueue) { Resume-InstallQueue }
        return
    }

    # LICENCE GATE (2026-08-18). Vendor codes live in config\licences.json, not
    # inline in apps.json. A stick that never received that file would otherwise
    # hand msiexec a literal {{TOKEN}} - and if the token were quietly stripped
    # instead, 'LICENCE=' with no code installs an UNLICENSED product that detects
    # green and only fails when a class opens it. Checked HERE, before either the
    # normal or the offload path, so a missing code costs nothing but a message.
    $licArgs = "$($appDef.install.arguments)"
    if ($licArgs -and (Test-LicenceTokenUnresolved (Expand-LicenceTokens $licArgs))) {
        $licMsg = Get-LicenceMissingMessage -Text $licArgs -AppId $AppId
        Write-LabLog -Event 'install.licence_missing' -Data @{ appId = $AppId; errorCode = 'E73' }
        $txtStatus.Text = $licMsg
        Reset-AppCardState -AppId $AppId -ErrorDetail $licMsg
        if ($FromQueue) { Resume-InstallQueue }
        return
    }

    # FAILSAFE SHORTCUT: app already installed, but its post-install step never
    # ran on this machine (a PC deployed before the step existed). Run ONLY that
    # step - reinstalling Vivado to get a driver script would mean 40 GB and an
    # hour for something that takes seconds.
    if (-not $FromQueue -and -not (Test-PostInstallDone -AppId $AppId)) {
        $chk = $script:DetectionCache[$AppId]
        if (-not $chk) { $chk = Test-AppInstalled -AppId $AppId; $script:DetectionCache[$AppId] = $chk }
        if ($chk.Installed -and -not $chk.UserOnly) {
            $card0 = $script:Cards[$AppId]
            Write-LabLog -Event 'postinstall.manual_run' -Data @{ appId = $AppId; reason = 'installed but post-install step missing' }
            $res0 = Invoke-AppPostInstall -AppId $AppId -Card $card0
            $chk2 = Test-AppInstalled -AppId $AppId
            $script:DetectionCache[$AppId] = $chk2
            Update-AppCard -AppId $AppId -Result $chk2      # re-reads the marker: amber -> green
            if ($res0 -and $res0.Ok) {
                $txtStatus.Text = "$($appDef.displayName): $($res0.Label) installed successfully"
            } elseif ($res0) {
                $lbl0 = if ($res0.Label) { $res0.Label } else { 'post-install step' }
                $txtStatus.Text = "[E71] $($appDef.displayName): $lbl0 did not complete - see the log"
            }
            Update-Summary
            return
        }
    }

    # Pre-flight: warn if Windows Installer is already busy (e.g. a previous
    # install still running in the background) -- starting now would fail 1618.
    # Skipped for queue continuations: the previous item just finished and the
    # MSI lock can linger a moment; the 1618 retry messaging covers rare races.
    # In a BATCH, never prompt and never barge in: wait for the other installer
    # to finish. Ansys HFSS detaches and holds the MSI lock for minutes after
    # reporting success, which cost Python and Visual Studio a whole run on
    # 2026-07-28. Waiting costs time; skipping costs the install.
    if ($FromQueue -and (Test-WindowsInstallerBusy)) {
        $waitRes = Wait-WindowsInstallerFree -ForApp $appDef.displayName -AllowPauseAbort
        if ("$waitRes" -eq 'PAUSED') {
            # Pause arrived while we were only WAITING for someone else's MSI
            # lock - our installer never launched, so nothing is half-done. Put
            # this app back at the FRONT of the queue (it is still the next
            # thing to install) and let Resume-InstallQueue's pause gate hold
            # the batch right here instead of committing one more install.
            $rest = @($script:installQueue.ToArray())
            $script:installQueue.Clear()
            $script:installQueue.Enqueue($AppId)
            foreach ($q in $rest) { $script:installQueue.Enqueue($q) }
            Write-LabLog -Event 'installall.paused_before_launch' -Data @{ appId = $AppId; requeued = $script:installQueue.Count }
            Resume-InstallQueue
            return
        }
        if (-not $waitRes) {
            Write-LabLog -Event 'install.blocked_installer_busy' -Data @{
                errorCode = 'E62'; appId = $AppId; name = $appDef.displayName; context = 'queue'
            }
            $txtStatus.Text = "[E62] $($appDef.displayName) skipped - Windows Installer still busy after 30 min"
            Reset-AppCardState -AppId $AppId -ErrorDetail "[E62] Windows Installer busy - another install never released it"
            Resume-InstallQueue
            return
        }
    }
    if (-not $FromQueue -and (Test-WindowsInstallerBusy)) {
        # Name the culprit when we can (Blake, 2026-08-12): "busy" alone forced
        # a guess about whether to wait or override.
        $busyWith = Get-WindowsInstallerBusyProduct
        $busyLine = if ($busyWith) { "Windows Installer is currently installing: $busyWith" }
                    else           { 'Windows Installer is busy - another installation is already running in the background.' }
        $busyAnswer = [System.Windows.MessageBox]::Show(
            "[E62] $busyLine`n`nStarting $($appDef.displayName) now will likely fail with error 1618.`n`nStart anyway?",
            'Installer Busy (E62)', 'YesNo', 'Warning')
        if ($busyAnswer -ne 'Yes') {
            Write-LabLog -Event 'install.blocked_installer_busy' -Data @{ errorCode = 'E62'; appId = $AppId; name = $appDef.displayName; busyWith = "$busyWith" }
            $txtStatus.Text = "[E62] Install of $($appDef.displayName) postponed - Windows Installer is busy with another installation"
            # Abandon any pending queue so the Install All button doesn't stay stuck
            Clear-InstallQueue   # repaints the dropped cards instead of silently dropping them
            $btnInstallMissing.IsEnabled = $true
            $btnInstallMissing.Content = 'Install All Missing'
            $script:BatchPaused = $false
            return
        }
    }

    # --- PENDING-REBOOT: RECORDED, NEVER BLOCKING (E73 gate DELETED 2026-07-29) ---
    # There used to be a hard gate here that skipped an install when Windows owed
    # a restart. It is gone, at Blake's call, and it was wrong to add:
    #   * It was speculation. On 07-28 we had THREE theories for why Rockwell CCW
    #     kept dying and this was one of them. The real cause was OUR bug - the
    #     VSIsoShell2015 detect path pointed at files the bundle never copies, so
    #     a dependency check could never pass. The shell had been installing
    #     perfectly the entire time.
    #   * The evidence was weak. Rockwell's troubleshooting doc opening with
    #     "restart and try setup again" is boilerplate in nearly every vendor's
    #     doc, and the DVD shipping ImmediateRestartPlugin.dll means the installer
    #     CAN reboot, not that it needs a clean slate.
    #   * It never caught anything, and it cost real throughput: a freshly imaged
    #     machine nearly always owes Windows Update a restart, so it blocked CCW
    #     on -04, -05 and -08 (-08 twice) in one afternoon. Installing software
    #     with updates pending is normal and it works.
    #   * The confirmed MSI-level blocker in this fleet is 1618 (another install
    #     already holding the lock - Ansys), a different mechanism entirely, and
    #     Wait-WindowsInstallerFree is what addresses that.
    # The reboot STATE is still worth knowing when something else fails later, so
    # it is logged once per install and nothing more. No skip, no dialog, no
    # error code. `install.blockOnPendingReboot` in apps.json is now ignored.
    try {
        $rb = Test-PendingReboot
        if ($rb.Pending) {
            Write-LabLog -Event 'install.pending_reboot_noted' -Data @{
                appId = $AppId; name = $appDef.displayName; reasons = ($rb.Reasons -join '; ')
                note  = 'informational only - installs are NOT blocked'
            }
        }
    } catch { }   # a probe that cannot answer must never stop an install

    # --- DEPENDENCY CHAIN (install.requires) ---
    # e.g. Logisim requires OpenJDK: if the dependency isn't installed yet,
    # install IT first and re-queue this app to continue right after.
    # One attempt per (app, dependency) per session (DepChainTried) so a failing
    # dependency can't bounce the two installs back and forth forever.
    #
    # The key MUST include the dependency. Keyed on the app alone, an app with
    # TWO requirements dies on the second one: install dep A, re-enter, find dep
    # B missing, see the app's own flag already set, and report E67 without ever
    # attempting B. That is exactly what RockwellCCW became when it gained
    # VSIsoShell2015 alongside DotNet35 on 2026-07-28.
    if ($appDef.install.requires) {
        foreach ($reqId in @($appDef.install.requires)) {
            $reqDef = $script:AppsConfig.apps.$reqId
            if (-not $reqDef) { continue }
            $req = if ($script:DetectionCache.ContainsKey($reqId)) { $script:DetectionCache[$reqId] } else { Test-AppInstalled -AppId $reqId }
            $script:DetectionCache[$reqId] = $req
            if ($req.Installed) { continue }
            $depKey = "$AppId|$reqId"
            if ($script:DepChainTried.ContainsKey($depKey)) {
                # Already tried once and the dependency is still missing -> stop with a clear error
                Write-LabLog -Event 'install.dependency_failed' -Data @{ errorCode = 'E67'; appId = $AppId; requires = $reqId }
                $txtStatus.Text = "[E67] $($appDef.displayName) needs $($reqDef.displayName), which could not be installed - fix that first"
                Reset-AppCardState -AppId $AppId -ErrorDetail "[E67] Needs $($reqDef.displayName) installed first"
                if ($FromQueue) { Resume-InstallQueue }
                return
            }
            $script:DepChainTried[$depKey] = $true
            Write-LabLog -Event 'install.dependency_first' -Data @{ appId = $AppId; requires = $reqId }
            $txtStatus.Text = "$($appDef.displayName) needs $($reqDef.displayName) first - installing that, then continuing automatically..."
            # Paint the PARENT card as busy-with-dependency: orange dot, spinner
            # bar labeled with the DEP's name. (The dep's own card may not be in
            # this room's view, so the parent card carries the progress. When the
            # dep finishes, this app re-enters through the queue and repaints as
            # its own normal install bar.)
            $pCard = $script:Cards[$AppId]
            if ($pCard) {
                $pCard.Dot.Fill              = $script:BrushOrange
                $pCard.Detail.Text           = "Installing $($reqDef.displayName) first (required), then $($appDef.displayName) starts automatically..."
                $pCard.Detail.Foreground     = $script:BrushOrange
                $pCard.Progress.Visibility   = [System.Windows.Visibility]::Visible
                $pCard.Progress.IsIndeterminate = $true
                $pCard.BtnInstall.IsEnabled  = $false
                $pCard.Status = 'Installing'
            }
            $script:installQueue.Enqueue($AppId)          # come back to this app right after
            # Always -FromQueue: the parent is now queued behind the dependency,
            # so if the dependency fails to LAUNCH, its early return must call
            # Resume-InstallQueue to dequeue the parent (else the parent strands
            # in the queue and fires unexpectedly after some later install).
            Start-SingleInstall -AppId $reqId -FromQueue
            return
        }
    }

    $card = $script:Cards[$AppId]
    if ($card) {
        $card.Dot.Fill          = $script:BrushOrange
        $card.Detail.Text       = 'Installing...'
        $card.Detail.Foreground = $script:BrushOrange
        $card.BtnInstall.IsEnabled    = $false
        $card.BtnUninstall.IsEnabled  = $false
        $card.BtnUninstall.Visibility = [System.Windows.Visibility]::Collapsed
        $card.BtnCancel.Visibility    = [System.Windows.Visibility]::Visible
        $card.BtnOpen.Visibility      = [System.Windows.Visibility]::Collapsed
        $card.Progress.Value           = 0
        $card.Progress.IsIndeterminate = $true
        $card.Progress.Visibility      = [System.Windows.Visibility]::Visible
        $card.Status = 'Installing'
    }

    # Reset progress tracking
    $script:installStartTime = [datetime]::Now
    $script:progressMode     = 'timer'
    $script:installAction    = if ($card -and $card.BtnInstall.Content -eq 'Reinstall') { 'Reinstalling' } else { 'Installing' }
    if ($script:progressFile -and (Test-Path $script:progressFile)) {
        Remove-Item $script:progressFile -Force -ErrorAction SilentlyContinue
    }
    $script:progressFile = Join-Path $env:TEMP "labdeploy_progress_$([guid]::NewGuid().ToString('N').Substring(0,8)).txt"

    # Disk-delta progress: when the app declares expectedSizeMB, estimate percent
    # from how much disk space the installer consumes. Covers installers with no
    # native progress reporting (VS bootstrapper, NSIS /S, vendor setups).
    # The 'copy' method overrides this with exact file-count percent below.
    $script:installExpectedBytes  = 0
    $script:installStartFreeBytes = 0
    if ($appDef.install.expectedSizeMB) {
        try {
            $script:installStartFreeBytes = (Get-PSDrive -Name $script:installDriveName -ErrorAction Stop).Free
            $script:installExpectedBytes  = [double]$appDef.install.expectedSizeMB * 1MB
            $script:progressMode          = 'diskdelta'
        } catch { }
    }

    $txtStatus.Text = "$($script:installAction): $($appDef.displayName)..."
    $inst = $appDef.install

    # --- AUTOMATIC WINGET FALLBACK ---
    # winget already failed for this app this session and the drive carries a
    # backup installer (install.fallback in apps.json). Swap it in seamlessly:
    # no popups, no extra clicks - the card and status bar say what happened.
    $script:SuppressPreviewOnce = $false
    if ($inst.method -eq 'winget' -and $inst.fallback -and $script:WingetFallback.ContainsKey($AppId)) {
        $inst = $inst.fallback
        $script:SuppressPreviewOnce = $true                    # user isn't re-prompted for the automatic retry
        $script:installAction = 'Installing (winget backup)'   # flows into progress + "Finished ..." texts
        Write-LabLog -Event 'install.using_winget_fallback' -Data @{ appId = $AppId; sourceSub = $inst.sourceSub }
        $txtStatus.Text = "winget failed - installing $($appDef.displayName) from the backup installer on the drive..."
        if ($card) { $card.Detail.Text = 'winget failed - using backup installer from the drive...' }
    }
    $actVerb = $script:installAction -replace 'ing$', ''   # Installing->Install, Reinstalling->Reinstall
    Write-LabLog -Event 'install.start' -Data @{
        appId = $AppId
        name = $appDef.displayName
        action = $script:installAction
        method = $inst.method
        sourceSub = $inst.sourceSub
        id = $inst.id
        arguments = $inst.arguments
    }

    # --- OFFLOAD: stage big vendor images to local disk, then install from there ---
    # Applies when: the app opts in (install.offload), the feature is on, we're
    # not already a fallback, and it's a file-based method. Falls back to a normal
    # (from-the-drive) install when off or short on local space -- and says so.
    if ($inst.offload -and $script:OffloadEnabled -and -not $NoOffload -and $inst.method -in @('exe','msi')) {
        $firstSeg   = ($inst.sourceSub -split '[\\/]')[0]
        $offloadSrc = Join-Path $script:SourceRoot $firstSeg
        if (Test-Path $offloadSrc) {
            $srcBytes = (Get-ChildItem $offloadSrc -Recurse -File -ErrorAction SilentlyContinue | Measure-Object Length -Sum).Sum
            $needBytes = $srcBytes + ([double]($inst.expectedSizeMB) * 1MB) + 3GB   # copy + install footprint + margin
            $freeBytes = try { (Get-PSDrive -Name $script:installDriveName -ErrorAction Stop).Free } catch { 0 }
            if ($freeBytes -lt $needBytes) {
                # E28: not enough local disk -> tell the user, install from the drive
                Write-LabLog -Event 'offload.insufficient_disk' -Data @{ errorCode = 'E28'; appId = $AppId; needGB = [math]::Round($needBytes/1GB,1); freeGB = [math]::Round($freeBytes/1GB,1) }
                $txtStatus.Text = "[E28] Not enough local disk to offload $($appDef.displayName) - installing from the drive instead"
                # fall through to the normal switch below (no offload)
            } else {
                Start-OffloadCopy -AppId $AppId -OffloadSrc $offloadSrc -FirstSeg $firstSeg -SrcBytes $srcBytes -FromQueue:$FromQueue
                return   # the copy timer chains to the install phase
            }
        }
    }

    # try/catch around the whole launch: Start-Process throws if the launcher
    # itself is missing (e.g. no winget on this machine) or access is denied,
    # and an unhandled exception here would crash the WPF click handler.
    try {
    switch ($inst.method) {
        'winget' {
            # E61 preflight: winget (App Installer) is per-user and often absent
            # on fresh lab accounts -- catch it here with a clear code instead of
            # a launch exception.
            if (-not (Get-Command winget -ErrorAction SilentlyContinue)) {
                Write-LabLog -Event 'install.winget_missing' -Data @{ errorCode = 'E61'; appId = $AppId }
                $txtStatus.Text = "[E61] winget is not installed on this machine - cannot install $($appDef.displayName)"
                Reset-AppCardState -AppId $AppId -ErrorDetail '[E61] winget (App Installer) missing on this PC - install it from the Microsoft Store, or skip this app'
                if ($FromQueue) { Resume-InstallQueue }
                return
            }
            # Run winget directly (not through cmd.exe) so we track the real process.
            # Winget waits for its child installer to finish before exiting.
            # (Progress mode stays as set above -- diskdelta if configured, else timer.
            # Winget's own stdout progress is unreliable to parse via redirect.)
            $launchFile = 'winget'
            # switches are per-card (set by the winget adder's checkboxes).
            # Defaults preserve the pre-checkbox behaviour for older cards:
            # silent + both accepts ON, no scope pin. --exact is always passed
            # so --id can never fuzzy-match a different package.
            $launchArgs = "install --id $($inst.id) --exact"
            if ($null -eq $inst.silent -or $inst.silent)                                   { $launchArgs += ' --silent' }
            if ($inst.scopeMachine)                                                        { $launchArgs += ' --scope machine' }
            if ($null -eq $inst.acceptPackageAgreements -or $inst.acceptPackageAgreements) { $launchArgs += ' --accept-package-agreements' }
            if ($null -eq $inst.acceptSourceAgreements -or $inst.acceptSourceAgreements)   { $launchArgs += ' --accept-source-agreements' }
            $what = "Windows Package Manager (winget) will download and install`nthis package from Microsoft's public catalog:`n`n    $($inst.id)"
            if (-not (Confirm-CommandPreview -DisplayName $appDef.displayName -Verb $actVerb -WhatHappens $what -ExactProgram $launchFile -ExactArguments $launchArgs)) {
                Write-LabLog -Event 'install.preview_declined' -Data @{ appId = $AppId; method = $inst.method; command = "$launchFile $launchArgs" }
                $txtStatus.Text = "$($appDef.displayName): cancelled at command preview"
                Reset-AppCardState -AppId $AppId
                if ($FromQueue) { Resume-InstallQueue }
                return
            }
            $script:installProcess = Start-Process -FilePath $launchFile -ArgumentList $launchArgs -PassThru -WindowStyle Hidden
            Write-LabLog -Event 'install.process_started' -Data @{
                appId = $AppId
                method = $inst.method
                filePath = $launchFile
                arguments = $launchArgs
                pid = $script:installProcess.Id
            }
        }
        'copy' {
            $src = Join-Path $script:SourceRoot $inst.sourceSub
            $dst = $inst.destination
            if (-not (Test-Path $src)) {
                Write-LabLog -Event 'install.source_missing' -Data @{ errorCode = 'E21'; appId = $AppId; method = $inst.method; source = $src; destination = $dst }
                $txtStatus.Text = "[E21] Source not found: $src"
                Reset-AppCardState -AppId $AppId -ErrorDetail "[E21] Source not found: $src"
                if ($FromQueue) { Resume-InstallQueue }
                return
            }
            # Copy method has no vendor command -- show the real source->destination
            # (computed live) rather than the internal temp copy-script path.
            $fileCount = @(Get-ChildItem -Path $src -Recurse -File -ErrorAction SilentlyContinue).Count
            # OVERLAY WARNING. The copy method is additive: it Copy-Item -Force's
            # over the destination and never removes files the previous version
            # left behind, so an in-place upgrade can leave a hybrid of two
            # versions. Deliberately NOT auto-wiping the destination - that is
            # destructive code running unattended on every stick, and a wrong
            # `destination` would delete the wrong folder. On the normal fleet
            # workflow (fresh image -> deploy) the destination does not exist and
            # none of this applies. When it DOES exist, say so out loud instead
            # of silently overlaying: the clean upgrade is Uninstall then Install.
            $script:copyOverlay = $false
            if ($dst -and (Test-Path $dst)) {
                $existing = @(Get-ChildItem -Path $dst -Recurse -File -ErrorAction SilentlyContinue).Count
                if ($existing -gt 0) {
                    $script:copyOverlay = $true
                    Write-LabLog -Event 'install.copy_overlay' -Data @{
                        appId = $AppId; destination = $dst; existingFiles = $existing; incomingFiles = $fileCount
                        note = 'additive copy over an existing install - stale files from the previous version are NOT removed; Uninstall first for a clean upgrade'
                    }
                }
            }
            $what = "Copy program files ($fileCount files):`n`nFROM:  $src`nTO:    $dst"
            if ($script:copyOverlay) {
                $what += "`n`nNOTE: $dst already exists. Files are copied OVER it; anything left by the previous version stays. Uninstall first if you want a clean upgrade."
            }
            if (-not (Confirm-CommandPreview -DisplayName $appDef.displayName -Verb $actVerb -WhatHappens $what)) {
                Write-LabLog -Event 'install.preview_declined' -Data @{ appId = $AppId; method = $inst.method; source = $src; destination = $dst }
                $txtStatus.Text = "$($appDef.displayName): cancelled at command preview"
                Reset-AppCardState -AppId $AppId
                if ($FromQueue) { Resume-InstallQueue }
                return
            }
            # Use a PowerShell child process that counts files and writes progress %
            $script:progressMode = 'percent'
            $pf = $script:progressFile
            # -ErrorAction Stop + try/catch so a failed Copy-Item exits NON-ZERO.
            # Without this, copy errors are non-terminating, the script exits 0,
            # and a broken/partial copy is judged 'installed'.
            $copyScript = @"
`$ErrorActionPreference = 'Stop'
try {
    `$src = '$($src -replace "'","''")'
    `$dst = '$($dst -replace "'","''")'
    `$pf  = '$($pf  -replace "'","''")'
    `$files = @(Get-ChildItem -Path `$src -Recurse -File -ErrorAction SilentlyContinue)
    `$total = `$files.Count
    if (`$total -eq 0) { '100' | Out-File `$pf -Force; exit 0 }
    if (-not (Test-Path `$dst)) { New-Item -ItemType Directory -Path `$dst -Force | Out-Null }
    `$i = 0
    foreach (`$f in `$files) {
        `$rel = `$f.FullName.Substring(`$src.Length)
        `$d   = Join-Path `$dst `$rel
        `$dir = Split-Path `$d -Parent
        if (-not (Test-Path `$dir)) { New-Item -ItemType Directory -Path `$dir -Force | Out-Null }
        Copy-Item -LiteralPath `$f.FullName -Destination `$d -Force
        `$i++
        [math]::Floor(`$i / `$total * 100) | Out-File `$pf -Force
    }
    exit 0
} catch {
    exit 1
}
"@
            $scriptFile = Join-Path $env:TEMP "labdeploy_copy_$([guid]::NewGuid().ToString('N').Substring(0,8)).ps1"
            $copyScript | Out-File -FilePath $scriptFile -Encoding UTF8 -Force
            $script:installProcess = Start-Process -FilePath 'powershell.exe' `
                -ArgumentList "-NoProfile -ExecutionPolicy Bypass -File `"$scriptFile`"" `
                -PassThru -WindowStyle Hidden
            Write-LabLog -Event 'install.process_started' -Data @{
                appId = $AppId
                method = $inst.method
                filePath = 'powershell.exe'
                arguments = "-NoProfile -ExecutionPolicy Bypass -File `"$scriptFile`""
                source = $src
                destination = $dst
                progressFile = $script:progressFile
                pid = $script:installProcess.Id
            }
        }
        'psadt' {
            $pkgPath = Join-Path $PSScriptRoot $inst.package
            $exe     = Join-Path $pkgPath 'Invoke-AppDeployToolkit.exe'
            if (-not (Test-Path $exe)) {
                Write-LabLog -Event 'install.source_missing' -Data @{ errorCode = 'E21'; appId = $AppId; method = $inst.method; packagePath = $pkgPath; exe = $exe }
                $txtStatus.Text = "[E21] PSADT package not found: $pkgPath"
                Reset-AppCardState -AppId $AppId -ErrorDetail "[E21] Package not found: $pkgPath"
                if ($FromQueue) { Resume-InstallQueue }
                return
            }
            $launchFile = $exe
            $launchArgs = '-DeployMode Silent'
            $what = "This deployment package will run silently:`n`n    $exe"
            if (-not (Confirm-CommandPreview -DisplayName $appDef.displayName -Verb $actVerb -WhatHappens $what -ExactProgram $launchFile -ExactArguments $launchArgs)) {
                Write-LabLog -Event 'install.preview_declined' -Data @{ appId = $AppId; method = $inst.method; command = "$launchFile $launchArgs" }
                $txtStatus.Text = "$($appDef.displayName): cancelled at command preview"
                Reset-AppCardState -AppId $AppId
                if ($FromQueue) { Resume-InstallQueue }
                return
            }
            $script:installProcess = Start-Process -FilePath $launchFile -ArgumentList $launchArgs -PassThru -WindowStyle Hidden
            Write-LabLog -Event 'install.process_started' -Data @{
                appId = $AppId
                method = $inst.method
                filePath = $launchFile
                arguments = $launchArgs
                pid = $script:installProcess.Id
            }
        }
        'exe' {
            $exePath = Join-Path $script:SourceRoot $inst.sourceSub
            if (-not (Test-Path $exePath)) {
                Write-LabLog -Event 'install.source_missing' -Data @{ errorCode = 'E21'; appId = $AppId; method = $inst.method; exe = $exePath }
                $txtStatus.Text = "[E21] Installer not found: $exePath"
                Reset-AppCardState -AppId $AppId -ErrorDetail "[E21] Installer not found: $exePath"
                if ($FromQueue) { Resume-InstallQueue }
                return
            }
            # Resolve {source}/{file} placeholders in the args (e.g. MATLAB's
            # -inputFile "{source}\MatlabImage\installer_input.txt"). Without this
            # the literal {source} reaches setup.exe and the silent install fails.
            $a = if ($inst.arguments) { Expand-LicenceTokens (($inst.arguments -replace '\{source\}', $script:SourceRoot) -replace '\{file\}', $exePath) } else { '' }
            # Run via cmd /c to inherit current admin elevation and avoid UAC re-prompt
            $launchFile = 'cmd.exe'
            $launchArgs = "/c `"`"$exePath`" $a`""
            $what = "This installer program will run:`n`n    $exePath`n`nWith these options:`n    $(if ($a) { $a } else { '(no options)' })"
            if (-not (Confirm-CommandPreview -DisplayName $appDef.displayName -Verb $actVerb -WhatHappens $what -ExactProgram $launchFile -ExactArguments $launchArgs)) {
                Write-LabLog -Event 'install.preview_declined' -Data @{ appId = $AppId; method = $inst.method; installer = $exePath; installerArguments = $a }
                $txtStatus.Text = "$($appDef.displayName): cancelled at command preview"
                Reset-AppCardState -AppId $AppId
                if ($FromQueue) { Resume-InstallQueue }
                return
            }
            $script:installProcess = Start-Process -FilePath $launchFile -ArgumentList $launchArgs -PassThru -WindowStyle Hidden
            Write-LabLog -Event 'install.process_started' -Data @{
                appId = $AppId
                method = $inst.method
                filePath = $launchFile
                arguments = $launchArgs
                installer = $exePath
                installerArguments = $a
                pid = $script:installProcess.Id
            }
        }
        'msi' {
            $msiPath = Join-Path $script:SourceRoot $inst.sourceSub
            if (-not (Test-Path $msiPath)) {
                Write-LabLog -Event 'install.source_missing' -Data @{ errorCode = 'E21'; appId = $AppId; method = $inst.method; msi = $msiPath }
                $txtStatus.Text = "[E21] MSI not found: $msiPath"
                Reset-AppCardState -AppId $AppId -ErrorDetail "[E21] MSI not found: $msiPath"
                if ($FromQueue) { Resume-InstallQueue }
                return
            }
            $msiArgs = "/i `"$msiPath`" /qn /norestart"
            if ($inst.arguments -and $inst.arguments -ne '') {
                $msiArgs = Expand-LicenceTokens ($inst.arguments -replace '\{file\}', $msiPath)
                # Safety: custom arguments that never mention the MSI would launch
                # a package-less msiexec, which hangs on a hidden usage dialog.
                # Prepend the standard install operation so that can't happen.
                if ($msiArgs -notlike "*$msiPath*") { $msiArgs = "/i `"$msiPath`" $msiArgs" }
            }
            $msiArgs = Add-MsiVerboseLog -Arguments $msiArgs -AppId $AppId
            $launchFile = 'msiexec.exe'
            $launchArgs = $msiArgs
            $what = "Windows Installer (msiexec) will install this file:`n`n    $msiPath"
            if (-not (Confirm-CommandPreview -DisplayName $appDef.displayName -Verb $actVerb -WhatHappens $what -ExactProgram $launchFile -ExactArguments $launchArgs)) {
                Write-LabLog -Event 'install.preview_declined' -Data @{ appId = $AppId; method = $inst.method; msi = $msiPath }
                $txtStatus.Text = "$($appDef.displayName): cancelled at command preview"
                Reset-AppCardState -AppId $AppId
                if ($FromQueue) { Resume-InstallQueue }
                return
            }
            $script:installProcess = Start-Process -FilePath $launchFile -ArgumentList $launchArgs -PassThru -WindowStyle Hidden
            Write-LabLog -Event 'install.process_started' -Data @{
                appId = $AppId
                method = $inst.method
                filePath = $launchFile
                arguments = $launchArgs
                msi = $msiPath
                pid = $script:installProcess.Id
            }
        }
        'msix' {
            $pkg = Join-Path $script:SourceRoot $inst.sourceSub
            if (-not (Test-Path $pkg)) {
                Write-LabLog -Event 'install.source_missing' -Data @{ errorCode = 'E21'; appId = $AppId; method = $inst.method; msix = $pkg }
                $txtStatus.Text = "[E21] MSIX not found: $pkg"
                Reset-AppCardState -AppId $AppId -ErrorDetail "[E21] MSIX not found: $pkg"
                if ($FromQueue) { Resume-InstallQueue }
                return
            }
            # Provision machine-wide (all users). Add-AppxPackage is per-user and
            # wrong for a shared lab; provisioning gives it to every user who logs
            # in afterward. Wrapped in a tracked powershell.exe so the
            # process/exit-code/preview model still holds. -ErrorAction Stop makes
            # a provisioning failure exit non-zero -> flagged failed by default rule.
            $lic = if ($inst.skipLicense -eq $false) { '' } else { ' -SkipLicense' }
            $inner = "Add-AppxProvisionedPackage -Online -PackagePath '$pkg'$lic -ErrorAction Stop"
            $launchFile = 'powershell.exe'
            $launchArgs = "-NoProfile -ExecutionPolicy Bypass -Command `"$inner`""
            $what = "Provision this MSIX for ALL users of this PC:`n`n    $pkg"
            if (-not (Confirm-CommandPreview -DisplayName $appDef.displayName -Verb $actVerb -WhatHappens $what -ExactProgram $launchFile -ExactArguments $launchArgs)) {
                Write-LabLog -Event 'install.preview_declined' -Data @{ appId = $AppId; method = $inst.method; msix = $pkg }
                $txtStatus.Text = "$($appDef.displayName): cancelled at command preview"
                Reset-AppCardState -AppId $AppId
                if ($FromQueue) { Resume-InstallQueue }
                return
            }
            $script:installProcess = Start-Process -FilePath $launchFile -ArgumentList $launchArgs -PassThru -WindowStyle Hidden
            Write-LabLog -Event 'install.process_started' -Data @{
                appId = $AppId
                method = $inst.method
                filePath = $launchFile
                arguments = $launchArgs
                msix = $pkg
                pid = $script:installProcess.Id
            }
        }
        default {
            Write-LabLog -Event 'install.unknown_method' -Data @{ errorCode = 'E20'; appId = $AppId; method = $inst.method }
            $txtStatus.Text = "[E20] Unknown install method: $($inst.method)"
            Reset-AppCardState -AppId $AppId -ErrorDetail "[E20] Unknown install method: $($inst.method)"
            if ($FromQueue) { Resume-InstallQueue }
            return
        }
    }
    } catch {
        Write-LabLog -Event 'install.launch_exception' -Data @{ errorCode = 'E22'; appId = $AppId; method = $inst.method; error = $_.Exception.Message }
        $txtStatus.Text = "[E22] Could not start install of $($appDef.displayName): $($_.Exception.Message)"
        Reset-AppCardState -AppId $AppId -ErrorDetail "[E22] Could not start: $($_.Exception.Message)"
        if ($FromQueue) { Resume-InstallQueue }
        return
    }

    $script:installAppId = $AppId
    $script:installTimer.Start()
}

# ============================================================
#  Build App List for a Room (with detection cache)
# ============================================================
# The room's apps PLUS the requires-closure of each (deps of deps included,
# cycles guarded). LAYER 1 of the stale-red fix proven on 10101LAB34-02:
# VSIsoShell2015 exists only as RockwellCCW's dependency, so room scans never
# looked at it, no snapshot ever mentioned it, and its one bogus E24 could
# never be retired by the newest-evidence fold. Scanning the closure makes
# every dependency card produce snapshot evidence like a normal room app.
function Get-RoomScanIds {
    param($AppIds)
    $order = New-Object System.Collections.ArrayList
    $seen  = New-Object 'System.Collections.Generic.HashSet[string]'
    foreach ($id in @($AppIds)) { if ($id -and $seen.Add([string]$id)) { [void]$order.Add([string]$id) } }
    $i = 0
    while ($i -lt $order.Count) {
        $def = $script:AppsConfig.apps.($order[$i]); $i++
        if (-not $def) { continue }
        # The REAL field is install.requires (that's what the install chain at
        # Start-SingleInstall reads and what every card in apps.json uses);
        # top-level requires is accepted too so a hand-added card can't miss.
        foreach ($dep in @(@($def.requires) + @($def.install.requires))) {   # string OR array either way
            if (-not $dep) { continue }
            $dd = $script:AppsConfig.apps.$dep
            if (-not $dd -or $dd.disabled) { continue }
            if ($seen.Add([string]$dep)) { [void]$order.Add([string]$dep) }
        }
    }
    return ,@($order)
}

function Set-RoomApps {
    param([string]$RoomId)

    $script:scanTimer.Stop()
    $script:scanQueue.Clear()
    # Drop pending version backfills for the outgoing room's cards. New-AppCard
    # re-enqueues (and restarts the timer) for any still-uncached app it shows.
    $script:verTimer.Stop()
    $script:verQueue.Clear()
    # Note: indexes are NOT cleared here -- the installed-software index is
    # machine-wide, so a plain room switch reuses it. It's rebuilt only when
    # state may have changed (Refresh All, or after an install/uninstall).

    $script:CurrentRoom = $RoomId
    $pnlApps.Children.Clear()
    $script:Cards.Clear()
    $script:CardOrder = @()

    # "ALL" is a synthetic room -- show every app in the catalog
    if ($RoomId -eq '_ALL_') {
        $appIds = @($script:AppsConfig.apps.PSObject.Properties.Name)
    } else {
        $room = $script:RoomsConfig.rooms.$RoomId
        if (-not $room) { $txtStatus.Text = "Unknown room: $RoomId"; Update-Summary; return }
        $appIds = @($room.apps)
    }
    # Remember the on-screen order: batch installs and scans follow it, so
    # "Install All Missing" runs top-to-bottom exactly as the cards appear.
    $script:CardOrder = @($appIds)

    foreach ($appId in $appIds) {
        $cardBorder = New-AppCard -AppId $appId
        $pnlApps.Children.Add($cardBorder) | Out-Null
        # Disabled apps are never scanned -- New-AppCard already greyed the card.
        if ($script:Cards[$appId].Disabled) { continue }
        # Auto-scan off: only process apps with cached results (instant).
        # The rest stay unscanned until the user acts on them.
        if ($script:AutoScan -or $script:DetectionCache.ContainsKey($appId)) {
            $script:scanQueue.Enqueue($appId)
        } else {
            $card = $script:Cards[$appId]
            $card.Detail.Text = 'Not scanned - click Refresh to scan (Install/Uninstall will scan first)'
            $card.Status = 'Unknown'
        }
    }

    # Dependency-closure scanning: queue the requires-chain of every room app
    # too. No card exists for these - the scan machinery is card-less-safe
    # (Update-AppCard no-ops, the snapshot reports everything in the cache),
    # so they contribute fleet evidence without touching the room's UI.
    foreach ($depId in (Get-RoomScanIds -AppIds $appIds)) {
        if ($script:Cards.ContainsKey($depId)) { continue }   # room app - already handled above
        if ($script:AutoScan -or $script:DetectionCache.ContainsKey($depId)) {
            $script:scanQueue.Enqueue($depId)
        }
    }

    Update-Summary
    if ($script:scanQueue.Count -gt 0) {
        # Build the detection indexes off the UI thread so the window stays
        # responsive during the ~2s filesystem walk, then start the (now fast)
        # per-app scan. If the index already exists (plain room switch), this
        # runs the scan immediately with no rebuild.
        $txtStatus.Text = 'Preparing scan (indexing installed software)...'
        Start-IndexBuildAsync -OnReady {
            $txtStatus.Text = 'Scanning installed software...'
            $script:scanTimer.Start()
        }
    } else {
        # Queue can also be empty with auto-scan ON (e.g. every app in the room
        # is disabled or already cached) -- don't claim auto-scan is off then.
        $txtStatus.Text = if ($script:AutoScan) { 'Ready' } else { 'Auto-scan is off - apps will be scanned when you act on them' }
        # ZERO-CARD MACHINES STILL REPORT TO CLOUDFLARE. A ENG 61+ station is GP/CM-only
        # (its number is outside the room's program rule, so it matches no cards) and any
        # valid-named machine in a real room with no configured programs is the same: the
        # scan queue is empty. Before, that meant the scan timer never started, so the
        # timer's completion block -- which writes the snapshot AND runs the Refresh-All push
        # AND the -Auto Install-All hand-off -- never fired, and machines like 64/65/66 could
        # NEVER reach the dashboard ("Refresh All did nothing when there were no cards").
        # Design (Blake, 2026-08-19): a valid decoded name in a real room is ALWAYS treated
        # as at least GP/CM-only and MUST report, cards or not. So start the scan timer even
        # with an empty queue: its first tick immediately hits the same completion block a
        # normal scan does, snapshotting and -- on a Refresh All ($PushAfterScan) or an
        # unattended -Auto run ($AutoInstallPending) -- pushing. Reuses ONE code path (no
        # dup, no ordering games: the dispatcher tick fires after startup, so the -Auto flag
        # is set by then). Nothing to install means the Install-All hand-off finds nothing
        # missing; GP/CM already run separately via Invoke-AutoGpCm at startup. An UNdecoded
        # name (no room) never reaches here -- it stands down for a rename (E11), by design.
        if (-not $script:scanTimer.IsEnabled) { $script:scanTimer.Start() }
    }
}

# ============================================================
#  Populate Room Dropdown  (real rooms + "All Applications")
# ============================================================
foreach ($p in $script:RoomsConfig.rooms.PSObject.Properties) {
    $cmbRoom.Items.Add($p.Value.displayName) | Out-Null
    $script:RoomIdList += $p.Name
}
# Add the synthetic "ALL" option at the end
$cmbRoom.Items.Add('--- All Applications ---') | Out-Null
$script:RoomIdList += '_ALL_'

# ============================================================
#  Event Handlers
# ============================================================

$cmbRoom.Add_SelectionChanged({
    if ($script:suppressRoomChange) { return }   # re-entrancy guard for programmatic reverts
    # Block room switch if an install/uninstall (or post-install verify) is running
    if (Test-OperationInProgress) {
        $txtStatus.Text = 'Cannot switch rooms while an install/uninstall is in progress'
        # Revert the dropdown to the room actually displayed, so it can't lie
        # about which room's apps/batch actions are live.
        $cur = [array]::IndexOf($script:RoomIdList, $script:CurrentRoom)
        if ($cur -ge 0 -and $cur -ne $cmbRoom.SelectedIndex) {
            $script:suppressRoomChange = $true
            $cmbRoom.SelectedIndex = $cur
            $script:suppressRoomChange = $false
        }
        return
    }
    $idx = $cmbRoom.SelectedIndex
    if ($idx -ge 0 -and $idx -lt $script:RoomIdList.Count) {
        Set-RoomApps -RoomId $script:RoomIdList[$idx]
        Apply-HealthVisibility   # the new room may enable/disable health chips
    }
})

$btnRefreshAll.Add_Click({
    # Block if an install/uninstall (or post-install verify) is running
    if (Test-OperationInProgress) {
        $txtStatus.Text = 'Cannot refresh while an install/uninstall is in progress'
        return
    }
    # Clear entire cache AND the machine-wide indexes, then rescan (forces a
    # fresh index build to pick up anything installed/removed outside the tool)
    $script:DetectionCache.Clear()
    Clear-DetectionIndexes
    if ($script:CurrentRoom) {
        # Refresh All must ALWAYS push the fresh scan to Cloudflare. The scan is async;
        # this flag is consumed right after it writes its snapshot (see Write-ScanSnapshot
        # call site), so the push carries the just-scanned truth.
        $script:PushAfterScan = $true
        Set-RoomApps -RoomId $script:CurrentRoom
    }
})

# DEDICATED CLOUDFLARE SYNC (Blake, 2026-08-19: "add a dedicated sync button, make it
# bulletproof, show when it's sending and when it's done"). Unlike Refresh All, this is
# NOT gated on a loaded room, program cards, or a completed scan - it calls Push-Observations
# straight on the stick's logs. Push-Observations ALWAYS re-sends the current session's live
# log (idempotent obs_ids) plus anything not yet confirmed-pushed, and skips what already
# landed - so one click reliably gets THIS machine onto the dashboard even when it's a
# GP/CM-only station with zero cards, or its hostname wouldn't decode into a room. Fully
# self-contained + wrapped: it can report a problem but it can never throw or wedge the UI.
$btnSyncCloud.Add_Click({
    $b = $this                         # the Sync button (event sender)
    $idleText = 'Sync To Server'
    $idleBg   = $b.Background
    $mkBrush  = { param($r,$g,$bl) New-Object System.Windows.Media.SolidColorBrush ([System.Windows.Media.Color]::FromRgb($r,$g,$bl)) }
    try {
        # 1) SENDING state - and force it to PAINT before the (blocking) push, or the
        #    label would only change after the call already returned.
        $b.IsEnabled = $false
        $b.Content   = 'Sending...'
        try { $b.Background = (& $mkBrush 0xB0 0x74 0x0D) } catch { }   # amber
        try { $txtStatus.Text = 'Sending results to Cloudflare...' } catch { }
        try { $b.Dispatcher.Invoke([System.Action]{}, [System.Windows.Threading.DispatcherPriority]::Render) } catch { }

        # 2) THE PUSH. Never throws (its own try/catch), but wrap anyway - belt and braces.
        $r = $null
        try { $r = Push-Observations -DeadlineSec 30 } catch { $r = @{ ok = $false; reason = "$($_.Exception.Message)"; sent = 0; stopped = 'error' } }
        if (-not $r) { $r = @{ ok = $false; reason = 'no-result'; sent = 0; stopped = 'error' } }

        # 3) DONE state - a clear, honest outcome on the button AND the status bar.
        $sent = 0; try { $sent = [int]$r.sent } catch { }
        if ("$($r.reason)" -ne '' -and $r.stopped -ne 'error') {
            $msg = switch ("$($r.reason)") {
                'disabled'    { 'Telemetry is turned off in telemetry.json.' }
                'no-endpoint' { 'No Cloudflare URL set in telemetry.json.' }
                'no-token'    { 'This stick has no telemetry token.' }
                'no-logs'     { 'No logs on this stick yet.' }
                default       { "Could not send: $($r.reason)" }
            }
            $b.Content = 'Not sent'
            try { $b.Background = (& $mkBrush 0xC0 0x3A 0x3E) } catch { }
            try { $txtStatus.Text = "[E72] $msg" } catch { }
        }
        elseif ($r.stopped -eq 'network' -or $r.stopped -eq 'error') {
            $b.Content = 'No internet - retry'
            try { $b.Background = (& $mkBrush 0xC0 0x3A 0x3E) } catch { }
            try { $txtStatus.Text = "Cloudflare unreachable from this PC (sent $sent so far). Check the network, then click Sync again." } catch { }
        }
        elseif ($sent -gt 0) {
            $b.Content = "Sent OK ($sent)"
            try { $b.Background = (& $mkBrush 0x2E 0xA0 0x43) } catch { }
            try { $txtStatus.Text = "Done - sent $sent result row(s) to Cloudflare." } catch { }
        }
        else {
            $b.Content = 'Up to date'
            try { $b.Background = (& $mkBrush 0x2E 0xA0 0x43) } catch { }
            try { $txtStatus.Text = 'Done - already up to date, nothing new to send.' } catch { }
        }
    }
    catch {
        try { $b.Content = 'Error - retry' } catch { }
        try { $b.Background = (& $mkBrush 0xC0 0x3A 0x3E) } catch { }
    }
    finally {
        $b.IsEnabled = $true
        # Return the button to its resting look after a few seconds (one-shot), so the
        # outcome is readable but the control is clean for the next machine.
        try {
            $rt = New-Object System.Windows.Threading.DispatcherTimer
            $rt.Interval = [TimeSpan]::FromSeconds(5)
            $rt.Tag = @{ Btn = $b; Text = $idleText; Bg = $idleBg; Timer = $rt }
            $rt.Add_Tick({ $t = $this.Tag; try { $t.Btn.Content = $t.Text; $t.Btn.Background = $t.Bg } catch { }; try { $t.Timer.Stop() } catch { } })
            $rt.Start()
        } catch { }
    }
})

$btnInstallMissing.Add_Click({
    # PAUSE / CONTINUE while a batch is mid-flight (Blake, 2026-08-12). The
    # button stays ENABLED during a batch and toggles:
    #   running          -> click = pause AFTER the current installer finishes
    #   pause requested  -> click = never mind, keep going
    #   actually paused  -> click = continue the queue
    # A batch is "mid-flight" while it still owns queued work; per-card installs
    # outside a batch fall through to the one-operation-at-a-time guard below.
    if (@($script:BatchQueued).Count -gt 0 -and ($script:installQueue.Count -gt 0 -or $script:MsiWaitActive)) {
        if (-not $script:BatchPaused) {
            $script:BatchPaused = $true
            if ($script:MsiWaitActive) {
                # Only WAITING for someone else's MSI lock - our installer never
                # launched. The wait pump sees the flag within a second, aborts,
                # requeues that app at the front, and holds right here.
                $btnInstallMissing.Content = 'Continue Install All Missing'
                $txtStatus.Text = 'Pausing - nothing was mid-install, holding before the next one starts...'
            } elseif (Test-OperationInProgress) {
                # Current installer keeps running - Resume-InstallQueue holds the
                # NEXT one. Never kill a vendor installer mid-flight.
                $btnInstallMissing.Content = 'Pausing after current install...'
                $txtStatus.Text = "Will pause after the current install finishes ($($script:installQueue.Count) more queued). Click again to keep going instead."
            } else {
                $btnInstallMissing.Content = 'Continue Install All Missing'
                $txtStatus.Text = "Paused - $($script:installQueue.Count) install(s) still queued."
            }
            Write-LabLog -Event 'installall.pause_requested' -Data @{ remaining = $script:installQueue.Count; duringMsiWait = [bool]$script:MsiWaitActive }
        } else {
            $script:BatchPaused = $false
            $btnInstallMissing.Content = 'Pause'
            Write-LabLog -Event 'installall.resumed' -Data @{ remaining = $script:installQueue.Count }
            if (-not (Test-OperationInProgress)) {
                # Genuinely held at the boundary -> restart the drain. If an
                # installer is still finishing, its completion path calls
                # Resume-InstallQueue itself and sails through the open gate.
                $txtStatus.Text = "Continuing - $($script:installQueue.Count) install(s) to go..."
                Resume-InstallQueue
            } else {
                $txtStatus.Text = 'Pause cancelled - the batch will continue automatically.'
            }
        }
        return
    }
    # Safeguard: one operation at a time
    if (Test-OperationInProgress) {
        $txtStatus.Text = 'Another install/uninstall is still in progress - wait for it to finish'
        return
    }
    # IMAGE GATE before anything is queued: a "No" on a year-old or unimaged
    # campus machine must leave the queue completely untouched, not abort
    # halfway through a 19-app batch.
    if (-not (Confirm-ImageGate)) { return }
    # Walk cards in ON-SCREEN order (rooms.json order for a room profile),
    # not hashtable order -- the batch installs top-to-bottom as displayed.
    $orderedCards = @(foreach ($id in $script:CardOrder) { if ($script:Cards.ContainsKey($id)) { $script:Cards[$id] } })
    $actionable = @($orderedCards | Where-Object { $_.Status -eq 'Missing' -or $_.Status -eq 'UserOnly' })
    # Honour install.excludeFromInstallAll. Keeping an app out of every room
    # profile is NOT enough to keep it out of a batch: this handler walks the
    # cards CURRENTLY ON SCREEN, so switching to "--- All Applications ---" and
    # clicking Install All swept up exactly the apps that were deliberately
    # room-less. That mattered for Npcap, whose FREE licence permits 5 installs
    # per ORGANISATION - one All-view batch per machine would have breached it
    # fleet-wide. Such apps stay individually installable from their own card.
    $excluded = @($actionable | Where-Object { $script:AppsConfig.apps.($_.AppId).install.excludeFromInstallAll })
    if ($excluded.Count -gt 0) {
        $actionable = @($actionable | Where-Object { -not $script:AppsConfig.apps.($_.AppId).install.excludeFromInstallAll })
        Write-LabLog -Event 'installall.excluded' -Data @{ apps = (($excluded | ForEach-Object { $_.AppId }) -join ', ') }
    }
    # ---- BATCH ORDER: ONE stable rank sort (replaces two chained moves) ----
    # Rank, low = earlier. Data-driven, so order changes live in apps.json:
    #     0   normal
    #    10   install.installLast                    (heavy / licence-fiddly)
    #    20   methodLabel contains "interactive"     (needs a human)
    #    install.installOrder = N  OVERRIDES all of the above
    #
    # Blake 2026-07-29: MATLAB must be 2nd-to-last and MatlabArduino dead last
    # (installOrder 90 / 100) - i.e. AFTER the wizards. That deliberately
    # reverses the earlier "interactive last" tweak, and the reasoning is
    # one-visit deployment: the tech clicks through every wizard while standing
    # there, kicks off the long silent MATLAB pair, and leaves for good, rather
    # than leaving early and having to COME BACK for the wizards.
    # MatlabArduino also `requires` MATLAB, so putting the pair last in this
    # order keeps the dependency chain natural - MATLAB is already done when
    # its packages start, and nothing ever has to be re-queued.
    #
    # The ORIGINAL INDEX is the tiebreaker because PowerShell's Sort-Object is
    # NOT a stable sort: without it, equal-rank apps could come out shuffled
    # and "Install All runs top-to-bottom as displayed" would quietly become
    # false. Chained Where-Object moves used to guarantee that implicitly.
    $ranked = @()
    for ($bi = 0; $bi -lt $actionable.Count; $bi++) {
        $bCard = $actionable[$bi]
        $bInst = $script:AppsConfig.apps.($bCard.AppId).install
        $bRank = 0
        if ($bInst.installLast) { $bRank = 10 }
        if ("$($bInst.methodLabel)" -match '(?i)interactive') { $bRank = 20 }
        if ($null -ne $bInst.installOrder) { $bRank = [int]$bInst.installOrder }
        $ranked += [pscustomobject]@{ Card = $bCard; Rank = $bRank; Idx = $bi }
    }
    $sortedBatch = @($ranked | Sort-Object Rank, Idx)
    $actionable  = @($sortedBatch | ForEach-Object { $_.Card })
    # Log the resolved order every run - this is the audit trail for "did it
    # actually install in the order I asked for?" without reading the code.
    Write-LabLog -Event 'installall.order' -Data @{
        order = (($sortedBatch | ForEach-Object { "$($_.Card.AppId)($($_.Rank))" }) -join ' > ')
    }
    $unknownCount = @($script:Cards.Values | Where-Object { $_.Status -eq 'Unknown' }).Count
    if ($actionable.Count -eq 0) {
        if ($unknownCount -gt 0) {
            $txtStatus.Text = "Nothing known to install - $unknownCount app(s) not scanned yet (use Refresh All or enable auto-scan)"
        } else {
            $txtStatus.Text = 'Nothing to install - all apps are present system-wide!'
        }
        return
    }
    if (-not $script:IsAdmin) {
        [System.Windows.MessageBox]::Show("[E60] Installing requires admin.`nPlease re-launch via Launch.bat.", 'Admin Required (E60)', 'OK', 'Warning')
        return
    }

    $mc = @($actionable | Where-Object { $_.Status -eq 'Missing'  }).Count
    $uc = @($actionable | Where-Object { $_.Status -eq 'UserOnly' }).Count
    $desc = @()
    if ($mc -gt 0) { $desc += "$mc missing" }
    if ($uc -gt 0) { $desc += "$uc user-only" }
    if ($unknownCount -gt 0) { $desc += "$unknownCount not scanned (skipped)" }

    $confirm = [System.Windows.MessageBox]::Show(
        "Install $($actionable.Count) application(s)?`n$($desc -join ', ')`n`nThis may take a while.",
        'Confirm Install', 'YesNo', 'Question')
    if ($confirm -ne 'Yes') { return }

    # Enqueue EVERYTHING and start via Resume-InstallQueue so the first item
    # runs with -FromQueue too. (Starting the first item directly meant an early
    # launch failure never called Resume-InstallQueue: the rest of the batch was
    # stranded in the queue and btnInstallMissing stayed disabled forever.)
    # The button stays ENABLED as the batch's Pause control - the pause branch
    # at the top of this handler owns every click until the queue drains.
    $script:BatchPaused = $false
    $btnInstallMissing.Content = 'Pause'
    # Record that a BATCH started and exactly what was queued. Without this an
    # "Install All" run is indistinguishable in the logs from someone clicking
    # cards one at a time - which made it impossible to tell, after the fact,
    # whether an app was skipped by the tool or simply never clicked. It also
    # gives the fleet ledger a real answer to "what did they attempt to install".
    $script:BatchQueued = @($actionable | ForEach-Object { $_.AppId })
    $script:BatchStarted = Get-Date
    Write-LabLog -Event 'installall.started' -Data @{
        count = $script:BatchQueued.Count
        queued = ($script:BatchQueued -join ', ')
        room = "$($cmbRoom.SelectedItem)"
    }
    foreach ($card in $actionable) { $script:installQueue.Enqueue($card.AppId) }
    Resume-InstallQueue
})

# In-app pass - no console window. Verifies (and creates where missing) the
# shared-desktop shortcut of every INSTALLED app in the current room, updating
# each card's Shortcut chip as it goes.
#
# A function, not just a button handler, because "Install All Missing" runs it
# automatically as its final step (Blake, 2026-07-30). Per-app shortcut repair
# already happens after each individual install, but a batch is exactly when
# things drift: a dependency installed mid-chain, an app that arrived via the
# retry path, or a vendor installer that dropped its own differently-named icon.
# One sweep at the end means a finished batch always leaves the shared desktop
# in a known-good state instead of relying on 19 separate steps each having
# gone right.
function Invoke-VerifyShortcuts {
    param([switch]$Auto)   # $Auto = end of a batch; phrases the status line differently
    $ok = 0; $made = 0; $failed = 0; $na = 0; $renamed = 0; $off = 0
    $script:LnkCache = $null   # fresh desktop read
    foreach ($card in $script:Cards.Values) {
        if ($card.Disabled) { continue }
        $id = $card.AppId
        if (-not ($script:DetectionCache.ContainsKey($id) -and $script:DetectionCache[$id].Installed)) { continue }
        $before = Test-AppShortcut -AppId $id
        if (-not $before.Applicable) { $na++; Update-ShortcutBox -AppId $id; continue }
        # Card's desktop-icon box unticked -> Verify must not put one back, or
        # the bulk button would silently undo the policy every time it runs.
        if (-not (Test-AppAutoShortcut -AppId $id)) { $off++; Update-ShortcutBox -AppId $id; continue }
        # Present is NOT enough: a card with a strict shortcutName (LabVIEW) can
        # be Present under the OLD name. Skipping on Present alone is what made
        # Verify report "already OK" and leave last year's icon untouched.
        if ($before.Present -and $before.NameOk) { $ok++; Update-ShortcutBox -AppId $id; continue }
        $wasRename = ($before.Present -and -not $before.NameOk)
        $after = Repair-AppShortcut -AppId $id
        if ($after.Present -and $after.NameOk) {
            if ($wasRename) { $renamed++ } else { $made++ }
        } else { $failed++ }
    }
    $summary = "$ok already OK, $made created, $renamed renamed, $failed failed, $na don't need one, $off turned off"
    Write-LabLog -Event 'shortcut.verify_all' -Data @{
        ok = $ok; created = $made; renamed = $renamed; failed = $failed
        notNeeded = $na; iconOff = $off; auto = [bool]$Auto
    }
    return @{ Text = $summary; Ok = $ok; Made = $made; Renamed = $renamed; Failed = $failed; Na = $na; Off = $off }
}

$btnShortcuts.Add_Click({
    $r = Invoke-VerifyShortcuts
    $txtStatus.Text = "Shortcuts: $($r.Text)  (installed apps in this room)"
})

$btnPKI.Add_Click({
    $sp = Join-Path $PSScriptRoot 'scripts\Test-PKICertificate.ps1'
    if (Test-Path $sp) {
        Write-LabLog -Event 'pki.check_launched' -Data @{ script = $sp }
        Start-Process -FilePath 'powershell.exe' -ArgumentList "-NoProfile -NoExit -ExecutionPolicy Bypass -File `"$sp`""
    } else { $txtStatus.Text = "Script not found: $sp" }
    # SECOND style - repair attempt: if the machine cert is missing, pulse the
    # certificate autoenrollment engine (certutil -pulse = the documented way to
    # kick AD auto-enrollment without waiting for the next GP cycle), then
    # re-check the chip shortly after. Harmless no-op when the cert exists.
    $missing = $false
    try {
        $missing = -not (Get-ChildItem Cert:\LocalMachine\My -ErrorAction Stop |
            Where-Object { $_.Subject -match $env:COMPUTERNAME -and $_.NotAfter -gt [datetime]::Now })
    } catch { }
    if ($missing) {
        try {
            Start-Process certutil.exe -ArgumentList '-pulse' -WindowStyle Hidden
            Write-LabLog -Event 'pki.pulse_fired' -Data @{ }
            $txtStatus.Text = 'No machine cert found - fired certificate auto-enrollment (certutil -pulse); chip re-checks in 25s'
            $t = New-Object System.Windows.Threading.DispatcherTimer
            $t.Interval = [TimeSpan]::FromSeconds(25)
            $t.Add_Tick({ $this.Stop(); Update-HealthStrip })
            $t.Start()
        } catch { }
    }
})

# ============================================================
#  Caffeine (stay-awake) -- stateful toggle button, no popups
# ============================================================
# Runs Zhorn Caffeine (portable) straight from the tool folder, so it works from
# the flash drive on any drive letter. Running the exe installs nothing. The
# button IS the indicator: green "Caffeine ON" while running, gray "Caffeine
# OFF" when stopped. Auto-started ON at launch; stopped when the tool closes.
function Get-CaffeineExe {
    $caffDir = Join-Path $PSScriptRoot 'tools\Caffeine'
    foreach ($n in 'caffeine64.exe','caffeine32.exe') {
        $p = Join-Path $caffDir $n
        if (Test-Path $p) { return $p }
    }
    return $null
}
function Test-CaffeineRunning {
    return [bool](Get-Process -Name 'caffeine32','caffeine64' -ErrorAction SilentlyContinue)
}
function Stop-Caffeine {
    try { Get-Process -Name 'caffeine32','caffeine64' -ErrorAction SilentlyContinue | Stop-Process -Force -ErrorAction SilentlyContinue } catch { }
}
function Start-Caffeine {
    if (Test-CaffeineRunning) { return $true }
    $exe = Get-CaffeineExe
    if (-not $exe) { return $false }
    try { Start-Process -FilePath $exe -WorkingDirectory (Split-Path $exe -Parent) | Out-Null; return $true }
    catch { return $false }
}
function Set-CaffeineState {
    param([bool]$On)
    # Chip indicator (Blake, 2026-07-31): state lives in the dot + label now,
    # not the button background - the chip chrome itself never changes.
    if ($On -and (Start-Caffeine)) {
        $script:CaffeineOn    = $true
        $txtCaffeineChip.Text = 'Caffeine ON'
        $dotCaffeine.Fill     = $script:BrushDotOn
    } elseif ($On) {
        # Requested ON but the exe is missing -> show OFF + one quiet status note
        $script:CaffeineOn    = $false
        $txtCaffeineChip.Text = 'Caffeine OFF'
        $dotCaffeine.Fill     = $script:BrushDotOff
        $txtStatus.Text       = 'Caffeine not found in tools\Caffeine - stay-awake unavailable'
    } else {
        Stop-Caffeine
        $script:CaffeineOn    = $false
        $txtCaffeineChip.Text = 'Caffeine OFF'
        $dotCaffeine.Fill     = $script:BrushDotOff
    }
    Write-LabLog -Event 'caffeine.state' -Data @{ on = $script:CaffeineOn }
}
$btnCaffeine.Add_Click({ Set-CaffeineState -On (-not $script:CaffeineOn) })

# ============================================================
#  Winget status / offline installer -- stateful button
# ============================================================
# The button IS the indicator: green "winget: Installed" when present, red
# "winget: MISSING" when not. Clicking a red button installs winget (App
# Installer) from <sources>\WingetBootstrap on this drive - works offline.
function Test-WingetPresent {
    if (Get-Command winget.exe -ErrorAction SilentlyContinue) { return $true }
    # Fallback: the per-user execution alias sometimes lags PATH lookup
    return (Test-Path (Join-Path $env:LOCALAPPDATA 'Microsoft\WindowsApps\winget.exe'))
}
function Update-WingetButton {
    # Chip indicator (Blake, 2026-07-31): dot + label, not button background.
    if (Test-WingetPresent) {
        $txtWingetChip.Text = 'winget'
        $dotWinget.Fill     = $script:BrushDotOn
    } else {
        $txtWingetChip.Text = 'winget MISSING - click to install'
        # Warning, not danger: missing winget is "action needed", nothing is
        # being destroyed. Red here previously (#C42B1C) broke the
        # "red = destructive" contract the Clean Temp button relies on.
        $dotWinget.Fill     = $script:BrushDotWarn
    }
}
$btnWinget.Add_Click({
    # Installing winget mid-operation would run Add-AppxPackage on the UI
    # thread while the install timer machinery is live -> crash. One slot rule.
    if (Test-OperationInProgress) {
        $txtStatus.Text = 'An install/uninstall is still in progress - wait for it to finish before installing winget'
        return
    }
    if (Test-WingetPresent) {
        Update-WingetButton
        # Already installed -> offer a repair. Useful when winget exists but
        # is broken (corrupted package, failing on every command).
        $ans = [System.Windows.MessageBox]::Show(
            "winget is already installed on this PC.`n`nReinstall (repair) it from the drive anyway?`nUse this if winget seems broken.",
            'Reinstall winget?',
            [System.Windows.MessageBoxButton]::YesNo,
            [System.Windows.MessageBoxImage]::Question)
        if ($ans -ne [System.Windows.MessageBoxResult]::Yes) {
            $txtStatus.Text = 'winget is already installed on this PC'
            return
        }
        Write-LabLog -Event 'winget.repair_requested' -Data @{ }
        # falls through to the normal install below (force flags make it a repair)
    }
    # Bootstrap files live on the drive so this works with no internet
    $bootDir = Join-Path $script:SourceRoot 'WingetBootstrap'
    $bundle  = Join-Path $bootDir 'Microsoft.DesktopAppInstaller_8wekyb3d8bbwe.msixbundle'
    if (-not (Test-Path $bundle)) {
        Write-LabLog -Event 'winget.bootstrap_missing' -Data @{ errorCode = 'E64'; path = $bundle }
        $txtStatus.Text = "[E64] winget bootstrap files not found on the drive: $bootDir"
        return
    }
    # Dependencies first (only the ones present on the drive), then the bundle
    $deps = @(
        (Join-Path $bootDir 'Microsoft.VCLibs.x64.14.00.Desktop.appx'),
        (Join-Path $bootDir 'Microsoft.UI.Xaml.2.8.x64.appx')
    ) | Where-Object { Test-Path $_ }


    Write-LabLog -Event 'winget.install_start' -Data @{ bundle = $bundle }
    $btnWinget.IsEnabled = $false
    $txtWingetChip.Text  = 'winget installing...'
    $dotWinget.Fill      = $script:BrushDotOff
    $txtStatus.Text      = 'Installing winget (App Installer) from the drive - takes about half a minute...'
    $window.Cursor = [System.Windows.Input.Cursors]::Wait
    $window.Dispatcher.Invoke([action]{}, [System.Windows.Threading.DispatcherPriority]::Render)
    try {
        foreach ($p in $deps)  { try { Add-AppxPackage -Path $p -ErrorAction Stop } catch { } }  # deps may already exist
        # Force flags make this work as a REPAIR too: reinstall over the same
        # (or newer) version, closing a stuck winget if one is running.
        # Harmless on a fresh install.
        Add-AppxPackage -Path $bundle -ForceApplicationShutdown -ForceUpdateFromAnyVersion -ErrorAction Stop
        # Best effort: provision for every future user of this PC too
        try { Add-AppxProvisionedPackage -Online -PackagePath $bundle -SkipLicense -ErrorAction Stop | Out-Null } catch { }
        # Fresh winget ships with an EMPTY package catalog - first app install
        # fails with SOURCE_DATA_MISSING (exit -1978335217) until the catalog
        # is downloaded. Prime it now (needs internet; 2-min cap so a hung
        # winget can never freeze the tool).
        $wg = Join-Path $env:LOCALAPPDATA 'Microsoft\WindowsApps\winget.exe'
        if (-not (Test-Path $wg)) { $wg = 'winget' }
        $txtStatus.Text = 'winget installed - downloading its package catalog (needs internet)...'
        $window.Dispatcher.Invoke([action]{}, [System.Windows.Threading.DispatcherPriority]::Render)
        try {
            $p = Start-Process -FilePath $wg -ArgumentList 'source update' -WindowStyle Hidden -PassThru -ErrorAction Stop
            if (-not (Wait-ProcessResponsive -Proc $p -TimeoutSec 120)) { try { $p.Kill() } catch { } }
        } catch { }
        if (Test-WingetPresent) {
            Write-LabLog -Event 'winget.install_ok' -Data @{ }
            $txtStatus.Text = 'winget installed - winget apps can be installed now'
        } else {
            Write-LabLog -Event 'winget.install_not_detected' -Data @{ errorCode = 'E66' }
            $txtStatus.Text = '[E66] winget was installed but is not detected yet - log off and back on, then retry'
        }
    } catch {
        Write-LabLog -Event 'winget.install_fail' -Data @{ errorCode = 'E65'; error = "$_" }
        $txtStatus.Text = "[E65] winget install failed: $($_.Exception.Message)"
    } finally {
        $window.Cursor = $null
        $btnWinget.IsEnabled = $true
        Update-WingetButton
    }
})
Update-WingetButton   # set the real state at startup

# ============================================================
#  Machine Health pill  (imaging timestamp / GP / CM / PKI)
# ============================================================
# The old chip strip, compressed into a pill on the tab row (Blake,
# 2026-07-31): each key owns a DOT in the pill and a ROW in the click-open
# popover. Set-HealthChip keeps its signature, so all eleven call sites are
# untouched - they now recolour a dot, rewrite a popover row, and re-aggregate
# the pill ("2 issues" amber, "1 issue" red if any bad, "healthy" grey).
# Still fully independent of the install machinery.
$script:HealthChips = @{}
$script:HealthDotBrush = @{
    ok    = New-FrozenBrush 0x4E 0xC7 0x49
    warn  = New-FrozenBrush 0xD9 0xA5 0x21
    bad   = New-FrozenBrush 0xE0 0x52 0x52
    muted = New-FrozenBrush 0x55 0x55 0x5E
}
$script:HealthPillTone = @{  # border / text per aggregate state
    bad   = @{ B = New-FrozenBrush 0x6E 0x2E 0x2E; T = New-FrozenBrush 0xE0 0x77 0x77 }
    warn  = @{ B = New-FrozenBrush 0x6E 0x58 0x14; T = New-FrozenBrush 0xD9 0xA5 0x21 }
    ok    = @{ B = New-FrozenBrush 0x3A 0x3A 0x40; T = New-FrozenBrush 0x8A 0x8A 0x95 }
}

function New-HealthChip {
    param([string]$Key)
    $dots = $window.FindName('pnlPillDots'); $rows = $window.FindName('pnlHealthRows')
    if (-not $dots -or -not $rows) { return }
    # dot in the pill
    $d = New-Object System.Windows.Shapes.Ellipse
    $d.Width = 8; $d.Height = 8
    $d.Margin = [System.Windows.Thickness]::new(0, 0, 5, 0)
    $d.Fill = $script:HealthDotBrush.muted
    $dots.Children.Add($d) | Out-Null
    # row in the popover: dot + text
    $row = New-Object System.Windows.Controls.StackPanel
    $row.Orientation = [System.Windows.Controls.Orientation]::Horizontal
    $row.Margin = [System.Windows.Thickness]::new(14, 4, 14, 4)
    $rd = New-Object System.Windows.Shapes.Ellipse
    $rd.Width = 8; $rd.Height = 8
    $rd.Margin = [System.Windows.Thickness]::new(0, 1, 9, 0)
    $rd.VerticalAlignment = [System.Windows.VerticalAlignment]::Center
    $rd.Fill = $script:HealthDotBrush.muted
    $rt = New-Object System.Windows.Controls.TextBlock
    $rt.FontSize = 12
    $rt.Foreground = $script:BrushText
    $rt.Text = "$Key : checking..."
    $row.Children.Add($rd) | Out-Null
    $row.Children.Add($rt) | Out-Null
    $rows.Children.Add($row) | Out-Null
    $script:HealthChips[$Key] = @{ Dot = $d; RowDot = $rd; RowText = $rt; Row = $row; State = 'muted' }
}

function Update-HealthPill {
    $pill = $window.FindName('brdHealthPill'); $txt = $window.FindName('txtHealthIssues')
    if (-not $pill -or -not $txt) { return }
    $bad  = @($script:HealthChips.Values | Where-Object { $_.State -eq 'bad' }).Count
    $warn = @($script:HealthChips.Values | Where-Object { $_.State -eq 'warn' }).Count
    $issues = $bad + $warn
    $tone = if ($bad) { $script:HealthPillTone.bad } elseif ($warn) { $script:HealthPillTone.warn } else { $script:HealthPillTone.ok }
    $pill.BorderBrush = $tone.B
    $txt.Foreground   = $tone.T
    $txt.Text = if ($issues) { "$issues issue$(if ($issues -ne 1) { 's' })" } else { 'healthy' }
}

function Set-HealthChip {
    param([string]$Key, [string]$Text, [string]$State, [string]$Tip)
    $c = $script:HealthChips[$Key]; if (-not $c) { return }
    if (-not $script:HealthDotBrush.ContainsKey($State)) { $State = 'muted' }
    $c.State = $State
    $c.RowText.Text = $Text
    $c.Dot.Fill = $script:HealthDotBrush[$State]
    $c.RowDot.Fill = $script:HealthDotBrush[$State]
    if ($Tip) { $c.Row.ToolTip = $Tip; $c.Dot.ToolTip = $Tip }
    Update-HealthPill
}

function Get-HealthConfig {
    # Per-room health-check settings (rooms.json "health" block on the active
    # room). Defaults preserve the classic three-chip behaviour when a room
    # (or the ALL view) configures nothing.
    $h = @{ pki = $true; checkImage = $true; imageFile = 'C:\timestamp_Cart.txt' }
    # 1) the PHYSICAL room this machine's hostname decodes to - the Rooms &
    #    Rules Designer's per-room save (deployment-rules.json roomHealth).
    #    Tied to the machine itself, so it wins over the dropdown profile.
    try {
        $hn = ConvertFrom-LabHostname
        if ($hn.Matched) {
            $rh = $script:RulesConfig.roomHealth."$($hn.Building)-$($hn.Room)"
            if ($rh) {
                if ($null -ne $rh.pki)        { $h.pki        = [bool]$rh.pki }
                if ($null -ne $rh.checkImage) { $h.checkImage = [bool]$rh.checkImage }
                if ($rh.imageFile)            { $h.imageFile  = "$($rh.imageFile)" }
                return $h
            }
        }
    } catch { }
    # 2) the active room profile's health block (rooms.json)
    try {
        $rid = $script:CurrentRoom
        if ($rid -and $rid -ne '_ALL_') {
            $cfg = $script:RoomsConfig.rooms.$rid.health
            if ($cfg) {
                if ($null -ne $cfg.pki)        { $h.pki        = [bool]$cfg.pki }
                if ($null -ne $cfg.checkImage) { $h.checkImage = [bool]$cfg.checkImage }
                if ($cfg.imageFile)            { $h.imageFile  = "$($cfg.imageFile)" }
            }
        }
    } catch { }
    $h
}

function Set-HealthChipVisible {
    param([string]$Key, [bool]$Visible)
    $c = $script:HealthChips[$Key]; if (-not $c) { return }
    $v = if ($Visible) { [System.Windows.Visibility]::Visible } else { [System.Windows.Visibility]::Collapsed }
    $c.Dot.Visibility = $v; $c.Row.Visibility = $v
    if (-not $Visible) {
        # a check the room has switched off can never count as an issue
        $c.State = 'muted'
        $c.Dot.Fill = $script:HealthDotBrush.muted; $c.RowDot.Fill = $script:HealthDotBrush.muted
    }
    Update-HealthPill
}

function Apply-HealthVisibility {
    # Cheap entry point for room switches: shows/hides chips (and the PKI
    # button) per the active room's health config WITHOUT re-running the
    # blocking checks themselves - Update-HealthStrip does those.
    param($Config)
    if (-not $Config) { $Config = Get-HealthConfig }
    Set-HealthChipVisible -Key Imaged -Visible ([bool]$Config.checkImage)
    Set-HealthChipVisible -Key PKI    -Visible ([bool]$Config.pki)
    $b = $window.FindName('btnPKI')
    if ($b) { $b.Visibility = if ($Config.pki) { [System.Windows.Visibility]::Visible } else { [System.Windows.Visibility]::Collapsed } }
}

# GP chip retired (Blake, 2026-08-12): "GP: 3d ago / unknown" never drove a
# decision - PKI is the chip that actually catches a GP problem (no cert = GP
# hasn't delivered), and the GP Update button carries its own live state. The
# last-processed time still lands in the health.strip ledger entry.
foreach ($k in 'Imaged','CM','PKI') { New-HealthChip -Key $k }

# Pill click toggles the popover (StaysOpen=False closes it on any outside click)
$brdHealthPill = $window.FindName('brdHealthPill')
$popHealth     = $window.FindName('popHealth')
if ($brdHealthPill -and $popHealth) {
    $brdHealthPill.Add_MouseLeftButtonUp({ $popHealth.IsOpen = -not $popHealth.IsOpen })
}

function Format-TimeAgo {
    param([datetime]$T)
    $s = ([datetime]::Now - $T)
    if ($s.TotalHours -lt 1)  { return "$([math]::Floor($s.TotalMinutes))m ago" }
    if ($s.TotalDays  -lt 1)  { return "$([math]::Floor($s.TotalHours))h ago" }
    return "$([math]::Floor($s.TotalDays))d ago"
}

# Last machine Group Policy processing time, from the core GPO extension's
# state key (StartTimeHi/Lo form a FILETIME).
function Get-GPLastTime {
    try {
        $k = Get-ItemProperty 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Group Policy\State\Machine\Extension-List\{35378EAC-683F-11D2-A89A-00C04FBBCFA2}' -ErrorAction Stop
        if ($null -ne $k.StartTimeHi) {
            # StartTimeLo is a REG_DWORD read as SIGNED Int32; when its high bit
            # is set (~half the time) a [uint32] cast throws overflow. Widen to
            # int64 and mask off sign-extension instead.
            return [datetime]::FromFileTime(([int64]$k.StartTimeHi -shl 32) -bor ([int64]$k.StartTimeLo -band 0xFFFFFFFFL))
        }
    } catch { }
    return $null
}

function Get-CMActionList {
    # Same list as the Control Panel ConfigMgr applet's Actions tab.
    # Throws if the CCM client isn't on this machine.
    $cpm = New-Object -ComObject CPApplet.CPAppletMgr
    return @($cpm.GetClientActions())
}

function Invoke-CMWmiTriggers {
    # SECOND style of firing client actions: the well-known ConfigMgr schedule
    # IDs sent via WMI SMS_Client.TriggerSchedule - the exact documented call
    # every SCCM right-click tool uses. Works even when the CPApplet COM only
    # lists 2 actions (half-registered client). Returns how many were accepted.
    $ids = '001','002','003','021','022','031','113','114','121'
    $ok = 0
    foreach ($i in $ids) {
        try {
            Invoke-WmiMethod -Namespace 'root\ccm' -Class SMS_Client -Name TriggerSchedule `
                -ArgumentList "{00000000-0000-0000-0000-000000000$i}" -ErrorAction Stop | Out-Null
            $ok++
        } catch { }
    }
    return $ok
}

function Update-HealthStrip {
    # Imaging date (C:\timestamp_Cart.txt): show "Imaged on <Month> <Year>".
    # Date source, most-authoritative first: (1) a real date parsed from the
    # file's content, else (2) the file's last-write time (the task sequence
    # writes/touches this file at image time). Colour by age vs the current year:
    #   this year   = green (fresh)   |   last year = red (reimage due)
    #   older       = red (overdue)   |   future     = amber (something's off)
    $hc = Get-HealthConfig
    Apply-HealthVisibility -Config $hc
    $cart = $hc.imageFile
    if ($hc.checkImage) {
    $srcLabel = if ($cart -eq 'auto') { 'Windows install date (registry)' } else { $cart }
    if ($cart -ne 'auto' -and -not (Test-Path $cart)) {
        Set-HealthChip -Key Imaged -Text 'ERROR: NO IMAGE FILE FOUND' -State bad -Tip "$cart not found - PC may not have been imaged with the standard task sequence"
    } else {
        $imgDate = Get-ImagedDate -Path $cart   # shared helper (also drives the opened-state fingerprint)
        if (-not $imgDate) {
            Set-HealthChip -Key Imaged -Text 'Imaged: date unreadable' -State warn -Tip "$srcLabel : no date could be read"
        } else {
            $thisYear = (Get-Date).Year
            $diff = $thisYear - $imgDate.Year   # 0=this year, 1=last year, >1=older, <0=future
            $label = 'Imaged on {0} {1}' -f $imgDate.ToString('MMMM'), $imgDate.Year
            if     ($diff -eq 0) { $state = 'ok' }
            elseif ($diff -ge 1) { $state = 'bad' }              # last year or older -> reimage due
            else                 { $state = 'warn'; $label += ' (future date?)' }  # safeguard
            Set-HealthChip -Key Imaged -Text $label -State $state -Tip "$srcLabel : imaged $($imgDate.ToString('yyyy-MM-dd')) ($([math]::Abs($diff)) year(s) $(if($diff -lt 0){'ahead'}else{'ago'}))"
        }
    }
    }

    # GP last-processed time: LOGGED but no longer a chip (see the chip list
    # note). PKI below is the honest GP health signal.
    $gp = Get-GPLastTime

    # ConfigMgr client health: action count (folk rule: ~2 = broken, 8+ = healthy)
    $ccmSvc = Get-Service ccmexec -ErrorAction SilentlyContinue
    try {
        $n = (Get-CMActionList).Count
        $state = if ($n -ge 8) { 'ok' } elseif ($n -ge 3) { 'warn' } else { 'bad' }
        $svcTxt = if ($ccmSvc) { "ccmexec service: $($ccmSvc.Status)." } else { 'ccmexec service NOT FOUND (odd - applet works without it?).' }
        Set-HealthChip -Key CM -Text "CM: $n actions" -State $state -Tip "$svcTxt Applet lists $n actions (2 or fewer usually means a half-registered client - the CM button also fires the 9 standard cycles via WMI as a fallback)"
    } catch {
        if ($ccmSvc) {
            Set-HealthChip -Key CM -Text "CM: applet broken ($($ccmSvc.Status))" -State bad -Tip "ccmexec service exists ($($ccmSvc.Status)) but the CPApplet COM failed - the CM Actions button will still fire the standard cycles via WMI"
        } else {
            Set-HealthChip -Key CM -Text 'CM: no client' -State warn -Tip 'Configuration Manager client not found on this PC (no ccmexec service, no applet)'
        }
    }

    # PKI: machine cert matching the hostname (same rule as scripts\Test-PKICertificate.ps1)
    # that is not expired. Skipped entirely when the room's health config says
    # its machines never get machine certs (chip and button are hidden above).
    if ($hc.pki) {
    try {
        $cert = Get-ChildItem Cert:\LocalMachine\My -ErrorAction Stop |
            Where-Object { $_.Subject -match $env:COMPUTERNAME -and $_.NotAfter -gt [datetime]::Now } |
            Select-Object -First 1
        # Record the OUTCOME, not just that a check happened. Previously the log
        # only showed 'pki.check_launched' - if PKI was broken in the field there
        # was no record of what was actually on the box (issuer, expiry, or that
        # certs existed but none matched the hostname).
        $allCerts = @(Get-ChildItem Cert:\LocalMachine\My -ErrorAction SilentlyContinue)
        Write-LabLog -Event 'pki.status' -Data @{
            matched    = [bool]$cert
            storeCount = $allCerts.Count
            subject    = $(if ($cert) { "$($cert.Subject)" } else { '<none matching hostname>' })
            issuer     = $(if ($cert) { "$($cert.Issuer)" } else { '<null>' })
            notAfter   = $(if ($cert) { $cert.NotAfter.ToString('s') } else { '<null>' })
            thumbprint = $(if ($cert) { "$($cert.Thumbprint)" } else { '<null>' })
        }
        if ($cert) { Set-HealthChip -Key PKI -Text "PKI $([char]0x2713)" -State ok -Tip "Machine certificate present, expires $($cert.NotAfter.ToString('yyyy-MM-dd'))" }
        else       { Set-HealthChip -Key PKI -Text "PKI $([char]0x2717)" -State bad -Tip 'No machine certificate matching this hostname - wrong AD group, or Group Policy has not run yet (try GP Update)' }
    } catch {
        Set-HealthChip -Key PKI -Text 'PKI: unknown' -State muted
    }
    }

    Write-LabLog -Event 'health.strip' -Data @{
        cartExists = $(if ($cart -eq 'auto') { $true } else { [bool](Test-Path $cart) })
        gpLast = if ($gp) { $gp.ToString('s') } else { '<null>' }
    }
}

# ---- GP Update button: gpupdate /force with the button as the progress bar ----
# Click once to start; CLICK AGAIN TO CANCEL (Blake, 2026-08-12 - a hung GP
# update used to leave only "reboot the GUI" as the way out, and even that
# orphaned the gpupdate pair: the next session's run then queued behind the
# orphan on the GP engine's own serialisation, which read as "GP takes
# forever"). Cancel and window-close both taskkill the WHOLE tree.
$script:gpProc    = $null
$script:gpOutFile = $null
$script:gpStarted = $null
$script:gpPhase   = 'computer'  # which scope the run is currently in, for the slow-log
$script:gpLastSlowLog = 0       # elapsed seconds at the last gp.still_running entry
$script:GpDeadlineMin = 20   # /wait:600 x2 scopes can legitimately run long; past this it is stuck
function Stop-GpUpdate {
    param([string]$Why)
    $p = $script:gpProc
    $script:gpTimer.Stop()
    $script:gpProc = $null
    if ($p) {
        try { Start-Process -FilePath 'taskkill' -ArgumentList "/PID $($p.Id) /T /F" -WindowStyle Hidden -Wait -ErrorAction SilentlyContinue } catch { }
    }
    Write-LabLog -Event 'gp.update_stopped' -Data @{ why = $Why; pid = $(if ($p) { $p.Id } else { 0 }) }
    if ($script:gpOutFile) { Remove-Item $script:gpOutFile -Force -ErrorAction SilentlyContinue }
}
$script:gpTimer   = New-Object System.Windows.Threading.DispatcherTimer
$script:gpTimer.Interval = [TimeSpan]::FromMilliseconds(600)
$script:gpTimer.Add_Tick({
    try {
        $p = $script:gpProc
        if (-not $p) { $script:gpTimer.Stop(); return }
        $out = try { Get-Content $script:gpOutFile -Raw -ErrorAction SilentlyContinue } catch { '' }
        $exited = try { $p.HasExited } catch { $true }
        if (-not $exited) {
            $el = if ($script:gpStarted) { [datetime]::Now - $script:gpStarted } else { [TimeSpan]::Zero }
            if ($el.TotalMinutes -ge $script:GpDeadlineMin) {
                Stop-GpUpdate -Why "deadline ($($script:GpDeadlineMin) min)"
                $pbGP.Value = 100; $txtGPBtn.Text = 'GP: timed out'
                $txtStatus.Text = "GP update killed after $($script:GpDeadlineMin) minutes - likely no domain controller reachable. Click GP Update to try again."
                return
            }
            $elTxt = '{0:m\:ss}' -f $el
            # Phase-based progress: gpupdate reports completion per policy type.
            # The elapsed clock is the honest part - the output file is buffered
            # by cmd.exe, so the bar alone can sit still while work continues.
            # WHERE THE TIME WENT (Blake, 2026-08-12): record the moment the
            # computer phase hands off to the user phase, so the ledger can say
            # "computer took 11 min, user took 20s" instead of just "slow".
            if     ($out -match 'User Policy update has completed')     { $pbGP.Value = 95 }
            elseif ($out -match 'Computer Policy update has completed') {
                if ($script:gpPhase -eq 'computer') {
                    $script:gpPhase = 'user'
                    Write-LabLog -Event 'gp.phase_computer_done' -Data @{ seconds = [int]$el.TotalSeconds }
                }
                $pbGP.Value = [math]::Max($pbGP.Value, 66); $txtGPBtn.Text = "GP: user $elTxt"
            }
            else   { if ($pbGP.Value -lt 55) { $pbGP.Value += 4 }; $txtGPBtn.Text = "GP: $elTxt (click = cancel)" }
            # Once a minute while still running: elapsed, which phase is holding
            # things up, and whether extra gpupdate processes are serialising us.
            if ($el.TotalSeconds - $script:gpLastSlowLog -ge 60) {
                $script:gpLastSlowLog = [int]$el.TotalSeconds
                $gpProcs = @(Get-Process gpupdate -ErrorAction SilentlyContinue)
                Write-LabLog -Event 'gp.still_running' -Data @{
                    elapsedSec = [int]$el.TotalSeconds; phase = "$($script:gpPhase)"
                    gpupdateProcs = $gpProcs.Count
                    otherPids = (@($gpProcs | Where-Object { $_.Id -ne $p.Id } | ForEach-Object { $_.Id }) -join ',')
                }
            }
            return
        }
        $script:gpTimer.Stop()
        $code = try { $p.ExitCode } catch { -1 }
        $script:gpProc = $null
        # Scopes run separately (see click handler) so a half-failure is precise:
        $compOk = [bool]($out -match 'Computer Policy update has completed successfully')
        $userOk = [bool]($out -match 'User Policy update has completed successfully')
        # Pull the REAL reason out of gpupdate's own output (the useful line is
        # usually "...failed because of lack of network connectivity to a
        # domain controller" or similar) instead of a bare exit code.
        $reason = ''
        foreach ($ln in ($out -split "`r?`n")) {
            if ($ln -match '(?i)(failed|error|could not|unable to|denied|connectivity)' -and $ln.Trim()) { $reason = $ln.Trim(); break }
        }
        $pbGP.Value = 100
        if ($compOk -and $userOk) {
            $txtGPBtn.Text = "GP: done $([char]0x2713) $([datetime]::Now.ToString('HH:mm'))"
            $txtStatus.Text = 'Group Policy update completed successfully (computer + user)'
            if ($out -match '(?i)restart|logoff|log off') { $txtStatus.Text += ' - some settings need a logoff/restart to apply' }
            $script:gpRetried = $false
        } elseif (-not $compOk -and -not $userOk -and -not $script:gpRetried) {
            # Total failure -> one automatic retry (transient DC/network hiccups
            # are the most common field cause and usually clear on 2nd attempt)
            $script:gpRetried = $true
            Write-LabLog -Event 'gp.update_retry' -Data @{ exitCode = $code; reason = $reason }
            $txtGPBtn.Text = 'GP: retrying...'
            $txtStatus.Text = "GP update failed$(if ($reason) { ": $reason" }) - retrying once automatically..."
            $pbGP.Value = 6
            try {
                $script:gpProc = Start-Process cmd.exe -ArgumentList "/c $($script:gpCmd)" -WindowStyle Hidden -PassThru
                $null = $script:gpProc.Handle
                $script:gpStarted = [datetime]::Now   # fresh deadline for the retry
                $script:gpPhase = 'computer'; $script:gpLastSlowLog = 0
                $script:gpTimer.Start()
                return
            } catch { }
            $txtGPBtn.Text = 'GP: FAILED'
        } elseif ($compOk -or $userOk) {
            $half = if ($compOk) { 'computer OK, USER failed' } else { 'user OK, COMPUTER failed' }
            $txtGPBtn.Text = 'GP: partial'
            $txtStatus.Text = "GP update partial - $half$(if ($reason) { ". Reason: $reason" })"
            $script:gpRetried = $false
        } else {
            $txtGPBtn.Text = 'GP: FAILED'
            $txtStatus.Text = "GP update failed (exit $code)$(if ($reason) { ": $reason" })"
            $script:gpRetried = $false
        }
        $tail = ''
        try { $tail = ($out -replace '\s+', ' '); if ($tail.Length -gt 600) { $tail = $tail.Substring($tail.Length - 600) } } catch { }
        $gpTotalSec = if ($script:gpStarted) { [int]([datetime]::Now - $script:gpStarted).TotalSeconds } else { -1 }
        Write-LabLog -Event 'gp.update_done' -Data @{ exitCode = $code; computerOk = $compOk; userOk = $userOk; reason = $reason; totalSec = $gpTotalSec; outputTail = $tail }
        # Refresh the health strip OFF this tick (PKI may have just gained its
        # cert via autoenrollment): Update-HealthStrip makes a blocking COM call
        # into ccmexec (Get-CMActionList), and ccmexec is busiest right after a
        # GP run - calling it inline here was the one real UI freeze in the
        # whole GP path ("Not Responding" at the END of the update).
        $hsOnce = New-Object System.Windows.Threading.DispatcherTimer
        $hsOnce.Interval = [TimeSpan]::FromMilliseconds(250)
        $hsOnce.Add_Tick({ $this.Stop(); try { Update-HealthStrip } catch { } })
        $hsOnce.Start()
        Remove-Item $script:gpOutFile -Force -ErrorAction SilentlyContinue
    } catch { $script:gpTimer.Stop() }
})
$btnGPUpdate.Add_Click({
    if ($script:gpTimer.IsEnabled) {
        # SECOND CLICK = CANCEL. The old behaviour silently ate the click, which
        # with a stalled DC read as a frozen app.
        Stop-GpUpdate -Why 'user clicked cancel'
        $pbGP.Value = 0; $txtGPBtn.Text = 'GP: cancelled'
        $txtStatus.Text = 'GP update cancelled. Policy will still refresh on its own schedule (or at next boot).'
        return
    }
    $script:gpOutFile = Join-Path $env:TEMP "labdeploy_gp_$([guid]::NewGuid().ToString('N').Substring(0,6)).txt"
    $ans = Join-Path $env:TEMP 'labdeploy_gp_answers.txt'
    Set-Content $ans "n`nn`n" -Encoding ASCII   # auto-answer 'No' to logoff/reboot prompts so it can never hang
    # Scopes run SEPARATELY (computer first, then user) so a half-failure is
    # visible as exactly that, and /wait:600 stops slow DCs from being read as
    # failures. Plain documented gpupdate - nothing a security agent would flag.
    $script:gpRetried = $false
    $script:gpCmd = "(gpupdate /target:computer /force /wait:600 < `"$ans`" & gpupdate /target:user /force /wait:600 < `"$ans`") > `"$($script:gpOutFile)`" 2>&1"
    try {
        $script:gpProc = Start-Process cmd.exe -ArgumentList "/c $($script:gpCmd)" -WindowStyle Hidden -PassThru
        $null = $script:gpProc.Handle
    } catch {
        $txtGPBtn.Text = 'GP: FAILED'; $txtStatus.Text = "Could not start gpupdate: $($_.Exception.Message)"; return
    }
    Write-LabLog -Event 'gp.update_start' -Data @{ pid = $script:gpProc.Id }
    # An orphaned gpupdate from a killed session makes THIS run queue behind it
    # on the GP engine - say so instead of looking mysteriously slow. Guarded:
    # StartTime can throw on a process that exits mid-enumeration.
    try {
        $orphans = @(Get-Process gpupdate -ErrorAction SilentlyContinue | Where-Object { $_.StartTime -lt $script:gpProc.StartTime })
        if ($orphans.Count) {
            $txtStatus.Text = "Note: another gpupdate (pid $($orphans[0].Id)) is already running - this one will wait its turn behind it."
            Write-LabLog -Event 'gp.update_preexisting' -Data @{ pids = (@($orphans | ForEach-Object { $_.Id }) -join ',') }
        }
    } catch { }
    # ENVIRONMENT SNAPSHOT: the two facts that explain 90% of slow GP runs -
    # is this machine domain-joined at all, and can it actually reach its
    # logon server on LDAP right now? Capped at ~1.5s so a dead DC cannot make
    # the CLICK slow while diagnosing why the UPDATE is slow. Read-only.
    try {
        $partOfDomain = [bool](Get-CimInstance Win32_ComputerSystem -ErrorAction SilentlyContinue).PartOfDomain
        $dc = "$env:LOGONSERVER".TrimStart('\')
        $dcOk = $null; $dcMs = -1
        if ($partOfDomain -and $dc -and $dc -ne $env:COMPUTERNAME) {
            $swDc = [Diagnostics.Stopwatch]::StartNew()
            $tcp = New-Object System.Net.Sockets.TcpClient
            $dcOk = $tcp.ConnectAsync($dc, 389).Wait(1500)
            $tcp.Close(); $swDc.Stop(); $dcMs = [int]$swDc.ElapsedMilliseconds
        }
        Write-LabLog -Event 'gp.env_check' -Data @{
            partOfDomain = $partOfDomain; logonServer = $dc
            dcReachableLdap = $(if ($null -eq $dcOk) { 'n/a' } else { "$dcOk" }); dcCheckMs = $dcMs
        }
        if ($partOfDomain -and $dcOk -eq $false) {
            $txtStatus.Text = "Heads up: logon server $dc is not answering on LDAP - this GP update will likely crawl until it times out. (Cancel any time with another click.)"
        }
    } catch { }
    $script:gpStarted = [datetime]::Now
    $script:gpPhase = 'computer'; $script:gpLastSlowLog = 0
    $pbGP.Value = 6; $txtGPBtn.Text = 'GP: updating...'
    $script:gpTimer.Start()
})

# ---- CM Actions button: trigger every client action, one per tick ----
$script:cmActions = @()
$script:cmIndex   = 0
$script:cmFails   = 0
# CM RETRY (Blake 2026-08-21): right after gpupdate the CM/WMI plumbing is often
# busy, so trigger calls bounce in a burst (failed=10) and 15s later succeed. A
# 40-second stick visit pushed that burst as "__cm__ missing" and stranded five
# healthy machines purple on the dashboard. So: a pass with failures no longer
# reports cm.actions_done at all - it re-runs JUST the failed actions once, 30s
# later, and only THEN reports final counts. Trigger-level bounces never reach
# telemetry; failing twice 30s apart is a real miss and still reports honestly.
$script:cmFailedActions = @()
$script:cmRetryPass = $false
$script:cmTotalAll  = 0
$script:cmTimer   = New-Object System.Windows.Threading.DispatcherTimer
$script:cmTimer.Interval = [TimeSpan]::FromMilliseconds(350)
$script:cmRetryTimer = New-Object System.Windows.Threading.DispatcherTimer
$script:cmRetryTimer.Interval = [TimeSpan]::FromSeconds(30)
$script:cmRetryTimer.Add_Tick({
    $script:cmRetryTimer.Stop()
    $script:cmRetryPass = $true
    $script:cmActions = @($script:cmFailedActions)
    $script:cmFailedActions = @()
    $script:cmIndex = 0; $script:cmFails = 0
    Write-LabLog -Event 'cm.retry_start' -Data @{ retrying = $script:cmActions.Count; ofTotal = $script:cmTotalAll }
    $txtCMBtn.Text = "CM: retrying $($script:cmActions.Count)..."
    $script:cmTimer.Start()
})
$script:cmTimer.Add_Tick({
    try {
        $n = $script:cmActions.Count
        if ($script:cmIndex -ge $n) {
            $script:cmTimer.Stop()
            # FIRST pass with failures: do NOT report cm.actions_done yet - the
            # bounces are usually the post-gpupdate busy window. Queue the 30s
            # retry of just the failed actions; the verdict waits for it.
            if ($script:cmFails -gt 0 -and -not $script:cmRetryPass) {
                Write-LabLog -Event 'cm.retry_scheduled' -Data @{ failed = $script:cmFails; total = $script:cmTotalAll; delaySec = 30 }
                $txtCMBtn.Text = "CM: $($script:cmFails) bounced - retry in 30s"
                $txtStatus.Text = "CM: $($script:cmFails) trigger(s) bounced (CM busy after GP?) - retrying them automatically in 30s. Leave the tool open."
                $script:cmRetryTimer.Start()
                return
            }
            # Belt + suspenders: after the applet loop, ALSO fire the 9 standard
            # cycles via WMI - catches whatever a half-registered applet missed.
            $wmiOk = Invoke-CMWmiTriggers
            $pbCM.Value = 100
            $tot = $script:cmTotalAll
            $txtCMBtn.Text = "CM: done ($tot+$wmiOk) $([char]0x2713)"
            $txtStatus.Text = if ($script:cmFails -gt 0) { "CM: $($tot - $script:cmFails)/$tot applet actions OK ($($script:cmFails) failed even after retry) + $wmiOk/9 standard cycles via WMI" }
                              else { "CM: all $tot applet actions + $wmiOk/9 standard cycles (WMI) triggered - they run in the background" }
            Write-LabLog -Event 'cm.actions_done' -Data @{ total = $tot; failed = $script:cmFails; wmiTriggered = $wmiOk; retried = [int]$script:cmRetryPass }
            return
        }
        $a = $script:cmActions[$script:cmIndex]
        # Log WHICH action failed and WHY. Counting failures alone ("failed=3")
        # is undiagnosable after the fact - you cannot tell a broken Machine
        # Policy cycle from a broken Hardware Inventory one, and both need
        # different fixes.
        $aName = try { "$($a.Name)" } catch { '(unnamed)' }
        try {
            $a.PerformAction()
            Write-LabLog -Event 'cm.action_ok' -Data @{ index = $script:cmIndex; name = $aName }
        } catch {
            $script:cmFails++
            $script:cmFailedActions += $a
            Write-LabLog -Event 'cm.action_failed' -Data @{
                errorCode = 'E72'; index = $script:cmIndex; name = $aName; error = $_.Exception.Message
            }
        }
        $script:cmIndex++
        $pbCM.Value = [math]::Floor($script:cmIndex * 100 / $n)
        $txtCMBtn.Text = "CM: $($script:cmIndex)/$n"
    } catch {
        $script:cmTimer.Stop()
        # This catch used to be entirely silent: the CM run simply stopped
        # partway with no record of why.
        Write-LabLog -Event 'cm.loop_error' -Data @{
            errorCode = 'E72'; index = $script:cmIndex; error = $_.Exception.Message
        }
        $txtStatus.Text = "[E72] CM actions stopped early: $($_.Exception.Message)"
    }
})
$btnCMActions.Add_Click({
    if ($script:cmTimer.IsEnabled -or $script:cmRetryTimer.IsEnabled) { return }   # its own single slot; installs unaffected
    try { $script:cmActions = Get-CMActionList } catch {
        # Applet dead - but if the ccmexec service exists, the WMI path can
        # still fire the standard cycles (documented SMS_Client interface).
        if (Get-Service ccmexec -ErrorAction SilentlyContinue) {
            $txtCMBtn.Text = 'CM: WMI fallback...'
            $wmiOk = Invoke-CMWmiTriggers
            $pbCM.Value = 100
            $txtCMBtn.Text = "CM: WMI $wmiOk/9 $([char]0x2713)"
            $txtStatus.Text = "CM applet is broken on this PC, but $wmiOk/9 standard cycles were fired via WMI instead"
            Write-LabLog -Event 'cm.wmi_fallback' -Data @{ wmiTriggered = $wmiOk }
        } else {
            $txtCMBtn.Text = 'CM: no client'
            $txtStatus.Text = 'Configuration Manager client not found on this PC - nothing to trigger'
            Write-LabLog -Event 'cm.no_client' -Data @{ }
        }
        return
    }
    if ($script:cmActions.Count -eq 0) {
        $txtCMBtn.Text = 'CM: 0 actions'
        Write-LabLog -Event 'cm.actions_none' -Data @{ errorCode = 'E72'; note = 'CPApplet returned an empty action list' }
        return
    }
    $script:cmIndex = 0; $script:cmFails = 0
    $script:cmFailedActions = @(); $script:cmRetryPass = $false
    $script:cmTotalAll = $script:cmActions.Count
    $pbCM.Value = 2; $txtCMBtn.Text = "CM: 0/$($script:cmActions.Count)"
    # Record the action NAMES, not just the count. Blake's field report was
    # "only 2 actions showed up when there are usually more" - that is only
    # diagnosable if the log says WHICH two the applet exposed.
    $cmNames = @()
    foreach ($a in $script:cmActions) { $cmNames += $(try { "$($a.Name)" } catch { '(unnamed)' }) }
    Write-LabLog -Event 'cm.actions_start' -Data @{ total = $script:cmActions.Count; actions = ($cmNames -join ' | ') }
    $script:cmTimer.Start()
})

# Health chips populate AFTER first render: Update-HealthStrip makes a blocking
# CM COM call that used to sit between the tech and the window. The chips show
# "checking..." for the first moment instead.
$script:hsStartup = New-Object System.Windows.Threading.DispatcherTimer
$script:hsStartup.Interval = [TimeSpan]::FromMilliseconds(250)
$script:hsStartup.Add_Tick({ $this.Stop(); $p0 = $script:UiPhase; $script:UiPhase = 'health-strip'; try { Update-HealthStrip } catch { }; $script:UiPhase = $p0 })
$script:hsStartup.Start()

# Auto-scan checkbox: initialize from saved setting BEFORE wiring events so
# the load itself doesn't trigger a save
$chkAutoScan.IsChecked = $script:AutoScan

$chkAutoScan.Add_Checked({
    $script:AutoScan = $true
    Save-GuiSettings
    # Scan whatever is still unscanned in the current room (screen order)
    $queued = 0
    foreach ($card in @(foreach ($id in $script:CardOrder) { if ($script:Cards.ContainsKey($id)) { $script:Cards[$id] } })) {
        if ($card.Status -eq 'Unknown') {
            $card.Detail.Text = 'Scanning...'
            $card.Detail.Foreground = $script:BrushMuted
            $card.Status = 'Scanning'
            $script:scanQueue.Enqueue($card.AppId)
            $queued++
        }
    }
    if ($queued -gt 0) {
        $txtStatus.Text = "Auto-scan enabled - scanning $queued unscanned app(s)..."
        Start-IndexBuildAsync -OnReady { if (-not $script:scanTimer.IsEnabled) { $script:scanTimer.Start() } }
    } else {
        $txtStatus.Text = 'Auto-scan enabled'
    }
})

$chkAutoScan.Add_Unchecked({
    $script:AutoScan = $false
    Save-GuiSettings
    $txtStatus.Text = 'Auto-scan disabled - apps will be scanned when you act on them'
})

# (Command-preview toggle removed 2026-07-15 - installs run popup-free;
#  the exact command of every operation is still recorded in the logs.)

# Offload toggle (persisted)
$chkOffload.IsChecked = $script:OffloadEnabled
$chkOffload.Add_Checked({
    $script:OffloadEnabled = $true
    Save-GuiSettings
    $txtStatus.Text = 'Offload ON - big installers copy to local disk first, then install'
})
$chkOffload.Add_Unchecked({
    $script:OffloadEnabled = $false
    Save-GuiSettings
    $txtStatus.Text = 'Offload OFF - big installers run straight from the drive'
})

# ============================================================
#  Startup
# ============================================================
if (-not $script:IsAdmin) {
    $txtStatus.Text = 'Running without admin - detection works, but installs need elevation (use Launch.bat)'
} else {
    $txtStatus.Text = 'Detecting room...'
}

$detected = Get-DetectedRoom
# A rule that carries its own app list resolves to the synthetic '_assigned_'
# profile, which Register-AssignedProfile only just created - AFTER the room
# dropdown above was populated. Splice it in (just before 'All Applications'),
# or the machine would decode perfectly and then auto-select nothing at all.
if ($detected -and ($script:RoomIdList -notcontains $detected) -and $script:RoomsConfig.rooms.$detected) {
    $ins = [array]::IndexOf($script:RoomIdList, '_ALL_')
    if ($ins -lt 0) { $ins = $script:RoomIdList.Count }
    $cmbRoom.Items.Insert($ins, "$($script:RoomsConfig.rooms.$detected.displayName)")
    $lst = New-Object System.Collections.Generic.List[string]
    foreach ($x in $script:RoomIdList) { [void]$lst.Add([string]$x) }
    $lst.Insert($ins, [string]$detected)
    $script:RoomIdList = @($lst)
}
if ($detected) {
    for ($i = 0; $i -lt $script:RoomIdList.Count; $i++) {
        if ($script:RoomIdList[$i] -eq $detected) { $cmbRoom.SelectedIndex = $i; break }
    }
} else {
    # No room matched. If the config carries a DEFAULT profile, select it -
    # that is the universal fallback set for machines outside every naming
    # scheme. Interactive only: unattended -Auto still stands down (E11),
    # because auto-installing onto unrecognised machines is how accidents
    # happen on somebody's personal PC.
    $defIdx = [array]::IndexOf($script:RoomIdList, 'DEFAULT')
    if ($defIdx -ge 0 -and $script:RoomsConfig.rooms.DEFAULT) {
        $cmbRoom.SelectedIndex = $defIdx
        $txtStatus.Text = "No room matched '$env:COMPUTERNAME' - showing the DEFAULT set. Pick a room profile if this machine should have one."
    } elseif ($cmbRoom.Items.Count -gt 0) {
        $txtStatus.Text = "Could not auto-detect room from hostname '$env:COMPUTERNAME'. Please select a room profile."
    }
}

# -Auto: press "Install All Missing" ourselves once the scan finishes, but ONLY
# for a machine that actually matched a known config. An unrecognised hostname
# means we do not know what it should have, and guessing there is how the wrong
# multi-GB image lands on someone's PC - so it stays parked for a human.
$script:AutoInstallPending = $false
if ($Auto) {
    if ($detected) {
        $script:AutoInstallPending = $true
        Write-LabLog -Event 'auto.armed' -Data @{ room = $detected; computer = $env:COMPUTERNAME }
        $txtStatus.Text = "Unattended mode: $detected detected - installing everything missing once the scan finishes."
    } else {
        Write-LabLog -Event 'auto.stood_down' -Data @{ errorCode = 'E11'; computer = $env:COMPUTERNAME; reason = 'hostname matched no rule or room profile' }
        $txtStatus.Text = "[E11] Unattended mode did NOTHING: '$env:COMPUTERNAME' matches no room profile or deployment rule. Pick a room and install by hand."
    }
}

# AUTOMATIC ERROR RECHECK at startup, from BOTH memories this machine has:
#   1. THE MASTER'S ORDERS (fleet-issues.json, carried out by every stick sync):
#      "some stick, somewhere, reported app Y broken on this machine" - so a
#      stick that has visited the master knows to check Y here even if IT never
#      saw the error itself.
#   2. THIS STICK'S OWN LOGS: every session this stick ever ran on this machine
#      is still in its logs folder, so run the SAME reconciliation fold over
#      them (same generations, newest-wins, tie rules as the fleet map) and
#      recheck whatever still stands. Covers the stick that found the error
#      yesterday but hasn't been back to the master since.
# The re-scan happens in the background with the normal startup scan - even for
# off-room dependency cards, and even with auto-scan off (a targeted recheck
# outranks the lazy-scan preference). Its snapshot is the strictly-newer
# evidence that retires the failure on the master, or re-confirms it for real.
try {
    $recheck = @{}   # appId -> 'master' | 'logs' | 'master+logs'

    # source 1: the master's standing orders
    try {
        $fiPath = Join-Path $ConfigRoot 'fleet-issues.json'
        if (Test-Path $fiPath) {
            $fi = Get-Content $fiPath -Raw | ConvertFrom-Json
            if ($fi.machines) {
                foreach ($p in $fi.machines.PSObject.Properties) {
                    if ($p.Name -ieq $env:COMPUTERNAME) {
                        foreach ($id in @($p.Value)) { if ($id -and $script:AppsConfig.apps.$id) { $recheck[$id] = 'master' } }
                        break
                    }
                }
            }
        }
    } catch { }

    # source 2: this stick's own memory of this machine
    try {
        $selfRoll = Get-FleetRollup -LogsDir $script:LogRoot -Machine $env:COMPUTERNAME
        $selfRec  = $selfRoll[$env:COMPUTERNAME]
        if ($selfRec) {
            foreach ($id in @($selfRec.RecheckApps)) {
                if (-not $id -or -not $script:AppsConfig.apps.$id) { continue }
                $recheck[$id] = if ($recheck.ContainsKey($id)) { 'master+logs' } else { 'logs' }
            }
        }
    } catch { }

    if ($recheck.Count -gt 0) {
        $ids = @($recheck.Keys | Sort-Object)
        $names = @($ids | ForEach-Object { $dn = "$($script:AppsConfig.apps.$_.displayName)"; if ($dn) { $dn } else { $_ } })
        Write-LabLog -Event 'fleet.recheck_queued' -Data @{
            apps = (@($ids | ForEach-Object { "$_($($recheck[$_]))" }) -join ';')
        }
        foreach ($id in $ids) {
            $script:DetectionCache.Remove($id)
            if (-not $script:scanQueue.Contains($id)) { $script:scanQueue.Enqueue($id) }
        }
        $fromMaster  = @($ids | Where-Object { $recheck[$_] -like 'master*' }).Count -gt 0
        $fromLogs = @($ids | Where-Object { $recheck[$_] -like '*logs' }).Count -gt 0
        $who = if ($fromMaster -and $fromLogs) { 'The master and this drive''s own logs report' }
               elseif ($fromMaster) { 'The master reports' }
               else { 'This drive''s own logs from earlier visits show' }
        $txtStatus.Text = "$who unresolved issue(s) here with: $($names -join ', ') - re-checking in the background now..."
        # Room load usually already started the scan (or its index build).
        # Only kick one off ourselves when neither is running - calling
        # Start-IndexBuildAsync while a build is in flight would CANCEL it
        # via the generation counter and orphan the first OnReady.
        if (-not $script:scanTimer.IsEnabled -and -not $script:indexHandle -and $script:scanQueue.Count -gt 0) {
            Start-IndexBuildAsync -OnReady { $script:scanTimer.Start() }
        }
    }
} catch { }

# ============================================================
#  Caffeine: auto-start ON, and clean shutdown handling
# ============================================================
Set-CaffeineState -On $true
$window.Add_Closing({
    param($sender, $e)
    # The drive-removed watchdog closes us automatically. Both gates below are
    # MessageBoxes, and an automatic close has nobody there to answer one - it
    # would hang forever with the window still on screen, which is the exact
    # confusion the watchdog exists to remove. The watchdog only ever force-
    # closes when NOTHING is running, so neither gate has anything to protect.
    if ($script:ForceClose) {
        Write-LabLog -Event 'app.closed_drive_removed' -Data @{ }
        Stop-IndexBuild
        Stop-Caffeine
        if ($script:gpProc) { Stop-GpUpdate -Why 'window closed (watchdog)' }
        return
    }
    # Closing mid-install leaves the installer running invisibly in the
    # background (this caused the orphaned-LabVIEW incident) -- confirm first.
    if (Test-OperationInProgress) {
        $ans = [System.Windows.MessageBox]::Show(
            "An install/uninstall is still running.`n`nIf you close now it will keep running invisibly in the background, and this tool won't be tracking it.`n`nClose anyway?",
            'Operation In Progress', 'YesNo', 'Warning')
        if ($ans -ne 'Yes') { $e.Cancel = $true; return }
        # $script:installAppId is $null during the offload COPY phase, so fall
        # back to the copy context or the ledger just says "something".
        $whichApp = $script:installAppId
        if (-not $whichApp -and $script:offloadCtx) { $whichApp = $script:offloadCtx.AppId }
        Write-LabLog -Event 'app.closed_during_operation' -Data @{ appId = $whichApp }

        # A vendor INSTALLER is deliberately left running - that is what the
        # dialog just promised. An offload COPY is different: it is our own
        # pre-staging robocopy, and the only thing that would ever consume the
        # staged files is the install this window was about to start. Leave it
        # and it silently mirrors tens of GB into C:\LabDeployOffload_Temp for
        # a session that no longer exists. Stop it and reclaim the space.
        if ($script:offloadCopyTimer -and $script:offloadCopyTimer.IsEnabled) {
            $script:offloadCopyTimer.Stop()
            $ctxOnClose = $script:offloadCtx
            try {
                if ($script:offloadCopyProc) {
                    Start-Process -FilePath 'taskkill' -ArgumentList "/PID $($script:offloadCopyProc.Id) /T /F" -WindowStyle Hidden -Wait -ErrorAction SilentlyContinue
                }
            } catch { }
            if ($ctxOnClose -and $ctxOnClose.TempBase) {
                Remove-Item $ctxOnClose.TempBase -Recurse -Force -ErrorAction SilentlyContinue
            }
            $script:offloadCopyProc = $null; $script:offloadCtx = $null
            Write-LabLog -Event 'offload.copy_abandoned_on_close' -Data @{ appId = $whichApp }
        }
    }

    # UNFINISHED-WORK GATE: a yellow "needs opening" card means the app is on
    # disk but its first-run setup (updates, licence prompt, vendor driver step)
    # has never been done and confirmed on this machine. That used to require
    # someone actively clicking No; now that the post-install prompt times out
    # unattended, it is a state you can reach with nobody ever having seen a
    # dialog - so it must not be possible to close the tool quietly on top of it.
    $pendingOpen = @($script:Cards.Keys | Where-Object { $script:Cards[$_].Status -eq 'NeedsOpen' })
    if ($pendingOpen.Count -gt 0) {
        $pendNames = ($pendingOpen | ForEach-Object {
            $dn = $script:AppsConfig.apps.$_.displayName
            if ($dn) { "     - $dn" } else { "     - $_" }
        }) -join "`n"
        $ansOpen = [System.Windows.MessageBox]::Show(
            "These are installed but have NOT been opened and confirmed yet:`n`n$pendNames`n`nEach one still needs to be opened once on this machine so it can finish its own first-run setup. Open it, then tick 'App Opened?' on the card.`n`nClose anyway?",
            "$($pendingOpen.Count) program(s) still need opening", 'YesNo', 'Warning')
        if ($ansOpen -ne 'Yes') { $e.Cancel = $true; return }
        Write-LabLog -Event 'app.closed_with_unopened' -Data @{ count = $pendingOpen.Count; appIds = ($pendingOpen -join ',') }
    }

    # Telemetry: drain the outbox, but NEVER block exit. Bounded to a few seconds;
    # whatever does not go leaves queued (the cursor makes giving up safe) and ships
    # next session. A hung network must never trap the window.
    try { $null = Push-Observations -DeadlineSec 3 } catch {}
    Stop-IndexBuild
    Stop-Caffeine
    # A gpupdate left behind by a closing session is exactly what made the NEXT
    # session's GP run "hang": the GP engine serialises, so the fresh run sat
    # invisibly behind the orphan (the laptop #25/#26 pattern). Kill the tree.
    if ($script:gpProc) { Stop-GpUpdate -Why 'window closed' }
})

# ============================================================
#  Drive-removed watchdog
# ============================================================
# Pulling the stick does NOT close this window on its own: PowerShell reads the
# whole script into memory at launch and WPF comes from the system, so the
# process needs nothing further from the drive and carries on happily.
#
# That is worse than untidy. The session log lives on the drive and Write-LabLog
# swallows its own errors, so after an unplug the tool keeps LOOKING normal
# while recording nothing - the tech believes the visit is being tracked and the
# fleet never hears about it. Installer sources are on the drive too, so any
# install started afterwards dies with E21.
#
# Only armed when actually running FROM removable media: the master runs from an
# internal disk that cannot vanish, and auto-closing the master would be absurd.
$script:ForceClose = $false
$script:DriveGoneAt = $null
$script:DriveGoneGraceSec = 20
$script:RunningFromRemovable = $false
try {
    $rootDrive = [System.IO.Path]::GetPathRoot($script:ScriptRoot)
    if ($rootDrive) {
        $di = New-Object System.IO.DriveInfo($rootDrive)
        $script:RunningFromRemovable = ("$($di.DriveType)" -eq 'Removable')
    }
} catch { }

if ($script:RunningFromRemovable) {
    $script:driveWatchTimer = New-Object System.Windows.Threading.DispatcherTimer
    $script:driveWatchTimer.Interval = [TimeSpan]::FromSeconds(2)
    $script:driveWatchTimer.Add_Tick({
        # The script's own file is the probe - if that is unreachable the drive
        # is gone, whatever the drive letter is doing.
        $alive = $false
        try { $alive = [System.IO.File]::Exists((Join-Path $script:ScriptRoot 'Deploy-LabGUI.ps1')) } catch { }

        if ($alive) {
            if ($script:DriveGoneAt) {
                # plugged back in (same letter) - carry on, and say so
                $script:DriveGoneAt = $null
                $brdDriveGone.Visibility = [System.Windows.Visibility]::Collapsed
                $txtStatus.Text = 'Drive reconnected - logging has resumed.'
                Write-LabLog -Event 'drive.reconnected' -Data @{ }
            }
            return
        }

        if (-not $script:DriveGoneAt) {
            $script:DriveGoneAt = Get-Date
            $brdDriveGone.Visibility = [System.Windows.Visibility]::Visible
            # This log line lands only if the drive returns; harmless either way.
            Write-LabLog -Event 'drive.removed' -Data @{ }
        }
        $goneFor = [int]((Get-Date) - $script:DriveGoneAt).TotalSeconds

        if (Test-OperationInProgress) {
            # NEVER auto-close mid-operation. An offloaded install genuinely
            # keeps running from the local staging copy and can still succeed,
            # and killing the window would just stop us tracking it.
            $txtDriveGone.Text = "DRIVE DISCONNECTED - an install is still running, so this window is staying open to track it. Nothing is being logged and any install that still needs the drive will fail. Plug the drive back in now."
            return
        }
        $left = $script:DriveGoneGraceSec - $goneFor
        if ($left -gt 0) {
            $txtDriveGone.Text = "DRIVE DISCONNECTED - nothing is being logged and installs will fail. Plug it back in to carry on, or this window closes in $left second$(if ($left -ne 1) { 's' })."
        } else {
            $script:ForceClose = $true
            $script:driveWatchTimer.Stop()
            try { $window.Close() } catch { }
        }
    })
    $script:driveWatchTimer.Start()
}

# ============================================================
#  Auto GP update + CM actions (theFuture item 4)
# ============================================================
# On a real FIELD stick only (never the master, never a non-removable dev machine),
# if this laptop's own history can't confirm GP/CM have run this image generation,
# kick them off now. Non-blocking (Start-Process); Invoke-AutoGpCm re-checks the
# toggle + need internally and no-ops otherwise, so this is safe even if the gates
# below ever loosen. Nothing here waits, so the window still shows immediately.
if ($script:RunningFromRemovable -and -not $script:IsMaster) {
    try { $null = Invoke-AutoGpCm } catch { Write-LabLog -Event 'autogpcm.startup_error' -Data @{ error = "$($_.Exception.Message)" } }
}

# Apply the saved display size LAST, so it captures the final window geometry
# as its 100% baseline (the master widens the window above; doing this earlier
# would treat the field size as the baseline and under-grow on the master).
# -Silent: this is restoring a saved preference, not a change to announce.
# Fit mode needs no baseline work here: ActualWidth is still 0 before the window
# is shown, so Update-UiFit no-ops and the FIRST SizeChanged (fired once WPF has
# laid the window out, after any master widening) captures the baseline and lands
# on exactly 1.0. Enable-UiFit only has to undo a scaled MinWidth/MinHeight.
try {
    if ($script:UiFit) { Enable-UiFit -Silent }
    elseif ([math]::Abs($script:UiScale - 1.0) -gt 0.001) { Set-UiScale -Scale $script:UiScale -Silent }
}
catch { Write-LabLog -Event 'ui.scale_apply_failed' -Data @{ scale = $script:UiScale; fit = $script:UiFit; error = $_.Exception.Message } }

# ============================================================
#  Show Window
# ============================================================
# Hide the launcher console at the last moment (all init done, no error) so the
# GUI never sits on top of a black box. Restored automatically when powershell exits.
try {
    $con = [LabDeploy.Win32]::GetConsoleWindow()
    if ($con -ne [System.IntPtr]::Zero) { [void][LabDeploy.Win32]::ShowWindow($con, 0) }
} catch { }

# UI freeze watchdog (log-only): a 500ms heartbeat on the UI thread. A late
# beat means the thread was BLOCKED for exactly that long - the log line says
# how long and which phase was running, so a field report of 'it froze' comes
# with its own diagnosis. Costs nothing measurable.
$script:UiPhase = "startup"
$script:UiPulseLast = $null
$script:UiPulse = New-Object System.Windows.Threading.DispatcherTimer
$script:UiPulse.Interval = [TimeSpan]::FromMilliseconds(500)
$script:UiPulse.Add_Tick({
    $now = Get-Date
    if ($script:UiPulseLast) {
        $gap = ($now - $script:UiPulseLast).TotalSeconds
        if ($gap -gt 2.0) {
            # blame the phase that was current when beats STOPPED (stored on
            # the previous beat), not whatever phase resumed afterwards
            Write-LabLog -Event 'ui.frozen' -Data @{ seconds = [math]::Round($gap, 1); phase = "$($script:UiPulsePhase)"; after = "$($script:UiPhase)" }
        }
    }
    $script:UiPulseLast = $now
    $script:UiPulsePhase = $script:UiPhase
})
$script:UiPulse.Start()
$window.ShowDialog() | Out-Null
